 */
--
-- ------------------------------------------------------------------------------------------------
--                                   Function GetParametro
--                     fornisce la descrizione di un parametro ed il numero
-- ------------------------------------------------------------------------------------------------
--
  Function GetParametro (p_parametro Number, p_descrizione Varchar2 )              
   Return Varchar2      Is
-- la variabile di input p_descrizione è inutile: è solo usata nella scrittura del codice per una maggiore facilità di lettura della messaggistica
      s_value   Varchar2 (4000);
  BEGIN

--          SELECT replace (DESCRIZIONE,'_',' (') ||')'                               --x.x.x.x.x.x (nome_parametro)
--          INTO s_value
--          FROM Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI
--          WHERE CODICE_PARAMETRO = p_parametro;

--          SELECT substr(DESCRIZIONE,instr(DESCRIZIONE,'_')+1)||' ('||substr(DESCRIZIONE,1,instr(DESCRIZIONE,'_')-1)||')'        --nome_parametro (x.x.x.x.x.x )
--          INTO s_value
--          FROM Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI
--          WHERE CODICE_PARAMETRO = p_parametro;

     Select ''''||Replace(DESCRIZIONE, '_',' - ')||''''       --'x.x.x.x.x.x - nome_parametro'
          Into s_value
          From Rinf_Anagrafiche_Evo.CATALOGO_PARAMETRI
          Where CODICE_PARAMETRO = p_parametro;
--
      Return s_value;
  EXCEPTION
      When NO_DATA_FOUND Then
      Return null;
  End GetParametro;
