-- ------------------------------------------------------------------------------------------------
--                              Function GetCorrectControlId 
-- ------------------------------------------------------------------------------------------------
--
  Function GetCorrectControlId (p_sol_op Varchar2)
      Return Number Is
      n_value   Number;
   BEGIN
      If p_sol_op Like 'TR%' Then
            Select CODICE_CONTROLLO
              Into n_value
              From Rinf_Controllati_Evo.SEZIONI_LINEA
             Where SEDE_TECNICA = p_sol_op;
      Else
           Select CODICE_CONTROLLO
             Into n_value
             From Rinf_Controllati_Evo.PUNTI_OPERATIVI
            Where SEDE_TECNICA = p_sol_op;
      End If; 
--
      Return n_value;
   EXCEPTION
      When NO_DATA_FOUND Then
      Return Null;
   End GetCorrectControlId;
--
-- ------------------------------------------------------------------------------------------------
--                               Function GetParameterValue
--        questa procedura ritorna il valore di un campo dell'area dati RINF_LAVORAZIONE_EVO
-- ------------------------------------------------------------------------------------------------
--
  Function GetParameterValue (p_tabella In Varchar2, p_campo_chiave In Varchar2, p_campo_valore In Varchar2, p_id_oggetto In Varchar2)    
   Return Varchar2   Is
       sqlstring Varchar2(3000);
       s_new_val Varchar2(500);
       c_val empcur;
   BEGIN
      sqlstring := 'SELECT new.'||p_campo_valore||' new_val ';
      sqlstring := sqlstring || ' FROM Rinf_Lavorazione_Evo.'||p_tabella||' new ';
      sqlstring := sqlstring || ' WHERE  ';
      sqlstring := sqlstring || ' new.'||p_campo_chiave||'  = '''||p_id_oggetto||''' ';
--
      Open c_val For sqlstring;
      Fetch c_val Into s_new_val;
      Close c_val;
--
      Return s_new_val;
   EXCEPTION
      When NO_DATA_FOUND Then
      Return Null;
   End GetParameterValue;
--
-- ------------------------------------------------------------------------------------------------
--                                  Function GetCorrectRange
--               valuta il range numerico e dice se il parametro lo rispetta
-- ------------------------------------------------------------------------------------------------
--
 Function GetCorrectRange (p_parametro Number, p_value Number)   
    Return  Number  Is
      n_min Number;
      n_max Number;
   BEGIN
-- 03/05/2018 inserito il format per gestire le virgole ed i punti nel formato numerico
-- a segutio di segnalazione SCHILLACI mail 24/04/2018 Anomalia su parametri binari AF
    --SELECT MIN (TO_Number (replace(valore,'.',','))), MAX (TO_Number (replace(valore,'.',',')))
      Select Min(To_Number(VALORE,'9999.9')), Max(To_Number(VALORE,'9999.9')) 
        Into n_min, n_max
        From Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO
       Where CODICE_TIPO_DOMINIO = 1 
	     And CODICE_PARAMETRO = p_parametro;
--
      If p_value Between n_min And n_max Then
         Return 1;
      Else
         Return 0;
      End If; 
--
   EXCEPTION                --03/05/2018 inserita anche exception
      When OTHERS Then
      Return 0;
   End GetCorrectRange;
--
-- ------------------------------------------------------------------------------------------------
--                             Function GetCorrectAP
--                    verifica la coppia AP/valore e NA/nullo
-- ------------------------------------------------------------------------------------------------
--
  Function GetCorrectAP (s_new_val_AP Varchar2, p_value Varchar2)  
   Return Number Is
   BEGIN
      If  (s_new_val_AP = 'N' And p_value Is Not Null )                         -- N: false (NA - non applicabile)
  	   Or (s_new_val_AP = 'Y' And p_value Is Null )                             -- Y: true  (A - applicabile)
      Then
         Return 0;                                                              -- 0: dato Errato
      Else
         Return 1;                                                              -- 1: dato Corretto
      End If; 
--
   EXCEPTION                --03/05/2018 inserita exception
      When OTHERS Then
      Return 0;
   End GetCorrectAP;
--
-- ------------------------------------------------------------------------------------------------
--                           Function GetCorrectAPDICH 
--               verifica la coppia AP/valore e NAP/nullo per le DICHIARAZIONI
--               !!!!!! per le quali non esiste null nel valore ma 'spazio'
-- ------------------------------------------------------------------------------------------------
--
  Function GetCorrectAPDICH (s_new_val_AP Varchar2, p_value Varchar2)   
   Return Number     Is
   BEGIN
 -- N: false - Y: true
      If ((s_new_val_AP = 'N' And p_value <> ' ' ) Or (s_new_val_AP = 'Y' And p_value =  ' '  ))  
	  Then                  
         Return 0;
      Else
         Return 1;
      End If; 
--
  EXCEPTION                --03/05/2018 inserita exception
      When OTHERS Then
      Return 0;
  End GetCorrectAPDICH;
--
-- ------------------------------------------------------------------------------------------------
--                                 Function GetIsNumber
--              funzione per verificare se il contenuto di una stringa è un numerico
-- ------------------------------------------------------------------------------------------------
--
  Function GetIsNumber (stringa Varchar2)      
   Return Number   Is
      numero Number;
    BEGIN
        Select To_Number(stringa) Into numero From dual;
        Return 1;                                    -- TRUE: contiene solo numeri
    EXCEPTION
     When OTHERS Then
       Return 0;                                      --FALSE: non contiene solo numeri
    End GetIsNumber;
--
-- ------------------------------------------------------------------------------------------------
--                             Function GetCorrectDECLFormat
--                  verifica se il formato della DICHIARAZIONE è corretto
-- ------------------------------------------------------------------------------------------------
--
  Function GetCorrectDECLFormat (s_val_new_1 Varchar2)   
      Return Number   Is
   BEGIN
       If       Length(s_val_new_1) = 29
            And Substr(s_val_new_1, 1, 2)= 'IT'                                                                                                                  --campo fisso CODICE ITALIA
            And Substr(s_val_new_1, 3, 1)= '/'
            And Substr(s_val_new_1, 4, 14)= '00001585570581'                                                                                            --campo fisso PARTITA IVA AZIEndALE
            And Substr(s_val_new_1, 18, 1)= '/'
            And GetIsNumber(Substr(s_val_new_1, 19, 4)) = 1 
			And To_Number(Substr(s_val_new_1, 19, 4)) > 2007    -- campo variabile ANNO EMISSIONE DICHIARAZIONE non inferiore a 2008
            And Substr(s_val_new_1, 23, 1) = '/'
            And GetIsNumber(Substr(s_val_new_1, 24, 6)) = 1                                                                                                    --campo variabile PROGRESSIVO DICH
      Then
         Return 1;                  -- Valore corretto
      Else
         Return 0;                  -- sbagliato
      End If; 
--
   EXCEPTION                       -- 03/05/2018 inserita exception
      When OTHERS Then 
      Return 0;
   End GetCorrectDECLFormat;
