-- ------------------------------------------------------------------------------------------------
--                              Function GetAbilitazioneControllo
--               ritorna se un gruppo di controlli è abilitato (1) o disabilitato (0)
-- ------------------------------------------------------------------------------------------------
--
  Function GetAbilitazioneControllo (p_sigla_controllo Varchar2)                        
      Return Number
    Is
      n_value   Number;
   BEGIN
      Select FLAG_ABILITATO
        Into n_value
        From Rinf_Anagrafiche_Evo.GESTIONE_CONTROLLI
       Where sigla_controllo = p_sigla_controllo;
--
      Return n_value;
   EXCEPTION
      When NO_DATA_FOUND Then
      Return 0;
   End GetAbilitazioneControllo;
