-- ------------------------------------------------------------------------------------------------
--                       Procedure GetOldNewValue
-- Questa procedura fornisce l'ultimo valore risultato corretto per il determinato parametro ed è valida per:
-- l'oggetto deve essere una stringa
-- la chiave primaria della tabella è costituita da un solo campo
-- ------------------------------------------------------------------------------------------------
--
   Procedure GetOldNewValue (p_tabella       In Varchar2, 
                             p_campo_join    In Varchar2, 
						     p_campo_valore  In Varchar2,
						     p_id_oggetto    In Varchar2, 
						     s_new_val      Out Varchar2, 
						     s_old_val      Out Varchar2  )    Is
      sqlstring Varchar2(3000);
      c_val EMPCUR;
   BEGIN
        sqlstring := 'Select new.'||p_campo_valore||' new_val, ';
        sqlstring := sqlstring || ' old.'||p_campo_valore||'      old_val   ';
        sqlstring := sqlstring || ' From Rinf_Lavorazione_Evo.'||p_tabella||' new, ';
        sqlstring := sqlstring || ' Rinf_Controllati_Evo.'||p_tabella||' old ';
        sqlstring := sqlstring || ' Where  ';
        sqlstring := sqlstring || ' new.'||p_campo_join||'  =old.'||p_campo_join||'  (+) And ';
        sqlstring := sqlstring || ' new.'||p_campo_join||'  = '''||p_id_oggetto||''' ';
--
        Open  c_val For  sqlstring;
        Fetch c_val Into s_new_val, s_old_val;
        Close c_val;
   End GetOldNewValue;
--
-- ------------------------------------------------------------------------------------------------
--                                   Procedure GetOldNewValueMultiplo
-- Questa procedura fornisce l'ultimo valore risultato corretto per il determinato parametro ed è valida per:
-- l'oggetto deve essere una stringa
-- la chiave primaria della tabella è costituita da un solo campo
-- PARAMETRO MULTIPLO
-- ------------------------------------------------------------------------------------------------
--
