-- ------------------------------------------------------------------------------------------------
--                        Procedure GetOldNewValueCorrMerciSOL
--                      Parametro Multiplo Per Corridoi Merci SOL
-- ------------------------------------------------------------------------------------------------
--
  Procedure GetOldNewValueCorrMerciSOL( p_id_oggetto In Varchar2, p_cursor Out EMPCUR  )  Is
         sqlstring Varchar2(3000);
    BEGIN
         sqlstring := 'Select   distinct (AC1.CODICE_CORRIDOIO_633*10) new_value, ';
         sqlstring := sqlstring || '  old.value old_val ';
         sqlstring := sqlstring || ' From ';
         sqlstring := sqlstring || ' Rinf_Staging_Evo.PIC_CORRIDOIOMERCI_TRATTA l, ';
         sqlstring := sqlstring || ' Rinf_Staging_Evo.PIC_PERCORSIINFR t, ';
         sqlstring := sqlstring || ' Rinf_Anagrafiche_Evo.ANAG_CORRIDOI ac1, ';
         sqlstring := sqlstring || ' (Select SEDE_TECNICA,Listagg(CODICE_CORRIDOIO, '' '') Within Group (Order By CODICE_CORRIDOIO) value ';
         sqlstring := sqlstring || ' From ';
         sqlstring := sqlstring || ' (Select Distinct old.SEDE_TECNICA, ac2.CODICE_CORRIDOIO_633*10 codice_corridoio   ';
         sqlstring := sqlstring || ' From  ';
         sqlstring := sqlstring || ' Rinf_Anagrafiche_Evo.ANAG_CORRIDOI ac2 , ';
         sqlstring := sqlstring || ' Rinf_Controllati_Evo.CORRIDOIO_SOL old ';
         sqlstring := sqlstring || ' Where  ';
         sqlstring := sqlstring || ' ac2.CODICE_GIURISDIZIONE = old.CODICE_CORRIDOIO) ';
         sqlstring := sqlstring || ' Group By SEDE_TECNICA) old ';
         sqlstring := sqlstring || ' Where  ';
         sqlstring := sqlstring || ' l.CODICETRATTA = t.CODICETRATTA And  ';
         sqlstring := sqlstring || ' t.CODICETRATTAIR2K = Substr('''||p_id_oggetto||''', 1, 6) And ';
         sqlstring := sqlstring || ' ac1.CODICE_GIURISDIZIONE = l.CODICEGIURISDIZIONE And ';
         sqlstring := sqlstring || ' t.CODICETRATTAIR2K  = old.SEDE_TECNICA  (+) And ';
         sqlstring := sqlstring || ' Nvl(T.DATAINIZIOVALIDITA, To_Date(''01011999'', ''DDMMYYYY'')) <= Sysdate And ';
         sqlstring := sqlstring || ' Nvl(T.DATAFINEVALIDITA, To_Date(''01012999'',''DDMMYYYY'')) >= Sysdate ';
--		 
        Open p_cursor For sqlstring;
--
   End GetOldNewValueCorrMerciSOL;
--
-- ------------------------------------------------------------------------------------------------
--                           Procedure GetOldNewValueCorrMerciPO
--                        Parametro Multiplo Per Corridoi Merci PO
-- ------------------------------------------------------------------------------------------------
--
  Procedure GetOldNewValueCorrMerciPO(p_id_oggetto In Varchar2, p_cursor Out EMPCUR  )    Is
          sqlstring Varchar2(3000);
     BEGIN
-- 7/11/2016 modificata procedura per l'estrazione dei corridoi dei binari, per gestire correttamente i corridoi dei binari di fermata.

          sqlstring := 'Select Distinct (ac1.CODICE_CORRIDOIO_633*10) new_value, ';
          sqlstring := sqlstring || ' old.value old_val ';
          sqlstring := sqlstring || ' From  ';
          sqlstring := sqlstring || ' (Select CODICELOCALITAIR2K sede_tecnica, ';
          sqlstring := sqlstring || '           CODICEGIURISDIZIONE codice_corridoio ';
          sqlstring := sqlstring || '      From Rinf_Staging_Evo.PIC_CORRIDOIOMERCI_LOCALITA l, ';
          sqlstring := sqlstring || '           Rinf_Staging_Evo.PIC_LOCALITACIRCINFR t ';
          sqlstring := sqlstring || '     Where l.CODICELOCALITA = t.CODICELOCALITAPIC ';
          sqlstring := sqlstring || '       And NVL(T.DATAINIZIOVALIDITA, To_Date (''01011999'', ''DDMMYYYY'')) <= Sysdate ';
          sqlstring := sqlstring || '       And Nvl(T.DATAFINEVALIDITA, To_Date (''01012999'', ''DDMMYYYY'')) >= Sysdate) corr, ';
          sqlstring := sqlstring || ' Rinf_Anagrafiche_Evo.ANAG_CORRIDOI ac1,   ';
          sqlstring := sqlstring || ' Rinf_Lavorazione_Evo.REL_PO_BINARI_CORSA rel, ';
          sqlstring := sqlstring || ' (Select SEDE_TECNICA, Listagg(CODICE_CORRIDOIO,'' '') Within Group (Order By CODICE_CORRIDOIO) value  ';
          sqlstring := sqlstring || ' From ';
          sqlstring := sqlstring || ' (Select Distinct old.SEDE_TECNICA,AC2.CODICE_CORRIDOIO_633*10 codice_corridoio    ';
          sqlstring := sqlstring || ' From   ';
          sqlstring := sqlstring || ' Rinf_Anagrafiche_Evo.ANAG_CORRIDOI ac2, ';
          sqlstring := sqlstring || ' Rinf_Controllati_Evo.CORRIDOIO_PO old ';
          sqlstring := sqlstring || ' Where ';
          sqlstring := sqlstring || ' ac2.CODICE_GIURISDIZIONE = old.CODICE_CORRIDOIO) ';
          sqlstring := sqlstring || ' Group By SEDE_TECNICA) old                     ';
          sqlstring := sqlstring || ' Where    ';
          sqlstring := sqlstring || ' REL.PO_TRACK_1_2_1_0_0_2 like ''LO%'' And ';
          sqlstring := sqlstring || ' REL.PO_TRACK_1_2_1_0_0_2 = '''||p_id_oggetto||''' And ';
          sqlstring := sqlstring || ' corr.SEDE_TECNICA = rel.sede_tecnica And  ';
          sqlstring := sqlstring || ' ac1.CODICE_GIURISDIZIONE = corr.CODICE_CORRIDOIO And  ';
          sqlstring := sqlstring || ' CORR.SEDE_TECNICA  = old.SEDE_TECNICA (+) ';
          sqlstring := sqlstring || ' Union ';
          sqlstring := sqlstring || ' Select Distinct (ac1.CODICE_CORRIDOIO_633*10) new_value, ';
          sqlstring := sqlstring || ' old.value old_val                                          ';
          sqlstring := sqlstring || ' From    ';
          sqlstring := sqlstring || ' (Select CODICETRATTAIR2K sede_tecnica, ';
          sqlstring := sqlstring || '         CODICEGIURISDIZIONE codice_corridoio ';
          sqlstring := sqlstring || '    From Rinf_Staging_Evo.PIC_CORRIDOIOMERCI_TRATTA l, ';
          sqlstring := sqlstring || '         Rinf_Staging_Evo.PIC_PERCORSIINFR t ';
          sqlstring := sqlstring || '   Where l.CODICETRATTA = t.CODICETRATTA ';
          sqlstring := sqlstring || '     And Nvl(t.DATAINIZIOVALIDITA, To_Date (''01011999'', ''DDMMYYYY'')) <= Sysdate ';
          sqlstring := sqlstring || '     And Nvl(t.DATAFINEVALIDITA, To_Date (''01012999'', ''DDMMYYYY'')) >= Sysdate) corr, ';
          sqlstring := sqlstring || ' Rinf_Anagrafiche_Evo.ANAG_CORRIDOI ac1, ';
          sqlstring := sqlstring || ' Rinf_Lavorazione_EVO.BINARI_CORSA_SOL  bin, ';
          sqlstring := sqlstring || ' (Select SEDE_TECNICA, Listagg(CODICE_CORRIDOIO,'' '') Within Group (Order By CODICE_CORRIDOIO) value ';
          sqlstring := sqlstring || ' From ';
          sqlstring := sqlstring || ' (Select Distinct old.SEDE_TECNICA, ac2.CODICE_CORRIDOIO_633*10 codice_corridoio    ';
          sqlstring := sqlstring || ' From   ';
          sqlstring := sqlstring || ' Rinf_Anagrafiche_Evo.ANAG_CORRIDOI ac2 , ';
          sqlstring := sqlstring || ' Rinf_Controllati_Evo.CORRIDOIO_SOL old ';
          sqlstring := sqlstring || ' Where ';
          sqlstring := sqlstring || ' ac2.CODICE_GIURISDIZIONE = old.CODICE_CORRIDOIO) ';
          sqlstring := sqlstring || ' Group By SEDE_TECNICA) old ';
          sqlstring := sqlstring || ' Where  ';
          sqlstring := sqlstring || ' bin.SOL_TRACK_1_1_1_0_0_1 = '''||p_id_oggetto||''' And ';
          sqlstring := sqlstring || ' corr.SEDE_TECNICA = bin.SEDE_TECNICA And  ';
          sqlstring := sqlstring || ' ac1.CODICE_GIURISDIZIONE = corr.CODICE_CORRIDOIO And  ';
          sqlstring := sqlstring || ' CORR.SEDE_TECNICA  = old.SEDE_TECNICA (+) ';
--                     
          Dbms_Output.Put_Line(sqlstring);
          Open p_cursor For sqlstring;

   End GetOldNewValueCorrMerciPO;
--
-- ------------------------------------------------------------------------------------------------
--                             Procedure GetOldNewValueMultiploDICH
--  Questa procedura fornisce l'ultimo valore risultato corretto per il determinato parametro ed è valida sotto queste condizioni:
--  l'oggetto deve essere una stringa
--  la chiave primaria della tabella è costituita da un solo campo
--  PARAMETRO MULTIPLO DICHIARAZIONI
-- ------------------------------------------------------------------------------------------------
--
   Procedure GetOldNewValueMultiploDICH (p_tabella         In Varchar2, 
                                         p_campo_join      In Varchar2,
										 p_campo_valore    In Varchar2,
										 p_campo_valore_AP In Varchar2,
										 p_id_oggetto      In Varchar2, 
										 p_tipo_dich       In Varchar2, 
										 p_cursor         Out EMPCUR  )   Is
        sqlstring Varchar2(3000);
   BEGIN
        sqlstring :=  'Select new.'||p_campo_valore||' new_val, ';
        sqlstring := sqlstring || ' old.'||p_campo_valore||'  old_val, ';
