-- -------------------------------------------------------------------------------------------------------------
--                          PROCEDURE SetControlDetails (modifica del 21/01/2020)
--             serve a definire cosa e quali parametri scrivere nei dettagli controllati
-- -------------------------------------------------------------------------------------------------------------
--
   Procedure SetControlDetails ( p_controllo        In Number, 
                                 p_id_sol_op        In Varchar2,
								 p_id_sede_tecnica  In Varchar2,     
                                 p_codice_parametro In Number, 
								 p_definizione      In Varchar2, 
								 p_codice_esito     In Number, 
								 p_codice_controllo In Number,
                                 p_anomalia         In Varchar2, 
								 p_new_value        In Varchar2,
								 p_old_value        In Varchar2,
								 p_old_controllo    In Number,
								 p_nya              In Number )  Is
     err_num   Number;                      --* aggiunto
     err_msg   Varchar2(300);               --* aggiunto
   BEGIN
        Insert
        Into RINF_LAVORAZIONE_EVO.DETTAGLIO_CONTROLLATI 
		                        ( CODICE_CONTROLLO,
                                  CODICE_SOL_PO,
                                  SEDE_TECNICA,
                                  CODICE_PARAMETRO,
                                  DEFINIZIONE,
                                  CODICE_ESITO,
                                  CODICE_TIPO_CONTROLLO,
                                  ANOMALIA,
                                  VALUE_NEW,
                                  VALUE_OK,
                                  CODICE_CONTROLLO_OK,
                                  NYA )
                        Values (  p_controllo             ,
                                  p_id_sol_op             ,
                                  p_id_sede_tecnica       ,
                                  p_codice_parametro      ,
                                  p_definizione           ,
                                  p_codice_esito          ,
                                  p_codice_controllo      ,
                                  p_anomalia              ,
                                  Nvl(p_new_value,' ')    ,
                                  p_old_value             ,
                                  p_old_controllo         ,
                                  p_nya 
								);
-- * aggiunto l'Exception		
	EXCEPTION
         When OTHERS Then
             err_num := SQLCODE;
             err_msg := SUBSTR(SQLERRM, 1, 300);   
             dbms_output.put_line (err_msg);

        Insert
         Into RINF_LAVORAZIONE_EVO.DETTAGLIO_CONTROLLATI
                            (  CODICE_CONTROLLO,
                               CODICE_SOL_PO,
                               SEDE_TECNICA,
                               CODICE_PARAMETRO,
                               DEFINIZIONE,
                               CODICE_ESITO,
                               CODICE_TIPO_CONTROLLO,
                               ANOMALIA,
                               VALUE_NEW,
                               VALUE_OK,
                               CODICE_CONTROLLO_OK,
                               NYA  )
                      Values (p_controllo,
                              p_id_sol_op  ,
                              p_id_sede_tecnica ,
                              p_codice_parametro ,
                              err_msg,
                              err_num,
                              null,
                              'ERRORE: '||err_msg,
                              null,
                              null,
                              null,
                              null
							 );	
  End SetControlDetails;
