--
-- ------------------------------------------------------------------------------------------------
--                         Procedure SET_1_2_1_0_0_1
--                  1.2.1.0.0.1 Codice GI  -  OBBLIGATORIO - valore='0083' in Dominio_parametro
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_0_1 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);  -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                  -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;   
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.0.1');
--
      GetOldNewValue ('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_1', id_op_track, s_val_new_1, s_val_old_ok_1) ;
--
      NYA := GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
--
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
--
           SetControlDetails 
		        (   n_controllo,
                    id_op,
                    id_op_track,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 
					     Then 1
                         Else n_errore
                    End,
                    4,
                    Case
                       When n_errore = 0 Then GetCorrectRangeStringObbl (n_parametro)
                       Else Null
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                    End 	);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--                  in p_error 1 è errato (al contrario di n_errore)
                    p_error_split := 1;                        
           End If; 
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('SET_1_2_1_0_0_1 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_0_1;
--
-- ------------------------------------------------------------------------------------------------
--                         Procedure SET_1_2_1_0_1_1
--  1.2.1.0.1.1 - Dichiarazione CE di verifica del binario (INF) - FORMATO e APP  (parametro con tabella multipla a parte)
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_2_1_0_1_1 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)
     IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;                            -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
    BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--	  
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);   
 dbms_output.put_line ('n_controllo_old_ok_1: '|| n_controllo_old_ok_1); 
--
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
dbms_output.put_line ('d_definizione: '||d_definizione);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.1.1');
	  dbms_output.put_line ('n_parametro: '||n_parametro);
--
      NYA := GetNYA (n_parametro);
--
-- multiplo
      GetOldNewValueMultiploDICH ('DICHIARAZIONI_BINARIO_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_1_1O2',' PO_TRACK_1_2_1_0_1_1O2_AP', id_op_track, 'EC', valori_multipli) ;           
	  dbms_output.put_line ('s_val_new_1: '||s_val_new_1);
	  dbms_output.put_line ('s_val_old_ok_1: '||s_val_old_ok_1);

--
-- inizializzo l'errore per poterlo puoi valorizzare nel loop
      n_errore := 1;              
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
	  dbms_output.put_line ('s_val_new_1: '||s_val_new_1);
	  dbms_output.put_line ('s_val_old_ok_1: '||s_val_old_ok_1);
	  dbms_output.put_line ('s_val_new_AP: '||s_val_new_AP);

--
          If n_controllo_padre = 0 Then
--
                  If VALORI_MULTIPLI%Found Then  Loop
--
                        n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);
	  dbms_output.put_line ('n_ok_AP: '||n_ok_AP);	  
--
                        If n_ok_AP = 1 Then
                                If ((s_val_new_1 = ' ') Or (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)) Then
-- se mi fallisce un parametro multiplo, fallisce il controllo
                                     n_errore := Greatest(n_errore, 1);                      
                                Else n_errore := Least(n_errore, 0);
                                End If; 
                        Else n_errore := 0;
                        End If; 

	  dbms_output.put_line ('n_errore: '||n_errore);
                        SetControlDetails(
                            n_controllo,
                            id_op,
                            id_op_track,
                            n_parametro,
                            d_definizione,
                            Case When NYA = 1 
							     Then 1
                                 Else n_errore
                            End,
                            7,
                            Case When n_ok_AP = 0  And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                 When n_ok_AP = 0  And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                 When n_errore = 0 And s_val_new_1 <> ' '     Then s_commento_DICH_FORM_KO
                                 Else Null
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                            Case When n_errore = 0 And NYA = 0 Then 0
                                 When n_errore = 0 And NYA = 1 Then 1
                                 When n_errore = 1             Then 0
                            End );
	  dbms_output.put_line ('Inserita riga in Dettaglio_controllati');

                        Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;

                              Exit When VALORI_MULTIPLI%NOTFOUND;
	  dbms_output.put_line ('s_val_new_1: '||s_val_new_1);
	  dbms_output.put_line ('s_val_old_ok_1: '||s_val_old_ok_1);
	  dbms_output.put_line ('s_val_new_AP: '||s_val_new_AP);

                     End LOOP;
                  Else
-- se non ci sono le Dich, non ci sarà neanche l'AP associata, perchè è nella stessa tabella
                        n_errore := 0;                 

                        SetControlDetails(
                            n_controllo,
                            id_op,
                            id_op_track,
                            n_parametro,
                            d_definizione,
                            Case When NYA = 1 Then 1
                                 Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_CE|| 'binario sottosistema INF'
                                 Else Null
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                            Case When n_errore = 0 And NYA = 0 Then 0
                                 When n_errore = 0 And NYA = 1 Then 1
                                 When n_errore = 1  Then 0
                               End
							);
                   End If; 
--
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                  p_error_split := MOD(n_errore +1, 2);                               
	  dbms_output.put_line ('p_error_split 1: '||p_error_split);

--
            Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_track,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                         Else 0
                    End,
                    14,                                                                    --  fallito padre
                    GetMessFallitoPadreSingolo(142),-------------------------------------->''Scartamento nominale''  - 1.2.1.0.4.1 - OP
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                    End 
				 );
-- in p_error 1 è errato (al contrario di n_errore)
                    p_error_split := 1;  
	  dbms_output.put_line ('p_error_split 2: '||p_error_split);                      
           End If; 
       Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_1_1: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_1_1;
--
-- ------------------------------------------------------------------------------------------------
--                               Procedure SET_1_2_1_0_1_2  - FORMATO e APP  
-- 1.2.1.0.1.2 - Dichiarazione di dimostrazione IE del binario (INF) - parametro con tabella multipla a parte
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_1_2 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                      --stringa concatenata del dominio
      NYA                    Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);    
--
-- Recupero la definizione dell'oggetto 
      d_definizione := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.1.2');
--
      NYA := GetNYA (n_parametro);

      GetOldNewValueMultiploDICH('DICHIARAZIONI_BINARIO_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_1_1O2', 'PO_TRACK_1_2_1_0_1_1O2_AP', id_op_track, 'EI', valori_multipli) ;           --multiplo
--
-- inizializzo l'errore per poterlo puoi valorizzare nel loop
      n_errore := 1;             
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
--
           If n_controllo_padre = 0 Then
--
                If VALORI_MULTIPLI%FOUND Then   Loop
--
                        n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);
--                      
                         If n_ok_AP = 1  Then
                                If ((s_val_new_1 = ' ') Or (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)) Then
                                     n_errore := Greatest(n_errore, 1);           -- se mi fallisce un parametro multiplo, fallisce il controllo
                                Else n_errore := Least(n_errore, 0);
                                End If; 
                         Else n_errore := 0;
                         End If; 
--
                         SetControlDetails(
                                n_controllo,
                                id_op,
                                id_op_track,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                7,
                                Case When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                     When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                     When n_errore = 0 And s_val_new_1 <> ' '     Then s_commento_DICH_FORM_KO
                                     Else
                                          Null
                                End,
                                s_val_new_1,
                                s_val_old_ok_1,
                                n_controllo_old_ok_1,
                                Case When n_errore = 0 And NYA = 0 Then 0
                                     When n_errore = 0 And NYA = 1 Then 1
                                     When n_errore = 1             Then 0
                                End);
--
                        Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1,s_val_new_AP;
                           Exit When VALORI_MULTIPLI%NOTFOUND;
--
                  End Loop;

                Else
                     n_errore:=0;                 --se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella
--
                     SetControlDetails(
                            n_controllo,
                            id_op,
                            id_op_track,
                            n_parametro,
                            d_definizione,
                            Case When  NYA = 1 Then 1
                                 Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_IE|| 'binario sottosistema INF'
                                 Else Null
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                            Case When n_errore = 0 And NYA = 0 Then 0
                                 When n_errore = 0 And NYA = 1 Then 1
                                 When n_errore = 1             Then 0
                            End  );
                End If; 
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := MOD(n_errore +1, 2);                               

           Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_track,
                    n_parametro,
                    d_definizione,
                    Case When NYA=1 Then 1
                         When n_controllo_padre = 1 Then 1
                         Else 0
                    End,
                    14,                            -- fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case When n_controllo_padre = 1 Then 1
                         When NYA = 0               Then 0
                         When NYA = 1               Then 1
                    End  );
--
                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
--
       Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_1_2: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_1_2;
--
-- ------------------------------------------------------------------------------------------------
--                 PROCEDURE SET_1_2_1_0_2_1 
-- 1.2.1.0.2.1  TEN class binari - DOMINIO - parametro con tabella multipla a parte
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_2_1 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )  Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --  variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                    -- stringa concatenata del dominio
      NYA                    Number;                             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;                             -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      conta_multiplo         Number;
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);   
--
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.2.1');
--
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_2_1_0_2_1_CAT_TEN_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_2_1', id_op_track, valori_multipli) ;           --multiplo
--
--      Select COUNT(*) into conta_multiplo                                                                             --eliminato con mail Galli 16/11/2015
--      from RINF_LAVORAZIONE_EVO.PAR_1_2_1_0_2_1_CAT_TEN_PO
--      where PO_TRACK_1_2_1_0_0_2 = id_op_track;

      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

           If n_controllo_padre = 0 Then
--
-- Se esistono valori si esegue il controllo sul dominio
                If VALORI_MULTIPLI%FOUND Then      Loop

--                      If conta_multiplo >1 And s_val_new_1 = '40'                       -- questo blocco è stato inserito per segnalare l'errore che non posso avere un binario con linea TEN
--                      Then n_errore:=0;                                                 -- e contemporaneamente OFF TEN
--                      Else  n_errore := GetCorrectValue (n_parametro, s_val_new_1);     -- eliminato con mail Galli 16/11/2015
--                      End If; 
                     n_errore := GetCorrectValue (n_parametro, s_val_new_1);
--
                     SetControlDetails(
                            n_controllo,
                            id_op,
                            id_op_track,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 And s_val_new_1 Not In ('10', '20', '30', '40') Then    -->(funzione che interroga il db Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO)
							          GetCorrectRangeString (n_parametro)      -- LookUp Value
                                     --When n_errore = 0 And s_val_new_1 = '40' Then 'Il campo non può essere contemporaneamente '||GetValueFromCode (136, '40')||' ed appartenere alla rete TEN'       --eliminato con mail Galli 16/11/2015
                                 Else Null
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                            Case When n_errore = 0 And NYA = 0 Then 0
                                 When n_errore = 0 And NYA = 1 Then 1
                                 When n_errore = 1             Then 0
                            End );

                     Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                         Exit When VALORI_MULTIPLI%NOTFOUND;
                   End LOOP;
                Else
                     n_errore :=0;

                     SetControlDetails(
                            n_controllo,
                            id_op,
                            id_op_track,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then 
							          GetCorrectRangeString (n_parametro)              --LookUp Value
                                 Else Null
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                            Case When n_errore = 0 And NYA = 0 Then 0
                                 When n_errore = 0 And NYA = 1 Then 1
                                 When n_errore = 1             Then 0
                            End  );
                End If; 
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);                               
--
           Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_track,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1               Then 1
                         When n_controllo_padre = 1 Then 1
                         Else 0
                    End,
                    14,                 -- fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case When n_controllo_padre = 1 Then 1
                         When NYA = 0               Then 0
                         When NYA = 1               Then 1
                    End );
-- in p_error: 1 è errato (al contrario di n_errore)
                    p_error_split := 1;                       
           End If; 
--
       Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_2_1: '||Substr(Sqlerrm, 1, 250));

  End SET_1_2_1_0_2_1;
--
--
-- ------------------------------------------------------------------------------------------------
--                    PROCEDURE SET_1_2_1_0_2_2 
-- 1.2.1.0.2.2  Categoria Linea - DOMINIO + APPLICABILITA'  -  parametro con tabella multipla a parte
-- 21/05/2021 Modificata la gestione delle anomalie: se il parametro non è valorizzato, non viene indicata l'anomalia ma l'applicabilità è sempre [NYA]
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_1_0_2_2 (n_controllo       In Number,
                            id_op             In Varchar2,
                            id_op_track       In Varchar2,
                            id_dtp            In Varchar2,
                            n_controllo_padre In Number,
                            p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                               
      n_errore               Number;                               
      d_definizione          Varchar2 (1000);                      
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;                            -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);  
--dbms_output.put_line (' n_controllo_old_ok_1: '||n_controllo_old_ok_1);
--
-- Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--dbms_output.put_line ('d_definizione: '||d_definizione);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.2.2');
--dbms_output.put_line ('n_parametro: '||n_parametro);
--
      NYA := GetNYA (n_parametro);
--dbms_output.put_line ('il parametro può essere NYA: '||NYA);
--
      GetOldNewValueMultiplo('PAR_1_2_1_0_2_2_CAT_LINEA', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_2_2', id_op_track, valori_multipli) ;           -- multiplo
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_2_2_AP', id_op_track);
--dbms_output.put_line ('Applicabilità (s_val_new_AP): '||s_val_new_AP);

--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
--dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);

      If n_controllo_padre = 0 Then
--dbms_output.put_line ('n_controllo_padre = 0');
--
-- -------------------------
-->     loop
-- -------------------------

-- Se esistono valori si esegue il controllo sul dominio e sull'applicabilità
           If VALORI_MULTIPLI%FOUND Then   Loop

 /***
               n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

                If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then   
				      n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then  
				      n_ok_dominio := 1;
				Else 
				      n_ok_dominio := 0;
                End If; 
***/
                If s_val_new_1 Is Not Null  Then                         
                     n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
 --                    dbms_output.put_line ('n_ok_dominio (s_val_new_1 Is Not Null): '||n_ok_dominio);
		        Else                                                                            
			         n_ok_dominio := 1;
 --                    dbms_output.put_line ('n_ok_dominio (s_val_new_1 Is Null): '||n_ok_dominio);
                End If; 
--
                n_errore := n_ok_dominio;
                dbms_output.put_line ('n_errore: '||n_errore);
--
               SetControlDetails(
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     12,
                     Case --When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          --When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When (n_errore = 1 And s_val_new_1 Is Null)   Then 1                      -- aggiunto per valorizzare l'applicabilità con [NYA] ma non avere anomalia                          When n_errore = 1             Then 0
						  When n_errore = 1             Then 0
                     End );
--
                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
--dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);

                Exit When VALORI_MULTIPLI%NOTFOUND;
--
             End Loop;
-- -----------------------------------
--         Se non esistono valori 
-- -----------------------------------

           Else   
/***
                If (VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'N') Then --Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NOTFOUND And s_val_new_AP='Y' Then --Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP := 0;
                     n_ok_dominio := 0;
                End If; 
***/
                n_errore := 1;                ---> aggiunto
--
                SetControlDetails(
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     12,
                     Null,            --> eliminato il case per non avere anomalie
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     1 );            --> eliminato il case e assegnato [NYA]           
			End If; 

--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else  SetControlDetails (
                n_controllo,
                id_op,
                id_op_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             --fallito padre
                GetMessFallitoPadreSingolo(142),-------------------------------------------------->'Scartamento nominale''  OP
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_2_2: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_2_2;
--
-- ------------------------------------------------------------------------------------------------
--                  PROCEDURE SET_1_2_1_0_2_3 
-- 1.2.1.0.2.3  -  Corridoio Merci - APPLICABILITA'
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_2_3 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)      Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                      --stringa concatenata del dominio
      NYA                    Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
  BEGIN
 --
 --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--	  
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);    
--
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.2.3');
--
      NYA := GetNYA (n_parametro);

--    GetOldNewValueMultiplo('CORRIDOIO_PO', 'SEDE_TECNICA','CODICE_CORRIDOIO',id_op_track, valori_multipli) ;        -- multiplo
      GetOldNewValueCorrMerciPO(id_op_track,  valori_multipli);                                                       -- procedura ad hoc per le linee merci
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_2_3_AP', id_op_track);
--
--      Dbms_Output.Put_Line('Applicabilità 1: '|| s_val_new_AP);

-- IPOTESI: se PIC o chi per lui ci manda le associazioni allora appartiene a corridoi; se PIC non ce le manda, non appartiene a corridoi
       Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;           
--
 --     Dbms_Output.Put_Line('cursore 0: '|| s_val_new_1||' old: '||s_val_old_ok_1);
             If n_controllo_padre = 0 Then
--
-- Se esistono valori, ossia PIC o chi per lui ci manda associazioni della sede tecnica a corridoi, si esegue il controllo sull'applicabilità
                If VALORI_MULTIPLI%FOUND Then   Loop
                     n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

    --                       If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
    --                      Then   n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
    --                      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
    --                      Then  n_ok_dominio := 1;
    --                      End If; 
--             Dbms_Output.Put_Line(' coerenza appl 2:'||to_char(n_ok_AP));
                     n_errore:=n_ok_AP;

                     SetControlDetails (
                               n_controllo,
                               id_op,
                               id_op_track,
                               n_parametro,
                               d_definizione,
                               Case When NYA = 1 Then 1
                                    Else n_errore
                               End,
                               5,      --ex 12
                               Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                    When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                    Else Null
                               End,
                               s_val_new_1,
                               s_val_old_ok_1,
                               n_controllo_old_ok_1,
                               Case When n_errore = 0 And NYA = 0 Then 0
                                    When n_errore = 0 And NYA = 1 Then 1
                                    When n_errore = 1             Then 0
                               End );
--
                     Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                        Exit When VALORI_MULTIPLI%NOTFOUND;
--
                   End Loop;
--
                Else 
-- Se non esistono valori, ossia PIC o chi per lui non ci manda associazioni della sede tecnica a corridoi, vuol dire che non ha corridoio associato e il cursore va in NOTFOUND
-- e nel dettaglio verrà inserito un record con dato vuoto. Non si fa il controllo del caso in cui si avesse valorizzato il parametro 1.2.1.0.2.3 e AP=Y (si spera che questo caso non possa mai avvenire perchè la valorizzazione dell'applicabilità dovrebbe escluderlo)
-- Per ovviare a questo problema si inserisce questo ciclo (ridondante ma di sicurezza)
--                   DBMS_OUTPUT.PUT_LINE('not found 3');
                     If s_val_new_AP = 'N' Then                                -- se NOTFOUND e AP = N è tutto ok

                          n_errore := 1;
--                        DBMS_OUTPUT.PUT_LINE('not found app = n 4');
                          SetControlDetails(
                                    n_controllo,
                                    id_op,
                                    id_op_track,
                                    n_parametro,
                                    d_definizione,
                                    Case When NYA = 1 Then 1
                                         Else n_errore
                                    End,
                                    5,
                                    Null,           -- non si inserisce l'anomalia perchè è corretto che, se non trova associazione PIC o in chi per lui, viene considerato non appartenente a corridoi
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                    Case When n_errore = 0 And NYA = 0 Then 0
                                         When n_errore = 0 And NYA = 1 Then 1
                                         When n_errore = 1             Then 0
                                    End  );

                     Else 
-- se NOTFOUND e AP <> N non è tutto ok; a rigor di logica NON dovrebbe mai entrare in questo ciclo
--                         DBMS_OUTPUT.PUT_LINE(' not found app<>n 5');
                          n_errore := 0;
--
                          SetControlDetails(
                                    n_controllo,
                                    id_op,
                                    id_op_track,
                                    n_parametro,
                                    d_definizione,
                                    Case When  NYA=1 Then 1
                                    Else n_errore
                                    End,
                                    5,
                                    s_commento_AP_ok,       -- il commento dice che ci deve essere un errore nell'applicabilità, cioè sarà Y ma il valore è nullo, cosa sbagliata
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                    Case When n_errore = 0 And NYA  =0 Then 0
                                         When n_errore = 0 And NYA = 1 Then 1
                                         When n_errore = 1             Then 0
                                    End  );
                   End If; 

               End If; 
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                             
--
           Else  SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA=1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 --fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
-- in p_error 1 è errato (al contrario di n_errore)
                  p_error_split :=1;                        
           End If; 
--
          Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_2_3: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_2_3;
--
-- ------------------------------------------------------------------------------------------------
--                 PROCEDURE SET_1_2_1_0_3_1
--     1.2.1.0.3.1 - Scart interoperabile - DOMINIO + CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_3_1 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)      Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                          -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                          -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                 -- stringa concatenata del dominio
      NYA                    Number;                          -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                 -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);    
--
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.3.1');
--
      GetOldNewValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_1', id_op_track, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
--
      n_errore := GetCorrectValue (n_parametro, s_val_new_1);
--
      s_val_new_2:= GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2','PO_TRACK_1_2_1_0_3_2',id_op_track);
--
      s_val_new_3:= GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2','PO_TRACK_1_2_1_0_3_3',id_op_track);
--
           If n_controllo_padre = 0 Then

                n_errore := GetCorrectValue (n_parametro, s_val_new_1);

--              If n_errore = 1                                                                                                                --modificato da SAL 29/10/2015
--              Then
--                        If       (s_val_new_1 ='G1' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='GA' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='GB' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='GC' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'G2' And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'GB1' And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'GB2' And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'none' And s_val_new_3 = 'FS')
--                        Then n_errore := 1;
--                        Else  n_errore := 0;
--                        End If; 
--              End If; 

                SetControlDetails (
                          n_controllo,
                          id_op,
                          id_op_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          7,
                          Case When n_errore = 0 /*And nvl(s_val_new_1,0) not in ('G1','GA','GB','GC','none')*/ Then 
						            GetCorrectRangeString (n_parametro)                    --eliminato da SAL 29/10/2015
-- When n_errore = 0 Then 'Valorizzazione parametri Sagome non coerente: se questo parametro assume valore G1 o GA o GB o GC, la Sagoma Multinazionale e la Sagoma Nazionale devono essere Non Applicabili; se questo parametro assume valore Nessuna e la Sagoma Multinazionale assume valore G2 o GB1 o GB2, la Sagoma Nazionale deve essere Non Applicabile; se questo parametro e la Sagoma Multinazionale assumono valore Nessuna, la Sagoma Nazionale deve essere FS'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split:=MOD(n_errore +1, 2);                               
--  
           Else SetControlDetails (
                          n_controllo,
                          id_op,
                          id_op_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                                    -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End  );
-- in p_error 1 è errato (al contrario di n_errore)
                 p_error_split := 1;                        
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_3_1: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_3_1;
--
-- ------------------------------------------------------------------------------------------------
--                    PROCEDURE SET_1_2_1_0_3_2 
-- 1.2.1.0.3.2 Sagome multi - DOMINIO + CORRELAZIONE + APPLICABILITA'
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_1_0_3_2  (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                  -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
--Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);    
--
-- Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.3.2');
--
      GetOldNewValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_2', id_op_track, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
-- 1.2.1.0.3.1
      s_val_new_2 := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_1', id_op_track);
-- 1.2.1.0.3.3
      s_val_new_3 := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_3', id_op_track);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_2_AP', id_op_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then  
		        n_ok_dominio := 1;
		   Else
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If      (s_val_new_2 ='G1'   And s_val_new_1 is null    /*And s_val_new_3 is null*/)                                                 --modificato da SAL 29/10/2015
                         Or  (s_val_new_2 ='GA'   And s_val_new_1 is null    /*And s_val_new_3 is null*/)
                         Or  (s_val_new_2 ='GB'   And s_val_new_1 is null    /*And s_val_new_3 is null*/)
                         Or  (s_val_new_2 ='GC'   And s_val_new_1 is null    /*And s_val_new_3 is null*/)
                         Or  (s_val_new_2 ='none' And s_val_new_1 = 'G2'    /*And s_val_new_3 is null*/)
                         Or  (s_val_new_2 ='none' And s_val_new_1 = 'GB1'    /*And s_val_new_3 is null*/)
                         Or  (s_val_new_2 ='none' And s_val_new_1 = 'GB2'    /*And s_val_new_3 is null*/)
                         Or  (s_val_new_2 ='none' And s_val_new_1 = 'none'    /*And s_val_new_3 = 'FS'*/)
                      Then n_errore := 1;                                
                      Else n_errore := 0;
                     End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case When (n_ok_AP = 0 And s_val_new_AP = v_ko_AP) Then s_commento_AP_ko
                          When (n_ok_AP = 0 And s_val_new_AP = v_ok_AP) Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 Then 'Valorizzazione parametri Sagome non coerente: se '||GetParametro(139, 'Sagoma Interoperabile')||' assume valore G1 o GA o GB o GC, questo parametro e '||GetParametro(141, 'Sagoma Nazionale')||' devono essere Non Applicabili; se '||GetParametro(139, 'Sagoma Interoperabile')||' assume valore Nessuna e questo parametro assume valore G2 o GB1 o GB2, '||GetParametro(141,'Sagoma Interoperabile')||' deve essere Non Applicabile; se '||GetParametro(139,'Sagoma Interoperabile')||' e questo parametro assumono valore Nessuna, '||GetParametro(141,'Sagoma Nazionale')||' deve essere FS'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 --fallito padre
                     GetMessFallitoPadreSingolo(139),------------------------------------------------------------>''Sagoma interoperabile'' OP
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_3_2: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_3_2;
--
-- ------------------------------------------------------------------------------------------------
--                      PROCEDURE SET_1_2_1_0_3_3
-- 1.2.1.0.3.3-  Sagome naz - DOMINIO + CORRELAZIONE + APPLICABILITA'
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_1_0_3_3  (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                  -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    
--
-- Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.3.3');
--
      GetOldNewValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_3', id_op_track, s_val_new_1, s_val_old_ok_1);
-- 1.2.1.0.3.1
      s_val_new_2 := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_1', id_op_track);
-- 1.2.1.0.3.2
      s_val_new_3 := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_2', id_op_track);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_3_AP', id_op_track);
--
      NYA := GetNYA (n_parametro);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then

           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then
               n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then  
		       n_ok_dominio := 1;
		   Else
		       n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If   (s_val_new_2 ='G1'   And s_val_new_3 Is Null  And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='GA'   And s_val_new_3 Is Null  And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='GB'   And s_val_new_3 Is Null  And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='GC'   And s_val_new_3 Is Null  And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='none' And s_val_new_3 = 'G2'   And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='none' And s_val_new_3 = 'GB1'  And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='none' And s_val_new_3 = 'GB2'  And s_val_new_1 Is Null)
                       Or (s_val_new_2 ='none' And s_val_new_3 = 'none' And s_val_new_1 = 'FS')
                     Then n_errore := 1;
                     Else n_errore := 0;
                     End If; 
                Else  n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case When (n_ok_AP = 0 And s_val_new_AP = v_ko_AP) Then s_commento_AP_ko
                          When (n_ok_AP = 0 And s_val_new_AP = v_ok_AP) Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 Then 'Valorizzazione parametri Sagome non coerente: se '||GetParametro(139,'Sagoma Interoperabile')||' assume valore G1 o GA o GB o GC, '||GetParametro(140,'Sagoma Multinazionale')||' e questo parametro devono essere Non Applicabili; se '||GetParametro(139,'Sagoma Interoperabile')||' assume valore Nessuna e '||GetParametro(140,'Sagoma Multinazionale')||' assume valore G2 o GB1 o GB2, questo parametro deve essere Non Applicabile; se '||GetParametro(139,'Sagoma Interoperabile')||' e '||GetParametro(139,'Sagoma Multinazionale')||' assumono valore Nessuna, questo parametro deve essere FS'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                                 -- fallito padre
                     GetMessFallitoPadreSingolo(140),------------------------------------------------->'''Sagoma multinazionale'' OP
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- in p_error 1 è errato (al contrario di n_errore)
                       p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_3_3: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_3_3;
--
-- ------------------------------------------------------------------------------------------------
--                PROCEDURE SET_1_2_1_0_3_4  - Nuovo parametro dal Reg.777/2019 342-SUP e 343-INF)
--     1.2.1.0.3.4 Sagoma - SUP e INF (Controllo: Dominio) - Sempre Applicabile
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_1_0_3_4   (n_controllo       In Number,
                              id_op             In Varchar2,
                              id_op_track       In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number)
    Is
       n_parametro1           Number;
       n_parametro2           Number;
       s_val_new_1            Varchar2 (1000);
       s_val_new_2            Varchar2 (1000);
       s_val_new_3            Varchar2 (1000);
       s_val_old_ok_1         Varchar2 (1000);
       s_val_new_AP           Varchar2 (1000);
       n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
       n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
       n_controllo_old_ok     Number;
       n_errore               Number;
       n_errore1              Number;
       n_errore2              Number;
       d_definizione          Varchar2 (1000);
       s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
       NYA                    Number;                           -- ritorna se è NYA = 1 o 0
-- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
       s_val_old_ok_2         Varchar2 (1000); 
-- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
       VALORI_MULTIPLI        EMPCUR;       
	   binario_fittizio       varchar2(100);
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--
-- Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok := GetCorrectControlId(id_op);    
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
--
      n_parametro1 := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.3.4.SUP');
      n_parametro2 := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.3.4.INF');
--
      GetOldNewValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_4_SUP', id_op_track, s_val_new_1, s_val_old_ok_1);
      GetOldNewValue('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_4_INF', id_op_track, s_val_new_2, s_val_old_ok_2);

-- come riferimento uso SUP: se SUP è NYA, allora considero anche INF NYA
      NYA := GetNYA(n_parametro1);  
--	  
-- verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
      n_errore1 := GetCorrectValue(n_parametro1, s_val_new_1);
      n_errore2 := GetCorrectValue(n_parametro2, s_val_new_2);

      If (n_errore1 = 1 And n_errore2 = 1) Then
          n_errore := 1;
       Else
          n_errore := 0;
      End If;

--  Modifica del 19/07/2021 a seguito della segnalazione nella mail del 09/07/2021 di Piantedosi
      If n_errore = 0 Then
           Begin

/*** i binari Fittizzi sono i binari di tipo Link
            Select PO_SD_1_2_2_0_0_2 into binario_fittizio
             From 
	     	    ( Select PO_SD_1_2_2_0_0_2 
	     		    From Rinf_Controllati_Evo.BINARI_RACCORDO_PO
                   Where PO_SD_1_2_2_0_0_2 = id_op_track
	     		   Union 
	              Select PO_SD_1_2_2_0_0_2 
	     		    From Rinf_Controllati_Evo.BINARI_RACCORDO_PO
                   Where PO_SD_1_2_2_0_0_2 = id_op_track );
***/
        Select SOL_TRACK_1_1_1_0_0_1 into binario_fittizio
		  From 
		 (Select a.SOL_TRACK_1_1_1_0_0_1
 		    From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL a,
                 Rinf_Lavorazione_Evo.SEZIONI_LINEA b
           Where a.SEDE_TECNICA = b.SEDE_TECNICA
             And a.SOL_TRACK_1_1_1_0_0_1 = id_op_track
             And b.SOL_1_1_0_0_0_6 = 'L'
 		   Union 
          Select c.SOL_TRACK_1_1_1_0_0_1
 		    From Rinf_Controllati_Evo.BINARI_CORSA_SOL c,
                 Rinf_Controllati_Evo.SEZIONI_LINEA d
           Where c.SEDE_TECNICA = d.SEDE_TECNICA
             And c.SOL_TRACK_1_1_1_0_0_1 = id_op_track
             And d.SOL_1_1_0_0_0_6 = 'L'
           );

	       Exception 
              When NO_DATA_FOUND Then 
	     		binario_fittizio := Null;
	       End;
--
		   If binario_fittizio = id_op_track Then
		        n_errore1 := 1;
		        n_errore2 := 1;
           End If;
      End If;
--
      If n_controllo_padre = 0 Then
-- SUP
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro1,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore1
                     End,
                     4,
                     Case
                          When n_errore = 0 And n_errore1 = 0 And s_val_new_1 Is Null Then 'Sagoma Superiore: Valore mancante'
                          When n_errore = 0 And n_errore1 = 0 Then GetCorrectRangeString(n_parametro1)
                          When n_errore = 0 And n_errore2 = 0 And s_val_new_2 Is Null Then 'Sagoma Inferiore: Valore mancante'
                          When n_errore = 0 And n_errore2 = 0 Then GetCorrectRangeString(n_parametro2)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
-- INF
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_track,
                     n_parametro2,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore2
                     End,
                     4,
                     Case
                          When n_errore = 0 And n_errore2 = 0 And s_val_new_2 Is Null Then 'Valore mancante'
                          When n_errore = 0 And n_errore2 = 0 Then GetCorrectRangeString(n_parametro2)
                          Else Null
                     End,
                     s_val_new_2,
                     s_val_old_ok_2,
                     n_controllo_old_ok,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           n_errore := least (n_errore1, n_errore2);
           p_error_split := MOD(n_errore +1, 2);                               
--
          Else SetControlDetails (
                          n_controllo,
                          id_op,
                          id_op_track,
                          n_parametro1,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                 --fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
               SetControlDetails (
                          n_controllo,
                          id_op,
                          id_op_track,
                          n_parametro2,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                 --fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_2,
                          s_val_old_ok_2,
                          n_controllo_old_ok,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
-- in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('SET_1_2_1_0_3_4 - Errore:'||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_3_4;
--
--
-- ------------------------------------------------------------------------------------------------
--                 PROCEDURE SET_1_2_1_0_3_5_A (A=345, B=346) - NA Intera Rete
--  1.2.1.0.3.5 - ILL_GaugeCheckLoc - Localizzazione ferroviaria di punti particolari che richiedono verifiche specifiche
-- Localizzazione di punti particolari che richiedono verifiche specifiche a causa di deviazioni dalla sagoma di cui al punto 1.2.1.0.3.4
-- Stringa di caratteri predefinita: - [±NNNN.NNN] + [Stringa di caratteri]
-- il valore deve essere sempre [non applicabile].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_3_5_A (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_track       In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)      Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                          -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                          -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                 -- stringa concatenata del dominio
      NYA                    Number;                          -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                 -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    
dbms_output.put_line (' n_controllo_old_ok_1: '||n_controllo_old_ok_1);
--
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
dbms_output.put_line ('d_definizione: '||d_definizione);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.3.5.A');
dbms_output.put_line ('n_parametro: '||n_parametro);
--
      GetOldNewValue ('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_3_5_A', id_op_track, s_val_new_1, s_val_old_ok_1);
dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
dbms_output.put_line ('il parametro può essere NYA: '||NYA);
--
