      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.3.2');

--    legge il valore attuale e precedente dalla tabella PAR_1_2_3_2_DOC_NORME degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValueMultiplo('PAR_1_2_3_2_DOC_NORME', 'SEDE_TECNICA', 'PO_1_2_3_2', id_op, valori_multipli); -- multiplo
--
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);

--    estrae il valore del parametro: 1.2.3.1_Esistenza di norme e restrizioni di natura strettamente locale (S/N)
      s_val_new_2 := GetParameterValue('PUNTI_OPERATIVI', 'SEDE_TECNICA', 'PO_1_2_3_1', id_op);
--
      s_val_new_AP := GetParameterValue ('PUNTI_OPERATIVI', 'SEDE_TECNICA', 'PO_1_2_3_2_AP', id_op);
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

      If n_controllo_padre = 0 Then
--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
--> loop
           Loop
--              verifica se la correlazione Valore = Not Null - AP = Y o AP = N - Valore = Null è corretta (=1) altrimenti=0
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);               

                If ((n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Or (n_ok_AP = 1 And s_val_new_AP = v_ko_AP)) Then
                     n_ok_dominio := 1;
		        Else 
                     n_ok_dominio := 0;
                End If; 
--              
                If n_ok_AP = 1  Then
                     If n_ok_dominio = 1 Then
                          If  (s_val_new_2 = 'Y' And s_val_new_1 Is Null ) Or (Nvl(s_val_new_2, 'N') <> 'Y' And s_val_new_1 Is Not Null )
                               Or (s_val_new_2 Is Null And s_val_new_1 Is Not Null) Then
                               n_errore := 0;
                          Else n_errore := 1;
                          End If; 
                     Else
                          n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
--
                SetControlDetails (
                          n_controllo,
                          id_op,
                          id_op,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
	                           Then 1
                               Else n_errore
                          End,
                          4,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                               When n_errore = 0 And s_val_new_2 = 'Y' And s_val_new_1 Is Null Then 'Se '||GetParametro(354, 'norme e restrizioni')||' è '||GetValueFromCode (354, 'Y')||', il parametro deve essere valorizzato'
                               When n_errore = 0 And Nvl(s_val_new_2, 'N') <> 'Y' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(354, 'Norme e Restrizioni')||' è diverso da '||GetValueFromCode (354, 'Y')||', il parametro non deve essere valorizzato'
                               When n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null Then 'Se '||GetParametro(354, 'Norme e Restrizioni')||' è non applicabile, il parametro non deve essere valorizzato'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
-->             
                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                Exit When VALORI_MULTIPLI%NotFound;
--> end loop 		 
             End Loop;
--			  
--         Se NO DATA FOUND
           Else 
                If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then          -- Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then      -- Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If; 
                     SetControlDetails
					  (   n_controllo,
                          id_op,
                          id_op,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          12,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP 
						       Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1  Then 0
                          End	  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(354),--------------------------------------------------------------->''Esistenza di Norme e Restrizioni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_2_3_2_MULT - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_2_3_2_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                     PROCEDURE SetControlOPTrack
-- procedura per il controllo dei parametri di PO TRACK (Binari di Circolazione dei Punti Operativi)
-- ------------------------------------------------------------------------------------------------
--
 Procedure SetControlOPTrack(n_controllo    In     Number,    
                             id_op          In     Varchar2,
                             id_op_track    In     Varchar2,
                             id_dtp         In     Varchar2,
                             p_error       Out     Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                        -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                        -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);               -- stringa concatenata del dominio
      NYA                    Number;
      VALORI_MULTIPLI        EMPCUR;                        -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO         Number;                        -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      p_error_split          Number;                        -- serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)
      p_error_1_2_1_0_4_1    Number;
      p_error_1_2_1_0_3_1    Number;
      p_error_1_2_1_0_3_2    Number;
  BEGIN
      p_error := 0;
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);    
--
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_PO', 'PO_TRACK_1_2_1_0_0_2', 'PO_TRACK_1_2_1_0_0_2_D', id_op_track);     
dbms_output.put_line ('d_definizione : '||d_definizione );

--    1.2.1.0.4.1 scartamento nominale = 1435 mm        N.B.  !!!!Spostato all'inizio perchè da questo dipEndono altri parametri a lui precedenti
      SET_1_2_1_0_4_1 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);       
	  p_error_1_2_1_0_4_1 := p_error_split;
dbms_output.put_line ('SET_1_2_1_0_4_1: '||p_error_split);
--
--    1.2.1.0.0.1 Codice GI - OBBLIGATORIO ('0083')
      SET_1_2_1_0_0_1 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_0_1: '||p_error_split);
--
--    1.2.1.0.0.2 ID OP Track  - OBBLIGATORIO
--
--    1.2.1.0.1.1  Dichiarazione INF EC - CORRELAZIONE  -  parametro con tabella multipla a parte
      SET_1_2_1_0_1_1 (n_controllo,  id_op, id_op_track, id_dtp, p_error_1_2_1_0_4_1, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_1_1: '||p_error_split);

--
--    1.2.1.0.1.2  Dichiarazione INF EI - CORRELAZIONE     parametro con tabella multipla a parte
      SET_1_2_1_0_1_2 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_1_2: '||p_error_split);

--
--    1.2.1.0.2.1  TEN class binari DOMINIO               parametro con tabella multipla a parte
      SET_1_2_1_0_2_1 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_2_1: '||p_error_split);

--
--    1.2.1.0.2.2  Categoria Linea DOMINIO + APPLICABILITA'                   parametro con tabella multipla a parte
      SET_1_2_1_0_2_2 (n_controllo,  id_op, id_op_track, id_dtp, p_error_1_2_1_0_4_1, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_2_2: '|| p_error_split);
--
--    1.2.1.0.2.3 Corridoio Merci APPLICABILITA'
      SET_1_2_1_0_2_3 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_2_3: '|| p_error_split);

--
--    1.2.1.0.3.1 Scart interoperabile DOMINIO + CORRELAZIONE
      SET_1_2_1_0_3_1 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);       
	  p_error_1_2_1_0_3_1 := p_error_split;
dbms_output.put_line ('SET_1_2_1_0_3_1: '|| p_error_split);

--
--    1.2.1.0.3.2 Sagome multi DOMINIO + CORRELAZIONE + APPLICABILITA'
      SET_1_2_1_0_3_2 (n_controllo,  id_op, id_op_track, id_dtp, p_error_1_2_1_0_3_1, p_error_split);     
	  p_error_1_2_1_0_3_2 := p_error_split;
dbms_output.put_line ('SET_1_2_1_0_3_2: '||p_error_split);

--
--    1.2.1.0.3.3 Sagome naz DOMINIO + CORRELAZIONE + APPLICABILITA'
      SET_1_2_1_0_3_3 (n_controllo,  id_op, id_op_track, id_dtp, p_error_1_2_1_0_3_2, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_3_3: '||p_error_split);

--
--    1.2.1.0.3.4 Sagoma DOMINIO + CORRELAZIONE + APPLICABILITA'
      SET_1_2_1_0_3_4 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_3_4: '||p_error_split);

--
--    1.2.1.0.3.5.A - NA Intera Rete
      SET_1_2_1_0_3_5_A (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_3_5_A: '||p_error_split);

--
--    1.2.1.0.3.5.B - NA Intera Rete
      SET_1_2_1_0_3_5_B (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_3_5_B: '||p_error_split);

--
--    1.2.1.0.3.6 - NA Intera Rete
      SET_1_2_1_0_3_6 (n_controllo,  id_op, id_op_track, id_dtp, 0, p_error_split);
dbms_output.put_line ('SET_1_2_1_0_3_6: '||p_error_split);

--
--    N.B. !!!!!! 1.2.1.0.4.1 scartamento = 1435 mm spostato all'inizio perchè da lui dipEndono altri parametri precedenti  !!!!!!!!
  EXCEPTION
      When OTHERS   Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SetControlOPTrack: '||Substr(Sqlerrm, 1, 250));
  End SetControlOPTrack;
--
-- ------------------------------------------------------------------------------------------------
--               PROCEDURE SET_1_2_2_0_0_1
-- 1.2.2.0.0.1 Codice GI  - OBBLIGATORIO - '0083'
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_2_0_0_1  (n_controllo      In Number,
                             id_op             In Varchar2,
                             id_op_siding      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                               
      n_errore               Number;                               
      d_definizione          Varchar2 (1000);                      
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;                            -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE

       BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);  
--	  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.0.1');
--
      GetOldNewValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_1', id_op_siding, s_val_new_1, s_val_old_ok_1) ;
--
      NYA := GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);

           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                         Else n_errore
                     End,
                     4,
                     Case When n_errore = 0 Then GetCorrectRangeStringObbl (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );

           p_error_split := Mod(n_errore +1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 --fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End );
-- in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_0_1: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_2_0_0_1;
--
-- ------------------------------------------------------------------------------------------------
--                   PROCEDURE SET_1_2_2_0_0_3
-- 1.2.2.0.0.3  TEN class siding - DOMINIO  - parametro con tabella multipla a parte
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_2_0_0_3 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_siding      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                              
      n_errore               Number;                              
      d_definizione          Varchar2 (1000);                     
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                  -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;                           -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      conta_multiplo         Number;
  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE  
      p_error_split := 0;  
--	  
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op); 
--	  
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.0.3');
--
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_2_2_0_0_3_CAT_TEN_SD', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_3', id_op_siding, valori_multipli) ;           --multiplo
--
--      Select COUNT(*) into conta_multiplo                                                            --eliminato mail Galli 16/11/2015
--      from RINF_LAVORAZIONE_EVO.PAR_1_2_2_0_0_3_CAT_TEN_SD
--      where PO_SD_1_2_2_0_0_2 = id_op_siding;
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

      If n_controllo_padre = 0 Then
--
--Se esistono valori si esegue il controllo sul dominio
           If VALORI_MULTIPLI%FOUND Then   Loop

--              If conta_multiplo >1 And s_val_new_1 = '40'                       --questo blocco è stato inserito per segnalare l'errore che non posso avere un binario con linea TEN
--                          Then n_errore:=0;                                                             --e contemporaneamente OFF TEN
--                          Else  n_errore := GetCorrectValue (n_parametro, s_val_new_1);           --eliminato mail Galli 16/11/2015
--                          End If; 

                n_errore := GetCorrectValue (n_parametro, s_val_new_1);

                SetControlDetails(
                          n_controllo,
                          id_op,
                          id_op_siding,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          4,
                          Case When n_errore = 0 And s_val_new_1 Not In ('10', '20', '30', '40') Then GetCorrectRangeString (n_parametro)      -- LookUp Value
                                  --When n_errore = 0 And s_val_new_1 = '40' Then 'Il campo non può essere contemporaneamente '||GetValueFromCode (167, '40')||' ed appartenere alla rete TEN'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End );
--
                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                 Exit When VALORI_MULTIPLI%NOTFOUND;

              End Loop;
           Else
                n_errore := 0;

                SetControlDetails(
                           n_controllo,
                           id_op,
                           id_op_siding,
                           n_parametro,
                           d_definizione,
                           Case When NYA = 1 Then 1
                                Else n_errore
                           End,
                           4,
                           Case When n_errore = 0 Then GetCorrectRangeString (n_parametro)              --LookUp Value
                                Else Null
                           End,
                           s_val_new_1,
                           s_val_old_ok_1,
                           n_controllo_old_ok_1,
                           Case When n_errore = 0 And NYA = 0 Then 0
                                When n_errore = 0 And NYA = 1 Then 1
                                When n_errore = 1             Then 0
                           End );
           End If; 
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End );
-- in p_error 1 è errato (al contrario di n_errore)
                       p_error_split :=1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_0_3: '||Substr(Sqlerrm, 1, 250));
