--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.2.1');
--
      GetOldNewValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_2_1', id_op_siding, s_val_new_1, s_val_old_ok_1) ;
--
      NYA:= GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
           If s_val_new_1 Is Null Then 
		        n_errore := 0;
           Else
                If s_val_new_1 >9999 Then 
				     n_errore := 0;
                Else n_errore := 1;
                End If; 
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     1,
                     Case When n_errore = 0 And s_val_new_1 > 9999 Then  'La lunghezza del parametro risulta essere maggiore di 4 cifre'
                          When n_errore = 0 And s_val_new_1 Is Null Then  'Il parametro è obbligatorio'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
