-- ---------------------------------------------------------------------------------------------------------------------------
--                 PROCEDURE SET_1_2_2_0_3_1 - Pendenza per i binari di ricovero (Tracciato della Linea - NCP [NN.N]
-- 1.2.2.0.3.1 Pend.max bin.serv. (12)-DOMINIO NEL RANGE e AP
--  versione di cert/prod con l'aggiunta dell'EXCEPTION per completare i controlli sui parametri successivi, in caso di errore
-- ---------------------------------------------------------------------------------------------------------------------------
--
   Procedure SET_1_2_2_0_3_1  (n_controllo       In     Number,
                               id_op             In     Varchar2,
                               id_op_siding      In     Varchar2,
                               id_dtp            In     Varchar2,
                               n_controllo_padre In     Number,
                               p_error_split    Out     Number  )   Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_new_3              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;              -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;              -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);     -- stringa concatenata del dominio
      NYA                      Number;              -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000);     -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI          EMPCUR;              -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      l_lungh                  Number;
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);   
--
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.3.1');
--
      GetOldNewValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_3_1', id_op_siding, s_val_new_1, s_val_old_ok_1) ;
--
      NYA:= GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_3_1_AP', id_op_siding);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
--         17/05/2016 aggiunto controllo sul range
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP  Then                         
                n_ok_dominio := GetCorrectRange (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
		   Else
				n_ok_dominio := 0;
           End If; 

           n_errore := n_ok_dominio;

--         scrittura nella tabella RINF_LAVORAZIONE_EVO.DETTAGLIO_CONTROLLATI

           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     12,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                        --When n_errore = 0 And s_val_new_AP='Y' And s_val_new_1>9.9 Then 'Sono ammessi solo valori maggiori di 2,5 e minori di 9,9' --fittizio se INE fa già i controlli di formato
                        --When n_errore = 0 And s_val_new_AP='Y' Then 'Sono ammessi solo valori maggiori di 2,5, altrimenti non applicabile'
                          When n_ok_dominio= 0 Then GetMessFuoriRange(171) --||' altrimenti non applicabile'
                        --When n_ok_dominio= 0 And s_val_new_AP='N' Then 'Sono ammessi solo valori maggiori di 2,5, altrimenti non applicabile'
                          Else NULL
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--        siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);                              

      Else  SetControlDetails (
                   n_controllo,
                   id_op,
                   id_op_siding,
                   n_parametro,
                   d_definizione,
                   Case When  NYA=1 Then 1
                           When n_controllo_padre = 1 Then 1
                   Else 0
                   End,
                   14,                 --fallito padre
                   MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                   s_val_new_1,
                   s_val_old_ok_1,
                   n_controllo_old_ok_1,
                   Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                   End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_3_1: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_2_0_3_1;
