--
-- ------------------------------------------------------------------------------------------------
--                     PROCEDURE SET_1_2_2_0_3_2 (172)  - Modificato dal Reg.777/2019 - NCT  
--     1.2.2.0.3.2 - ILL_MinRadHorzCurve - Raggio minimo di curvatura orizzontale - (12-DOMINIO NEL RANGE e AP)
-- Il parametro deve essere valorizzato se il raggio di curvatura orizzontale è minore di 150 m: sempre N.A.
-- Per RFI il parametro è sempre non applicabile
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_2_0_3_2 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_siding      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
--    CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      VALORI_MULTIPLI        EMPCUR;       
      l_lungh                Number;
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.3.2');
--
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_RACCORDO_PO
      GetOldNewValue ('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_3_2', id_op_siding, s_val_new_1, s_val_old_ok_1);
--	  
--      n_errore := GetCorrectRange (n_parametro, s_val_new_1);
--
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--
--    acquisisce il valore dell'Applicabilità associata al parametro
--      s_val_new_AP := GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_3_2_AP', id_op_siding);
--
--    verifica la coerenza della coppia di dati AP/valore parametro e NAP/nullo: 1:ok - 0:KO
--      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

      If n_controllo_padre = 0 Then

           If Nvl(s_val_new_1, 0) = 999  Then 
		        n_errore := 1;
		   Else  
		        n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     12,
                     Case
                          When Nvl(s_val_new_1, 0) <> 999  Then 'Il parametro 1.2.2.0.3.2 - Raggio minimo di curvatura orizzontale - è sempre Non Applicabile'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                              
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0               Then 0
                          When NYA = 1               Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line   ('SET_1_2_2_0_3_2 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_2_0_3_2;
--
-- ------------------------------------------------------------------------------------------------
--                PROCEDURE SET_1_2_2_0_3_3_A  - Modificata dal Reg.777/2019 (173 e 174)
-- 1.2.2.0.3.3 TOTALE - ILL_MinRadVertCurve - Raggio minimo di Curvatura vertivale - concava A + convessa B - 
-- (CORRELAZIONE) AP - [NNN+NNN] Raggio della curva verticale più piccola, espresso in metri.
-- Questo parametro è applicabile se il valore del raggio verticale è inferiore ai limiti previsti nelle STI INF, di sotto riportati.
-- Per RFI il parametro è sempre non applicabile.
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_2_0_3_3_A (n_controllo      In Number,
                             id_op             In Varchar2,
                             id_op_siding      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
--    CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      VALORI_MULTIPLI        EMPCUR;       
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.3.3.A');
--
      GetOldNewValue ('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_3_3_A', id_op_siding, s_val_new_1, s_val_old_ok_1);
--
--    come riferimento uso A: se A è NYA, allora considero anche B NYA
      NYA := GetNYA (n_parametro);        
--
      If n_controllo_padre = 0 Then
--
           If  Nvl(s_val_new_1, 0) = 999  Then 
                n_errore := 1;
           Else 
		        n_errore := 0;
           End If; 
 --
           SetControlDetails(
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     12,
                     Case
                         When Nvl(s_val_new_1, 0) <> 999  Then 'Il parametro 1.2.2.0.3.3 - Raggio minimo di curvatura verticale - (concava e convessa) è sempre Non Applicabile'
                         Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 --fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line   ('SET_1_2_2_0_3_3_A - Errore: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_2_0_3_3_A;
--
-- ------------------------------------------------------------------------------------------------
--                PROCEDURE SET_1_2_2_0_3_3_B  - Modificata dal Reg.777/2019 (173 e 174)
-- 1.2.2.0.3.3 TOTALE - ILL_MinRadVertCurve - Raggio minimo di Curvatura vertivale - concava A + convessa B - 
-- (CORRELAZIONE) AP - [NNN+NNN] Raggio della curva verticale più piccola, espresso in metri.
-- Questo parametro è applicabile se il valore del raggio verticale è inferiore ai limiti previsti nelle STI INF, di sotto riportati.
-- Per RFI il parametro è sempre non applicabile.
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_2_0_3_3_B (n_controllo      In Number,
                             id_op             In Varchar2,
                             id_op_siding      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
--    CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      VALORI_MULTIPLI        EMPCUR;       
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.3.3.B');
--
      GetOldNewValue ('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_3_3_B', id_op_siding, s_val_new_1, s_val_old_ok_1);
--
--    come riferimento uso A: se A è NYA, allora considero anche B NYA
      NYA := GetNYA (n_parametro);        
--
      If n_controllo_padre = 0 Then
--
           If Nvl(s_val_new_1, 0) = 999 Then 
			     n_errore := 1;
           Else 
			     n_errore := 0;
           End If; 
--
           SetControlDetails(
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     12,
                     Case
                         When Nvl(s_val_new_1, 0) <> 999  Then 'Il parametro 1.2.2.0.3.3 - Raggio minimo di curvatura verticale - (concava e convessa) è sempre Non Applicabile'
                         Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                     End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_siding,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 --fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line   ('SET_1_2_2_0_3_3_B - Errore:'||Substr(Sqlerrm, 1, 250));
   End SET_1_2_2_0_3_3_B;

