      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      l_lungh Number;

       BEGIN
       -- 1.2.2.0.4.5 Imp.riforn.sabbia DOMINIO deve contenere solo N

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2','PO_SD_1_2_2_0_0_2_D',id_op_siding);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.4.5');

      GetOldNewValue('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2','PO_SD_1_2_2_0_4_5',id_op_siding, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

          If n_controllo_padre = 0 Then

          n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);                   --inutile perchè ammesso solo N

              If n_ok_dominio = 1
              Then
                  If nvl(s_val_new_1,0) <> 'N'
                  Then n_errore := 0;
                  Else n_errore := 1;
                  End If; 
              Else n_errore:=0;
              End If; 

          SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_siding,
                    n_parametro,
                    d_definizione,
                     Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    4,
                    Case
                       When n_ok_dominio = 0 Then 'Il parametro deve essere valorizzato ed ammette solamente '||GetValueFromCode (n_parametro, 'N')     --commento non generalizzabile perchè ammette sono un valore non una stringa
                       When n_errore = 0 And nvl(s_val_new_1,0) <> 'N' Then 'Il parametro deve essere valorizzato ed ammette solamente '||GetValueFromCode (n_parametro, 'N')--commento non generalizzabile perchè ammette sono un valore non una stringa
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                         When n_errore = 0 And NYA=0 Then 0
                         When n_errore = 0 And NYA=1 Then 1
                         When n_errore = 1  Then 0
                     End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_siding,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_4_5: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_2_0_4_5;
