   PROCEDURE SetControlOPSiding (n_controllo    IN     Number,    --procedura per il controllo dei parametri di PO SIDING
                                 id_op         IN     Varchar2,
                                 id_op_siding   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 p_error           OUT Number)
   IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_code_new_1   Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_code_new_2    Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      s_valore_A Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      s_valore_B Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      s_valore_C Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      m_min Number;                                 --variabile di appoggio per il commento
      m_max Number;                                 --variabile di appoggio per il commento
      NYA Number;
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;       --serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      l_lungh                Number;
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      s_val_old_ok_2         Varchar2 (1000);
      p_error_split Number;                 --serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)

   BEGIN
      p_error := 0;

      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    --Recupero il codice del controllo del dato pubblicato

      d_definizione := GetParameterValue ('BINARI_RACCORDO_PO', 'PO_SD_1_2_2_0_0_2', 'PO_SD_1_2_2_0_0_2_D', id_op_siding);     --Recupero la definizione dell'oggetto

      -- 1.2.2.0.0.1 Codice GI                        OBBLIGATORIO
      SET_1_2_2_0_0_1 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.0.2 ID OP Siding                      OBBLIGATORIO

      -- 1.2.2.0.0.3  TEN class siding DOMINIO               parametro con tabella multipla a parte
      SET_1_2_2_0_0_3 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.1.1  Dichiarazione SD EC CORRELAZIONE                            parametro con tabella multipla a parte
      SET_1_2_2_0_1_1 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.1.2  Dichiarazione SD EI CORRELAZIONE                            parametro con tabella multipla a parte
      SET_1_2_2_0_1_2 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.2.1 Lunghezza SD - lungh paramatro e diverso da nullo
      SET_1_2_2_0_2_1 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.3.1 PEnd.max bin.serv. DOMINIO NEL RANGE e AP
      SET_1_2_2_0_3_1 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.3.2 R.min.curv.oriz. DOMINIO NEL RANGE e AP
      SET_1_2_2_0_3_2 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.3.3 TOTALE  Curva vert.concava A + convessa B (CORRELAZIONE) AP
      SET_1_2_2_0_3_3_A (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);
      SET_1_2_2_0_3_3_B (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.4.1 Scarichi igienici DOMINIO deve contenere solo N
      SET_1_2_2_0_4_1 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.4.2 Imp.pulizia est. DOMINIO Y/N
      SET_1_2_2_0_4_2 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.4.3 IImp.riforn.idrico DOMINIO Y/N
      SET_1_2_2_0_4_3 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.4.4 Riappr.carburante DOMINIO Y/N
      SET_1_2_2_0_4_4 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.4.5 Imp.riforn.sabbia DOMINIO deve contenere solo N
      SET_1_2_2_0_4_5 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.4.6 Alim.elettr.terra DOMINIO Y/N
      SET_1_2_2_0_4_6 (n_controllo,  id_op, id_op_siding,   id_dtp, 0, p_error_split);

      -- 1.2.2.0.6.1 - Corrente massima a treno fermo per pantografo 
      SET_1_2_2_0_6_1 (n_controllo, id_op, id_op_siding, id_dtp, 0, p_error_split);


  EXCEPTION
      When OTHERS
      Then
         p_error := SQLCODE;
         DBMS_OUTPUT.PUT_LINE   ('Errore '||SUBSTR(SQLERRM, 1, 250));
   End SetControlOPSiding;
