PROCEDURE SET_1_2_1_0_6_3 (n_controllo    IN     Number,
                                 id_op         IN     Varchar2,
                                 id_op_platform   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      conta_multiplo Number;

       BEGIN
       -- 1.2.1.0.6.3  TEN class marciapiede DOMINIO               parametro con tabella multipla a parte

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('MARCIAPIEDI_BINARI_PO', 'PO_TR_PLATFORM_1_2_1_0_6_2','PO_TR_PLATFORM_1_2_1_0_6_2_D',id_op_platform);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.6.3');

      NYA:= GetNYA (n_parametro);

      GetOldNewValueMultiplo('PAR_1_2_1_0_6_3_CAT_TEN_PL', 'PO_TR_PLATFORM_1_2_1_0_6_2','PO_TR_PLATFORM_1_2_1_0_6_3',id_op_platform, valori_multipli) ;           --multiplo

--      Select COUNT(*) into conta_multiplo                                                                 --eliminato con mail Galli 16/11/2015
--      from RINF_LAVORAZIONE_EVO.PAR_1_2_1_0_6_3_CAT_TEN_PL
--      where PO_TR_PLATFORM_1_2_1_0_6_2 = id_op_platform;

      FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1;

          If n_controllo_padre = 0 Then

             If VALORI_MULTIPLI%FOUND Then --Se esistono valori si esegue il controllo sul dominio
                  LOOP

--                   If conta_multiplo >1 And s_val_new_1 = '40'                       --questo blocco è stato inserito per segnalare l'errore che non posso avere un binario con linea TEN
--                      Then n_errore:=0;                                                             --e contemporaneamente OFF TEN
--                      Else  n_errore := GetCorrectValue (n_parametro, s_val_new_1);               --eliminato con mail Galli 16/11/2015
--                      End If; 
                n_errore := GetCorrectValue (n_parametro, s_val_new_1);

                    SetControlDetails(
                                n_controllo,
                                id_op,
                                id_op_platform,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                4,
                                Case When n_errore = 0 And s_val_new_1 not in ('10', '20', '30', '40') Then GetCorrectRangeString (n_parametro)      --LookUp Value
                                         --When n_errore = 0 And s_val_new_1 = '40' Then 'Il campo non può essere contemporaneamente '||GetValueFromCode (157, '40')||' ed appartenere alla rete TEN'
                                Else NULL
                                End,
                                s_val_new_1,
                                s_val_old_ok_1,
                                n_controllo_old_ok_1,
                                      Case
