      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      l_lungh Number;

       BEGIN
       -- 1.2.1.0.6.7 Campo utilizzo dispositivo ausilio accesso LUNGHEZZA (e AP fittizia perchè non esistente)

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('MARCIAPIEDI_BINARI_PO', 'PO_TR_PLATFORM_1_2_1_0_6_2','PO_TR_PLATFORM_1_2_1_0_6_2_D',id_op_platform);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.6.7');

      GetOldNewValue('MARCIAPIEDI_BINARI_PO', 'PO_TR_PLATFORM_1_2_1_0_6_2','PO_TR_PLATFORM_1_2_1_0_6_7',id_op_platform, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

--      l_lungh := LENGTH (s_val_new_1);

          If n_controllo_padre = 0 Then

              If s_val_new_1 is null
              Then n_errore:=0;
              Else
                          If s_val_new_1 > 9999
                          Then n_errore := 0;
                          Else n_errore := 1;
                          End If; 
              End If; 

          SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_platform,
                    n_parametro,
                    d_definizione,
                     Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    1,
                    Case
                       When n_errore = 0 And s_val_new_1 > 9999 Then  'Il parametro deve avere formato [NNNN]'
                       When n_errore = 0 And s_val_new_1 is null Then  'Il parametro deve essere valorizzato'
                       Else
                          NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                       When n_errore = 0 And NYA=0 Then 0
                       When n_errore = 0 And NYA=1 Then 1
                       When n_errore = 1  Then 0
                    End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_platform,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_6_7: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_6_7;
