PROCEDURE SetControlOPPlatform (n_controllo    IN     Number,    --procedura per il controllo dei parametri di OP PLATFORM
                                 id_op       IN     Varchar2,
                                 id_op_platform   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 p_error           OUT Number)
   IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_new_5            Varchar2 (1000);
      s_val_new_6            Varchar2 (1000);
      s_val_new_7            Varchar2 (1000);
      s_val_new_8            Varchar2 (1000);
      s_val_new_9           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_ok_dominio_2       Number;                           --variabile appoggio esistenza valore in dominio 0/1 per un parametro di confronto;
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      s_valore_A Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      s_valore_B Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      s_valore_C Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      m_min Number;                                 --variabile di appoggio per il commento
      m_max Number;                                 --variabile di appoggio per il commento
      NYA Number;
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;       --serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      l_lungh Number;
      p_error_split Number;                 --serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)

   BEGIN
      p_error := 0;

      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato

      d_definizione:=GetParameterValue('MARCIAPIEDI_BINARI_PO', 'PO_TR_PLATFORM_1_2_1_0_6_2','PO_TR_PLATFORM_1_2_1_0_6_2_D',id_op_platform);     --Recupero la definizione dell'oggetto

      -- 1.2.1.0.6.1 Codice GI  OBBLIGATORIO
      SET_1_2_1_0_6_1 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.2 ID Marciapiede

      -- 1.2.1.0.6.3  TEN class marciapiede DOMINIO               parametro con tabella multipla a parte
      SET_1_2_1_0_6_3 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.4.B1 Lungh. marciapiedi obbligatorio
      SET_1_2_1_0_6_4_B1 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.4.B2 Lungh. marciapiedi obbligatorio
      SET_1_2_1_0_6_4_B2 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.4.B3 Lungh. marciapiedi obbligatorio
      SET_1_2_1_0_6_4_B3 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.4.B4 Lungh. marciapiedi obbligatorio
      SET_1_2_1_0_6_4_B4 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.5.B1 Altez. marciapiedi B1 DOMINIO
      SET_1_2_1_0_6_5_B1 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.5.B2 Altez. marciapiedi B2 DOMINIO
      SET_1_2_1_0_6_5_B2 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.5.B3 Altez. marciapiedi B3 DOMINIO
      SET_1_2_1_0_6_5_B3 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.5.B4 Altez. marciapiedi B4 DOMINIO
      SET_1_2_1_0_6_5_B4 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.6 Assitenza marciapiede DOMINIO (deve contenere solo N)
      SET_1_2_1_0_6_6 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);

      -- 1.2.1.0.6.7 Campo utilizzo dispositivo ausilio accesso LUNGHEZZA (e AP fittizia perchè non esistente)
      SET_1_2_1_0_6_7 (n_controllo,  id_op, id_op_platform,   id_dtp, 0, p_error_split);


  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line   ('Errore - SetControlOPPlatform: '||Substr(Sqlerrm, 1, 250));
   End SetControlOPPlatform;
