                                        If (s_val_new_1 = ' ')
                                        OR (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)
                                        Then n_errore:=GREATEST(n_errore,1);                           --se mi fallisce un parametro multiplo, fallisce il controllo
                                        Else n_errore:=LEAST(n_errore, 0);
                                        End If; 
                              Else n_errore := 0;
                            End If; 

                      SetControlDetails(
                                n_controllo,
                                id_sol,
                                id_sol_tunnel,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                7,
                                Case
                                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                       --When n_errore = 0 And s_val_new_1 = ' ' Then 'Non esistono Dichiarazioni Gallerie SOL EI'
                                       When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                                       Else
                                          NULL
                                    End,
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                      Case
                                            When n_errore = 0 And NYA=0 Then 0
                                            When n_errore = 0 And NYA=1 Then 1
                                            When n_errore = 1  Then 0
                                       End);

                        FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;
                        EXIT When VALORI_MULTIPLI%NOTFOUND;

                       End LOOP;

                   Else
                   n_errore:=0;                 --se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella

                    SetControlDetails(
                            n_controllo,
                            id_sol,
                            id_sol_tunnel,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_IE|| 'galleria di binario'
                               Else NULL
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                                  Case
                                    When n_errore = 0 And NYA=0 Then 0
                                    When n_errore = 0 And NYA=1 Then 1
                                    When n_errore = 1  Then 0
                               End);
                   End If; 


           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 

       CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_1_1_1_8_6: '||Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_1_8_6;
--
-- ------------------------------------------------------------------------------------------------
--                  Procedure SET_1_1_1_1_8_7  - AP=Y
--  1.1.1.1.8.7 - Lunghezza della galleria (50) - Controlli: maggiore 100 m (inutile) e lunghezza digit 5
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_7 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_tunnel     In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                              
      n_errore               Number;                              
      d_definizione          Varchar2 (1000);                     
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      m_min                  Number;                           -- variabile di appoggio per il commento
      m_max                  Number;                           -- variabile di appoggio per il commento
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      NYA                    Number;
      --l_lungh  Number;
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol); 
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.7');
--
      GetOldNewValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_7', id_sol_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    l_lungh := LENGTH (s_val_new_1);          -- eliminato il controllo sulla lunghezza dei digit delle LG e sostituito con controllo <99999
      If n_controllo_padre = 0 Then
           If nvl(s_val_new_1, 0) < 100 Then 
		        n_errore := 0;
           Else
                If  s_val_new_1 > 99999
                     Then n_errore := 0;
                     Else n_errore := 1;
                 End If; 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     3,
                     Case
                          When n_errore = 0 And Nvl(s_val_new_1, 0) < 100 Then 'Il parametro deve essere valorizzato per lunghezza maggiore di 100 m in quanto gallerie di lunghezza minore non vengono prese in considerazione dal RINF'
                          When n_errore = 0 And s_val_new_1 > 99999 Then 'Il parametro deve avere lunghezza massima di 5 digit'
                        --When n_errore = 0 And l_lungh <>5 Then 'Deve essere 5 digit'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split:=MOD(n_errore+1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_1_1_1_8_7: '||Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_1_8_7;
/*
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_1_1_1_8_8 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_AP Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
