--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_8_8 (51) 
--                     1.1.1.1.8.8 - Area della Sezione Trasversale [NNN]
--         parametro Modificato dal Reg.777/2019 - Tipo Controllo: 5-AP+CORRELAZIONE con altro parametro
-- I valori ammessi dipendo dal parametro 1.1.1.1.2.5 - velocità massima consentita 
-- Il parametro deve essere valorizzato solo se la velocità della sezione di linea su cui insiste la galleria >= 200 km/h
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_8    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_tunnel     In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )     Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
	  id_sol_track              RINF_LAVORAZIONE_EVO.REL_GALLERIE_BINARI_SOL.SOL_TRACK_1_1_1_0_0_1%Type;
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
	  dbms_output.put_line ('n_controllo_old_ok_1: '|| n_controllo_old_ok_1);
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
	  dbms_output.put_line ('d_definizione: '||d_definizione);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.8');
	  dbms_output.put_line ('n_parametro: '||n_parametro);
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_8', id_sol_tunnel, s_val_new_1, s_val_old_ok_1);
	  dbms_output.put_line ('s_val_new_1: '||s_val_new_1);
	  dbms_output.put_line ('s_val_old_ok_1: '||s_val_old_ok_1);
--
      Begin
            Select SOL_TRACK_1_1_1_0_0_1 
			  Into id_sol_track 
            From (Select rgb.SOL_TRACK_1_1_1_0_0_1 
	              From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL rgb,
				       Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b
		         Where rgb.SOL_TUNNEL_1_1_1_1_8_2 = id_sol_tunnel
				   And rgb.SOL_TRACK_1_1_1_0_0_1 = b.SOL_TRACK_1_1_1_0_0_1
				   And b.SEDE_TECNICA = id_sol
				   order by SOL_TRACK_1_1_1_1_2_5 desc)
	         Where rownum < 2;
      Exception
	     When NO_DATA_FOUND Then
		   id_sol_track := Null;
		   dbms_output.put_line ('SET_1_1_1_1_8_8 - non è stato trovato il Binario associato alla galleria: '|| id_sol_tunnel||' - '||id_sol);
	  End;
	  dbms_output.put_line ('id_sol_track : '||id_sol_track );

--    acquisisce il valore del parametro 1.1.1.1.2.5 - Velocità massima consentita per il binario associato alla galleria
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
	  dbms_output.put_line ('s_val_new_2: '||s_val_new_2);
--
      NYA := GetNYA(n_parametro);
	  dbms_output.put_line ('NYA: '||NYA);
--
--      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_8_AP', id_sol_tunnel); 
     Begin
--      modifica del 27/04/2021 per correggere l'acquisizione del parametro perchè valorizzato nella  REL_GALLERIE_BINARI_SOL
	  Select SOL_TUNNEL_1_1_1_1_8_8_AP Into s_val_new_AP
	    From RINF_LAVORAZIONE_EVO.REL_GALLERIE_BINARI_SOL
	   Where SOL_TUNNEL_1_1_1_1_8_2 = id_sol_tunnel
	     And SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
      Exception
	     When NO_DATA_FOUND Then
		   s_val_new_AP := Null;
		   dbms_output.put_line ('SET_1_1_1_1_8_8 - non è stato trovato il Binario associato alla galleria: '|| id_sol_tunnel||' - '||id_sol_track);
	  End;

	  dbms_output.put_line ('s_val_new_AP: '||s_val_new_AP);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
	  dbms_output.put_line ('n_ok_AP: '||n_ok_AP);	  
--    Controllo padre dipende dal parametro 1.1.1.1.2.5 
      If n_controllo_padre = 0 Then
--         se l'applicabilità è coerente
           If n_ok_AP = 1 Then 
--              se la velocità massima consentita è minore di 200 km/h e il parametro è Null
                If (s_val_new_2 < 200 And s_val_new_1 Is Null) Then
			         n_errore := 1;                                        --> N.B. aggiornato a 1 (era 0 e quindi generave il NYA)
--	  dbms_output.put_line ('se la velocità massima consentita è minore di 200 km/h e il parametro è diverso da Null: '||n_errore);
--              se la velocità massima consentita è maggiore di 200 km/h e il parametro è valorizzato
                ElsIf (s_val_new_2 >= 200 And s_val_new_1 Is Not Null) Then
                     n_errore := 1;                        -- errore
--	  dbms_output.put_line ('se la velocità massima consentita è maggiore di 200 km/h e il parametro è valorizzato: '||n_errore);
                Else  
   		             n_errore := 0;
                End If; 
           Else  n_errore := 0;                                 -- il valore del parametro non è coerente con l'applicabilità 
           End If; 	  
--  dbms_output.put_line ('n_errore: '||n_errore);

--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 >= 200 And s_val_new_1 Is Null Then 'Se '||GetParametro(17, 'Velocità max')||' è maggiore o uguale a 200 Km/h, il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 < 200 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(17, 'Velocità max')||' è minore di 200 Km/h, il parametro non deve essere valorizzato'
				          When Nvl(s_val_new_1, 0) > 999 Then 'Il formato prevede l iserimento al massimo di 3 cifre [NNN]'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_erroè giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
	  dbms_output.put_line ('p_error_split 1: '||p_error_split);
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(17),--------------------------------------------->''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
	  dbms_output.put_line ('p_error_split 2: '||p_error_split);

      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_8_8 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_8_8;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_8_8_1 (284) 
--                     1.1.1.1.8.8.1 - Conformità della galleria alla STI INF - NCT
--         Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE - 
-- I valori ammessi (S/N) dipendo dal parametro 1.1.1.1.2.5 - velocità massima consentita 
-- Il parametro deve essere valorizzato solo se la velocità della sezione di linea su cui insiste la galleria >= 200 km/h
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_8_1  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_tunnel     In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)
    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
	  id_sol_track              RINF_LAVORAZIONE_EVO.REL_GALLERIE_BINARI_SOL.SOL_TRACK_1_1_1_0_0_1%Type;
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.8.1');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_8_1', id_sol_tunnel, s_val_new_1, s_val_old_ok_1) ;
--
      Begin
            Select SOL_TRACK_1_1_1_0_0_1 
			  Into id_sol_track 
            From (Select rgb.SOL_TRACK_1_1_1_0_0_1 
	              From Rinf_Lavorazione_Evo.REL_GALLERIE_BINARI_SOL rgb,
				       Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b
		         Where rgb.SOL_TUNNEL_1_1_1_1_8_2 = id_sol_tunnel
				   And rgb.SOL_TRACK_1_1_1_0_0_1 = b.SOL_TRACK_1_1_1_0_0_1
				   And b.SEDE_TECNICA = id_sol
				   order by SOL_TRACK_1_1_1_1_2_5 desc)
	         Where rownum < 2;
--
      Exception
	     When NO_DATA_FOUND Then
		   id_sol_track := Null;
		   dbms_output.put_line ('SET_1_1_1_1_8_8_1 - non è stato trovato il Binario associato alla galleria: '|| id_sol_tunnel||' - '||id_sol);
	  End;
--    acquisisce il valore del parametro 1.1.1.1.2.5 - Velocità massima consentita per il binario associato alla galleria
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
--
      NYA := GetNYA(n_parametro);
--
--      s_val_new_AP:= Nvl(GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_8_1_AP', id_sol_tunnel), 'Y'); 
      Begin
--      modifica del 27/04/2021 per correggere l'acquisizione del parametro perchè valorizzato nella  REL_GALLERIE_BINARI_SOL
	  Select SOL_TUNNEL_1_1_1_1_8_8_1_AP Into s_val_new_AP
	    From RINF_LAVORAZIONE_EVO.REL_GALLERIE_BINARI_SOL
	   Where SOL_TUNNEL_1_1_1_1_8_2 = id_sol_tunnel
	     And SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
--
      Exception
	     When NO_DATA_FOUND Then
		   s_val_new_AP := Null;
		   dbms_output.put_line ('SET_1_1_1_1_8_8_1 - non è stato trovato il Binario associato alla galleria: '|| id_sol_tunnel||' - '||id_sol_track);
	  End;
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Controllo padre dipende dal parametro 1.1.1.1.2.5 
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
                Then  n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                Then  n_ok_dominio := 1;
	       Else  n_ok_dominio := 0;
           End If; 

           If n_ok_AP = 1 Then           -- se l'applicabilità è coerente
                If n_ok_dominio = 1 Then  -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
--	 
--                   Inoltre, se la velocità massima consentita è minore di 200 km/h e il parametro è diverso da null
                     If (s_val_new_2 < 200 And s_val_new_1 Is Not Null)
                          Then n_errore := 0;                        -- errore
--                   se la velocità massima consentita è maggiore di 200 km/h e il parametro è Null
                     Elsif (s_val_new_2 >= 200 And s_val_new_1 Is Null)
                          Then n_errore := 0;                        -- errore
                     Else n_errore := 1;
                     End If; 
                Else  n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_errore = 0 And s_val_new_2 >= 200 And s_val_new_1 Is Null Then s_commento_AP_ok 
                          When n_errore = 0 And s_val_new_2 < 200 And s_val_new_1 Is Not Null Then s_commento_AP_ko
                          When n_errore = 0 Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--           
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--  
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(17),--------------------------------------------->''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--  
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_8_8_1: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_8_8_1;
--
-- ------------------------------------------------------------------------------------------------
-- 1.1.1.1.8.8.2 - Documento messo a disposizione dal GI contenente la descrizione esatta della galleria - NA Intera Rete
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_8_2  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_tunnel     In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)
    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
	  id_sol_track              RINF_LAVORAZIONE_EVO.REL_GALLERIE_BINARI_SOL.SOL_TRACK_1_1_1_0_0_1%Type;
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.8.2');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_8_2', id_sol_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA(n_parametro);
--
      s_val_new_AP := Nvl(GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_8_2_AP', id_sol_tunnel), 'N'); 
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                 n_errore := 1;
	       Else  
		        n_errore := 0;
           End If; 
--  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     10,
                     Case
                          When n_errore = 0 Then s_commento_AP_ko
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--           
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--  
            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                            -- fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                        When n_controllo_padre = 1 Then 1
                        When NYA = 0 Then 0
                        When NYA = 1 Then 1
                    End  );
--  
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_8_8_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_8_8_2;

/**********
--
-- ------------------------------------------------------------------------------------------------
--                              PROCEDURE SET_1_1_1_1_8_9 
--                     1.1.1.1.8.9  - ITU_EmergencyPlan  -Piano emergenza  DOMINIO E CORRELAZIONE
--                      Esistenza del Piano di Emergenza (Galleria) 
-- Procedura Modificata con il Reg.777/2019 e il 15/03/2021 modificata l'applicabilità: se la galleria è minore di 1000m non è applicabile
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_9 (    n_controllo       In     Number,
                                 id_sol            In     Varchar2,
                                 id_sol_tunnel     In     Varchar2,
                                 id_dtp            In     Varchar2,
                                 n_controllo_padre In     Number,
                                 p_error_split    Out     Number)
   Is   
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);       -- stringa concatenata del dominio
      m_min                  Number;                -- variabile di appoggio per il commento
      m_max                  Number;                -- variabile di appoggio per il commento
      n_ok_AP                Number;                -- variabile appoggio applicabilità 0/1
      NYA                    Number;
      l_lungh                Number;

  BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split :=0;         
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.9');
--
      GetOldNewValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_9', id_sol_tunnel, s_val_new_1, s_val_old_ok_1) ;
--
-- verifica se il parametro accetta valori NYA
      NYA := GetNYA (n_parametro);
---> aggiunto per la verifica sullìapplicabilità e la sua gestione 16/03/20221
--    legge l'applicabilità del parametro 1.1.1.1.8.9 nella tabella RINF_LAVORAZIONE_EVO.GALLERIE_BINARI_SOL (campo chiave: SOL_TUNNEL_1_1_1_1_8_2)
      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_9_AP', id_sol_tunnel);
--      dbms_output.put_line ('Applicabilità del dato SOL_TUNNEL_1_1_1_1_8_9_AP (s_val_new_AP): '||s_val_new_AP);	
--
--    SOL_TUNNEL_1_1_1_1_8_7 - Lunghezza della galleria (s_val_new_2)
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_7', id_sol_tunnel);
--      dbms_output.put_line ('Lunghezza della Galleria - SOL_TUNNEL_1_1_1_1_8_7 (s_val_new_2): '||s_val_new_2);
--
--> ******   aggiunto temporaneamente per gestire i messaggi di errore al territorio nel frattempo che In.Rete corregga il dato ******
      If s_val_new_AP = 'N' And s_val_new_1 = 'N' Then 
	     s_val_new_1 := Null;
	  End If;

--
--    Verifica che l'applicabilità e il valore siano coerenti (AP=Y e valore not null / AP=N e valore null)--> n_ok_AP=1 altrimenti =0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--      dbms_output.put_line ('Il valore è coerente con l''applicabilità - n_ok_AP :'||n_ok_AP );

--    Se il codice di ritorno SET_1_1_1_1_8_7 = 0 - lunghezza della galleria (1.1.1.1.8.7)
      If n_controllo_padre = 0 Then    
--
--         se l'applicabilità del parametro 1.1.1.1.8.9 = Y ed coerente con il valore (not null) legge se in RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO 
--         il valore acquisito è presente: n_ok_dominio = 1, altrimenti = 0
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
 --               dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ok_AP --> n_ok_dominio: '||n_ok_dominio);		
--              altrimenti se l'applicabilità del parametro 1.1.1.1.8.9 = N ed è coerente con il valore (null): n_ok_dominio = 1
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
 --             dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ko_AP --> n_ok_dominio = 1');	
           Else 	                   --> aggiunto per tutti gli altri casi 
			    n_ok_dominio := 0;     --> (non era previsto)
           End If; 
--          dbms_output.put_line ('n_ok_dominio (end if): '||n_ok_dominio);	
--
--         Valorizzazione del flag "N_ERRORE": 0-errore, 1-OK
--         Se l'applicabilità e il valore del parametro 1.1.1.1.8.9 sono coerenti
           If n_ok_AP = 1 Then
 --               dbms_output.put_line ('n_ok_AP = 1 ');	
                If n_ok_dominio = 1 Then      -- se anche il valore è compreso nell'elenco dei valori ammessi [A],[B], [nessuna]
--                   dbms_output.put_line ('n_ok_AP = 1 e n_ok_dominio = 1');
--                   se la lunghezza della galleria è inferiore a 1000m e il parametro è diverso da null
                     If (s_val_new_2 <= 1000 And s_val_new_1 Is Not Null) Then                                -- Per richiesta di Schillaci (evitare le anomalie per il territotio con la regola modficata)
 --                        dbms_output.put_line ('lungh. galleria < 1000m ma il valore del parametro è not null - ERRORE'); -- errore
					      n_errore := 0;
                     Elsif (s_val_new_2 > 1000 And s_val_new_1 Is Null) Then 
					      n_errore := 0;
 --                         dbms_output.put_line ('lungh.galleria >= 1000m e valore del parametro null- ERRORE');
                     Else n_errore := 1;
 --                         dbms_output.put_line ('lungh.galleria < 1000m e valore del parametro è null o lungh.galleria >= 1000m e valore del parametro not null- OK'); -- ok
                     End If; 
                Else n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
 --         dbms_output.put_line ('n_errore: '||n_errore);



          SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         Else n_errore
                    End,
                    6,
                    Case
                        When n_errore = 0 And s_val_new_2 >= 1000 Then 'Se '||GetParametro(50, 'lunghezza')||' è maggiore o uguale a 1000 m, il parametro deve essere valorizzato '||GetCorrectRangeStringPURA(52)
-- aggiunto con mail Schillaci del 21/06/2016
-- Reg.777/2019?       When n_ok_dominio = 0 And s_val_new_2 < 1000 Then 'Parametro non valorizzato per effetto della regola automatica applicata'    
-- aggiunto 21/06/2016 per gestire il caso in cui arrivasse una galleria senza lunghezza (praticamente impossibile)
                        When s_val_new_2 is null Then 'Parametro non valutabile in quanto presente un errore su '||GetParametro(50, 'lunghezza')           
-- Reg.777/2019                        When n_errore = 0 And s_val_new_2 < 1000 Then 'Se '||GetParametro(50,'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
--                        When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 <>'N' Then 'Se '||GetParametro(50, 'lunghezza')||' minore di 1000m deve essere '|| GetValueFromCode (n_parametro, 'N')
                        When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(50, 'lunghezza')||' minore di 1000m il presente parametro non deve essere valorizzato'
                        When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
--
                       --17/05/2016  modificato secondo accordi riunione
                       --When n_ok_dominio = 0 And s_val_new_2<1000 Then 'Se '||GetParametro(50,'lunghezza')||' minore di 1000 m deve essere '|| GetValueFromCode (n_parametro, 'N')
                       --When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                        Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                    End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);   
--                il parametro padre è risultato errato
            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
--                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    GetMessFallitoPadreSingolo(50),---> 'Lunghezza galleria' 
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                        When n_controllo_padre = 1 Then 1
                        When NYA = 0 Then 0
                        When NYA = 1 Then 1
                    End);
-- in p_error 1 è errato (al contrario di n_errore)
               p_error_split := 1;                        
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_1_1_1_8_9: '||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_8_9;

  ************************/
-- ------------------------------------------------------------------------------------------------
--                              PROCEDURE SET_1_1_1_1_8_9 
--                     1.1.1.1.8.9 - ITU_EmergencyPlan  - Piano emergenza  DOMINIO E CORRELAZIONE
--                      Esistenza del Piano di Emergenza (Galleria) 
-- Procedura Modificata con il Reg.777/2019
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_9 (n_controllo       In     Number,
                             id_sol            In     Varchar2,
                             id_sol_tunnel     In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split    Out     Number)    Is   
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);       -- stringa concatenata del dominio
      m_min                  Number;                -- variabile di appoggio per il commento
      m_max                  Number;                -- variabile di appoggio per il commento
      n_ok_AP                Number;                -- variabile appoggio applicabilità 0/1
      NYA                    Number;
      l_lungh                Number;

  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.9');
--
      GetOldNewValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_9', id_sol_tunnel, s_val_new_1, s_val_old_ok_1) ;
--
--    verifica se il parametro accetta valori NYA
      NYA := GetNYA (n_parametro);
--
--    lunghezza della galleria - parametro 1.1.1.1.8.7 (s_val_new_2)
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_7', id_sol_tunnel);
--
--    legge se in RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO il valore acquisito del parametro è presente nell'elenco: n_ok_dominio = 1, altrimenti = 0
      n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--
         If n_controllo_padre = 0 Then
--
              If n_ok_dominio = 1 Then                -- se il valore è valido
/***
--                     If    s_val_new_2 <1000 And s_val_new_1 <>'N'      --17/05/2016  modificato secondo accordi riunione
--                     If    (s_val_new_2 <1000 And s_val_new_1 is not null)
--                   If (s_val_new_2 < 1000 ) OR (s_val_new_2 >= 1000 And s_val_new_1 is null)  --> lungh. galleria < 1000m oppure >1000m e piano emerg.=null
***/
                   If s_val_new_2 >= 1000 Then
				          If s_val_new_1 is not null  --> lungh. galleria > 1000m e piano emerg. not null (S o N)
                             Then n_errore := 1;    
                             Else n_errore := 0;  
                          End If;							   
                   Else                                   
	          			  If s_val_new_1 = 'N'       --> lungh. galleria < 1000m e piano emerg. = N
                             Then n_errore := 1;    
                             Else n_errore := 0;  
                          End If;		
                   End If; 
              Else                                    -- il valore del parametro non è valido
				   n_errore := 0;
              End If; 

          SetControlDetails(
                    n_controllo,
                    id_sol,
                    id_sol_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 
					     Then 1
                         Else n_errore
                    End,
                    7,
                    Case
                        When n_errore = 0 And s_val_new_2 >= 1000 Then 'Se '||GetParametro(50, 'lunghezza')||' è maggiore o uguale a 1000 m, il parametro deve essere valorizzato '||GetCorrectRangeStringPURA(52)
-- aggiunto con mail Schillaci del 21/06/2016
-- Reg.777/2019?       When n_ok_dominio = 0 And s_val_new_2 < 1000 Then 'Parametro non valorizzato per effetto della regola automatica applicata'    
-- aggiunto 21/06/2016 per gestire il caso in cui arrivasse una galleria senza lunghezza (praticamente impossibile)
                        When s_val_new_2 Is Null Then 'Parametro non valutabile in quanto presente un errore su '||GetParametro(50, 'lunghezza')           
                        When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
-- Reg.777/2019                        When n_errore = 0 And s_val_new_2 < 1000 Then 'Se '||GetParametro(50,'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
                       --17/05/2016  modificato secondo accordi riunione
                       --When n_ok_dominio = 0 And s_val_new_2<1000 Then 'Se '||GetParametro(50,'lunghezza')||' minore di 1000 m deve essere '|| GetValueFromCode (n_parametro, 'N')
                       --When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                        When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 <> 'N' Then 'Se '||GetParametro(50, 'lunghezza')||' minore di 1000m deve essere '|| GetValueFromCode (n_parametro, 'N')
                        Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1           Then 0
                    End);
--
--          siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);   
--
-- il parametro padre è risultato errato
      Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
--                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    GetMessFallitoPadreSingolo(50),---> 'Lunghezza galleria' 
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                        When n_controllo_padre = 1 Then 1
                        When NYA = 0 Then 0
                        When NYA = 1 Then 1
                    End);
--
--             in p_error 1 è errato (al contrario di n_errore)
               p_error_split := 1;                        
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_1_1_1_8_9: '||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_8_9;
--
-- ------------------------------------------------------------------------------------------------
--                                    PROCEDURE SET_1_1_1_1_8_10 (41)
-- 1.1.1.1.8.10  Categoria di sicurezza antincendio richiesta per il materiale rotabile - AP+DOMINIO+CORRELAZIONE
-- Procedura Modificata con il Reg.777/2019  - I valori possono essere [A], [B] o [Nessuna/none]
-- Il parametro è applicabile per gallerie aventi lunghezza maggiore o uguale a 1000 m
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_10 (n_controllo       In     Number,
                              id_sol            In     Varchar2,
                              id_sol_tunnel     In     Varchar2,
                              id_dtp            In     Varchar2,
                              n_controllo_padre In     Number,
                              p_error_split    Out     Number  )  Is
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      n_ok_dominio            Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;
      n_errore                Number;
      d_definizione           Varchar2 (1000);
      s_stringa_dominio       Varchar2 (1000);                   -- stringa concatenata del dominio
      m_min                   Number;                            -- variabile di appoggio per il commento
      m_max                   Number;                            -- variabile di appoggio per il commento
      n_ok_AP                 Number;                            -- variabile appoggio applicabilità 0/1
      NYA                     Number;
      l_lungh                 Number;
      conta_multiplo          Number;
 BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);   
--dbms_output.put_line (' n_controllo_old_ok_1: '||n_controllo_old_ok_1);	  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--dbms_output.put_line ('d_definizione: '||d_definizione);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.10');
--dbms_output.put_line ('n_parametro: '||n_parametro);
--
      GetOldNewValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_10', id_sol_tunnel, s_val_new_1, s_val_old_ok_1);
--dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--dbms_output.put_line ('il parametro può essere NYA: '||NYA);
--
--    legge l'applicabilità del parametro 1.1.1.1.8.10 nella tabella RINF_LAVORAZIONE_EVO.GALLERIE_BINARI_SOL (campo chiave: SOL_TUNNEL_1_1_1_1_8_2)
      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_10_AP', id_sol_tunnel);
--dbms_output.put_line ('Applicabilità del dato SOL_TUNNEL_1_1_1_1_8_10_AP (s_val_new_AP): '||s_val_new_AP);	
--
--    SOL_TUNNEL_1_1_1_1_8_7 - Lunghezza della galleria (s_val_new_2)
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_7', id_sol_tunnel);
--dbms_output.put_line ('Lunghezza della Galleria - SOL_TUNNEL_1_1_1_1_8_7 (s_val_new_2): '||s_val_new_2);
--
--    Verifica che l'applicabilità e il valore siano coerenti (AP=Y e valore not null / AP=N e valore null)--> n_ok_AP=1 altrimenti =0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--dbms_output.put_line ('Il valore è coerente con l''applicabilità - n_ok_AP :'||n_ok_AP );
/*
      Select count(*) into conta_multiplo                             -- eliminati da SAL 29/10/2015 
        from RINF_LAVORAZIONE_EVO.DICHIARAZIONI_GALLERIE_BIN_SOL
       where SOL_TUNNEL_1_1_1_1_8_2 = id_sol_tunnel
         And TIPO_DICHIARAZIONE = 'EC'
         And SOL_TUNNEL_1_1_1_1_8_5O6_AP = 'N'; --> 'Y'
*/
--    Se il codice di ritorno SET_1_1_1_1_8_7 = 0 - lunghezza della galleria (1.1.1.1.8.7)
      If n_controllo_padre = 0 Then    
--dbms_output.put_line ('n_controllo_padre = 0 (lunghezza della galleria (1.1.1.1.8.7) is not null)');	  
--
--         se l'applicabilità del parametro 1.1.1.1.8.10 = Y ed coerente con il valore (not null) legge se in RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO 
--         il valore acquisito è presente: n_ok_dominio = 1, altrimenti = 0
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ok_AP --> n_ok_dominio: '||n_ok_dominio);		
--         altrimenti se l'applicabilità del parametro 1.1.1.1.8.10 = N ed coerente con il valore (null): n_ok_dominio = 1
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
--dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ko_AP --> n_ok_dominio = 1');	
           Else 	                   --> aggiunto per tutti gli altri casi 
			    n_ok_dominio := 0;     --> (non era previsto)
           End If; 
--dbms_output.put_line ('n_ok_dominio (end if): '||n_ok_dominio);	
--
--         Valorizzazione del flag "N_ERRORE": 0-errore, 1-OK
--         Se l'applicabilità e il valore del parametro 1.1.1.1.8.10 sono coerenti
           If n_ok_AP = 1 Then
--dbms_output.put_line ('n_ok_AP = 1 ');	
                If n_ok_dominio = 1 Then      -- se anche il valore è compreso nell'elenco dei valori ammessi [A],[B], [nessuna]
--dbms_output.put_line ('n_ok_AP = 1 e n_ok_dominio = 1');
--                   se la lunghezza della galleria è inferiore a 1000m e il parametro è diverso da null
                     If (s_val_new_2 < 1000 And s_val_new_1 Is Not Null) Then 
                      --    OR (s_val_new_2 >= 1000 And conta_multiplo <> 0 And nvl(s_val_new_1,0) <>'none')   -- eliminati da SAL 29/10/2015
--dbms_output.put_line ('lungh. galleria < 1000m ma il valore del parametro è not null - ERRORE'); -- errore
					      n_errore := 0;
                     Elsif (s_val_new_2 >= 1000 And s_val_new_1 Is Null) Then 
					      n_errore := 0;
--dbms_output.put_line ('lungh.galleria >= 1000m e valore del parametro null- ERRORE');
                     Else n_errore := 1;
--dbms_output.put_line ('lungh.galleria < 1000m e valore del parametro è null o lungh.galleria >= 1000m e valore del parametro not null- OK'); -- ok
                     End If; 
                Else n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--dbms_output.put_line ('n_errore: '||n_errore);
--
--         scrittura nella tabella RINF_LAVORAZIONE_EVO.DETTAGLIO_CONTROLLATI dell'esito del controllo
           SetControlDetails(
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                        When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko       
                        When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                        When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                        When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(50, 'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
                        When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_1 Is Null Then 'Se '||GetParametro(50, 'lunghezza')||' è maggiore o uguale a 1000 m, il parametro deve essere valorizzato'
                        Else Null
                     End,  
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);  

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(50),---> 'Lunghezza galleria' --eliminata correlazione con Dichiarazione EC gallerie da Galli 29/10/2015
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line ('SET_1_1_1_1_8_10 - Errore: '||Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_1_8_10;
--
-- ------------------------------------------------------------------------------------------------
--                         Procedure SET_1_1_1_1_8_11 (43) - NCT 
-- 1.1.1.1.8.11 - Categoria di sicurezza antincendio nazionale richiesta per il materiale rotabile
-- Categorizzazione delle modalità con cui un treno passeggeri con incendio a bordo può
-- proseguire la corsa per un periodo di tempo determinato.
-- Il parametro è applicabile per gallerie aventi lunghezza maggiore o uguale a 1000 m e quando il parametro 1.1.1.1.8.10 è
-- valorizzato con “nessuna”.   - AP+DOMINIO
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_8_11 (n_controllo       In Number,
                              id_sol            In Varchar2,
                              id_sol_tunnel     In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number  )  Is
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_new_3             Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      n_ok_dominio            Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;
      n_errore                Number;
      d_definizione           Varchar2 (1000);
      s_stringa_dominio       Varchar2 (1000);                   -- stringa concatenata del dominio
      m_min                   Number;                            -- variabile di appoggio per il commento
      m_max                   Number;                            -- variabile di appoggio per il commento
      n_ok_AP                 Number;                            -- variabile appoggio applicabilità 0/1
      NYA                     Number;
      l_lungh                 Number;
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.8.11');
--
      GetOldNewValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_11', id_sol_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_11_AP', id_sol_tunnel);
--    1.1.1.1.8.7 - lunghezza della galleria 
      s_val_new_2 := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_7', id_sol_tunnel);
--    1.1.1.1.8.10 - categoria di sicurezza antincendio
      s_val_new_3 := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_10', id_sol_tunnel);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                n_ok_dominio := 1;
		   Else 
                n_ok_dominio := 0;
           End If; 
--         If s_val_new_1 is not null            sospeso con mail Galli 27/08/2015
--         Then n_errore:=0;
--         Else n_errore:=1;
--         End If; 
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (s_val_new_2  < 1000 And s_val_new_1 Is Not Null) Or
                        (s_val_new_2 >= 1000 And s_val_new_3 = 'none' And s_val_new_1 Is Null) Or
                        (s_val_new_2 >= 1000 And s_val_new_3 <> 'none' And s_val_new_1 Is Not Null)  Then
                          n_errore := 0;
                     Else n_errore := 1;
                     End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(50, 'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_3 = 'none' And s_val_new_1 Is Null Then 'Se '||GetParametro(50, 'lunghezza')||' è maggiore o uguale a 1000 m e '||GetParametro(41, 'Categoria di sicurezza antincendio')||' è '||GetValueFromCode (41, 'none')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_3 <> 'none' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(50, 'lunghezza')||' è maggiore o uguale 1000 m e '||GetParametro(41, 'Categoria di sicurezza antincEndio')||' è diversa da '||GetValueFromCode (41, 'none')||', il parametro non deve essere valorizzato'
--                        sospeso con mail Galli 27/08/2015
--                        When n_ok_dominio = 0 Then 'Il parametro deve essere sempre non applicabile'--'GetCorrectRangeString (n_parametro)
--                        When n_errore=0 And s_val_new_1 is not null Then 'Il parametro deve essere sempre non applicabile'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split:=MOD(n_errore+1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                 --fallito padre
                     GetMessFallitoPadreSingolo(41),------------------------------------------->''Categoria Sicurezza AntincEndio per Materiale Rotabile''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                       End);
--         in p_error 1 è errato (al contrario di n_errore)
            p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line ('SET_1_1_1_1_8_11 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_8_11;
--
-- ------------------------------------------------------------------------------------------------
--                 Procedure SetControlSOLTunnel
--           procedura per il controllo dei parametri di SOL TUNNEL
-- ------------------------------------------------------------------------------------------------
--
    Procedure SetControlSOLTunnel (n_controllo    In Number,    
                                   id_sol         In Varchar2,
                                   id_sol_tunnel  In Varchar2,
                                   id_dtp         In Varchar2,
                                   p_error       Out Number  )   Is
      n_parametro                  Number;
      s_val_new_1                  Varchar2 (1000);
      s_val_new_2                  Varchar2 (1000);
      s_val_new_AP                 Varchar2 (1000);
      s_val_old_ok_1               Varchar2 (1000);
      n_ok_dominio                 Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1         Number;
      n_errore                     Number;
      d_definizione                Varchar2 (1000);
      s_stringa_dominio            Varchar2 (1000);                   -- stringa concatenata del dominio
      m_min                        Number;                            -- variabile di appoggio per il commento
      m_max                        Number;                            -- variabile di appoggio per il commento
      n_ok_AP                      Number;                            -- variabile appoggio applicabilità 0/1
      NYA                          Number;
      l_lungh                      Number;
--    serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa 
--    come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)
      p_error_split                Number;     
      p_error_UNION                Number;
      p_error_1_1_1_1_8_5          Number;
      p_error_1_1_1_1_8_7          Number;
      p_error_1_1_1_1_8_10         Number;
  BEGIN
      p_error := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('GALLERIE_BINARI_SOL', 'SOL_TUNNEL_1_1_1_1_8_2', 'SOL_TUNNEL_1_1_1_1_8_2_D', id_sol_tunnel);     

--    1.1.1.1.8.1 Codice del GI - OBBLIGATORIO
      SET_1_1_1_1_8_1 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);
--
--    1.1.1.1.8.2 ID galleria
--
--    1.1.1.1.8.3 Inizio galleria
--
--    1.1.1.1.8.4 Fine galleria
--
--    1.1.1.1.8.5  Dichiarazione GALL SOL EC FORMATO E APP  - parametro con tabella multipla a parte
      SET_1_1_1_1_8_5 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);         
	  p_error_1_1_1_1_8_5 := p_error_split;
--
--    1.1.1.1.8.6  Dichiarazione GALL SOL  EI FORMATO E APP - parametro con tabella multipla a parte
      SET_1_1_1_1_8_6 (n_controllo,  id_sol, id_sol_tunnel,   id_dtp, 0, p_error_split);
--
--    1.1.1.1.8.7 Lunghezza della galleria         maggiore 100 m (inutile) e lunghezza digit 5
      SET_1_1_1_1_8_7 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);       
	  p_error_1_1_1_1_8_7 := p_error_split;
--	  
--    1.1.1.1.8.8 Area della sezione trasversale  -  obbligatoria per galleria maggiore 100 m (inutile) - Applicabile se la velocità è > 200 Km/h
--      SET_1_1_1_1_8_8 (n_controllo, id_sol, id_sol_tunnel, id_dtp, nvl(p_error_1_1_1_1_2_5, 0), p_error_split);
      SET_1_1_1_1_8_8 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);
--	  
--    1.1.1.1.8.8.1 Conformità della galleria alla STI INF  -  obbligatoria per galleria maggiore 100 m (inutile) - Applicabile se la velocità è > 200 Km/h
--      SET_1_1_1_1_8_8_1 (n_controllo, id_sol, id_sol_tunnel, id_dtp, nvl(p_error_1_1_1_1_2_5, 0), p_error_split);
      SET_1_1_1_1_8_8_1 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);
--	  
--    1.1.1.1.8.8.2 - Documento messo a disposizione del GI contenente la descrizione esatta della galleria - NA - per Intera Rete RFI
      SET_1_1_1_1_8_8_2 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);
--	  
--    1.1.1.1.8.9  Piano emergenza  DOMINIO E CORRELAZIONE
--      SET_1_1_1_1_8_9 (n_controllo, id_sol, id_sol_tunnel, id_dtp, 0, p_error_split);
      SET_1_1_1_1_8_9 (n_controllo, id_sol, id_sol_tunnel, id_dtp, p_error_1_1_1_1_8_7, p_error_split);
--	  
--    1.1.1.1.8.10  Categoria di sicurezza Antincendio richiesta per il materiale rotabile - AP+DOMINIO+CORRELAZIONE
--    eliminato da Gallli 29/10/2015 p_error_UNION := GREATEST (p_error_1_1_1_1_8_5, p_error_1_1_1_1_8_7);                            
--    dipende da due padri, quindi faccio la sintesi tra i due errori dei padri (se almeno uno è 1, il controllo sul figlio deve fallire)
      SET_1_1_1_1_8_10 (n_controllo, id_sol, id_sol_tunnel, id_dtp, p_error_1_1_1_1_8_7, p_error_split);       
	  p_error_1_1_1_1_8_10 := p_error_split;
--	  
--    1.1.1.1.8.11 Naz.antincen. m.r. AP+DOMINIO
      SET_1_1_1_1_8_11 (n_controllo, id_sol, id_sol_tunnel, id_dtp, p_error_1_1_1_1_8_10, p_error_split);
--
  EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('SetControlSOLTunnel - Errore: '||Substr(Sqlerrm, 1, 250));
   End SetControlSOLTunnel;
--                                 1.2.1.0.5 Galleria
-- ------------------------------------------------------------------------------------------------
--                               Procedure SET_1_2_1_0_5_1
-- 1.2.1.0.5.1 - OPTrackTunnelIMCode
-- 1.2.1.0.5.1 - Codice del GI - OBBLIGATORIO
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_5_1 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_tunnel      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                
      n_errore               Number;                
      d_definizione          Varchar2 (1000);       
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1:=GetCorrectControlId(id_op); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.1');
--
      GetOldNewValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_1', id_op_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then

           n_errore := GetCorrectValue (n_parametro, s_val_new_1);

           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case When n_errore = 0 Then GetCorrectRangeStringObbl (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line ('SET_1_2_1_0_5_1 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_5_1;
--
-- 1.2.1.0.5.2 Identificazione della galleria
--
-- ------------------------------------------------------------------------------------------------
--                Procedure SET_1_2_1_0_5_3 (146)
-- 1.2.1.0.5.3 Dichiarazione CE di verifica della galleria (SRT)
-- FORMATO E APP  - parametro con tabella multipla a parte
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_5_3 (n_controllo       In Number,
                             id_op             In Varchar2,
                             id_op_tunnel      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                
      n_errore               Number;                
      d_definizione          Varchar2 (1000);       
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                    -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE

  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_op); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.3');
--
      NYA := GetNYA (n_parametro);
---- multiplo: DICHIARAZIONI_GALLERIE_BIN_PO
      GetOldNewValueMultiploDICH('DICHIARAZIONI_GALLERIE_BIN_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_3O4', 'PO_TR_TUNNEL_1_2_1_0_5_3O4_AP', id_op_tunnel, 'EC', valori_multipli) ;           
--    inizializzo l'errore per poterlo puoi valorizzare nel loop
      n_errore := 1;              
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
--
           If n_controllo_padre = 0 Then
--
                If VALORI_MULTIPLI%FOUND Then
                  Loop
--> loop 
                     n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);
--
                     If n_ok_AP = 1 Then
                          If (s_val_new_1 = ' ') Or (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1) Then 
--                             se mi fallisce un parametro multiplo, fallisce il controllo
                               n_errore := Greatest(n_errore, 1);    
                          Else n_errore := Least(n_errore, 0);
                          End If; 
                     Else n_errore := 0;
                     End If; 
--
                     SetControlDetails(
                               n_controllo,
                               id_op,
                               id_op_tunnel,
                               n_parametro,
                               d_definizione,
                               Case When NYA = 1 
							        Then 1
                                    Else n_errore
                               End,
                               7,
                               Case
                                    When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                    When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                    When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                                    Else Null
                               End,
                               s_val_new_1,
                               s_val_old_ok_1,
                               n_controllo_old_ok_1,
                               Case
                                    When n_errore = 0 And NYA = 0 Then 0
                                    When n_errore = 0 And NYA = 1 Then 1
                                    When n_errore = 1             Then 0
                               End );

                        Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
                        Exit When VALORI_MULTIPLI%NOTFOUND;

                  End Loop;
--              se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella
                Else
                     n_errore := 0;                 

                     SetControlDetails(
                               n_controllo,
                               id_op,
                               id_op_tunnel,
                               n_parametro,
                               d_definizione,
                               Case When NYA = 1 
							        Then 1
                                    Else n_errore
                               End,
                               4,
                               Case When n_errore = 0 Then s_commento_DICH_CE||'galleria di binario di PO'
                                    Else Null
                               End,
                               s_val_new_1,
                               s_val_old_ok_1,
                               n_controllo_old_ok_1,
                               Case
                                    When n_errore = 0 And NYA = 0 Then 0
                                    When n_errore = 0 And NYA = 1 Then 1
                                    When n_errore = 1             Then 0
                               End  );
                End If; 
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := MOD(n_errore+1, 2);                               

           Else SetControlDetails (
                          n_controllo,
                          id_op,
                          id_op_tunnel,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End  );
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split :=1;                        
           End If; 
--
       Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line ('SET_1_2_1_0_5_3 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_5_3;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_2_1_0_5_4 (n_controllo    IN     Number,
                                 id_op         IN     Varchar2,
                                 id_op_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;       --serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO

       BEGIN
       --1.2.1.0.5.4  Dichiarazione GALL PO EI FORMATO E APP                             parametro con tabella multipla a parte

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2','PO_TR_TUNNEL_1_2_1_0_5_2_D',id_op_tunnel);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.4');

      NYA:= GetNYA (n_parametro);

      GetOldNewValueMultiploDICH('DICHIARAZIONI_GALLERIE_BIN_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2','PO_TR_TUNNEL_1_2_1_0_5_3O4','PO_TR_TUNNEL_1_2_1_0_5_3O4_AP',id_op_tunnel,'EI', valori_multipli) ;           --multiplo

      n_errore:=1;              --inizializzo l'errore per poterlo puoi valorizzare nel loop

      FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;

          If n_controllo_padre = 0 Then

                  If VALORI_MULTIPLI%FOUND Then
                      LOOP

                            n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);

                             If n_ok_AP = 1
                            Then
                                        If (s_val_new_1 = ' ')
                                        OR (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)
                                        Then n_errore:=GREATEST(n_errore,1);                           --se mi fallisce un parametro multiplo, fallisce il controllo
                                        Else n_errore:=LEAST(n_errore, 0);
                                        End If; 
                              Else n_errore := 0;
                            End If; 

                      SetControlDetails(
                                n_controllo,
                                id_op,
                                id_op_tunnel,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                7,
                                Case
                                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                       When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                                       Else
                                          NULL
                                    End,
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                      Case
                                            When n_errore = 0 And NYA=0 Then 0
                                            When n_errore = 0 And NYA=1 Then 1
                                            When n_errore = 1  Then 0
                                       End);

                        FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;
                        EXIT When VALORI_MULTIPLI%NOTFOUND;

                       End LOOP;

                   Else
                   n_errore:=0;                 --se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella

                    SetControlDetails(
                            n_controllo,
                            id_op,
                            id_op_tunnel,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_IE|| 'galleria di binario di PO'
                               Else NULL
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                                  Case
                                    When n_errore = 0 And NYA=0 Then 0
                                    When n_errore = 0 And NYA=1 Then 1
                                    When n_errore = 1  Then 0
                               End);
                   End If; 


           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 

       CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_5_4: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_5_4;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_2_1_0_5_5 (n_controllo    IN     Number,
                                 id_op         IN     Varchar2,
                                 id_op_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_AP Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      m_min Number;                                 --variabile di appoggio per il commento
      m_max Number;                                 --variabile di appoggio per il commento
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      NYA Number;
      --l_lungh  Number;

       BEGIN
       -- 1.2.1.0.5.5 Lungh. galleria         maggiore 100 m (inutile) e lunghezza digit 5

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      s_commento_AP_ok :=  'Errore applicabilità: il parametro è definito Applicabile ma non è valorizzato';
      s_commento_AP_ko :=  'Errore applicabilità: il parametro è definito Non Applicabile ma è valorizzato';
      v_ok_AP := 'Y';                           -- Y è true
      v_ko_AP := 'N';                           -- N è false
      n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2','PO_TR_TUNNEL_1_2_1_0_5_2_D',id_op_tunnel);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.5');

      GetOldNewValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2','PO_TR_TUNNEL_1_2_1_0_5_5',id_op_tunnel, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      --l_lungh := LENGTH (s_val_new_1);

         If n_controllo_padre = 0 Then

                  If nvl(s_val_new_1,0) < 100
                  Then n_errore := 0;
                  Else
                        If  s_val_new_1 > 99999
                        Then n_errore:=0;
                        Else n_errore:=1;
                       End If; 
                  End If; 

          SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                     Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    3,
                        Case
                           When n_errore = 0 And nvl(s_val_new_1,0) <100 Then 'Il parametro deve essere valorizzato per lunghezza maggiore di 100 m in quanto gallerie di lunghezza minore non vengono prese in considerazione dal RINF'
                           When n_errore = 0 And s_val_new_1 > 99999 Then 'Il parametro deve avere lunghezza massima di 5 digit'
                           --When n_errore = 0 And l_lungh <>5 Then 'Deve essere 5 digit'
                           Else NULL
                        End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                         When n_errore = 0 And NYA=0 Then 0
                         When n_errore = 0 And NYA=1 Then 1
                         When n_errore = 1  Then 0
                     End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_5_5: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_5_5;

--
/************************************
-- ------------------------------------------------------------------------------------------------
--                        PROCEDURE SET_1_2_1_0_5_6 
-- Piano emergenza  Applicabilità, DOMINIO E CORRELAZIONE
--    1.2.1.0.5.6 - ITU_EmergencyPlan -     Esistenza del Piano di Emergenza (Galleria) 
-- Procedura Modificata con il Reg.777/2019 e il 15/03/2021 modificata l'applicabilità: se la galleria è minore di 1000m non è applicabile
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_1_0_5_6 (n_controllo        In Number,
                            id_op              In Varchar2,
                            id_op_tunnel       In Varchar2,
                            id_dtp             In Varchar2,
                            n_controllo_padre  In Number,
                            p_error_split     Out Number)           Is
       n_parametro          Number;
       s_val_new_1          Varchar2 (1000);
       s_val_new_2          Varchar2 (1000);
       s_val_new_AP         Varchar2 (1000);
       s_val_old_ok_1       Varchar2 (1000);
       n_ok_dominio         Number;                               --variabile appoggio esistenza valore in dominio 0/1
       n_controllo_old_ok_1 Number;
       n_errore             Number;
       d_definizione        Varchar2 (1000);
       s_stringa_dominio    Varchar2 (1000);                      --stringa concatenata del dominio
       m_min                Number;                               --variabile di appoggio per il commento
       m_max                Number;                               --variabile di appoggio per il commento
       n_ok_AP              Number;                               --variabile appoggio applicabilità 0/1
       NYA                  Number;
       l_lungh              Number;
       CONTA_MULTIPLO       Number;

 BEGIN                                                        -- 1.2.1.0.5.6 piano emergenza Applicabilità, DOMINIO E CORRELAZIONE

--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;    
--
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);  
--
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.6');
--
      GetOldNewValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_6', id_op_tunnel, s_val_new_1, s_val_old_ok_1);
--
--    verifica se il parametro accetta valori NYA
      NYA:= GetNYA (n_parametro);
--
--    1.2.1.0.5.5_Lunghezza della galleria
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_5', id_op_tunnel);
--
--    legge l'applicabilità del parametro 1.2.1.0.5.6 nella tabella RINF_LAVORAZIONE_EVO.GALLERIE_BINARI_PO (campo chiave: PO_TR_TUNNEL_1_2_1_0_5_2)
      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_6_AP', id_op_tunnel);
--
--> ******   aggiunto temporaneamente per gestire i messaggi di errore al territorio nel frattempo che In.Rete corregga il dato ******
      If s_val_new_AP = 'N' And s_val_new_1 = 'N' Then 
	     s_val_new_1 := Null;
	  End If;
--
--    Verifica che l'applicabilità e il valore siano coerenti (AP=Y e valore not null / AP=N e valore null)--> n_ok_AP=1 altrimenti =0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);


--    Se il codice di ritorno SET_1_2_1_0_5_5 = 0 - lunghezza della galleria (1.2.1.0.5.5)
      If n_controllo_padre = 0 Then


--         se l'applicabilità del parametro 1.2.1.0.5.6 = Y ed coerente con il valore (not null) legge se in RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO 
--         il valore acquisito è presente: n_ok_dominio = 1, altrimenti = 0
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                 n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--               dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ok_AP --> n_ok_dominio: '||n_ok_dominio);		
--
--               altrimenti se l'applicabilità del parametro 1.2.1.0.5.6 = N ed è coerente con il valore (null): n_ok_dominio = 1
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
--				
--             dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ko_AP --> n_ok_dominio = 1');	
           Else 	                   --> aggiunto per tutti gli altri casi 
			    n_ok_dominio := 0;     --> (non era previsto)
           End If; 
--             dbms_output.put_line ('n_ok_dominio (end if): '||n_ok_dominio);	
--
--         Valorizzazione del flag "N_ERRORE": 0-errore, 1-OK
--         Se l'applicabilità e il valore del parametro 1.1.1.1.8.9 sono coerenti
           If n_ok_AP = 1 Then
 --               dbms_output.put_line ('n_ok_AP = 1 ');	
                If n_ok_dominio = 1 Then      -- se anche il valore è compreso nell'elenco dei valori ammessi [S]/[N]
--                   dbms_output.put_line ('n_ok_AP = 1 e n_ok_dominio = 1');
--                   se la lunghezza della galleria è inferiore a 1000m e il parametro è diverso da null
                     If (s_val_new_2 <= 1000 And s_val_new_1 Is Not Null) Then                                -- Per richiesta di Schillaci (evitare le anomalie per il territotio con la regola modficata)
 --                        dbms_output.put_line ('lungh. galleria < 1000m ma il valore del parametro è not null - ERRORE'); -- errore
					      n_errore := 0;
                     Elsif (s_val_new_2 > 1000 And s_val_new_1 Is Null) Then 
					      n_errore := 0;
 --                         dbms_output.put_line ('lungh.galleria >= 1000m e valore del parametro null- ERRORE');
                     Else n_errore := 1;
 --                         dbms_output.put_line ('lungh.galleria < 1000m e valore del parametro è null o lungh.galleria >= 1000m e valore del parametro not null- OK'); -- ok
                     End If; 
                Else n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
 --         dbms_output.put_line ('n_errore: '||n_errore);


          SetControlDetails(
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA = 1 
					     Then 1
                         Else n_errore
                    End,
                    6,
                    Case
                         When n_errore = 0 And  s_val_new_2 >= 1000 Then 'Se '||GetParametro(148, 'lunghezza')||' è maggiore o uguale a 1000 m, il parametro deve essere valorizzato '||GetCorrectRangeStringPURA(149)
   --                       When n_ok_dominio = 0 And s_val_new_2 < 1000 And s_val_new_1 <> 'N' Then 'Parametro non valorizzato per effetto della regola automatica applicata'    --aggiunto con mail Schillaci del 21/06/2016
                         When s_val_new_2 Is Null Then 'Parametro non valutabile in quanto presente un errore su '||GetParametro(148,'lunghezza')           --aggiunto 21/06/2016 per gestire il caso in cui arrivasse una galleria senza lunghezza (praticamente impossibile)
                         When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                         When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null  Then 'Se '||GetParametro(148,'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
--                          When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 <> 'N'  Then 'Se '||GetParametro(50,'lunghezza')||' è minore di 1000 m, il parametro può assumere solo il valore [N]'
                       --17/05/2016  modificato secondo accordi riunione
                       --When n_ok_dominio = 0 And s_val_new_2<1000 Then 'Se '||GetParametro(148,'lunghezza')||' minore di 1000 m deve essere '|| GetValueFromCode (n_parametro, 'N')
                       --When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       --When n_errore = 0 And  s_val_new_2 <1000 And s_val_new_1<>'N' Then 'Se '||GetParametro(148,'lunghezza')||' minore di 1000 m deve essere '|| GetValueFromCode (n_parametro, 'N')
                         Else Null
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1  Then 0
                     End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore+1, 2);                               

      Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                         Else 0
                    End,
                    14,                 --fallito padre
 --                   MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    GetMessFallitoPadreSingolo(148),                                           ---> 'Lunghezza galleria' 
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                    End);

           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_5_6: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_5_6;
--
*****************************/
-- ------------------------------------------------------------------------------------------------
--                        PROCEDURE SET_1_2_1_0_5_6 
-- Piano emergenza  Applicabilità, DOMINIO E CORRELAZIONE
--    1.2.1.0.5.6 - ITU_EmergencyPlan -     Esistenza del Piano di Emergenza (Galleria) 
-- Procedura Modificata con il Reg.777/2019 e il 15/03/2021 modificata l'applicabilità: se la galleria è minore di 1000m non è applicabile
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_2_1_0_5_6 (n_controllo        In Number,
                            id_op              In Varchar2,
                            id_op_tunnel       In Varchar2,
                            id_dtp             In Varchar2,
                            n_controllo_padre  In Number,
                            p_error_split     Out Number)           Is
       n_parametro          Number;
       s_val_new_1          Varchar2 (1000);
       s_val_new_2          Varchar2 (1000);
       s_val_new_AP         Varchar2 (1000);
       s_val_old_ok_1       Varchar2 (1000);
       n_ok_dominio         Number;                               --variabile appoggio esistenza valore in dominio 0/1
       n_controllo_old_ok_1 Number;
       n_errore             Number;
       d_definizione        Varchar2 (1000);
       s_stringa_dominio    Varchar2 (1000);                      --stringa concatenata del dominio
       m_min                Number;                               --variabile di appoggio per il commento
       m_max                Number;                               --variabile di appoggio per il commento
       n_ok_AP              Number;                               --variabile appoggio applicabilità 0/1
       NYA                  Number;
       l_lungh              Number;
       CONTA_MULTIPLO       Number;

 BEGIN                                                        -- 1.2.1.0.5.6 piano emergenza Applicabilità, DOMINIO E CORRELAZIONE

--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;    
--
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_op);  
--
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.6');
--
      GetOldNewValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_6', id_op_tunnel, s_val_new_1, s_val_old_ok_1);
--
--    verifica se il parametro accetta valori NYA
      NYA:= GetNYA (n_parametro);
--
--    1.2.1.0.5.5_Lunghezza della galleria
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_5', id_op_tunnel);
--
--     legge se in RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO il valore acquisito del parametro è presente nell'elenco: n_ok_dominio = 1, altrimenti = 0
      n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--
--    Se il codice di ritorno SET_1_2_1_0_5_5 = 0 - lunghezza della galleria (1.2.1.0.5.5)
      If n_controllo_padre = 0 Then
--
--          modificato il controllo sulla base delle indicazioni di Schillaci del 12/03/2021 - se Lungh. galleria < 1000m e valore = 'N' nessuna anomalia!
            If n_ok_dominio = 1  Then
 /****
                    If  (s_val_new_2 < 1000 And s_val_new_1 = 'N')   Or         --17/05/2016  modificato secondo accordi riunione
 --                   If    (s_val_new_2 <1000 And s_val_new_1 is not null) Or
                        (s_val_new_2 >= 1000 And ( (s_val_new_1 = 'S') Or (s_val_new_1 = 'N') ) )
                     Then n_errore := 1;
                     Else n_errore := 0;
                     End If; 
            Else n_errore := 0;
            End If; 
***/
                If s_val_new_2 >= 1000 Then
		             If s_val_new_1 Is Not Null                   --> lungh. galleria > 1000m e piano emerg. not null (S o N)
                          Then n_errore := 1;    
                          Else n_errore := 0;  
                     End If;							   
                Else                                   
	               	If s_val_new_1 = 'N'       --> lungh. galleria < 1000m e piano emerg. = N
                          Then n_errore := 1;    
                          Else n_errore := 0;  
                     End If;		
                End If; 
          Else                                    -- il valore non è valido 
		        n_errore := 0;
          End If; 

          SetControlDetails(
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA = 1 
					     Then 1
                         Else n_errore
                    End,
                    6,
                    Case
                         When n_errore = 0 And s_val_new_2 >= 1000 Then 'Se '||GetParametro(148, 'lunghezza')||' è maggiore o uguale a 1000 m, il parametro deve essere valorizzato '||GetCorrectRangeStringPURA(149)
   --                       When n_ok_dominio = 0 And s_val_new_2 < 1000 And s_val_new_1 <> 'N' Then 'Parametro non valorizzato per effetto della regola automatica applicata'    --aggiunto con mail Schillaci del 21/06/2016
                         When s_val_new_2 Is Null Then 'Parametro non valutabile in quanto presente un errore su '||GetParametro(148, 'lunghezza')           --aggiunto 21/06/2016 per gestire il caso in cui arrivasse una galleria senza lunghezza (praticamente impossibile)
                         When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
      --                   When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null  Then 'Se '||GetParametro(148,'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 <> 'N'  Then 'Se '||GetParametro(148, 'lunghezza')||' è minore di 1000 m, il parametro può assumere solo il valore [N]'
                       --17/05/2016  modificato secondo accordi riunione
                       --When n_ok_dominio = 0 And s_val_new_2<1000 Then 'Se '||GetParametro(148,'lunghezza')||' minore di 1000 m deve essere '|| GetValueFromCode (n_parametro, 'N')
                       --When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       --When n_errore = 0 And  s_val_new_2 <1000 And s_val_new_1<>'N' Then 'Se '||GetParametro(148,'lunghezza')||' minore di 1000 m deve essere '|| GetValueFromCode (n_parametro, 'N')
                         Else Null
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1 Then 0
                     End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore+1, 2);                               

      Else  SetControlDetails (
                    n_controllo,
                    id_op,
                    id_op_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                         Else 0
                    End,
                    14,                 --fallito padre
 --                   MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    GetMessFallitoPadreSingolo(148),                                           ---> 'Lunghezza galleria' 
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                    End);

           p_error_split := 1;                        --in p_error 1 è errato (al contrario di n_errore)
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_1_0_5_6: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_5_6;
--
-- ------------------------------------------------------------------------------------------------
--               Procedure SET_1_2_1_0_5_7 (150) - NCT 
-- 1.2.1.0.5.7 - TU_FireCatReq - Categoria di sicurezza antincendio richiesta per il materiale rotabile 
-- Il parametro è applicabile per gallerie aventi lunghezza maggiore o uguale a 1000 m. -  AP+DOMINIO+CORRELAZIONE
-- valori possono essere solo: [A], [B], [Nessuna/none] 
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_5_7 (n_controllo       In     Number,
                             id_op             In     Varchar2,
                             id_op_tunnel      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split    Out     Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      m_min                  Number;                            -- variabile di appoggio per il commento
      m_max                  Number;                            -- variabile di appoggio per il commento
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      NYA                    Number;
      l_lungh                Number;
 BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.7');
--
      GetOldNewValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_7', id_op_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_7_AP', id_op_tunnel);
--    1.2.1.0.5.5 - Lunghezza della galleria
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_5', id_op_tunnel);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

--      Select count (*) into conta_multiplo                                                                                -- eliminati da SAL 29/10/2015
--      from RINF_LAVORAZIONE_EVO.DICHIARAZIONI_GALLERIE_BIN_PO
--      where PO_TR_TUNNEL_1_2_1_0_5_2 = id_op_tunnel
--      And TIPO_DICHIARAZIONE = 'EC'
--      And PO_TR_TUNNEL_1_2_1_0_5_3O4_AP = 'N';

      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (s_val_new_2 < 1000 And s_val_new_1 Is Not Null)
--                    Or (s_val_new_2 >= 1000 And conta_multiplo <>0 And nvl(s_val_new_1,0) <>'none')  -- eliminati da SAL 29/10/2015
                     Then n_errore := 0;
                     Else n_errore := 1;
                     End If; 
                Else  n_errore := 0;
                End If; 
           Else   n_errore := 0;
           End If; 

           SetControlDetails(
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null Then 'Se'||GetParametro(148,'lunghezza')||' è minore di 1000, il parametro non deve essere valorizzato'
--                          When n_errore = 0 And s_val_new_2 >= 1000 And conta_multiplo <>0 And nvl(s_val_new_1,0) <>'none' Then 'Se '||GetParametro(148,'lunghezza')||' maggiore o uguale a 1000 m e se '||GetParametro(146,'Dichiarazioni EC')||' non esistono, il valore deve essere '||GetValueFromCode (n_parametro, 'none')             -- eliminati da SAL 29/10/2015
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(148),---------------------------------------------------------------> 'Lunghezza galleria'' --eliminata correlazione con Dichiarazione EC gallerie da Galli 29/10/2015
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('SET_1_2_1_0_5_7 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_1_0_5_7;
--
-- ------------------------------------------------------------------------------------------------
--                Procedure SET_1_2_1_0_5_8 (151) - AP+DOMINIO - NCT
-- 1.2.1.0.5.8 - ITU_NatFireCatReq - Categoria di sicurezza antincendio nazionale richiesta per il materiale rotabile
-- Categorizzazione della modalità con cui un treno passeggeri con un incendio a bordo può
-- proseguire la marcia per un periodo di tempo determinato, conformemente alle regole nazionali
-- laddove esistono.
-- Il parametro è applicabile per gallerie aventi lunghezza maggiore o uguale a 1000 m e quando il parametro 1.2.1.0.5.7 è
-- valorizzato con “nessuna”.
-- Quando applicabile, il valore del presente parametro è sempre: “nessuna categoria specifica richiesta”. [NC]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_5_8 (n_controllo       In     Number,
                             id_op             In     Varchar2,
                             id_op_tunnel      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split    Out     Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      m_min                  Number;                            -- variabile di appoggio per il commento
      m_max                  Number;                            -- variabile di appoggio per il commento
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      NYA                    Number;
      l_lungh                Number;
 BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.8');
--
      GetOldNewValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_8', id_op_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_8_AP', id_op_tunnel);
--    1.2.1.0.5.5
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_5', id_op_tunnel);
--    1.2.1.0.5.7
      s_val_new_3 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_7', id_op_tunnel);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
	       Else 
                n_ok_dominio := 0;
           End If; 

--              If s_val_new_1 is not null                                          sospeso con mail Galli 27/08/2015
--              Then n_errore:=0;
--              Else n_errore:=1;
--              End If; 
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                    If (s_val_new_2 < 1000 And s_val_new_1 Is Not Null)
                    Or (s_val_new_2 >= 1000 And s_val_new_3 = 'none' And s_val_new_1 Is Null)
                    Or (s_val_new_2 >= 1000 And s_val_new_3 <> 'none' And s_val_new_1 Is Not Null) Then
                         n_errore:=0;
                    Else n_errore:=1;
                End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(148, 'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_3 = 'none' And s_val_new_1 Is Null Then 'Se'||GetParametro(148, 'lunghezza')||' è maggiore o uguale a 1000 m e '||GetParametro(150, 'Categoria sicurezza antincEndio')||' è '||GetValueFromCode (150, 'none')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_3 <> 'none' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(148, 'lunghezza')||' è maggiore o uguale a 1000 m e '||GetParametro(150, 'Categoria sicurezza antincEndio')||' è diversa da '||GetValueFromCode (150, 'none')||', il parametro non deve essere valorizzato'
--                        sospeso con mail Galli 27/08/2015
--                        When n_ok_dominio = 0 Then 'Il parametro deve essere sempre non applicabile'--'GetCorrectRangeString (n_parametro)
--                        When n_errore=0 And s_val_new_1 is not null Then 'Il parametro deve essere sempre non applicabile'
                        Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                    GetMessFallitoPadreSingolo(150), --------------------------------------------->''Categoria Sicurezza AntincEndio per Materiale Rotabile''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (148), ---------------------------------------->''Lunghezza galleria''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo (148), ---------------------------------------->''Lunghezza galleria''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(150), --------------------------------------------->''Categoria Sicurezza AntincEndio per Materiale Rotabile''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('SET_1_2_1_0_5_8 - Errore: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_5_8;
--
-- ------------------------------------------------------------------------------------------------
--                          Procedure SET_1_2_1_0_5_9 (350) [S/N] - AP + Dominio + Correlazione
-- 1.2.1.9.5.9 - TU_DieselThermAllowed - Trazione diesel o altri sistemi di trazione termica consentiti
-- Indicazione se sia consentito utilizzare la trazione diesel o altri sistemi di trazione termica in galleria
-- Per RFI il parametro risulta sempre non applicabile, in quanto non esistono norme o prescrizioni che limitino l’utilizzo della
-- trazione diesel o di altri sistemi di trazione termica all’interno delle gallerie.
-- N.B.  Questo parametro deve essere sempre valorizzato [non applicabile] Tuttavia (Application Guide):
-- ‘N’=not applicable shall be selected when respective national rules do not exist
--  Y only for tunnels when for the parameter 1.2.1.0.5.7 the option ‘none’ was selected
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_2_1_0_5_9 (n_controllo       In     Number,
                             id_op             In     Varchar2,
                             id_op_tunnel      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split    Out     Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      m_min                  Number;                            -- variabile di appoggio per il commento
      m_max                  Number;                            -- variabile di appoggio per il commento
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      NYA                    Number;
      l_lungh                Number;
 BEGIN
-- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
-- Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_op);    
-- Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_2_D', id_op_tunnel);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.1.0.5.9');
--
      GetOldNewValue ('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_9', id_op_tunnel, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_9_AP', id_op_tunnel);
--    1.2.1.0.5.5
      s_val_new_2 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_5', id_op_tunnel);
--    1.2.1.0.5.7
      s_val_new_3 := GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2', 'PO_TR_TUNNEL_1_2_1_0_5_7', id_op_tunnel);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
	       Else 
                n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                    If (s_val_new_2 < 1000 And s_val_new_1 Is Not Null)
                    Or (s_val_new_2 >= 1000 And s_val_new_3 = 'none' And s_val_new_1 Is Null)
                    Or (s_val_new_2 >= 1000 And s_val_new_3 <> 'none' And s_val_new_1 Is Not Null) Then
                         n_errore:=0;
                    Else n_errore:=1;
                End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 < 1000 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(148, 'lunghezza')||' è minore di 1000 m, il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_3 = 'none' And s_val_new_1 Is Null Then 'Se'||GetParametro(148, 'lunghezza')||' è maggiore o uguale a 1000 m e '||GetParametro(150, 'Categoria sicurezza antincEndio')||' è '||GetValueFromCode (150, 'none')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 >= 1000 And s_val_new_3 <> 'none' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(148, 'lunghezza')||' è maggiore o uguale a 1000 m e '||GetParametro(150, 'Categoria sicurezza antincEndio')||' è diversa da '||GetValueFromCode (150, 'none')||', il parametro non deve essere valorizzato'
--                        sospeso con mail Galli 27/08/2015
--                        When n_ok_dominio = 0 Then 'Il parametro deve essere sempre non applicabile'--'GetCorrectRangeString (n_parametro)
--                        When n_errore=0 And s_val_new_1 is not null Then 'Il parametro deve essere sempre non applicabile'
                        Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                    GetMessFallitoPadreSingolo(150), --------------------------------------------->''Categoria Sicurezza AntincEndio per Materiale Rotabile''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (148), ---------------------------------------->''Lunghezza galleria''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo (148), ---------------------------------------->''Lunghezza galleria''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_op,
                     id_op_tunnel,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(150), --------------------------------------------->''Categoria Sicurezza AntincEndio per Materiale Rotabile''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         Dbms_Output.Put_Line ('SET_1_2_1_0_5_9 - Errore: '||Substr(Sqlerrm, 1, 250));
   End SET_1_2_1_0_5_9;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SetControlOPTunnel (n_controllo    IN     Number,    --procedura per il controllo dei parametri di OP TUNNEL
                                 id_op         IN     Varchar2,
                                 id_op_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 p_error           OUT Number)
   IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_code_new_1   Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_code_new_2    Varchar2 (1000);
      s_val_new_AP Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      s_valore_A Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      s_valore_B Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      s_valore_C Varchar2 (1000);           --copia il valore INQ da usare nei commenti
      m_min Number;                                 --variabile di appoggio per il commento
      m_max Number;                                 --variabile di appoggio per il commento
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      NYA Number;
      l_lungh  Number;
      p_error_split Number;                 --serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)
      p_error_union Number;
      p_error_1_2_1_0_5_3 Number;
      p_error_1_2_1_0_5_5 Number;
      p_error_1_2_1_0_5_7 Number;

   BEGIN
     p_error := 0;

     n_controllo_old_ok_1:=GetCorrectControlId(id_op);    --Recupero il codice del controllo del dato pubblicato

     d_definizione:=GetParameterValue('GALLERIE_BINARI_PO', 'PO_TR_TUNNEL_1_2_1_0_5_2','PO_TR_TUNNEL_1_2_1_0_5_2_D',id_op_tunnel);     --Recupero la definizione dell'oggetto

     -- 1.2.1.0.5.1 Codice del GI  OBBLIGATORIO
     SET_1_2_1_0_5_1 (n_controllo,  id_op, id_op_tunnel,   id_dtp, 0, p_error_split);

      --1.2.1.0.5.2 ID galleria

     -- 1.2.1.0.5.3 Dichiarazione GALL PO EC FORMATO E APP                             parametro con tabella multipla a parte
     SET_1_2_1_0_5_3 (n_controllo,  id_op, id_op_tunnel,   id_dtp, 0, p_error_split);                         
	 p_error_1_2_1_0_5_3 := p_error_split;

     -- 1.2.1.0.5.4  Dichiarazione GALL PO  EI FORMATO E APP                             parametro con tabella multipla a parte
     SET_1_2_1_0_5_4 (n_controllo,  id_op, id_op_tunnel,   id_dtp, 0, p_error_split);

     -- 1.2.1.0.5.5 Lungh. galleria         maggiore 100 m (inutile) e lunghezza digit 5
     SET_1_2_1_0_5_5 (n_controllo,  id_op, id_op_tunnel,   id_dtp, 0, p_error_split);                       
	 p_error_1_2_1_0_5_5 := p_error_split;

     --1.2.1.0.5.6 Piano emergenza
     SET_1_2_1_0_5_6 (n_controllo,  id_op, id_op_tunnel,   id_dtp, p_error_1_2_1_0_5_5, p_error_split);

     --1.2.1.0.5.7 Antincen.m.r. AP+DOMINIO+CORRELAZIONE
     --eliminato da SAL Galli 29/10/2015 p_error_UNION:=GREATEST (p_error_1_2_1_0_5_3,p_error_1_2_1_0_5_5);                            -- dipende da due padri, quindi faccio la sintesi tra i due errori dei padri (se almeno uno è 1, il controllo sul figlio deve fallire)
     SET_1_2_1_0_5_7 (n_controllo,  id_op, id_op_tunnel,   id_dtp, p_error_1_2_1_0_5_5, p_error_split);       
	 p_error_1_2_1_0_5_7 := p_error_split;

     --1.2.1.0.5.8 Naz.antincen. m.r. AP+DOMINIO
     SET_1_2_1_0_5_8 (n_controllo,  id_op, id_op_tunnel,   id_dtp, p_error_1_2_1_0_5_7, p_error_split);

     --1.2.1.0.5.9 TrazioneDiesel o altri sistemi di trazione termica consentiti. AP+DOMINIO+correlazione
     SET_1_2_1_0_5_9 (n_controllo,  id_op, id_op_tunnel,   id_dtp, p_error_1_2_1_0_5_7, p_error_split);

  EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line   ('Errore - SetControlOPTunnel: '||Substr(Sqlerrm, 1, 250));
   End SetControlOPTunnel;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_2_2_0_5_1 (n_controllo    IN     Number,
                                 id_op_sd         IN     Varchar2,
                                 id_op_sd_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_AP Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      m_min Number;                                 --variabile di appoggio per il commento
      m_max Number;                                 --variabile di appoggio per il commento
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      NYA Number;
      l_lungh  Number;
      CONTA_MULTIPLO Number;

       BEGIN
       -- 1.2.2.0.5.1 Codice del GI OBBLIGATORIO

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op_sd);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('GALLERIE_RACCORDO_PO', 'PO_SD_TUNNEL_1_2_2_0_5_2','PO_SD_TUNNEL_1_2_2_0_5_2_D',id_op_sd_tunnel);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.5.1');

      GetOldNewValue('GALLERIE_RACCORDO_PO', 'PO_SD_TUNNEL_1_2_2_0_5_2','PO_SD_TUNNEL_1_2_2_0_5_1',id_op_sd_tunnel, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

         If n_controllo_padre = 0 Then

          n_errore := GetCorrectValue (n_parametro, s_val_new_1);

          SetControlDetails (
                    n_controllo,
                    id_op_sd,
                    id_op_sd_tunnel,
                    n_parametro,
                    d_definizione,
                     Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    4,
                    Case
                       When n_errore = 0 Then GetCorrectRangeStringObbl (n_parametro)
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op_sd,
                    id_op_sd_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_5_1: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_2_0_5_1;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_2_2_0_5_3 (n_controllo    IN     Number,
                                 id_op_sd         IN     Varchar2,
                                 id_op_sd_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;       --serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO

       BEGIN
       --1.2.2.0.5.3  Dichiarazione GALL SD EC FORMATO E APP                             parametro con tabella multipla a parte

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op_sd);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('GALLERIE_RACCORDO_PO', 'PO_SD_TUNNEL_1_2_2_0_5_2','PO_SD_TUNNEL_1_2_2_0_5_2_D',id_op_sd_tunnel);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.5.3');

      NYA:= GetNYA (n_parametro);

      GetOldNewValueMultiploDICH('DICHIARAZIONI_GALLERIE_SD_PO', 'PO_SD_TUNNEL_1_2_2_0_5_2','PO_SD_TUNNEL_1_2_2_0_5_3O4','PO_SD_TUNNEL_1_2_2_0_5_3O4_AP',id_op_sd_tunnel,'EC', valori_multipli) ;           --multiplo

      n_errore:=1;              --inizializzo l'errore per poterlo puoi valorizzare nel loop

      FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;

          If n_controllo_padre = 0 Then

                  If VALORI_MULTIPLI%FOUND Then
                      LOOP

                            n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);

                             If n_ok_AP = 1
                            Then
                                        If (s_val_new_1 = ' ')
                                        OR (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)
                                        Then n_errore:=GREATEST(n_errore,1);                           --se mi fallisce un parametro multiplo, fallisce il controllo
                                        Else n_errore:=LEAST(n_errore, 0);
                                        End If; 
                              Else n_errore := 0;
                            End If; 

                      SetControlDetails(
                                n_controllo,
                                id_op_sd,
                                id_op_sd_tunnel,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                7,
                                Case
                                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                       When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                                       Else
                                          NULL
                                    End,
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                      Case
                                            When n_errore = 0 And NYA=0 Then 0
                                            When n_errore = 0 And NYA=1 Then 1
                                            When n_errore = 1  Then 0
                                       End);

                        FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;
                        EXIT When VALORI_MULTIPLI%NOTFOUND;

                       End LOOP;

                   Else
                   n_errore:=0;                 --se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella

                    SetControlDetails(
                            n_controllo,
                            id_op_sd,
                            id_op_sd_tunnel,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_CE||'galleria di binario di raccordo di PO'
                               Else NULL
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                                  Case
                                    When n_errore = 0 And NYA=0 Then 0
                                    When n_errore = 0 And NYA=1 Then 1
                                    When n_errore = 1  Then 0
                               End);
                   End If; 


           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op_sd,
                    id_op_sd_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 

       CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_5_3: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_2_0_5_3;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_2_2_0_5_4 (n_controllo    IN     Number,
                                 id_op_sd         IN     Varchar2,
                                 id_op_sd_tunnel   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;       --serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO

       BEGIN
       --1.2.2.0.5.4  Dichiarazione GALL SD EI FORMATO E APP                             parametro con tabella multipla a parte

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_op_sd);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('GALLERIE_RACCORDO_PO', 'PO_SD_TUNNEL_1_2_2_0_5_2','PO_SD_TUNNEL_1_2_2_0_5_2_D',id_op_sd_tunnel);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.2.2.0.5.4');

      NYA:= GetNYA (n_parametro);

      GetOldNewValueMultiploDICH('DICHIARAZIONI_GALLERIE_SD_PO', 'PO_SD_TUNNEL_1_2_2_0_5_2','PO_SD_TUNNEL_1_2_2_0_5_3O4','PO_SD_TUNNEL_1_2_2_0_5_3O4_AP',id_op_sd_tunnel,'EI', valori_multipli) ;           --multiplo

      n_errore:=1;              --inizializzo l'errore per poterlo puoi valorizzare nel loop

      FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;

          If n_controllo_padre = 0 Then

                  If VALORI_MULTIPLI%FOUND Then
                      LOOP

                            n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);

                            If n_ok_AP = 1
                            Then
                                        If (s_val_new_1 = ' ')
                                        OR (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)
                                        Then n_errore:=GREATEST(n_errore,1);                           --se mi fallisce un parametro multiplo, fallisce il controllo
                                        Else n_errore:=LEAST(n_errore, 0);
                                        End If; 
                              Else n_errore := 0;
                            End If; 

                      SetControlDetails(
                                n_controllo,
                                id_op_sd,
                                id_op_sd_tunnel,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                7,
                                Case
                                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                       When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                                       Else
                                          NULL
                                    End,
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                      Case
                                            When n_errore = 0 And NYA=0 Then 0
                                            When n_errore = 0 And NYA=1 Then 1
                                            When n_errore = 1  Then 0
                                       End);

                        FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;
                        EXIT When VALORI_MULTIPLI%NOTFOUND;

                       End LOOP;

                   Else
                   n_errore:=0;                 --se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella

                    SetControlDetails(
                            n_controllo,
                            id_op_sd,
                            id_op_sd_tunnel,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_IE||'galleria di binario di raccordo di PO'
                               Else NULL
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                                  Case
                                    When n_errore = 0 And NYA=0 Then 0
                                    When n_errore = 0 And NYA=1 Then 1
                                    When n_errore = 1  Then 0
                               End);
                   End If; 


           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_op_sd,
                    id_op_sd_tunnel,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 

       CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore SET_1_2_2_0_5_4: '||Substr(Sqlerrm, 1, 250));
  End SET_1_2_2_0_5_4;
--
