-- ------------------------------------------------------------------------------------------------
--                          PROCEDURE SET_1_1_1_1_2_3 
--    1.1.1.1.2.3 - Parte di un Corridoio Ferroviario Merci (RFC: Rail Freight Corridor) -- APPLICABILITA'
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_2_3 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split    Out  Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                    -- stringa concatenata del dominio
      NYA                    Number;                             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);  -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;           -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO         Number;           -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol); 
--
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.3');
--
      NYA := GetNYA (n_parametro);
--    multiplo
--    GetOldNewValueMultiplo('CORRIDOIO_SOL', 'SEDE_TECNICA','CODICE_CORRIDOIO',id_sol_track, valori_multipli) ;           
--    procedura ad hoc per le linee merci
      GetOldNewValueCorrMerciSOL(id_sol_track, valori_multipli);                               
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_1_2_3_AP', id_sol_track);
--
--    IPOTESI: se PIC ci manda le associazioni allora appartiene a corridoi; se PIC non ce le manda, non appartiene a corridoi
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;          

      If n_controllo_padre = 0 Then
--        Se esistono valori, ossia PIC ci manda associazioni della sede tecnica a corridoi, si esegue il controllo sull'applicabilità
           If VALORI_MULTIPLI%FOUND Then     
--> loop 
		      Loop
--                Dbms_Output.Put_Line(s_val_new_1||' '||s_val_old_ok_1);
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

--              If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
--                   Then   n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--              Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
--                   Then  n_ok_dominio := 1;
--              End If; 
--
                n_errore := n_ok_AP;

                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          5,      --ex 12
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End );

                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                 Exit When VALORI_MULTIPLI%NOTFOUND;
--> end loop
              End Loop;

           Else 
-- Se non esistono valori, ossia PIC non ci mAnda associazioni della sede tecnica a corridoi, vuol dire che non ha corridoio associato e il cursore va in NOTFOUND
-- e nel dettaglio verrà inserito un record con dato vuoto. Non si fa il controllo del caso in cui si avesse valorizzato il parametro 1.1.1.1.2.3 
-- e AP=Y (si spera che questo caso non possa mai avvenire perchè la valorizzazione dell'applicabilità dovrebbe escluderlo)
-- Per ovviare a questo problema si inserisce questo ciclo (ridondante ma di sicurezza)
                If s_val_new_AP = 'N'  Then             --se NOTFOUND e AP = N è tutto ok
                     n_errore := 1;
--             
                     SetControlDetails(
                               n_controllo,
                               id_sol,
                               id_sol_track,
                               n_parametro,
                               d_definizione,
                               Case When NYA = 1 
			     			        Then 1
                                    Else n_errore
                               End,
                               5,
                               Null,--non si inserisce l'anomalia perchè è corretto che, se non trova associazione PIC, viene considerato non appartenente a corridoi
                               s_val_new_1,
                               s_val_old_ok_1,
                               n_controllo_old_ok_1,
                               Case When n_errore = 0 And NYA = 0 Then 0
                                    When n_errore = 0 And NYA = 1 Then 1
                                    When n_errore = 1             Then 0
                               End);

                Else --se NOTFOUND e AP <> N non è tutto ok; a rigor di logica NON dovrebbe mai entrare in questo ciclo
                     n_errore:=0;

                     SetControlDetails(
                               n_controllo,
                               id_sol,
                               id_sol_track,
                               n_parametro,
                               d_definizione,
                               Case When  NYA=1 Then 1
                               Else n_errore
                               End,
                               5,
                               s_commento_AP_ok,       --il commento dice che ci deve essere un errore nell'applicabilità, cioè sarà Y ma il valore è nullo, cosa sbagliata
                               s_val_new_1,
                               s_val_old_ok_1,
                               n_controllo_old_ok_1,
                               Case When n_errore = 0 And NYA = 0 Then 0
                                    When n_errore = 0 And NYA = 1 Then 1
                                    When n_errore = 1             Then 0
                               End);
                End If; 

           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When  NYA=1 Then 1
                             When n_controllo_padre = 1 Then 1
                     Else 0
                     End,
                     14,                                      -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--        in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_2_3: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_3;
--
-- ------------------------------------------------------------------------------------------------
--                     Procedure SET_1_1_1_1_2_4_MULT
-- 1.1.1.1.2.4 Capacità carico ---> parte seconda: DOMINIO + CORRELAZIONE - parametro con tabella multipla a parte
/**
-- 21/05/2021 Modificata la gestione delle anomalie: se il parametro non è valorizzato, non viene indicata l'anomalia ma l'applicabilità è sempre [NYA]

Mail Schilalci del 20/05/2021:

1)	1.1.1.1.2.2         IPP_LineCat
2)	1.1.1.1.2.4         IPP_LoadCap
3)	1.1.1.1.6.1         ILR_MaxDeceleration
4)	1.2.1.0.2.2         IPP_LineCat

i quattro parametri in questione sono tutti sempre applicabili, ovvero non esistono regole di non applicabilità.
Pertanto, per la produzione dell’xml, o arrivano valori coerenti con Look Up Value che devono essere mostrati oppure arrivano dei vuoti che si tramutano in NYA. Questo è già così e dovrà rimanere così.

Quello che vorrei avere nella fase 3 è che, seppur i parametri vengano forniti come NYA se vuoti, non ci sia l’errore nel rapporto di validazione per i depositari.
Questo perché, seppur sempre applicabili, nelle Linee Guida alla valorizzazione dei parametri RINF è stato scritto che questi parametri devono essere valorizzati solo se la tratta (o la località) ha subito una attivazione.

Abbiamo sempre mostrato gli errori su questi 4 parametri come “falsi errori”. Vorrei eliminare i “falsi errori” per avere un rapporto di validazione quanto più aderente possibile alle effettive mancanze/errori da parte delle DTP rispetto a quello che gli viene richiesto da sede centrale.

**/
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_1_2_4_MULT (n_controllo       In  Number,
                                 id_sol            In  Varchar2,
                                 id_sol_track      In  Varchar2,
                                 id_dtp            In  Varchar2,
                                 n_controllo_padre In  Number,
                                 p_error_split    Out  Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;          -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;          -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;          
      n_errore               Number;          
      d_definizione          Varchar2 (1000); 
      s_stringa_dominio      Varchar2 (1000); -- stringa concatenata del dominio
      NYA                    Number;          -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI_FIGLIO EMPCUR;          -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE FIGLIO
      CONTA_MULTIPLO         Number;          -- serve per contare se è presente un avalore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      conteggio_totale       Number;          -- variabile di conteggio sui record del parametro padre
 Begin
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.4');
--
      NYA := GetNYA(n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_1_1_1_2_4_CAP_CARICO', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4', id_sol_track, valori_multipli_figlio) ;           --multiplo figlio
--    Parametro 1.1.1.1.2.5 - velocità massima consentita sulla linea
