                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.4.1');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA(n_parametro);
--
           If n_controllo_padre = 0 Then
--
--             verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
                n_errore := GetCorrectValue(n_parametro, s_val_new_1);

                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          4,
                          Case
                               When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                               When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End);
--
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_2_4_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_4_1;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_2_4_2 (249) - Tipo Controllo: 6-Applicabilità, dominio e correlazione con altro parametro
-- 1.1.1.1.2.4.2 - Conformità delle strutture al modello di carico ad alta velocità (S/N) - Nuovo parametro - Reg.777/2019 
-- Per sezioni di linea con velocità massima consentita maggiore di 200 km/h.
-- Il parametro è applicabile quando la velocità è maggiore di 200 km/h, ovvero quando il parametro 1.1.1.1.2.5 – velocità massima consentita > 200 km/h
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_2_4_2  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.4.2');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_2_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.1.2.5 - velocità massima consentita (17)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (n_ok_ap=1) altrimenti n_ok_ap=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" (SET_1_1_1_1_2_5) è terminata correttamente
      If n_controllo_padre = 0 Then
--         Test AP 
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                   -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);   -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--         Test di Correlazione con altro parametro
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (s_val_new_2 > 200 And s_val_new_1 Is Not Null) or
 					     (s_val_new_2 <= 200 And s_val_new_1 Is Null) Then
--                      If (s_val_new_2 >= 200 And s_val_new_1 Is Not Null) or           -- 15/12/2021 richiesto con il Sal odierno 
--				           (s_val_new_2 <  200 And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                           -- valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And s_val_new_2 <= 200 And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And s_val_new_2 > 200  And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And s_val_new_2 > 200 ) Then GetCorrectRangeString (n_parametro)
 --                         When (n_errore = 0 And s_val_new_2 < 200 And s_val_new_1 Is Not Null) Then s_commento_AP_ko
 --                         When (n_errore = 0 And s_val_new_2 >= 200  And s_val_new_1 Is Null) Then s_commento_AP_ok
 --                         When (n_errore = 0 And s_val_new_2 >= 200 ) Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                 --fallito padre
                          GetMessFallitoPadreSingolo(17),--------------------------------------------->Controllo padre fallito 
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_2_4_2: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_4_2;
--
-- ------------------------------------------------------------------------------------------------
--                           Procedure SET_1_1_1_1_2_4_3_MULT 
--            1.1.1.1.2.4.3 - Localizzazione ferroviaria di strutture che richiedono verifiche specifiche (251)
-- Questo parametro è applicabile nel caso in cui sulla sezione di linea siano presenti strutture che richiedono verifiche specifiche.
-- Controllo:  AP + DOMINIO (12) - parametro con tabella multipla a parte PAR_1_1_1_1_2_4_3_LOCAVERSPEC - NCT 
-- il parametro, se applicabile, deve essere inserito nel formato [±NNNN.NNN]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_2_4_3_MULT (n_controllo       In     Number,
                                    id_sol            In     Varchar2,
                                    id_sol_track      In     Varchar2,
                                    id_dtp            In     Varchar2,
                                    n_controllo_padre In     Number,
                                    p_error_split     Out    Number   )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                                   -- Cursore Per I Valori NEW e OLD Dei Parametri In Tabella Multipli A Parte
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.4.3');
--
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_1_1_1_2_4_3_LOCAVERSPEC', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_3', id_sol_track, valori_multipli) ;  -- multiplo
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_3_AP', id_sol_track);
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

	  If s_val_new_1 = 9999.999 Then    ---> correzione per rendere il controllo AP e valore coerente con il "Non Applicabile" 19/04/2021
	       s_val_new_1 := Null;
	  End If;	  
--
      If n_controllo_padre = 0 Then

--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
			    Loop
                     n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
                     If n_ok_AP = 0 Then 
		                  n_errore := 0;
                     Else
                          If s_val_new_1 > 9999.999 
						      Then n_errore := 0;
                              Else n_errore := 1;
                          End If; 
                     End If; 
--
                     SetControlDetails
                        (     n_controllo,
                              id_sol,
                              id_sol_track,
                              n_parametro,
                              d_definizione,
                              Case When NYA = 1 Then 1
                                   Else n_errore
                              End,
                              5,
                              Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
					               When n_errore = 0 Then 'La lunghezza del parametro risulta essere maggiore di 4 cifre'
                                   Else Null
                              End,
                              s_val_new_1,
                              s_val_old_ok_1,
                              n_controllo_old_ok_1,
                              Case When n_errore = 0 And NYA = 0 Then 0
                                   When n_errore = 0 And NYA = 1 Then 1
                                   When n_errore = 1 Then 0
                              End  );
--		 
                      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                      Exit When VALORI_MULTIPLI%NotFound;

                  End Loop;
--         Se NO DATA FOUND
           Else 
               If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then --Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then --Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio :=0;
                End If; 
                    SetControlDetails
					  ( n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When NYA = 1 
						     Then 1
                             Else n_errore
                        End,
                        12,
                        Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                             Else Null
                        End,
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                        Case When n_errore = 0 And NYA = 0 Then 0
                             When n_errore = 0 And NYA = 1 Then 1
                             When n_errore = 1  Then 0
                        End
					  );
          End If; 
--        siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
          p_error_split := Mod(n_errore +1, 2);                               
--
     Else  SetControlDetails 
                  (  n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     'Valori errati',--s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End	    );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_2_4_3_MULT: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_4_3_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_2_4_4 (253) - Tipo Controllo: 4-DOMINIO (valore INTERA RETE)
-- Documento riportante la/le procedura/e per le verifiche di compatibilità statica e dinamica della tratta - Nuovo parametro - Reg.777/2019 - AP=Y
-- Il parametro assume sempre il valore [RFI DTC SI MA IFS 001 D-II-2] per l'Intera Rete RFI
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_2_4_4  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.4.4');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA(n_parametro);
--
           If n_controllo_padre = 0 Then
--
--              verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
                n_errore := GetCorrectValue(n_parametro, s_val_new_1);
--
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          4,
                          Case
                               When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                               When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
--
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := MOD(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                                           -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_2_4_4 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_4_4;


--
-- ------------------------------------------------------------------------------------------------
--             Procedure SET_1_1_1_1_2_5 - Velocità massima consentita (17) - NCT - AP=Y
-- 1.1.1.1.2.5 V. max - Controllo: DOMINIO e RANGE - Il parametro è costituito da un numero che va da 0 a 500  
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_2_5 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)     Is                   
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.5');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
--       SELECT MIN (TO_Number (valore)), MAX (TO_Number (valore))     -- blocco per la scrittura del minimo e massimo valore nel commento
--       INTO m_min, m_max                                             -- 24/05/2016 centralizzazione messaggi
--       FROM RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO
--       WHERE CODICE_PARAMETRO = n_parametro;
--
      If n_controllo_padre = 0 Then
           n_errore := GetCorrectRange (n_parametro, s_val_new_1);
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
				          Then 1
                          Else n_errore
                     End,
                     8,
                     Case
                          When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                          When n_errore = 0 Then GetMessFuoriRange(17)   --'Valore fuori range: deve essere compreso tra '|| m_min|| ' e '|| m_max||''       --24/05/2016 centralizzazione messaggi
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                                     -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_2_5 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_5;
