-- ------------------------------------------------------------------------------------------------
--                                 Procedure SET_1_1_1_1_2_7 
-- 1.1.1.1.2.7 Altitudine Max - AP=Y Controllo: LUNGHEZZA (max 4 digit: [+/-][NNNN] )
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_2_7 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number)        Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                    -- stringa concatenata del dominio
      NYA                    Number;                             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      l_lungh                Number;
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.2.7');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_1_2_7', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      l_lungh := Length(s_val_new_1);
--
      If n_controllo_padre = 0 Then
-- 
           If s_val_new_1 Is Null
                Then n_errore := 0;
                Else
--                   inserito il controllo per verificare che contenga solo numeri, benchè il dato ci arrivi come varchar da In.Rete;
--                   il controllo +/- è inserito per verificare che ci arrivi con +/- da In.Rete;
                     If GetIsNumber(s_val_new_1) = 1 And Substr(s_val_new_1, 1, 1) In ('+', '-') Then  
                          If l_lungh > 5
                               Then n_errore := 0;
                               Else n_errore := 1;
                          End If; 
--                        se non contiene numeri va in errore o non contiene +/- all'inizio
                          Else n_errore := 0;                         
                     End If; 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     1,
                     Case
                          When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                          When n_errore = 0 And l_lungh > 5 Then 'Il formato del parametro prevede obbligatoriamente [+/-] seguito da massimo 4 cifre'
                          When n_errore = 0 And GetIsNumber(s_val_new_1) = 0 Then 'Valorizzazione errata: sono ammessi solo numeri'
                          When n_errore = 0 And Substr(s_val_new_1,1,1) Not In ('+','-') Then 'Valorizzazione errata: il formato del parametro prevede obbligatoriamente [+/-] seguito da massimo 4 cifre'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio					 
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--          in p_error 1 è errato (al contrario di n_errore)
            p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_2_7: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_1_2_7;
