--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_1_3_1 - parametro cancellato
--           1.1.1.1.3.1 Sagoma interoperabile DOMINIO + CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_1 (n_controllo       In     Number,
                             id_sol            In     Varchar2,
                             id_sol_track      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split     Out    Number )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol); 
--    Recupero la definizione dell'oggetto 
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track); 
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_1_3_1', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--
      NYA:= GetNYA (n_parametro);
--
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_2', id_sol_track);
--
      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_3', id_sol_track);
--
      If n_controllo_padre = 0 Then
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);

--                  If n_errore = 1                                                                                                                 --eliminato da SAL 29/10/2015
--                  Then
--                            If       (s_val_new_1 ='G1' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='GA' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='GB' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='GC' And s_val_new_2 is null And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'G2' And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'GB1' And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'GB2' And s_val_new_3 is null)
--                                OR  (s_val_new_1 ='none' And s_val_new_2 = 'none' And s_val_new_3 = 'FS')
--                            Then n_errore := 1;
--                            Else n_errore := 0;
--                            End If; 
--                  End If; 

              SetControlDetails 
			       (    n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When  NYA=1 Then 1
                        Else n_errore
                        End,
                        7,
                        Case When n_errore = 0 /*And nvl(s_val_new_1,0) not in ('G1','GA','GB','GC','none')*/ Then GetCorrectRangeString (n_parametro)                        --eliminato da SAL 29/10/2015
                           --When n_errore = 0 Then 'Valorizzazione parametri Sagome non coerente: se questo parametro assume valore G1 o GA o GB o GC, la Sagoma Multinazionale e la Sagoma Nazionale devono essere Non Applicabili; se questo parametro assume valore Nessuna e la Sagoma Multinazionale assume valore G2 o GB1 o GB2, la Sagoma Nazionale deve essere Non Applicabile; se questo parametro e la Sagoma Multinazionale assumono valore Nessuna, la Sagoma Nazionale deve essere FS'
                            Else Null
                        End,
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                        Case When n_errore = 0 And NYA = 0 Then 0
                             When n_errore = 0 And NYA = 1 Then 1
                             When n_errore = 1  Then 0
                        End
					);
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
               p_error_split := MOD(n_errore+1, 2);                               
--
                Else  SetControlDetails 
				  (     n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When NYA = 1 Then 1
                             When n_controllo_padre = 1 Then 1
                             Else 0
                        End,
                        14,                 --fallito padre
                        MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                        Case When n_controllo_padre = 1 Then 1
                             When NYA = 0 Then 0
                             When NYA = 1 Then 1
                        End
					);
-- in p_error 1 è errato (al contrario di n_errore)
                           p_error_split := 1;
               End If; 
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_3_1: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_1;
--
-- ------------------------------------------------------------------------------------------------
--                              Procedure SET_1_1_1_1_3_2 (parametro cancellato)
--            1.1.1.1.3.2 Sagome multi DOMINIO + CORRELAZIONE + APPLICABILITA'
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_2 (n_controllo       In     Number,
                             id_sol            In     Varchar2,
                             id_sol_track      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split     Out    Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.2');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_2', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_1', id_sol_track);
--
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_3', id_sol_track);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_2_AP', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                 n_ok_dominio := 1;
           End If; 

           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If      (s_val_new_2 = 'G1' And s_val_new_1 is null    /*And s_val_new_3 is null*/ )       -- eliminato da SAL 29/10/2015
                         Or  (s_val_new_2 = 'GA' And s_val_new_1 is null    /*And s_val_new_3 is null*/ )
                         Or  (s_val_new_2 = 'GB' And s_val_new_1 is null    /*And s_val_new_3 is null*/ )
                         Or  (s_val_new_2 = 'GC' And s_val_new_1 is null    /*And s_val_new_3 is null*/ )
                         Or  (s_val_new_2 = 'none' And s_val_new_1 = 'G2'   /*And s_val_new_3 is null*/ )
                         Or  (s_val_new_2 = 'none' And s_val_new_1 = 'GB1'  /*And s_val_new_3 is null*/ )
                         Or  (s_val_new_2 = 'none' And s_val_new_1 = 'GB2'  /*And s_val_new_3 is null*/ )
                         Or  (s_val_new_2 = 'none' And s_val_new_1 = 'none' /*And s_val_new_3 = 'FS'*/ )
                     Then n_errore := 1;
                     Else n_errore := 0;
                     End If; 
                 Else  n_errore := 0;
                 End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails 
				  (  n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 Then 'Valorizzazione parametri Sagome non coerente: se '||GetParametro(21,'Sagoma Interoperabile')||' assume valore G1 o GA o GB o GC, questo parametro e '||GetParametro(23,'Sagoma Nazionale')||' devono essere Non Applicabili; se '||GetParametro(21,'Sagoma Interoperabile')||' assume valore Nessuna e questo parametro assume valore G2 o GB1 o GB2, '||GetParametro(23,'Sagoma Nazionale')||' deve essere Non Applicabile; se '||GetParametro(21,'Sagoma Interoperabile')||' e questo parametro assumono valore Nessuna, '||GetParametro(23,'Sagoma Nazionale')||' deve essere FS'
                          Else NULL
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );  
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails 
		       (     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                          -- fallito padre
                     GetMessFallitoPadreSingolo(21),--------------------------------------------------------------->''Sagoma interoperabile''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End   );
-- in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_3_2: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_2;
--
-- ------------------------------------------------------------------------------------------------
--                        Procedure SET_1_1_1_1_3_3 (parametro cancellato)
--           1.1.1.1.3.3 Sagome naz DOMINIO + CORRELAZIONE + APPLICABILITA'
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_3 (n_controllo       In     Number,
                             id_sol            In     Varchar2,
                             id_sol_track      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split     Out    Number)   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.3');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_3', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_1', id_sol_track);
--
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_2', id_sol_track);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_3_AP', id_sol_track);
--
      NYA := GetNYA (n_parametro);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP  Then 
                n_ok_dominio := GetCorrectValue(n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
			    n_ok_dominio := 1;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If     (s_val_new_2 ='G1' And s_val_new_3 Is Null And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='GA' And s_val_new_3 Is Null And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='GB' And s_val_new_3 Is Null And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='GC' And s_val_new_3 Is Null And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='none' And s_val_new_3 = 'G2' And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='none' And s_val_new_3 = 'GB1' And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='none' And s_val_new_3 = 'GB2' And s_val_new_1 Is Null)
                        Or  (s_val_new_2 ='none' And s_val_new_3 = 'none' And s_val_new_1 = 'FS')
                     Then  n_errore := 1;
                     Else  n_errore := 0;
                     End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails 
                 (   n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
                          Then 1
                          Else n_errore
                     End,
                     6,
                     Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 Then 'Valorizzazione parametri Sagome non coerente: se '||GetParametro(21,'Sagoma Interoperabile')||' assume valore G1 o GA o GB o GC, '||GetParametro(22,'Sagoma Multinazionale')||' e questo parametro devono essere Non Applicabili; se '||GetParametro(21,'Sagoma Interoperabile')||' assume valore Nessuna e '||GetParametro(22,'Sagoma Multinazionale')||' assume valore G2 o GB1 o GB2, questo parametro deve essere Non Applicabile; se '||GetParametro(21,'Sagoma Interoperabile')||' e '||GetParametro(22,'Sagoma Multinazionale')||' assumono valore Nessuna, questo parametro deve essere FS'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
-- 
              p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails 
		         (   n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(22),------------------------------------------------------------>''Sagome multinazionali''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_3_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_3;
--
-- ------------------------------------------------------------------------------------------------
--                PROCEDURE SET_1_1_1_1_3_1_1  - Nuovo parametro dal Reg.777/2019 255-SUP e 256-INF)
--     1.1.1.1.3.1.1 Sagoma - SUP e INF (Controllo: Dominio) - Sempre Applicabile
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_1_3_1_1 (n_controllo       In Number,
                              id_sol            In Varchar2,
                              id_sol_track      In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number  )    Is
       n_parametro1           Number;
       n_parametro2           Number;
       s_val_new_1            Varchar2 (1000);
       s_val_new_2            Varchar2 (1000);
       s_val_new_3            Varchar2 (1000);
       s_val_old_ok_1         Varchar2 (1000);
       s_val_new_AP           Varchar2 (1000);
       n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
       n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
       n_controllo_old_ok_1   Number;
       n_controllo_old_ok_2   Number;
       n_errore               Number;
       n_errore1              Number;
       n_errore2              Number;
       d_definizione          Varchar2 (1000);
       s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
       NYA                    Number;                           -- ritorna se è NYA = 1 o 0
--     serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
       s_val_old_ok_2         Varchar2 (1000); 
--     CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
       VALORI_MULTIPLI        EMPCUR;       
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro1 := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.1.1.SUP');
      n_parametro2 := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.1.1.INF');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_1_1_SUP', id_sol_track, s_val_new_1, s_val_old_ok_1);
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_1_1_INF', id_sol_track, s_val_new_2, s_val_old_ok_2);

--    come riferimento uso SUP: se SUP è NYA, allora considero anche INF NYA
      NYA := GetNYA(n_parametro1);   
--    verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
      n_errore1 := GetCorrectValue (n_parametro1, s_val_new_1);
      n_errore2 := GetCorrectValue (n_parametro2, s_val_new_2);

      If (n_errore1 = 1 And n_errore2 = 1) Then
          n_errore := 1;
       Else
          n_errore := 0;
      End If;		  
--
      If n_controllo_padre = 0 Then
-- SUP
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro1,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore1
                     End,
                     4,
                     Case
                          When n_errore = 0 And n_errore1 = 0 And s_val_new_1 Is Null Then 'Sagoma Superiore: Valore mancante'
                          When n_errore = 0 And n_errore1 = 0 Then GetCorrectRangeString(n_parametro1)
                          When n_errore = 0 And n_errore2 = 0 And s_val_new_2 Is Null Then 'Sagoma Inferiore: Valore mancante'
                          When n_errore = 0 And n_errore2 = 0 Then GetCorrectRangeString(n_parametro2)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
-- INF
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro2,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore2
                     End,
                     4,
                     Case
                          When n_errore = 0 And n_errore2 = 0 And s_val_new_2 Is Null Then 'Valore mancante'
                          When n_errore = 0 And n_errore2 = 0 Then GetCorrectRangeString(n_parametro2)
                          Else Null
                     End,
                     s_val_new_2,
                     s_val_old_ok_2,
                     n_controllo_old_ok_2,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
--         n_errore := leatest (n_errore1, n_errore2);
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro1,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
               SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro2,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                 --fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_2,
                          s_val_old_ok_2,
                          n_controllo_old_ok_2,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1;
         -- p_error := SQLCODE;
         Dbms_Output.Put_Line ('SET_1_1_1_1_3_1_1 - Errore: '||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_1_1;
