--
-- ------------------------------------------------------------------------------------------------
--                           Procedure SET_1_1_1_1_3_4_MULT
--            1.1.1.1.3.4  Profilo casse mobili ----------> AP + DOMINIO + CORRELAZIONE     
--                         parametro con tabella multipla a parte
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_4_MULT (n_controllo       In     Number,
                                  id_sol            In     Varchar2,
                                  id_sol_track      In     Varchar2,
                                  id_dtp            In     Varchar2,
                                  n_controllo_padre In     Number,
                                  p_error_split     Out    Number)    Is
      n_parametro                 Number;
      s_val_new_1                 Varchar2 (1000);
      s_val_new_2                 Varchar2 (1000);
      s_val_old_ok_1              Varchar2 (1000);
      s_val_new_AP                Varchar2 (1000);
      n_ok_AP                     Number;                 -- variabile appoggio applicabilità 0/1
      n_ok_dominio                Number;                 -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1        Number;                 
      n_errore                    Number;                 
      d_definizione               Varchar2 (1000);        
      s_stringa_dominio           Varchar2 (1000);        -- stringa concatenata del dominio
      NYA                         Number;                 -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2              Varchar2 (1000);        -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI             EMPCUR;                 -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
-- dbms_output.put_line ('n_controllo_old_ok_1: '||n_controllo_old_ok_1);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);
-- dbms_output.put_line ('d_definizione: '||d_definizione);
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.4');
-- dbms_output.put_line ('n_parametro: '||n_parametro);
--
      NYA:= GetNYA (n_parametro);
-- dbms_output.put_line ('il parametro può essere NYA: '||NYA);
--
      GetOldNewValueMultiplo('PAR_1_1_1_1_3_4_PROF_CAS_M', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_4', id_sol_track, valori_multipli) ;           --multiplo
--    Sagoma Nazionale
--      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_3', id_sol_track);  
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_1_3_4_AP', id_sol_track);
-- dbms_output.put_line ('Applicabilità (s_val_new_AP): '||s_val_new_AP);	  
--
/**** eliminato il controllo sul parametro 1.1.1.1.2.1 dopo mail di Schillaci del 09/02/2021 e verificato che l'ERA non effettua più alcuna verifica
       Begin
            Select Max(SOL_TRACK_1_1_1_1_2_1) 
	              Into s_val_new_2 
	         From rinf_lavorazione_evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL
	        Where SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
       Exception
	        When NO_DATA_FOUND Then
			     s_val_new_2 := Null;
	   End;

dbms_output.put_line ('1.1.1.1.2.1 (s_val_new_2): '||s_val_new_2);	  
--
****/
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
-- dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);
--
      If n_controllo_padre = 0 Then
--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then   
		      Loop
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
-- dbms_output.put_line ('Il valore è coerente con l''applicabilità - n_ok_AP :'||n_ok_AP );
--
                If n_ok_AP = 1 And s_val_new_AP = v_ok_AP  Then 
					 n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
-- dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ok_AP --> n_ok_dominio: '||n_ok_dominio);	
                Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
					 n_ok_dominio := 1;
-- dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ko_AP --> n_ok_dominio = 1');
			    Else
					 n_ok_dominio := 0;
                End If; 
-- dbms_output.put_line ('n_ok_dominio (end if): '||n_ok_dominio);	
/***
                If n_ok_AP = 1 Then
 			         If n_ok_dominio = 1  Then                                        -- se DOMINIO E AP OK
                          If Nvl(s_val_new_2, '00') = '40' And s_val_new_1 Is Not Null Then      -- 40: Off-TEN 
                               n_errore := 0;
                          Else n_errore := 1;
                          End If; 
                     Else n_errore := 0;
                     End If; 
                Else n_errore := 0;
                End If; 
dbms_output.put_line ('n_errore: '||n_errore);
--
***/
                n_errore := n_ok_dominio;

                SetControlDetails
                     (    n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
--                                 When n_errore = 0 And s_val_new_2 = '40' And s_val_new_1 Is Not NulL Then 'Valore non ammesso: se la Classificazione TEN del binario è Off-TEN, questo parametro non deve essere valorizzato'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End
								 );
--
--                       Else     --se DOMINIO E AP KO
--                       n_errore := 0;
--
--                          SetControlDetails(
--                                    n_controllo,
--                                    id_sol,
--                                    id_sol_track,
--                                    n_parametro,
--                                    d_definizione,
--                                    Case When  NYA=1 Then 1
--                                    Else n_errore
--                                    End,
--                                    6,
--                                    Case
--                                           When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
--                                           When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
--                                           When n_errore = 0 Then GetCorrectRangeString (n_parametro)      --LookUpValue
--                                       Else NULL
--                                    End,
--                                    s_val_new_1,
--                                    s_val_old_ok_1,
--                                    n_controllo_old_ok_1,
--                                          Case
--                                            When n_errore = 0 And NYA=0 Then 0
--                                            When n_errore = 0 And NYA=1 Then 1
--                                            When n_errore = 1  Then 0
--                                       End);
--
--                       End If; 
                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                  Exit When VALORI_MULTIPLI%NOTFOUND;
-- dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);

--> end loop
              End Loop;
--         Se NO DATA FOUND
           Else 
-- dbms_output.put_line ('Dati non trovati per la tratta: '||id_sol );
                If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then --Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then --Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If;
-- dbms_output.put_line ('s_val_new_AP: '	||s_val_new_AP);			
                SetControlDetails
                    (     n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          12,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP 
						       Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1  Then 0
                          End   );
           End If; 
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails 
		         (   n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
--                     GetMessFallitoPadreSingolo(13),------------------------------------>'Classificazione TEN del binario'
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End );
-- Dbms_Output.Put_Line ('1.1.1.1.2.1 - Padre non corretto');
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
        p_error_split := 1; 
		Dbms_Output.Put_Line ('SET_1_1_1_1_3_4_MULT - Errore: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_1_3_4_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                              Procedure SET_1_1_1_1_3_5_MULT
--                 1.1.1.1.3.5  Profilo semi rimorchi ----------> AP + DOMINIO + CORRELAZIONE                
--                              parametro con tabella multipla a parte
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_5_MULT (n_controllo       In     Number,
                                  id_sol            In     Varchar2,
                                  id_sol_track      In     Varchar2,
                                  id_dtp            In     Varchar2,
                                  n_controllo_padre In     Number,
                                  p_error_split     Out    Number)   Is
      n_parametro                 Number;
      s_val_new_1                 Varchar2 (1000);
      s_val_new_2                 Varchar2 (1000);
      s_val_old_ok_1              Varchar2 (1000);
      s_val_new_AP                Varchar2 (1000);
      n_ok_AP                     Number;                 -- variabile appoggio applicabilità 0/1
      n_ok_dominio                Number;                 -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1        Number;                
      n_errore                    Number;                
      d_definizione               Varchar2 (1000);       
      s_stringa_dominio           Varchar2 (1000);        -- stringa concatenata del dominio
      NYA                         Number;                 -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2              Varchar2 (1000);        -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI             EMPCUR;                 -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.5');
--
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_1_1_1_3_5_PROF_SEMI_R', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_5', id_sol_track, valori_multipli) ;           --multiplo
--      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_3', id_sol_track);            
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_5_AP', id_sol_track);
--
/******************
       Begin
            Select Max(SOL_TRACK_1_1_1_1_2_1) 
	              Into s_val_new_2 
	         From rinf_lavorazione_evo.PAR_1_1_1_1_2_1_CAT_TEN_SOL
	        Where SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
       Exception
	        When NO_DATA_FOUND Then
			     s_val_new_2 := Null;
	   End;

-- dbms_output.put_line ('1.1.1.1.2.1 (s_val_new_2): '||s_val_new_2);	  

--
*********************/

      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

      If n_controllo_padre = 0 Then
--         Il controllo di correlazione va eseguito solo se essitono valori
           If VALORI_MULTIPLI%Found Then 
		     Loop
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
                If n_ok_AP = 1 And s_val_new_AP = v_ok_AP  Then 
					 n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
					 n_ok_dominio := 1;
			    Else
					 n_ok_dominio := 0;
                End If; 
--
/******************
                If n_ok_AP = 1 Then
 			         If n_ok_dominio = 1  Then                                        -- se DOMINIO E AP OK
                          If Nvl(s_val_new_2, '00') = '40' And s_val_new_1 Is Not Null Then      -- 40: Off-TEN 
                               n_errore := 0;
                          Else n_errore := 1;
                          End If; 
                     Else n_errore := 0;
                     End If; 
                Else n_errore := 0;
                End If; 
********************/
                n_errore :=  n_ok_dominio;
--              
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          6,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
--                               When n_errore = 0 And s_val_new_2 = 'FS' And s_val_new_1 Is Not Null Then 'Valore non ammesso: se '||GetParametro(23,'Sagoma Nazionale')||' ha codifica FS, questo parametro non deve essere valorizzato'
--                               When n_errore = 0 And s_val_new_2 = '40' And s_val_new_1 Is Not NulL Then 'Valore non ammesso: se la Classificazione TEN del binario è Off-TEN, questo parametro non deve essere valorizzato'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1 Then 0
                          End  );       

--                             Else     --se DOMINIO E AP KO
--                               n_errore := 0;
--
--                                  SetControlDetails(
--                                            n_controllo,
--                                            id_sol,
--                                            id_sol_track,
--                                            n_parametro,
--                                            d_definizione,
--                                            Case When  NYA=1 Then 1
--                                            Else n_errore
--                                            End,
--                                            6,
--                                            Case
--                                                    When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
--                                                    When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
--                                                    When n_errore = 0 Then GetCorrectRangeString (n_parametro)      --LookUpValue
--                                               Else NULL
--                                            End,
--                                            s_val_new_1,
--                                            s_val_old_ok_1,
--                                            n_controllo_old_ok_1,
--                                                  Case
--                                                    When n_errore = 0 And NYA=0 Then 0
--                                                    When n_errore = 0 And NYA=1 Then 1
--                                                    When n_errore = 1  Then 0
--                                               End);
--
--                              End If; 

                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                Exit When VALORI_MULTIPLI%NotFound;
              End Loop;
-- Se NO DATA FOUND
           Else 
                If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then --Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                 Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then --Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio :=0;
                 End If; 
                 SetControlDetails  (
					      n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          12,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );

           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
--                     GetMessFallitoPadreSingolo(13),------------------------------------>'Classificazione TEN del binario'
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_3_5 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_5_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_3_5_1 (262) - Tipo Controllo: 
-- 1.1.1.1.3.5.1 - ILL_SpecificInfo
-- Informazioni Specifiche: Ogni informazione pertinente messa a disposizione dal GI relativa al tracciato della linea - Nuovo parametro - Reg.777/2019 - AP=Y
-- Dovrà essere inserito il numero del fascicolo linea cui la sezione di linea appartiene preceduto da “FL” (es. [FL 96] per la TR7631 Grosseto-Alberese).
-- Il valore del presente parametro, già presente in altre banche dati aziendali, sarà fornito in modo massivo da sede centrale e, a
-- seguito di verifica da parte del depositario RINF, dovrà essere inserito nel sistema informativo In.Rete 2000 e gestito in caso di modifiche.

-- ****************************************ATTENZIONE: Il parametro è (ora) ripetibile! **********************************
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_5_1  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number  )  Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.5.1');
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_5_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA(n_parametro);
--      
      If s_val_new_1 Is Null Then
	      n_errore := 0;
      Else
	      n_errore := 1;
      End If;
--
      If n_controllo_padre = 0 Then
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_errore = 0 Then 'Valore mancante'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_3_5_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_5_1;
--
-- ------------------------------------------------------------------------------------------------
--                   Procedure SET_1_1_1_1_3_6 - NCT - AP=Y - (213)
-- 1.1.1.1.3.6 - Profilo del gradiente - DOMINIO IN RANGE  
--  parametro con tabella multipla a parte: PAR_1_1_1_1_3_6_GRADIENTE 
-- Il valore della pendenza deve essere contenuto fra 35 mm/m [+35.0] e – 35 mm/m [-35].
-- Stringa di caratteri predefinita: [±NN.N] ([NNNN.NNN])
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_3_6 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )      Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;          -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;          -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      n_errore_totale        Number;          -- usato per il gradiente per evitare di far scrivere tante righe di errore delle livellette
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000); -- stringa concatenata del dominio
      NYA                    Number;          -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      n_conta_grad           Number;
      VALORI_MULTIPLI        EMPCUR;          -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.6');
--
      NYA:= GetNYA (n_parametro);

--    17/05/2016: siccome l'ERA ora le ammette, eliminato vincolo su KM positiva, confermato con riunione RFI

--      select count(*) into n_conta_grad                             --select inserita per scartare a priori i record del gradiente che hanno progressiva negativa; considera solo il km_inzio (e non il fine) perchè è il km_inizio che viene scritto nell'xml a fianco al gradiente
--      from RINF_LAVORAZIONE_EVO.PAR_1_1_1_1_3_6_GRADIENTE
--      where
--      SOL_TRACK_1_1_1_0_0_1=id_sol_track And
--      (KM_INIZIO <0 or KM_FINE <0);        --inserita per intercettare se KM_INIZIO e/o KM_FINE è neg.; va fatto pure sulla km_fine perchè le tratte potrebbero avere km_fin<km_inizio;

--    If n_conta_grad = 0 Then     -- if che serve per le chilometriche positive; in caso di chilometriche negative non entra proprio
      Select Count(*) Into n_conta_grad              -- per diversificare il commento del caso "senza valori" o " valore sbagliato" abbiamo aggiunto la conta all'inizio e poi l'abbiamo inserita nel commento dell'errore
        From RINF_LAVORAZIONE_EVO.PAR_1_1_1_1_3_6_GRADIENTE
       where SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
--  
      GetOldNewValueMultiplo ('PAR_1_1_1_1_3_6_GRADIENTE', 'SOL_TRACK_1_1_1_0_0_1',' Pendenza', id_sol_track, valori_multipli) ;           --multiplo
--
      Select Min (To_Number(valore)), Max (To_Number(valore))     -- blocco per la scrittura del minimo e massimo valore nel commento
        Into m_min, m_max
        From Rinf_Anagrafiche_Evo.DOMINIO_PARAMETRO
       Where CODICE_PARAMETRO = n_parametro;
--	  
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

      If n_controllo_padre = 0 Then
           If VALORI_MULTIPLI%FOUND Then
                n_errore_totale := 1;    -- Variabile che registra se esiste almeno una riga con errore o se tutte le righe sono corrette
--> loop
                Loop
                     n_errore := GetCorrectRange (n_parametro, s_val_new_1);
                     n_errore_totale := Least (n_errore, n_errore_totale);       -- aggiorno con il minimo tra 0 (errore) e 1 (corretto)
--
                     Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                     Exit When VALORI_MULTIPLI%NOTFOUND;
--
                End Loop;
           Else
                n_errore_totale := 0;
           End If; 
--
           SetControlDetails(
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore_totale
                     End,
                     8,
                     Case When n_errore_totale = 0 And NYA = 0 And n_conta_grad = 0 Then 'Valore errato. Il censimento delle livellette non è corretto'--unificato messaggio di errore con mail Schillaci 20/06/2016 'Valore mancante'     --la conta è stata inserita per diversificare il caso gradiente errato/gradiente mancante
                          When n_errore_totale = 0 And NYA = 1 And n_conta_grad = 0 Then 'Valore errato. Il censimento delle livellette non è corretto'--unificato messaggio di errore con mail Schillaci 20/06/2016 'Valore mancante'
                          When n_errore_totale = 0 And NYA = 0 And n_conta_grad > 0 Then 'Valore errato. Il censimento delle livellette non è corretto'--unificato messaggio di errore con mail Schillaci 20/06/2016 'Valore errato: deve essere valorizzato e deve essere compreso tra '|| m_min|| ' e '|| m_max||''
                          When n_errore_totale = 0 And NYA = 1 And n_conta_grad > 0 Then 'Valore errato. Il censimento delle livellette non è corretto'--unificato messaggio di errore con mail Schillaci 20/06/2016 'Valore errato: deve essere valorizzato e deve essere compreso tra '|| m_min|| ' e '|| m_max||''
                          Else Null
                     End,
                     Case When n_errore_totale = 0 And n_conta_grad = 0 Then 'Valore errato. Il censimento delle livellette non è corretto'--unificato messaggio di errore con mail Schillaci 20/06/2016    'Valore gradiente mancante' --Per evitare di inserire un controllo per ogni livelletta del gradiente del binario
                          When n_errore_totale = 1 And n_conta_grad = 0 Then 'Valore gradiente corretto'     --la conta è stata inserita per diversificare il caso grAnditen errato/gradiente mancante
                          When n_errore_totale = 0 And n_conta_grad > 0 Then 'Valore errato. Il censimento delle livellette non è corretto'--unificato messaggio di errore con mail Schillaci 20/06/2016      'Valore gradiente errato'
                          When n_errore_totale = 1 And n_conta_grad > 0 Then 'Valore gradiente corretto'
                          Else Null
                     End,
                     'Valore gradiente corretto',
                     n_controllo_old_ok_1,
                     Case When n_errore_totale = 0 And NYA = 0 Then 0
                          When n_errore_totale = 0 And NYA = 1 Then 1
                          When n_errore_totale = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
--
      CLOSE VALORI_MULTIPLI;
--                  blocco per scrittura dell'errore in caso di KM negativa
--                  Else    --esiste almeno una chilometrica negativa di inzio o fine
--                       SetControlDetails (
--                                    n_controllo,
--                                    id_sol,
--                                    id_sol_track,
--                                    n_parametro,
--                                    d_definizione,
--                                    1,
--                                    4,                 --fallito perchè un valore negativo della chilometrica non può appartenere al dominio dei valori ammissibili
--                                    'Controllo sul valore positivo delle chilometriche iniziale e finale fallito',
--                                    NULL,
--                                    NULL,
--                                    NULL,
--                                     Case
--                                            When NYA=0 Then 0
--                                            When NYA=1 Then 1
--                                       End);
--                   End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := SQLCODE;
         Dbms_Output.Put_Line ('SET_1_1_1_1_3_6 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_6;
--
-- ------------------------------------------------------------------------------------------------
--                  Procedure SET_1_1_1_1_3_7  - NCT - AP=Y (26)
-- 1.1.1.1.3.7 - Raggio minimo di curvatura orizzontale - [NNNNN]
-- Il raggio minimo di curvatura, nelle sezioni di linea, deve essere maggiore di [150] m.
-- Le sezioni rette tra due PO andranno espresse con [99999]
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_1_3_7 (n_controllo       In Number,
                            id_sol            In Varchar2,
                            id_sol_track      In Varchar2,
                            id_dtp            In Varchar2,
                            n_controllo_padre In Number,
                            p_error_split    Out Number  )      Is                   
      n_parametro           Number;
      s_val_new_1           Varchar2 (1000);
      s_val_new_2           Varchar2 (1000);
      s_val_new_3           Varchar2 (1000);
      s_val_old_ok_1        Varchar2 (1000);
      s_val_new_AP          Varchar2 (1000);
      m_min                 Number;
      m_max                 Number;
      n_ok_AP               Number;          -- variabile appoggio applicabilità 0/1
      n_ok_dominio          Number;          -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1  Number;
      n_errore              Number;
      n_errore_totale       Number;          -- usato per il gradiente per evitare di far scrivere tante righe di errore delle livellette
      d_definizione         Varchar2 (1000);
      s_stringa_dominio     Varchar2 (1000); -- stringa concatenata del dominio
      NYA                   Number;          -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2        Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI       EMPCUR;          -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
    BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.3.7');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_3_7', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);

      If n_controllo_padre = 0 Then
           If NVL (s_val_new_1, 0) < 151 Then
                n_errore := 0;
           Else
                n_errore := 1;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     8,
                     Case
                          When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                          When n_errore = 0 Then 'Errata valorizzazione: il parametro deve essere maggiore di 150'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_3_7 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_3_7;
