-- ------------------------------------------------------------------------------------------------
--            Procedure SET_1_1_1_1_4_4 (30)
-- 1.1.1.1.4.4 - ITP_Ballast - Esistenza ballast - Controllo: DOMINIO+CORRELAZIONE+APPLICABILITA'- 6
-- Questo parametro è applicabile sulle sezioni di linea con velocità di percorrenza superiore a 250 km/h. MODIFICATO (220 km/h)
-- Il valore di questo parametro, quando applicabile, deve essere sempre = [N] 
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_4_4 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number ) Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.4.4');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_4_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    parametro correlato: 1.1.1.1.2.5 - velocità massima consentita sulla tratta
      s_val_new_2:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_4_4_AP', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--         controllo applicabilità e Dominio
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
		        n_ok_dominio := GetCorrectValue(n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
		        n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--         controllo correlazione con altro parametro (velocità)
           If n_ok_AP = 1  Then
                If n_ok_dominio = 1 Then
                     If (Nvl (s_val_new_2, 0) > 250 And s_val_new_1 = 'N' ) Then
					      n_errore := 1;
                     Elsif s_val_new_1 Is Null Then 
					      n_errore := 1;
                     Else n_errore := 0;

--                     If  (Nvl (s_val_new_2, 0) Between 201 And 249 And s_val_new_1 <> 'N')
--                      Or (Nvl (s_val_new_2, 0) > 249 And s_val_new_1 <> 'Y')
--                      Or (Nvl (s_val_new_2, 0) < 201 And s_val_new_1 Is Not Null)
--                     Then n_errore := 0;
--                     Else n_errore := 1;
                     End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And Nvl(s_val_new_2, 0) > 250 And s_val_new_1 <> 'N' Then 'Se '||GetParametro(17, 'Velocità')||' è maggiore di 250 km/h, il parametro deve essere '|| GetValueFromCode (n_parametro, 'N')
       --                   When n_errore = 0 And NVL (s_val_new_2, 0) between 201 And 249 And s_val_new_1 <> 'N' Then 'Se '||GetParametro(17,'Velocità')||' superiore a 200 km/h e inferiore a 250 km/h, il parametro deve essere '|| GetValueFromCode (n_parametro, 'N')
                          When n_errore = 0 And nvl (s_val_new_2, 0) <= 250 And s_val_new_1 Is Not Null Then 'Se '||GetParametro(17, 'Velocità')||' minore o uguale a 250 km/h, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(17),------------------------------------>'Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_4_4 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_4_4;
--                         1.1.1.1.5 - DISPOSITIVI DI ARMAMENTO 
-- ------------------------------------------------------------------------------------------------
--                           Procedure SET_1_1_1_1_5_1 - AP=Y (31)
-- 1.1.1.1.5.1 Rispetto da parte dei dispositivi di armamento dei valori di utilizzazione previsti dalla STI
-- Il valore di questo parametro deve essere sempre [S] - Dominio
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_5_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                
      n_errore               Number;                
      d_definizione          Varchar2 (1000);       
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.5.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_5_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
           If n_errore = 1 Then
                If s_val_new_1 <> 'Y' Then 
				     n_errore :=0;
                 Else 
				     n_errore :=1;
                 End If; 
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                          When n_errore = 0 Then 'Errata valorizzazione: è obbligatorio il valore '||GetValueFromCode (n_parametro, 'Y')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_5_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_5_1;
--
-- ------------------------------------------------------------------------------------------------
--                    Procedure SET_1_1_1_1_5_2 - NCT - AP=Y (32)
-- 1.1.1.1.5.2 - SC_MinWheelDiaFixObtuseCrossings- Diametro minimo delle ruote per il deviatoio fisso ad angolo ottuso 
-- DOMINIO: Il valore di questo parametro deve essere sempre[NNN] = 330
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_5_2 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  ) Is                   
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                
      n_errore               Number;                
      d_definizione          Varchar2 (1000);       
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.5.2');

       GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_5_2', id_sol_track, s_val_new_1, s_val_old_ok_1);

       NYA:= GetNYA (n_parametro);

       If n_controllo_padre = 0 Then

           n_errore := GetCorrectValue (n_parametro, s_val_new_1);

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                          When n_errore = 0 Then 'Errata valorizzazione: è obbligatorio il valore ' || GetCorrectRangeStringPURA (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_5_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_5_2;
--                           1.1.1.1.6 Resistenza del binario ai carichi applicati
-- ------------------------------------------------------------------------------------------------
--            Procedure SET_1_1_1_1_6_1 - NCT - AP=Y Il parametro è sempre Applicabile (34)
-- 1.1.1.1.6.1 - ILR_MaxDeceleration - Decelerazione massima del treno - AP+CORRELAZIONE (dominio tirato fuori)
-- Il valore di questo parametro deve essere [N.N]=[2.5] quando il valore del parametro 1.1.1.1.1.1 è diverso da [non applicabile].
-- Il valore di questo parametro deve essere [ ] quando il valore del parametro 1.1.1.1.1.1 è uguale a [non applicabile].
-- 21/05/2021 Modificata la gestione delle anomalie: se il parametro non è valorizzato, non viene indicata l'anomalia ma l'applicabilità è sempre [NYA]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_6_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      n_conta                Number;
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.6.1');

      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_6_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      s_val_new_1 := Replace(s_val_new_1, ',', '.');  -- 13/06/2016 aggiunta questa conversione in quanto, nel caso di parametri numerici CON VIRGOLA, il DB non riconosce la virgola ma il punto
--                                                       ATTENZIONE: questo parametro nel DB è definito varchar ma in realtà è numerico (è un vecchio refuso di INE)
 --     dbms_output.put_line ('s_val_new_1: '||s_val_new_1);
--
      NYA := GetNYA (n_parametro);
 --     dbms_output.put_line ('NYA: '||NYA);
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_6_1_AP', id_sol_track);
--	  
--    Estrazione valore assegnato al parametro: 1.1.1.1.1.1 - Dichiarazione di verifica CE del binario (INF)
      Select Count (*) Into n_conta                  -- se NON esiste una dichiarazione di EC per il binario corrente, allora =0
        From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_INF a,
             Rinf_Lavorazione_Evo.BINARI_CORSA_SOL b
       WHERE TIPO_DICHIARAZIONE = 'EC'
         And a.SOL_TRACK_1_1_1_1_1_1O2_AP = 'Y'
         And a.SOL_TRACK_1_1_1_0_0_1 = b.SOL_TRACK_1_1_1_0_0_1
         And b.SOL_TRACK_1_1_1_0_0_1 = id_sol_track
		 And tipo_dichiarazione = 'EC'                          -- condizione per distinguere il parametro 1.1.1.1.1.1 (dichiarazione CE) da 1.1.1.1.1.2 (dichiarazione IE)
         And Trim(SOL_TRACK_1_1_1_1_1_1O2) Is Not Null;         -- aggiunta questa clausola così non mi conta le dichiarazioni inserite vuote, ossia con lo spazio

 --          dbms_output.put_line ('n_conta: '||n_conta);
--
      If n_controllo_padre = 0 Then
--
           If n_conta > 0  Then                         
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
 --                    dbms_output.put_line ('n_ok_dominio (n_conta > 0): '||n_ok_dominio);
		   Else                                                                            -- Non sono presenti dichiarazioni EC INF
		        If s_val_new_1 Is Null Then
			          n_ok_dominio := 1;
 --                     dbms_output.put_line ('n_ok_dominio (s_val_new_1 Is Null): '||n_ok_dominio);
			    Else 
			          n_ok_dominio := 0;
 --                    dbms_output.put_line ('n_ok_dominio (s_val_new_1 Is Not Null): '||n_ok_dominio);
	            End if;	   
           End If; 
--
           n_errore := n_ok_dominio;
--           dbms_output.put_line ('n_errore: '||n_errore);
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                     Else n_errore
                     End,
                     6,--5
                     Case
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
 --                         When n_errore = 0 And n_conta = 0 And s_val_new_1 Is Null Then 'Non ancora valorizzato perchè in attesa di Dichiarazioni EC INF'
                          When n_errore = 0 And (n_conta = 0 And s_val_new_1 Is Not Null) Then 'Valorizzazione da verificare in quanto non ancora presenti Dichiarazioni EC INF'
                          When n_errore = 0 And (n_conta > 0 And s_val_new_1 Is Null) Then 'Errore applicabilità: il parametro è definito Applicabile ma non è valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1 And n_conta = 0   Then 1                                 -- aggiunto per valorizzare l'applicabilità con [NYA] ma non avere anomalia
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else  SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_6_1 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_1_6_1;

--
-- ------------------------------------------------------------------------------------------------
--         Procedure SET_1_1_1_1_6_2 (35) - NCT - AP=Y
-- 1.1.1.1.6.2 - ILR_EddyCurrentBrakes - Utilizzo di freni a correnti parassite DOMINIO (valore unico ammissibile = [not allowed])
-- Il valore di questo parametro deve essere sempre [non autorizzato].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_6_2 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;  
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.6.2');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_6_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then

           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                        When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
