      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.2');
--    legge il valore attuale e il precedente del parametro
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    controlla se il parametro accetta valori NYA
      NYA:= GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
--         controlla in RINF_ANAGRAFICHE_EVO.DOMINIO_PARAMETRO se il valore acquisito è presente(S/N): n_ok_dominio = 1, altrimenti = 0
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                        When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                        When n_errore = 0 Then GetCorrectRangeString (n_parametro)
                        Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_2;
--
-- ------------------------------------------------------------------------------------------------
--                 Procedure SET_1_1_1_1_7_3  (39)
-- 1.1.1.1.7.3 - IHS_AccelerationLevelCrossing - Accelerazione consentita presso i passaggi a livello
-- Il parametro è “applicabile” quando il valore del parametro 1.1.1.1.7.2 è [S].
-- Questo parametro deve assumere sempre il valore [0.0].
-- AP+DOMINIO 0.0 (se AP) (+CORRELAZIONE IMPLICITA) (dominio tirato fuori)
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_3 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is                    
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000);    -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.3');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_3_AP', id_sol_track);
--    1.1.1.1.7.2 - Esistenza passaggi a livello
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_2', id_sol_track);            
--    controlla se l'applicabilità è coerente con il valore
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                             -- (13/06/2016 dominio tirato fuori)
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
		   Else 
                n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If      --(nvl(s_val_new_2, 0)='Y' And s_val_new_1 <> 0) OR
                        (Nvl(s_val_new_2, '0') = 'N' And s_val_new_1 Is Null) Or
                        (Nvl(s_val_new_2, '0') = 'Y' And s_val_new_1 Is Not Null) Then   
                          n_errore := 1;
                     Else 
					      n_errore := 0;
                     End If; 
                Else 
				     n_errore := 0;
                End If; 
           Else 
		        n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' Then 'Se '||GetParametro(38,'Esitenza PL')||' è valorizzato '||GetValueFromCode (38, 'N')|| ', il parametro non deve essere valorizzato'
--                          When n_errore = 0 And Nvl(s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(38,'Esitenza PL')||' è valorizzato '||GetValueFromCode (38, 'Y')|| ', il parametro deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(38,'Esitenza PL')||' è valorizzato '||GetValueFromCode (38, 'Y')|| ', il parametro deve essere '||GetCodeFromValue (n_parametro, '0.0')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(38),------------------------------------------------>''Esistenza Passaggi a Livello''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_3;
--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_1_7_4 - NCT - AP=Y - (268) 
--     1.1.1.1.7.4 - IHS_HABDExist - Esistenza di un sistema di rilevamento di anomalo riscaldamento boccole (RTB) a terra
--         Nuovo parametro - Reg.777/2019 - Tipo Controllo: 4-DOMINIO - 
--  Il valore del parametro può essere solo [S] o [N]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_4    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number  )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.4');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica che il parametro accetti valori NYA      
      NYA := GetNYA(n_parametro);
--
      If n_controllo_padre = 0 Then
--
--         verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
           n_errore := GetCorrectValue(n_parametro, s_val_new_1);
--        
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                          When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_4 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_4;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_7_5 - NCT - (270) 
--                     1.1.1.1.7.5 - HS_TSIHABD - Sistema RTB a terra conforme a STI
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--       Applicabile se 1.1.1.1.7.4 = [S] Altrimenti: NA  - Il valore del parametro può essere solo [S] o [N].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_5    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number  )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.5');
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_5', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--    legge se il dato è applicabile o meno
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_5_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.1.7.4 - Esistenza di Sistema di Rilevamento di anomalo riscaldamento boccole RTB a terra (268)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_4', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_1_7_4 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (Nvl(s_val_new_2, 'N') = 'Y' And s_val_new_1 Is Not Null) or        -- Controllo con il parametro "padre" 1.1.1.1.7.4 
					     (Nvl(s_val_new_2, 'N') = 'N' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                      -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
--                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When (n_errore = 0 And Nvl(s_val_new_2, 'N') = 'N' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And Nvl(s_val_new_2, 'N') = 'Y' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And Nvl(s_val_new_2, 'N') = 'Y') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(268),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_5 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_5;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_7_6 (272) 
--                     1.1.1.1.7.6 - IHS_HABDID - Individuazione di Sistema RTB a terra 
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 5-AP e CORRELAZIONE CON ALTRO PARAMETRO 
--       Applicabile se 1.1.1.1.7.5 = [N] Altrimenti: NA  - NCT (Modificato con mail Schillaci del 19/02/2021
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_6    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--  
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.6');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_6', id_sol_track, s_val_new_1, s_val_old_ok_1);
--	  
--    verifica se può assumere valori NYA
      NYA := GetNYA (n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_6_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.1.7.5 - Sistema dRTB a terra conforme a STI (270)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_5', id_sol_track);  
--	  
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_1_7_5 è terminata correttamente
      If n_controllo_padre = 0 Then
--
--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := 1;       
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If ((Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Not Null) Or        -- Controllo con il parametro "padre" 1.1.1.1.7.5 
					      (Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Null)) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else 
				     n_errore := 0;                                                 -- valore non incluso nella LookUp value
                End If; 
           Else 
		        n_errore := 0;                                                      -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     5,
                     Case
					      When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(270),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_1_7_6: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_6;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_7_7 (274) 
--                     1.1.1.1.7.7 - IHS_HABDGen - Generazione di Sistema RTB a terra 
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP - DOMINIO VALORI - CORRELAZIONE CON ALTRO PARAMETRO 
--       Applicabile se 1.1.1.1.7.4 = [N] Altrimenti: NA  - NCT (Modificato con mail Schillaci del 19/02/2021
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_7    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.7');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_7', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_7_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.1.7.4 - esistenza di un Sistema di rilevamento di anomalo riscaldamento boccole(RTB) a terra (268)
--      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_4', id_sol_track);    
--
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_5', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_1_7_4 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value" - N.B: Ancora non valorizzato!!!
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Not Null) or        -- Controllo con il parametro "padre" 1.1.1.1.7.5
					     (Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                      -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
					      When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'N') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
--                     GetMessFallitoPadreSingolo(268),--------------------------------------------->Controllo padre fallito 
                     GetMessFallitoPadreSingolo(270),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_7 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_7;
