-- ------------------------------------------------------------------------------------------------
--                           Procedure SET_1_1_1_1_7_8_MULT - NCT -(276)
--            1.1.1.1.7.8 - IHS_HABDLoc - Localizzazione ferroviaria di un sistema RTB a terra 
-- Il parametro è applicabile solo se il parametro 1.1.1.1.7.5 = [N]  -- Modificato con mail di Schillaci del 19/02/2021
-- Controllo:  AP - Correlazione con altro parametro (5) - parametro con tabella multipla a parte PAR_1_1_1_1_7_8_LOCA_SIST_RTB 
-- il parametro, se applicabile, deve essere inserito nel formato [±NNNN.NNN]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_8_MULT (n_controllo         In     Number,
                                    id_sol            In     Varchar2,
                                    id_sol_track      In     Varchar2,
                                    id_dtp            In     Varchar2,
                                    n_controllo_padre In     Number,
                                    p_error_split     Out    Number   )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                                   -- Cursore Per I Valori NEW e OLD Dei Parametri In Tabella Multipli A Parte
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.8');
--
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_1_1_1_7_8_LOCA_SIST_RTB', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_8', id_sol_track, valori_multipli) ;  -- multiplo
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_8_AP', id_sol_track);

--    legge il valore del parametro "padre" 1.1.1.1.7.5 - Sistema di RTB a terra conforme a STI (270)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_5', id_sol_track);    
---
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then
--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
--> loop
			    Loop
                     n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

--                   Test AP e Correlazione
                     If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                          n_ok_dominio := 1;
                     Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                          n_ok_dominio := 1;
		             Else n_ok_dominio := 0;
                     End If; 
--                   
                     If n_ok_AP = 1 Then
--                        Se il valore è nella LookUp value
                          If n_ok_dominio = 1 Then
                                If (Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 between 0 and 9999) or        -- Controllo con il parametro "padre" 1.1.1.1.7.5 
			          		       (Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Null) Then
			          		      n_errore := 1;
			          	      Else
			          		      n_errore := 0;
                                End If;
                          Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                          End If; 
                     Else n_errore := 0;                                                      -- valore non coerente con AP
                     End If; 
---
                     SetControlDetails
                        (     n_controllo,
                              id_sol,
                              id_sol_track,
                              n_parametro,
                              d_definizione,
                              Case When NYA = 1 Then 1
                                   Else n_errore
                              End,
                              5,
                              Case 
                                   When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                                   When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
 							       When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                   When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
					               When n_errore = 0 And s_val_new_1 > 9999 Then 'La lunghezza del parametro risulta essere maggiore di 4 cifre'
                                   Else Null
                              End,
                              s_val_new_1,
                              s_val_old_ok_1,
                              n_controllo_old_ok_1,
                              Case When n_errore = 0 And NYA = 0 Then 0
                                   When n_errore = 0 And NYA = 1 Then 1
                                   When n_errore = 1             Then 0
                              End  );
--		 
                      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                      Exit When VALORI_MULTIPLI%NotFound;
--> end loop		 
                  End Loop;
--         Se NO DATA FOUND
           Else 
               If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then --Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then --Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If; 
                SetControlDetails (
					      n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          5,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1  Then 0
                          End );
          End If; 
--        siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
          p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(270),--------------------------------------------->Controllo padre fallito 
                     'Valori errati',--s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_8_MULT - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_8_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_1_7_9 - NCT  - (278) 
--        1.1.1.1.7.9 - IHS_HABDDirection - Direzione della misurazione di sistema RTB a terra [N/O/B]
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--       Applicabile se 1.1.1.1.7.5 = [N] Altrimenti: NA  Modificato con Mail di Schillaci del 19/02/2021
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_1_7_9    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.1.7.9');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_9', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_9_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.1.7.5_Sistema di RTB a terra conforme a STI (270)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_7_5', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_1_7_5 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Not Null) or        -- Controllo con il parametro "padre" 1.1.1.1.7.5
					     (Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                      -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
					      When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'Y' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And Nvl(s_val_new_2, 'Y') = 'N') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(270),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_1_7_9 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_1_7_9;
