--                       1.1.1.2 Sottosistema Energia
--                       1.1.1.2.1 Dichiarazioni di verifica dei binari
-- ------------------------------------------------------------------------------------------------
--                          Procedure SET_1_1_1_2_1_1 
-- 1.1.1.2.1.1 - EDE_ECVerification - Dichiarazione CE di verifica del binario (ENE)
-- FORMATO E APP - parametro con tabella multipla a parte: DICHIARAZIONI_BINARIO_SOL_ENE
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_1_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )  Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                
      n_errore               Number;                
      d_definizione          Varchar2 (1000);       
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;             -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO         Number;             -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.1.1');
--
      NYA := GetNYA (n_parametro);
--
      GetOldNewValueMultiploDICH ('DICHIARAZIONI_BINARIO_SOL_ENE', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_1_1O2', 'SOL_TRACK_1_1_1_2_1_1O2_AP', id_sol_track,'EC', valori_multipli);           --multiplo
--    inizializzo l'errore per poterlo puoi valorizzare nel loop
      n_errore := 1;              
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;

      If n_controllo_padre = 0 Then
           If VALORI_MULTIPLI%FOUND Then
--> loop
             Loop
                n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);
                If n_ok_AP = 1 Then
                     If (s_val_new_1 = ' ') Or
                        (s_val_new_1 <> ' ' And GetCorrectDECLFormat (s_val_new_1) = 1) Then 
--                        se mi fallisce un parametro multiplo, fallisce il controllo
                          n_errore := Greatest(n_errore, 1);                           
                     Else n_errore := Least(n_errore, 0);
                     End If; 
                Else n_errore := 0;
                End If; 

                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          7,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case 
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );

                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
                Exit When VALORI_MULTIPLI%NOTFOUND;
--> end loop
             End Loop;
-- se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella
           Else
                n_errore := 0;                
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1  
						       Then 1
                               Else n_errore
                          End,
                          4,
                          Case When n_errore = 0 Then s_commento_DICH_CE|| 'binario sottosistema ENE'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 

       CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_1_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_1_1;
--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_2_1_2
-- 1.1.1.2.1.2 - EDE_EIDemonstration - Dichiarazione di dimostrazione IE del binario (ENE)
-- FORMATO E APP - parametro con tabella multipla a parte: DICHIARAZIONI_BINARIO_SOL_ENE
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_1_2 (n_controllo       IN Number,
                             id_sol            IN Varchar2,
                             id_sol_track      IN Varchar2,
                             id_dtp            IN Varchar2,
                             n_controllo_padre IN Number,
                             p_error_split    OUT Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;             -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO         Number;             -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.1.2');
--
      NYA := GetNYA (n_parametro);
--
      GetOldNewValueMultiploDICH('DICHIARAZIONI_BINARIO_SOL_ENE', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_1_1O2', 'SOL_TRACK_1_1_1_2_1_1O2_AP', id_sol_track, 'EI', valori_multipli);           --multiplo
--    inizializzo l'errore per poterlo puoi valorizzare nel loop
      n_errore:=1;              
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
--
      If n_controllo_padre = 0 Then
           If VALORI_MULTIPLI%FOUND Then
--> loop 
             Loop
                n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);
                If n_ok_AP = 1 Then
                     If (s_val_new_1 = ' ') Or
                        (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)  Then
--                        se mi fallisce un parametro multiplo, fallisce il controllo
                          n_errore := Greatest(n_errore, 1);                           
                     Else n_errore := Least(n_errore, 0);
                     End If; 
                Else n_errore := 0;
                End If; 
--
                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          7,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );

                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1, s_val_new_AP;
                Exit When VALORI_MULTIPLI%NOTFOUND;
--> end loop
             End LOOP;
           Else
--              se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella
                n_errore := 0;                 

                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          4,
                          Case When n_errore = 0 Then s_commento_DICH_IE||'binario sottosistema ENE'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split:=MOD(n_errore+1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
--
      CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_1_2 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_1_2;
--                       1.1.1.2.2 Sistema di linea di contatto
-- ------------------------------------------------------------------------------------------------
--                          Procedure SET_1_1_1_2_2_1_1 - NCT - AP=Y - (240)
-- 1.1.1.2.2.1.1 - ECS_SystemType - Tipo di sistema di linea di contatto - DOMINIO
-- Questo parametro può essere valorizzato con [10-Linea di contatto aerea (OCL)] oppure con [40-non elettrificato].
-- Quando questo parametro è valorizzato con [40-non elettrificato] i successivi parametri da 1.1.1.2.2.1.2 a 1.1.1.2.5.3 sono non applicabili
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_1_1 (n_controllo       In Number,
                               id_sol            In Varchar2,
                               id_sol_track      In Varchar2,
                               id_dtp            In Varchar2,
                               n_controllo_padre In Number,
                               p_error_split    Out Number  )    Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_dominio             Number;           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);  -- stringa concatenata del dominio
      NYA                       Number;          -- ritorna se è NYA = 1 o 0
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.1.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track, s_val_new_1,s_val_old_ok_1) ;
--
      NYA := GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                        When n_errore = 0 Then GetCorrectRangeString (n_parametro)
                        Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                         
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_1_1 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_1_1;
--
-- ------------------------------------------------------------------------------------------------
--                          Procedure SET_1_1_1_2_2_1_2  - NCT - (55)
-- 1.1.1.2.2.1.2 - ECS_VoltFreq - Sistema alimentazione elettrica (tensione e frequenza) AP+DOMINIO+CORRELAZIONE
-- Il parametro non è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato con [non elettrificato]
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_2_2_1_2 (n_controllo       In Number,
                              id_sol            In Varchar2,
                              id_sol_track      In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number  )  Is
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      n_ok_AP                 Number;            -- variabile appoggio applicabilità 0/1
      n_ok_dominio            Number;            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;            
      n_errore                Number;            
      d_definizione           Varchar2 (1000);   
      s_stringa_dominio       Varchar2 (1000);   -- stringa concatenata del dominio
      NYA                     Number;            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2          Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
--    estrae il codice_parametro 
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.1.2');
--
--    legge il valore attuale e il precedente del parametro dalla tabella BINARI_CORSA_SOL degli schemi LAVORATI e CONTROLLATI
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA (n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.2.2.1.1 - tipo di Sistema di Linea di Contatto (240)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);      --082
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
-- Se la procedura "padre" SET_1_1_1_3_2_2_1_1 è terminata correttamente
      If n_controllo_padre = 0 Then    
--
-- Test AP e Correlazione
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                               -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);             -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                            -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
--
                     If (s_val_new_2 = '10' And s_val_new_1 = '30' ) Or                   -- Linea di contatto aerea - CA 25kV 50Hz
                        (s_val_new_2 = '10' And s_val_new_1 = '20' ) Or                   -- Linea di contatto aerea - CA 15kV 16.7Hz
                        (s_val_new_2 = '10' And s_val_new_1 = '10')  Or                   -- Linea di contatto aerea - CC  3kV 
                        (s_val_new_2 = '40' And s_val_new_1 Is Null) Or                   -- Non Elettrificato - Null (NA)
                        (s_val_new_2 = '20' And s_val_new_1 Is Not Null )  Or             -- terza rotaia      - <> Null
                        (s_val_new_2 = '30' And s_val_new_1 Is Not Null )                 -- quarta rotaia     - <> Null
                       Then  n_errore := 1;
                       Else  n_errore := 0;
                     End If; 
                Else n_errore := 0;                                                          --valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                               --valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2= 40 Then  'Se '||GetParametro(240, 'Tipo linea')|| ' è ' ||GetValueFromCode (240, '40')|| ', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2= 10 Then  'Se '||GetParametro(240, 'Tipo linea')|| ' è ' ||GetValueFromCode (240, '10')|| ', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2= 20 Then  'Se '||GetParametro(240, 'Tipo linea')|| ' è ' ||GetValueFromCode (240, '20')|| ', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2= 30 Then  'Se '||GetParametro(240, 'Tipo linea')|| ' è ' ||GetValueFromCode (240, '30')|| ', il parametro deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
-- siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := MOD(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_2_2_1_2: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_1_2;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_2_2_1_2_1 (288) 
--  1.1.1.2.2.1.2.1 - CS_TSIVoltFreq - Conformità alle STI del sistema di alimentazione elettrica (tensione nominale e frequenza)
--         Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE - NCT
-- Il parametro deve essere valorizzato solo se parametro 1.1.1.2.2.1.1 - Tipo di Sistema di linea di contatto è diverso da [NON elettrificato] (240)
-- I valori ammessi (S/N) dipendono dal parametro 1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (voltaggio e frequenza) (55)
-- Se il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica (voltaggio e frequenza) è
-- valorizzato = [CC 3 kV] o = [CA 25 kV – 50 Hz], allora questo parametro deve essere = [S]
-- Se il parametro 1.1.1.2.2.1.1 - Tipo di sistema di linea di contatto sia stata valorizzato = [non
-- elettrificato], questo parametro non è applicabile.
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_1_2_1(n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number  )  Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.1.2.1');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2_1', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (voltaggio e frequenza) dalla tabella BINARI_CORSA_SOL
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.1 - Tipo di Sistema di linea di contatto dalla tabella BINARI_CORSA_SOL
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2_1_AP', id_sol_track); 
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Controllo padre dipende dai parametri 1.1.1.2.2.1.1 e 1.1.1.2.2.1.2
--    n.b. se il parametro 1.1.1.2.2.1.1 assume il valore 40-Non elettrificato anche il parametro 1.1.1.2.2.1.2 è N.A. (=Null)

      If n_controllo_padre = 0 Then
--		   
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                                -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);              -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif n_ok_AP = 1 And (s_val_new_AP = v_ko_AP Or s_val_new_AP Is Null) Then   -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else
				n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1   Then                                                   -- se l'applicabilità è coerente con il valore
                If n_ok_dominio = 1 Then                                           -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
--		     
                     If s_val_new_3 = 40 Then                                      -- [Non elettrificato]
					      If s_val_new_1 Is Null Then 
                               n_errore := 1;                        
						  Else
                               n_errore := 0;                                      -- errore
						  End if;
                     Else
						  If (s_val_new_2 = 10 Or s_val_new_2 = 30) And s_val_new_1 = 'Y' Then   -- [CC 3kV o CA 25kV - 50 Hz]
   						         n_errore := 1;
						  ElsIf (s_val_new_2 = 20 Or s_val_new_2 = 40) And s_val_new_1 = 'Y' Then   -- [CA 15kV-16.7Hz o CC 1.5kV]
   						         n_errore := 1;
						  Else 
                                 n_errore := 0;
                          End If; 
                     End If; 
                Else  
				     n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else  
		        n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0   And s_val_new_1 Is Not Null Then s_commento_AP_ko
                          When (n_errore = 0 And s_val_new_3 = 40 And s_val_new_1 Is Not Null) Then 'Errore Applicabilità: il parametro non è applicabile quando il Tipo di Sistema di linea di contatto è [non elettrificato]'
                          When (n_errore = 0 And (s_val_new_3 = 10 or s_val_new_3 = 30) And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And s_val_new_2 = 10) Then  'Se '||GetParametro(55, 'Sistema Alimentazione')|| ' è ' ||GetValueFromCode (55, '10')|| ', il parametro deve essere valorizzato con [S]'
                          When (n_errore = 0 And s_val_new_2 = 20) Then  'Se '||GetParametro(55, 'Sistema Alimentazione')|| ' è ' ||GetValueFromCode (55, '20')|| ', il parametro deve essere valorizzato con [S]'
                          When (n_errore = 0 And s_val_new_2 = 30) Then  'Se '||GetParametro(55, 'Sistema Alimentazione')|| ' è ' ||GetValueFromCode (55, '30')|| ', il parametro deve essere valorizzato con [S]'
                          When (n_errore = 0 And s_val_new_2 = 40) Then  'Se '||GetParametro(55, 'Sistema Alimentazione')|| ' è ' ||GetValueFromCode (55, '40')|| ', il parametro deve essere valorizzato con [S]'
				          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--                
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
-->
--   se falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                21,                             -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(240),--------------------------------------------------------->''Tipo di Sistema di Linea di Contatto''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				    When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                15,                            -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(55),-------------------------------------------------------->''Sistema di Alimentazione Elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il primo padre,
      Elsif n_controllo_padre = 2 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				     When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             -- falliti padri
                GetMessFallitoPadreSingolo(240),--------------------------------------------------------->''Tipo di Sistema di Linea di Contatto''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                     When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				    When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                14,                            -- falliti padri
                GetMessFallitoPadreSingolo(55),-------------------------------------------------------->''Sistema di Alimentazione Elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                    End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_1_2_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_1_2_1;
--
-- 1.1.1.2.2.1.3 - ECS_Umax2 - Umax2 per linee di cui al punto 7.4.2.2.1 del regolamento (UE) n. 1301/2014 -NA Intera rete (290)

--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_2_2_1_3 (292) - NA Intera Rete
-- 1.1.1.2.4.3 - ECS_Umax2 - Umax2 per linee di cui al punto 7.4.2.2.1 del regolamento (UE) n. 1301/2014
-- Nuovo parametro - Reg.777/2019 solo per la rete francese - AP=N - [N]
-- Questo parametro deve essere sempre valorizzato [non applicabile]. Cotrollo: Campo obbligatoriamente nullo (10)
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_1_3  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.1.3');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      s_val_new_AP := Nvl(GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_3_AP', id_sol_track), 'N'); 
--
      NYA := GetNYA(n_parametro);
--
 --          If n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                 n_errore := 1;
--	       Else  
--		        n_errore := 0;
--           End If; 
--
           If n_controllo_padre = 0 Then
--
--              verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
--                n_errore := GetCorrectValue(n_parametro, s_val_new_1);

                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          10,
                          Case
                               When n_errore = 0 And s_val_new_1 Is Not Null Then s_commento_AP_ko
--                               When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End);
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_1_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_1_3;
--
-- ------------------------------------------------------------------------------------------------
--                            PROCEDURE SET_1_1_1_2_2_2 - NCT - [NNNN] - (56)
--      1.1.1.2.2.2 - ECS_MaxTrainCurrent - Corrente massima del treno (AP+CORRELAZIONE)- MODIFICATO Reg.777/2019 
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato]
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_2_2_2  (n_controllo       In     Number,
                             id_sol            In     Varchar2,
                             id_sol_track      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split    Out     Number)   Is                       
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.2');
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifico che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--    acquisisce il valore dell'Applicabilità associata al parametro
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_2_AP', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (tensione e frequenza)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.1 - tipo di sistema di linea di contatto:
--    (10- Linea di contatto aerea (OCL) / 40-Non elettrificato)
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);        --082
--
--    verifica la coerenza della coppia di dati AP/valore parametro e NAP/nullo: 1:ok - 0:KO
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--    se il codice di ritorno della procedura SET_1_1_1_2_2_1_1 = 0 (non SET_1_1_1_2_2_1_2 = 0)
      If n_controllo_padre = 0 Then
--         se i valori di AP e parametro sono coerenti
           If n_ok_AP = 1  Then
-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Nel caso in cui il parametro 1.1.1.2.2.1.1 – Tipo di sistema di linea di contatto è valorizzato = [non elettrificato], questo parametro non è applicabile;
-- Nel caso in cui il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica (voltaggio e frequenza) è valorizzato = [CA 25 kV – 50 Hz], questo parametro deve essere = [800]
-- Nel caso in cui il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica (voltaggio e frequenza) è valorizzato = [CC 3 kV], questo parametro deve essere = [3000].
-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------
--
                If   ((s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> 800) Or    -- 212 25 kV   - Modificato il valore con Reg.777/2019
                      (s_val_new_2 = '30' And s_val_new_1 > 3000)         Or    -- 212  3 kV   - Modificato il valore con Reg.777/2019
                      (s_val_new_3 = '40' And s_val_new_1 Is Not Null) )        -- 211 not electrified
                Then 
                   n_errore := 0;  --KO
                Else
                   n_errore := 1;  --OK
                End If; 
           Else
                n_errore := 0;   -- dati AP/Valore non coerenti(n_ok_AP=0): KO
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0  And s_val_new_AP = v_ko_AP  Then s_commento_AP_ko
                          When n_ok_AP = 0  And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2  = '10' And s_val_new_1 <> 800      Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', questo parametro deve essere = [800]'
                          When n_errore = 0 And s_val_new_2  = '30' And s_val_new_1 > 3000      Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è ' ||GetValueFromCode (55, '30')||', questo parametro deve essere <= [3000]'
                          When n_errore = 0 And s_val_new_2  = '30' And s_val_new_1 Is Null     Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_3  = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1 Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End );
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->'''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre 1.1.1.2.2.1.1 
      Elsif n_controllo_padre = 2 Then            

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),-------------------------------------------->'Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;   
--		   
--    fallisce il secondo padre 1.1.1.2.2.1.2
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(55),------------------------------------------------>''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_2 Errore: '|| Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_2;
--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_2_2_3 (57) - NCT
-- 1.1.1.2.2.3 - ECS_MaxStandstillCurrent - Corrente massima a treno fermo per pantografo [NNN]
-- Indicazione della corrente massima autorizzata per il treno fermi per sistemi in corrente continua
-- (CC), espressa in ampere. AP+CORRELAZIONE (dominio tirato fuori)
-- Il parametro non è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato con [non elettrificato].=[40]
-- Il parametro è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato con [Linea di contatto aerea (OCL)] =[10]
-- e il parametro 1.1.1.2.2.1.2 è valorizzato con [CC 3 kV]-->  il valore di questo parametro deve essere [200].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_3 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is                   
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.3');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_2_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_3_AP', id_sol_track);
--    1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (tensione e frequenza) (55)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1 - Tipo di sistema di linea di contatto (240)
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);       --082
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then              -- (13/06/2016 dominio tirato fuori)
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                n_ok_dominio := 1;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
 --                    If (s_val_new_3 = '10' And s_val_new_2 = '30' And s_val_new_1 Is Not Null) Then                  -- OCL e CC 3kV
 --                         n_errore := 1;
 --                    Else 
--					      n_errore := 0;
 --                    End If; 

                     If    (s_val_new_3 = '10' And s_val_new_2 = '30' And s_val_new_1 Is Null)              -- OCL e CC 3kV
                        Or (s_val_new_3 = '10' And s_val_new_2 = '20' And s_val_new_1 Is Not Null )         -- OCL e CA 15 kV-16.7Hz
                        Or (s_val_new_3 = '40' And s_val_new_1 Is Not Null)                                 -- not electrified
                        Or (s_val_new_3 = '10' And s_val_new_2 = '10' And s_val_new_1 Is Not Null)          -- OCL e CA 25 kV-50Hz
                     Then n_errore := 0;
                     Else n_errore := 1;
                     End If; 

                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					 Then 1
                     Else n_errore
                     End,
                     6, --5
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere valorizzato, altrimenti no'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio					
           p_error_split := Mod(n_errore +1, 2);
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
        --18/05/2016 Schillaci con mail ha choesto di splittare i messaggi nei casi di padri multipli falliti in quanto potrebbero riferirsi a padri di gruppi referenti differenti
        --per i parametri con padre multiplo segnalati esplicitamente i messaggi sono stati splittati; gli altri con padre multiplo ma non segnalati esplicitamente
        --vengono comunque splittati per uniformità ma per sicurezza viene commentata la porzione di codice relativa al commento non splittato

        --        SetControlDetails (
        --                n_controllo,
        --                id_sol,
        --                id_sol_track,
        --                n_parametro,
        --                d_definizione,
        --                Case When  NYA=1 Then 1
        --                        When n_controllo_padre = 1 Then 1
        --                Else 0
        --                End,
        --                14,                 --fallito padre
        --                GetMessFallitiPadriMultipli (240,55), ---------------------------------------->''Tipo Linea Contatto'' e ''Sistema alimentazione elettrica''
        --                s_val_new_1,
        --                s_val_old_ok_1,
        --                n_controllo_old_ok_1,
        --                 Case
        --                        When n_controllo_padre = 1 Then 1
        --                        When NYA=0 Then 0
        --                        When NYA=1 Then 1
        --                   End);

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre  - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->'''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then           
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->'Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_3;
--
-- ------------------------------------------------------------------------------------------------
--                Procedure SET_1_1_1_2_2_4 - NCT - (58) - MODIFICATO - AP+DOMINIO+CORRELAZIONE
-- 1.1.1.2.2.4 - ECS_RegenerativeBraking - Autorizzazione della frenatura a recupero
-- Indicazione se sia autorizzata la frenatura a recupero oppure no. [S/N]
-- Il parametro non è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato con [40]=(non elettrificato).
-- Se il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica (voltaggio e frequenza) è
--     valorizzato = [30](CC 3 kV o = [10] (CA 25 kV – 50 Hz), allora questo parametro deve essere = [S].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_4 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.4');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_4_AP', id_sol_track);
--    1.1.1.2.2.1.2
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1
      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);            --082
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                n_ok_dominio := 1;
		   Else 
                n_ok_dominio := 0;		   
           End If; 

           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
--
                    If (Nvl(s_val_new_3, '40') = '40' And s_val_new_1 Is Null) Then
                          n_errore := 1;
                    Else
  					     If (((s_val_new_2 = '30') Or (s_val_new_2 = '10'))                            -- 1.1.1.2.2.1.2 = [CC 3kV] o [CA 25kV-50Hz] 
                          And (s_val_new_3 <> '40') And (s_val_new_1 = 'Y' ))  Then                    -- 1.1.1.2.2.1.1 <> [non elettrificato] e 1.1.1.2.2.4 = [Y]
                               n_errore := 1;
                          Elsif (((s_val_new_2 = '20') Or (s_val_new_2 = '40')) And (s_val_new_3 <> '40' And s_val_new_1 is Not Null)) Then    -- Sol al confine
                              n_errore := 1;
                          Else 
   					          n_errore := 0;
                         End If; 

                     End If; 
/* 
                    If     (s_val_new_2 = '30' And s_val_new_1 <> 'Y')                   --212 3kV
                           OR (s_val_new_2 = '10' And s_val_new_1 <> 'Y' )               --212 25kV
                           --OR s_val_new_2 = '20' And s_val_new_1 <> 'Y'                --212 15kV
                           OR (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)           --211 not electrified
                        Then
                           n_errore := 0;
                        Else
                           n_errore := 1;
                        End If; 
 */
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP    Then s_commento_AP_ok
                          When n_ok_dominio = 0  Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then  'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '30' Then  'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'Y')
                          When n_errore = 0 And s_val_new_2 = '10' Then  'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'Y')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);
--		   
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre  - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->'''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then           
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->'Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_2_2_4: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_4;
--
-- ------------------------------------------------------------------------------------------------
--          Procedure SET_1_1_1_2_2_5 - NCT (59) - AP+CORRELAZIONE - [N.NN]
-- 1.1.1.2.2.5 - ECS_MaxWireHeight - Altezza massima del filo di contatto
-- Indicazione dell’altezza massima del filo di contatto, espressa in metri.
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato].
-- Il valore di questo parametro nelle linee a 25 kV deve essere pari a [5.50] metri in quanto tutti i
--    punti sotto sospensione hanno un valore di altezza pari a 5,3 metri.
-- Il valore di questo parametro nelle linee a 3 kV deve essere <= [6.10] metri.
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_5 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.5');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_2_5',id_sol_track, s_val_new_1,s_val_old_ok_1) ;
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_5_AP', id_sol_track);
--
--    1.1.1.2.2.1.2
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1
      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);            --082
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 Then
-- ------------------------------------------------------------------------------------------------
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica
--    (voltaggio e frequenza) è valorizzato = [CC 3 kV], questo parametro deve essere <= [6.10].
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica
--    (voltaggio e frequenza) è valorizzato = [CA 25 kV-50 Hz], questo parametro deve essere [5.50].
-- Nel caso in cui il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica (voltaggio e
--     frequenza) è valorizzato = [non elettrificato], questo parametro non è applicabile
-- ------------------------------------------------------------------------------------------------
/*
       If    (s_val_new_2 = '10' And NVL (s_val_new_1, 0) <> 5.5)                             --212 25 kV
                   OR (s_val_new_2 = '30' And s_val_new_1 > 6.1)                              --212 3 kV
                   OR (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)                        --211 not electrified
                Then
                   n_errore := 0;
                Else
                   n_errore := 1;
                End If; 
*/  
                If s_val_new_3 = '40' And s_val_new_1 Is Null Then 
                     n_errore := 1;
                ElsIf (s_val_new_3 <> '40' And s_val_new_2 = '10' And Nvl(s_val_new_1, 0)  = 5.5)  Or      -- [CA 25 kV-50Hz] 
                      (s_val_new_3 <> '40' And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) <= 6.1)  Or      -- [CC 3 kv]
                      (s_val_new_3 <> '40' And (s_val_new_2 = '20' Or s_val_new_2 = '40') And s_val_new_1 Between 5.5 And 6.1) Then   -- Sezioni Linea al confine
                     n_errore := 1;
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then   s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '10' And s_val_new_1 <> 5.5 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere 5,50'
                          When n_errore = 0 And s_val_new_2 = '30' And s_val_new_1 > 6.1 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere minore o uguale a 6,10'
                          When n_errore = 0 And (s_val_new_2 = '20' Or s_val_new_2 = '40') And s_val_new_1 Not Between 5.5 And 6.1 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '20')||' o '||GetValueFromCode (55, '40')||', il parametro deve essere compreso tra 5,5 e 6,10 m'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio	      
           p_error_split := Mod(n_errore +1, 2);                               
--		   
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre  - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->'''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then           
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->'Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_5 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_2_5;
--
-- ------------------------------------------------------------------------------------------------
--                      Procedure SET_1_1_1_2_2_6 - NCT - (60) - [N.NN]
-- 1.1.1.2.2.6 - ECS_MinWireHeight - Altezza minima del filo di contatto - AP+CORRELAZIONE
-- Indicazione dell’altezza minima del filo di contatto, espressa in metri
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato].
-- Il valore di questo parametro nelle linee a 25 kVca deve essere pari a [5.20] metri in quanto tutti i
--     punti sotto sospensione hanno un valore di altezza pari a 5,3 metri.
-- Il valore di questo parametro nelle linee a 3 kVcc deve essere >= [4.51] metri.
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_2_6 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
       n_ok_AP                Number;             -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;             -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);    -- stringa concatenata del dominio
      NYA                    Number;             -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.2.6');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_2_6',id_sol_track, s_val_new_1,s_val_old_ok_1) ;
--
      NYA:= GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_2_6_AP',id_sol_track);
--    1.1.1.2.2.1.2
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1
      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);            --082
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 Then
/*
                If        (s_val_new_2 = '10' And NVL (s_val_new_1, 0) <> 5.2   )               --212 25 kV
                        OR (s_val_new_2 = '30' And s_val_new_1 < 4.51)                                 --212 3 kV
                        OR (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)                --211 not electrified
*/
                If  s_val_new_3 = '40' And s_val_new_1 Is Null Then 
                     n_errore := 1;
				Elsif (s_val_new_2 = '10' And s_val_new_3 <> '40' And Nvl(s_val_new_1, 0) = 5.2 ) Or              -- [CA 25 kV-50Hz]
                      (s_val_new_2 = '30' And s_val_new_3 <> '40' And Nvl(s_val_new_1, 0) >= 4.51 )  Or           -- [CC 3 kv]
                     ((s_val_new_2 = '20' Or s_val_new_2 = '40') And s_val_new_3 <> '40' And Nvl(s_val_new_1, 0) Between  4.51 And 5.2 )    Then       -- Tratte al confine
                     n_errore := 1;
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then  'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '10' And s_val_new_1 <> 5.2 Then  'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere 5,20 m'
                          When n_errore = 0 And s_val_new_2 = '30' And s_val_new_1 < 4.51 Then  'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere maggiore o uguale a 4,51 m'
                          When n_errore = 0 And (s_val_new_2 = '20' Or s_val_new_2 = '40') And s_val_new_1 Not Between 4.51 And 5.2 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '20')||' o '||GetValueFromCode (55, '40')||', il parametro deve essere compreso tra 4,51 e 5,2 m'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--		   
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre  - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->'''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then           
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->'Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_2_6 - Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_2_2_6;
--                                   1.1.1.2.3 Pantografo
-- ------------------------------------------------------------------------------------------------
--                         PROCEDURE SET_1_1_1_2_3_1 - NCT - (61) - MODIFICATO Reg.777/2019
-- 1.1.1.2.3.1 - EPA_TSIHeads - Archetti del pantografo accettati conformi alla STI - AP+DOMINIO+CORRELAZIONE
-- Indicazione degli archetti del pantografo conformi alla STI il cui uso è autorizzato
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 (240) è valorizzato = [non elettrificato].
-- Se questo parametro è applicabile il valore deve essere = [1600 mm] o [nessuno].
-- se il parametro 1.1.1.2.2.1.2 (55) = [10]=CA 25 kV-50 Hz --> [1600 mm]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_3_1  (n_controllo       In     Number,
                              id_sol            In     Varchar2,
                              id_sol_track      In     Varchar2,
                              id_dtp            In     Varchar2,
                              n_controllo_padre In     Number,
                              p_error_split    Out     Number  )  Is
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_new_3             Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      n_ok_AP                 Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio            Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;
      n_errore                Number;
      d_definizione           Varchar2 (1000);
      s_stringa_dominio       Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                     Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2          Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--	  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.3.1');
--
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
	  dbms_output.put_line ('NYA: '||NYA);
--
--    acquisisce il valore dell'Applicabilità associata al parametro
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_1_AP', id_sol_track);
	  dbms_output.put_line ('s_val_new_AP: '||s_val_new_AP);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (tensione e frequenza)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
	  dbms_output.put_line ('s_val_new_2: '||s_val_new_2);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.1 - tipo di sistema di linea di contatto:
--    (10- Linea di contatto aerea (OCL) / 40-Non elettrificato)
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);        --082
	  dbms_output.put_line ('s_val_new_3: '||s_val_new_3);
--
--    verifica la coerenza della coppia di dati AP/valore parametro e NAP/nullo: 1:ok - 0:KO
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
	  dbms_output.put_line ('n_ok_AP: '||n_ok_AP);
--
--    se il codice di ritorno delle procedure SET_1_1_1_2_2_1_1 = 0 e SET_1_1_1_2_2_1_2 = 0
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                               -- se è corretto e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);             -- verifica il valore del parametro nella tabella DOMINIO_PARAMETRO
 	            dbms_output.put_line ('n_ok_dominio GetCorrectValue: '||n_ok_dominio);
--
          Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP  Then                           -- oppure se non è Applicabile (NA)
                n_ok_dominio := 1;
		   Else 
		        n_ok_dominio := 0;                                                      --> aggiunta istruzione perchè non presente
           End If; 
 	            dbms_output.put_line ('n_ok_dominio: '||n_ok_dominio);
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
/*
                     If   (s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> '1600'  )              -- 212 25 kV
                       Or (s_val_new_3 = '40' And s_val_new_1 Is Not Null)                      -- 211 not electrified
                          Then n_errore := 0;               -- KO
                          Else n_errore := 1;
*/
                     If (s_val_new_3 = '40' And s_val_new_1 Is Null) Then    
                          n_errore := 1;               -- ok
                     ElsIf (s_val_new_2 = '10' And s_val_new_3 <> '40' And Nvl(s_val_new_1, 0) = '1600') Then       -- [CA 25 kV-50Hz]
                          n_errore := 1;               -- ok
                     Elsif (s_val_new_3 <> '40' And ( Nvl(s_val_new_1, 0) = 'none' Or Nvl(s_val_new_1, 0) = '1600' )) Then 
                          n_errore := 1;               -- ok
                     Else n_errore := 0;               -- ko
                     End If; 
                Else n_errore := 0;                         -- KO (dominio)
                End If; 
           Else n_errore := 0;                              -- dati AP/Valore non coerenti(n_ok_AP=0): KO
           End If;  	            dbms_output.put_line ('n_errore: '||n_errore);

--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '10' And NVL (s_val_new_1, 0) <> '1600' Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere '||GetValueFromCode (n_parametro, '1600')
--                          When n_ok_dominio = 0 And s_val_new_2 = '10' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, '1600')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_3_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_1;
--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_2_3_2 - NCT - (62) AP+DOMINIO+CORRELAZIONE
-- 1.1.1.2.3.2 - EPA_OtherHeads - Altri archetti del pantografo accettati 
-- Indicazione degli archetti del pantografo il cui uso è autorizzato
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato].
-- Se questo parametro è applicabile il valore deve essere = [1450 mm].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_3_2 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.3.2');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_2_AP', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (tensione e frequenza)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.2.2.1.1 - tipo di sistema di linea di contatto:
--    (10- Linea di contatto aerea (OCL) / 40-Non elettrificato)
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);        --082
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
/*
                 If  (s_val_new_2 = '10' And NVL (s_val_new_1, 0) <> '1450'  )              --212 25 kV
                    OR  (s_val_new_2 = '30' And NVL (s_val_new_1, 0) <> '1450' )               --3 kV
                    OR  (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)                         --211 not electrified
                 Then  n_errore := 0;
                 Else   n_errore := 1;
                 End If; 
*/
                     If ((s_val_new_3 = '40' And s_val_new_1 Is Null) Or
                         (s_val_new_3 <> '40' And s_val_new_1 Is Not Null)) Then
				          n_errore := 1;
                     Else
                          n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
--                          When n_ok_dominio = 0 And s_val_new_2 = '10' Then 'Il campo deve essere valorizzato '||GetValueFromCode (n_parametro, '1450')
--                          When n_ok_dominio = 0 And s_val_new_2 = '30' Then 'Il campo deve essere valorizzato '||GetValueFromCode (n_parametro, '1450')
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240,'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> '1450' Then 'Se '||GetParametro(55,'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere '||GetValueFromCode (n_parametro, '1450')
                          When n_errore = 0 And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) <> '1450' Then 'Se '||GetParametro(55,'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere '||GetValueFromCode (n_parametro, '1450')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             -- fallito padre
                GetMessFallitoPadreSingolo(240),--------------------------------------------------------------->''Tipo Linea Contatto''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                     When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_3_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_2;
--
-- ------------------------------------------------------------------------------------------------
--  Procedure SET_1_1_1_2_3_3_A - NCT (63) - stringa di caratteri predefinita: [N] [NNN] [NNN]
-- 1.1.1.2.3.3 - EPA_NumRaisedSpeed - Requisiti in materia di numero di pantografi alzati e distanza tra loro a una data velocità
-- DOMINIO +AP +CORRELAZIONE        prima parte A
-- Indicazione del numero massimo di pantografi alzati autorizzato per treno e la distanza minima tra archetti adiacenti, 
--   da asse mediano ad asse mediano, espressa in metri a una data velocità
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato].
-- Qualora applicabile, la stringa di caratteri che valorizza il parametro, deve avere una delle 3 formulazioni seguenti:
-- 1° Nelle sezioni di linea alimentate a 3 kV e velocità massima di linea minore o uguale a 160 km/h deve essere indicato: [3] [20] [160]
-- 2° Nelle sezioni di linea alimentate a 3 kV e velocità massima di linea maggiore di 160 km/h deve essere indicato: [2] [200] [250];
-- 3° Nelle sezioni di linea alimentate a 25 kV deve essere indicato: [2] [200] [300].
-- Per le sezioni di linea ai confini con Svizzera/Austria e Francia, per le quali il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione
--  elettrica (voltaggio e frequenza) sia rispettivamente [CA 15kV-16.7Hz] oppure [CC 1.5 kV], occorre valorizzare il parametro
--  secondo le peculiarità del sistema
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_3_3_A (n_controllo       In  Number,
                               id_sol            In  Varchar2,
                               id_sol_track      In  Varchar2,
                               id_dtp            In  Varchar2,
                               n_controllo_padre In  Number,
                               p_error_split     Out Number  )     Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_new_3              Varchar2 (1000);
      s_val_new_4              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                      Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.3.3.A');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_3_3_A', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--AP unica
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_3_AP', id_sol_track);   
--    1.1.1.2.2.1.2 - tipo alimentazione
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);           
--     1.1.1.2.2.1.1 - sist alimentazione
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);       
--    1.1.1.1.2.5 - velocità
      s_val_new_4 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);            
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
           Else 
                n_ok_dominio := 0;
           End If; 
-- --------------------------------------------------------------------------------------------------------------------------------------
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato].
-- Qualora applicabile, la stringa di caratteri che valorizza il parametro, deve avere una delle 3 formulazioni seguenti:
-- 1° Nelle sezioni di linea alimentate a 3 kV e velocità massima di linea minore o uguale a 160 km/h deve essere indicato: [3] [20] [160]
-- 2° Nelle sezioni di linea alimentate a 3 kV e velocità massima di linea maggiore di 160 km/h deve essere indicato: [2] [200] [250];
-- 3° Nelle sezioni di linea alimentate a 25 kV deve essere indicato: [2] [200] [300].
-- --------------------------------------------------------------------------------------------------------------------------------------
/*

           If n_ok_AP = 1 Then
                If          (s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 <>'2')
                            OR (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <=160 And s_val_new_1 <>'3')
                            OR (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 >160 And s_val_new_1 <>'2')
                            OR (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)
                     Then n_errore := 0;
                     Else  n_errore := 1;
                     End If; 
              Else
                 n_errore := 0;
              End If; 
*/
--
            If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                    If s_val_new_3 = '40' and s_val_new_1 Is Null Then 
					      n_errore := 1;
                    Elsif (s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 = 2)  Or
                          (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <= 160 And s_val_new_1 = 3) Or
                          (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4  > 160 And s_val_new_1 = 2)  Then
                          n_errore := 1;
                     Elsif (s_val_new_3 <> '40' And (s_val_new_2 = '20' Or s_val_new_2 = '40')) Then 
                          n_errore := 1;
                     Else n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
            Else
                 n_errore := 0;
            End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP   Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP   Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then 'Il campo Numero Pantografi ammette solamente ' || GetCorrectRangeStringPURA (n_parametro)
                          When n_errore = 0 And s_val_new_3  = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro deve essere nullo perchè non applicabile'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 <> 2 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere [2] [200] [300] '
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <= 160 And s_val_new_1 <> 3 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17, 'Velocità')||' è minore o uguale a 160 km/h, il parametro deve essere [3] [20] [160]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4  > 160 And s_val_new_1 <> 2 Then 'Se '||GetParametro(55, 'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17, 'Velocità')||' è maggiore di 160 km/h, il parametro deve essere [2] [200] [250]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 Is Null Then 'Poichè '||GetParametro(55,'Sistema alim. elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17, 'Velocità')||' non è valorizzato, non si può valutare se deve essere [3] o [2]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 Is Null Then 'Poichè '||GetParametro(240, 'Tipo linea contatto')||' è diversa da '||GetValueFromCode (240, '40')||' e '||GetParametro(55,'Sistema alim.elettr.')||' non è valorizzato, non si può valutare se deve essere [3] o [2]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_1 Is Null Then 'Numero Pantografi mancante'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);  
--		   
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
