                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
