           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_2_3_3_A: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_3_A;
