-- ------------------------------------------------------------------------------------------------
--  Procedure SET_1_1_1_2_3_3_B - NCT (241) - stringa di caratteri predefinita: [N] [NNN] [NNN]
-- 1.1.1.2.3.3 - EPA_NumRaisedSpeed - Requisiti in materia di numero di pantografi alzati e distanza tra loro a una data velocità
-- DOMINIO +AP +CORRELAZIONE - seconda parte B - DistMin.pantografi. Per le regole vedi sopra              
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_2_3_3_B (n_controllo       In Number,
                                id_sol            In Varchar2,
                                id_sol_track      In Varchar2,
                                id_dtp            In Varchar2,
                                n_controllo_padre In Number,
                                p_error_split    Out Number  )     Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_new_4               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                       Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.3.3.B');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_3_B', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    AP unica
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_3_AP', id_sol_track);   
--    1.1.1.2.2.1.2 - tipo alimentazione
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track); 
--    1.1.1.2.2.1.1 - sist alimentazione
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);  
--    1.1.1.1.2.5 - velocità
      s_val_new_4 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);    
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
     If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
           Else 
                n_ok_dominio := 0;
           End If; 
/*
     If n_ok_AP = 1      Then
         If (s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 <>'200')
                OR (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <=160 And s_val_new_1 <>'20')
                OR (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 >160 And s_val_new_1 <>'200')
                OR (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)
         Then n_errore := 0;
         Else  n_errore := 1;
         End If; 
      Else
         n_errore := 0;
      End If; 
*/
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (s_val_new_3 = '40' And s_val_new_1 Is Null) Then
                          n_errore := 1;
                     Elsif (s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 = 200)    Or
                        (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <= 160 And s_val_new_1 = 20) Or
                        (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4  > 160 And s_val_new_1 = 200) Then 
                          n_errore := 1;
                     Elsif (s_val_new_3 <> '40' And (s_val_new_2 = '20' Or s_val_new_2 = '40')) Then 
                          n_errore := 1;
                     Else n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP   Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP   Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then 'Il campo Distanza Minima Pantografi ammette solamente ' || GetCorrectRangeStringPURA (n_parametro)
                          When n_errore = 0 And s_val_new_3 =  '40' And s_val_new_1 Is Not Null Then 'Se '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 <> 200 Then 'Se '||GetParametro(55,'Sistema lim.elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere [2] [200] [300] '
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <= 160 And s_val_new_1 <> 20  Then 'Se '||GetParametro(55,'Sistema lim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17, 'Velocità')||' è minore o uguale a 160 km/h, il parametro deve essere [3] [20] [160]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4  > 160 And s_val_new_1 <> 200 Then 'Se '||GetParametro(55,'Sistema lim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17, 'Velocità')||' è maggiore di 160 km/h, il parametro deve essere [2] [200] [250]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 Is Null Then 'Poichè '||GetValueFromCode (55, '30')||' e '||GetParametro(17, 'Velocità')||' non è valorizzato, non si può valutare se deve essere [20] o [200]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 Is Null Then 'Poichè '||GetParametro(240, 'Tipo linea contatto')||' è diversa da '||GetValueFromCode (240, '40')||' e '||GetParametro(55,'Sistema lim.elettr.')||' non è valorizzato, non si può valutare se deve essere [20] o [200]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_1 Is Null Then 'Distanza Minima Pantografi mancante'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
 EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_3_3_B - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_3_B;
