           End If; 
--
/*     If n_ok_AP = 1
      Then
         If         (s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 <>'300')
                OR (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <=160 And s_val_new_1 <>'160')
                OR (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 >160 And s_val_new_1 <>'250')
                OR (s_val_new_3 = '40' And s_val_new_1 IS NOT NULL)
         Then n_errore := 0;
         Else  n_errore := 1;
         End If; 
      Else
         n_errore := 0;
      End If; 
*/
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (s_val_new_3 = '40' And s_val_new_1 Is Null) Then
                          n_errore := 1;
                     Elsif (s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 = 300)   Or
                           (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <= 160 And s_val_new_1 = 160) Or
                           (s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4  > 160 And s_val_new_1 = 250)  Then 
                          n_errore := 1; 
                     Elsif (s_val_new_3 <> '40' And (s_val_new_2 = '20' Or s_val_new_2 = '40')) Then 
                          n_errore := 1;
                     Else 
					      n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP   Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP   Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then 'Il campo Velocità Riferimento ammette solamente ' ||GetCorrectRangeStringPURA (n_parametro)
                          When n_errore = 0 And s_val_new_3  = '40' And s_val_new_1 Is Not Null Then 'Se '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '10' And s_val_new_1 <> 300 Then 'Se '||GetParametro(55,'Sistema lim.elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere [2] [200] [300] '
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 <= 160 And s_val_new_1 <> 160 Then 'Se '||GetParametro(55,'Sistema lim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17,'Velocità')||' è minore o uguale a 160 km/h, il parametro deve essere [3] [20] [160]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4  > 160 And s_val_new_1 <> 250 Then 'Se '||GetParametro(55,'Sistema lim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17,'Velocità')||' è maggiore di 160 km/h, il parametro deve essere [2] [200] [250]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 = '30' And s_val_new_4 Is Null Then 'Poichè '||GetValueFromCode (55, '30')||' e '||GetParametro(17,'Velocità')||' non è valorizzato, non si può valutare se deve essere [160] o [250]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_2 Is Null Then 'Poichè '||GetParametro(240,'Tipo linea contatto.')||' è diversa da '||GetValueFromCode (240, '40')||' e '||GetParametro(55,'Sistema lim.elettr.')||' non è valorizzato, non si può valutare se deve essere [160] o [250] o [300]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_1 Is Null Then 'Velocità di Riferimento mancante'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 

  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_3_3_C - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_3_C;
--
-- ------------------------------------------------------------------------------------------------
--                 PROCEDURE SET_1_1_1_2_3_3_TOTALE
-- 1.1.1.2.3.3 TOTALE req.n.patografi+dist+velocità AP+CORRELAZIONE  concatenato
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_3_3_TOTALE (n_controllo      In Number,
                                   id_sol            In Varchar2,
                                   id_sol_track      In Varchar2,
                                   id_dtp            In Varchar2,
                                   n_controllo_padre In Number,
                                   p_error_split    Out Number  )  Is
      n_parametro                  Number;
      s_val_new_1                  Varchar2 (1000);
      s_val_new_2                  Varchar2 (1000);
      s_val_new_3                  Varchar2 (1000);
      s_val_new_4                  Varchar2 (1000);
      s_val_new_5                  Varchar2 (1000);
      s_val_new_6                  Varchar2 (1000);
      s_val_old_ok_1               Varchar2 (1000);
      s_val_new_AP                 Varchar2 (1000);
      n_ok_AP                      Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio                 Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1         Number;
      n_errore                     Number;
      d_definizione                Varchar2 (1000);
      s_stringa_dominio            Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                          Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2               Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3               Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.3.3.A');          -- come riferimento uso A
----  recupero valori A new e old ok
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_3_A', id_sol_track, s_val_new_1, s_val_old_ok_1) ; 
--    recupero valori B new e old ok in variabile 2 DISTANZA
      Select new.SOL_TRACK_1_1_1_2_3_3_B new_val,                                             
             old.SOL_TRACK_1_1_1_2_3_3_B old_val   
		    Into s_val_new_2, s_val_old_ok_2
            From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
                 Rinf_Controllati_Evo.BINARI_CORSA_SOL old
           Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
		     And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track ;
--     recupero valori C new e old ok in variabile 3 VELOCITA'
      SELECT new.SOL_TRACK_1_1_1_2_3_3_C new_val,                                             
             old.SOL_TRACK_1_1_1_2_3_3_C old_val   
		    Into s_val_new_3, s_val_old_ok_3
            From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
                 Rinf_Controllati_Evo.BINARI_CORSA_SOL old
        Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
		  And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track ;
--    come riferimento uso A: se NYA A, allora do per scontato se lo siano anche B e C
      NYA := GetNYA (n_parametro);         
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_3_AP', id_sol_track);
--    1.1.1.2.2.1.2 - tipo alimentazione
      s_val_new_4 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);           
--    1.1.1.2.2.1.1 - sist alimentazione
      s_val_new_5 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);       
--    1.1.1.1.2.5 - velocità
      s_val_new_6 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_1_2_5', id_sol_track);            
--    come riferimento uso A: se NYA A, allora do per scontato se lo siano anche B e C
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);         
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1  Then
                If  (s_val_new_5 <> '40' And s_val_new_4 = '10' And Nvl(s_val_new_1, 0) = 2 And Nvl(s_val_new_2, 0) = 200 And Nvl(s_val_new_3, 0) = 300)
                 Or (s_val_new_5 <> '40' And (s_val_new_4 = '20' or s_val_new_4 = '40') And s_val_new_4 Is Not Null And s_val_new_1 Is Not Null And s_val_new_2 Is Not Null And s_val_new_3 Is Not Null)
                 Or (s_val_new_5 <> '40' And s_val_new_4 = '30' And s_val_new_6 <= 160 And Nvl(s_val_new_1, 0) = 3 And Nvl(s_val_new_2, 0) = 20  And NVL (s_val_new_3, 0) = 160)
                 Or (s_val_new_5 <> '40' And s_val_new_4 = '30' And s_val_new_6  > 160 And Nvl(s_val_new_1, 0) = 2 And Nvl(s_val_new_2, 0) = 200 And NVL (s_val_new_3, 0) = 250)
                 Or (s_val_new_5  = '40' And s_val_new_4 Is Null And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null)             --211 not electrified -->A,B,C nulli
                Then
                     n_errore := 1;
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When  NYA=1 Then 1
                     Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_errore = 0 And s_val_new_5  = '40' Then 'Se '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_5 <> '40' And s_val_new_1 not in (2,3) And s_val_new_2 not in (20,200) And  s_val_new_3 not in (160,250,300) Then 'Valori non ammissibili: sono ammessi solo le sequenze [3] [20] [160] o [2] [200] [250] o [2] [200] [300]'
                          When n_errore = 0 And s_val_new_5 <> '40' And s_val_new_4 = '10' Then 'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere [2] [200] [300]'
                          When n_errore = 0 And s_val_new_5 <> '40' And s_val_new_4 = '30' And s_val_new_6 <= 160 Then  'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17,'Velocità')||' è minore o uguale a 160 km/h, il parametro deve essere [3] [20] [160]'
                          When n_errore = 0 And s_val_new_5 <> '40' And s_val_new_4 = '30' And s_val_new_6 > 160 Then 'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17,'Velocità')||' è maggiore di 160 km/h, il parametro deve essere [2] [200] [250]'
                          When n_errore = 0 And s_val_new_5 <> '40' And s_val_new_4 = '30' And s_val_new_6 Is Null Then 'Poichè '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||' e '||GetParametro(17,'Velocità')||' non è valorizzato, non si può valutare se deve essere [3] [20] [160] o [2] [200] [250]'
                          When n_errore = 0 And s_val_new_3 <> '40' And s_val_new_4 Is Null Then 'Poichè '||GetParametro(240,'Tipo linea contatto')||' è diversa da '||GetValueFromCode (240, '40')||' e '||GetParametro(55,'Sistema alim.elettr.')||' non è valorizzato, non si può valutare se deve essere [3] [20] [160] o [2] [200] [250] o [2] [200] [300]'
                          When n_errore = 0 And s_val_new_5 <> '40' And (s_val_new_4 <> '20' And s_val_new_4 <> '40') And (s_val_new_1 Is Null Or s_val_new_2 Is Null Or s_val_new_3 Is Null) Then 'Numero Pantografi/ Distanza Minima Pantografi/ Velocità di Riferimento mancante'
                          Else Null
                     End,
                     s_val_new_1||' '||s_val_new_2||' '||s_val_new_3,
                     s_val_old_ok_1||' '||s_val_old_ok_2||' '||s_val_old_ok_3,
                     n_controllo_old_ok_1,
                     Case
                             When n_errore = 0 And NYA = 0 Then 0
                             When n_errore = 0 And NYA = 1 Then 1
                             When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     18,  --21,                               -- fallito padre (composito) -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     18,                              -- fallito padre (composito)
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     19,  --14,                             -- fallito padre (composito)
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                20, --14,                            -- fallito padre (composito)
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_2_3_3_TOTALE: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_3_TOTALE;
--
-- ------------------------------------------------------------------------------------------------
--        Procedure SET_1_1_1_2_3_4 - NCT - (61)
-- 1.1.1.2.3.4 - EPA_StripMaterial - Materiali degli striscianti autorizzati
-- Indicazione di quali materiali degli striscianti è consentito l'uso
-- archetti accettati AP+DOMINIO+CORRELAZIONE
-- Questo parametro non è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato = [non elettrificato].
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica
--   (voltaggio e frequenza) è impostata = [CC 3 kV], questo parametro deve essere = [carbonio con placcatura in rame].
-- Se, invece, 1.1.1.2.2.1.2 = [CA 25 kV-50 Hz], questo parametro deve essere [carbonio solo].
-- Modificata la procedura per la variazione di un valore dell'elenco con conseguente modifica dei controlli (28/10/2024)
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_3_4 (n_controllo    IN     Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.3.4');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_3_4_AP', id_sol_track);
--
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);        
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
--
-- GetCodValueFromXML (64, '20') = 'plain carbon'  -- inserito a partire da 10/2024
-- GetCodValueFromXML (64, '40') = 'copper alloy'  -- dismesso a partire da 10/2024
-- GetCodValueFromXML (64, '70') = 'carbon with cladded copper'
--
-- verifica e controllo sulla congruità e vincoli con gli altri parametri:
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
--
/*
                     If (s_val_new_3 = '40' And s_val_new_1 Is Null ) Or
                        (s_val_new_3 <> '40' And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) = 'carbon with cladded copper') Or     -- [CC 3 kV]
--                        (s_val_new_3 <> '40' And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) = 'copper alloy') Then               -- [CA 25 Kv-50Hz]                  --212 25 kV
                        (s_val_new_3 <> '40' And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) = 'plain carbon') Then                 -- [CA 25 Kv-50Hz]                  --212 25 kV
*/
                     If (s_val_new_3 = '40' And s_val_new_1 Is Null ) Or
                        (s_val_new_3 <> '40' And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) = GetCodValueFromXML (64, '70')) Or     -- [CC 3 kV]
--                        (s_val_new_3 <> '40' And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) = GetCodValueFromXML (64, '40')) Or               -- [CA 25 Kv-50Hz]                  --212 25 kV
                        (s_val_new_3 <> '40' And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) = GetCodValueFromXML (64, '20')) Then                 -- [CA 25 Kv-50Hz]                  --212 25 kV
--
                          n_errore := 1;
                     Elsif (s_val_new_3 <> '40' And (s_val_new_2 = '20' Or s_val_new_2 = '40' )) Then
                          n_errore := 1;
                     Else
                          n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
/*                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 And s_val_new_2 = '10' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'copper alloy')
                          When n_ok_dominio = 0 And s_val_new_2 = '30' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'carbon with cladded copper')
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240,'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) <> 'carbon with cladded copper'  Then 'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'carbon with cladded copper')
                          When n_errore = 0 And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> 'copper alloy' Then  'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'copper alloy')
                          Else Null
                     End,
*/					 
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 And s_val_new_2 = '10' Then 'Il parametro deve essere valorizzato '||GetCodValueFromXML (64, '20')
                          When n_ok_dominio = 0 And s_val_new_2 = '30' Then 'Il parametro deve essere valorizzato '||GetCodValueFromXML (64, '70')
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240,'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) <> GetCodValueFromXML (64, '70')  Then 'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere '||GetCodValueFromXML (64, '70')
                          When n_errore = 0 And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> GetCodValueFromXML (64, '20')  Then 'Se '||GetParametro(55,'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere '||GetCodValueFromXML (64, '20')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_3_4 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_3_4;
--                         1.1.1.2.4 - Tratti a separazione della catenaria
-- ------------------------------------------------------------------------------------------------
--             Procedure SET_1_1_1_2_4_1_1 - (65)
-- 1.1.1.2.4.1.1 - EOS_Phase - Separazione di fase - AP+DOMINIO+CORRELAZIONE [S/N]
-- Il parametro è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato [Linea di contatto aerea (OCL)].
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica
--   (voltaggio e frequenza) è impostato al valore [CC 3 kV], questo parametro deve essere [N].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_1_1 (n_controllo       In  Number,
                               id_sol            In  Varchar2,
                               id_sol_track      In  Varchar2,
                               id_dtp            In  Varchar2,
                               n_controllo_padre In  Number,
                               p_error_split     Out Number  )     Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_new_3              Varchar2 (1000);
      s_val_new_4              Varchar2 (1000);
      s_val_new_5              Varchar2 (1000);
      s_val_new_6              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                      Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3           Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.1.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_1_AP', id_sol_track);
--    1.1.1.2.2.1.2
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1
      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
/*                           If    (s_val_new_2 = '30' And NVL (s_val_new_1, 0) <> 'N')
                               OR (s_val_new_3 <> '10' And s_val_new_1 IS NOT NULL)
                            Then n_errore := 0;
                            Else n_errore := 1;
                            End If; 
*/
                     If (s_val_new_3 <> '10' And s_val_new_1 Is Null) Then       -- 1.1.1.2.2.1.1=[Linea di contatto aerea (OCL)]
                          n_errore := 1;
                     Elsif (s_val_new_3 <> '10' And s_val_new_1 Is Not Null) Then       -- 1.1.1.2.2.1.1=[Linea di contatto aerea (OCL)]
					      n_errore := 0;
					 ElsIf (s_val_new_2  = '30' And Nvl(s_val_new_1, 0) = 'N') Then   -- 1.1.1.2.2.1.2=[CC 3Kv]
                          n_errore := 1;
					 ElsIf (s_val_new_2 <> '30' And s_val_new_1 Is Not Null) Then
 					      n_errore := 1;
                     Else 
					      n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 <>'10' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' non è '||GetValueFromCode (240, '10')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) <> 'N' Then 'Se '||GetParametro(55, 'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'N')
--                          When n_errore = 0 And s_val_new_3 ='40' And s_val_new_1 IS NOT NULL Then 'Se '||GetParametro(240,'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'     --è una specifica della successiva per il caso non elettrificato
--                          When n_errore = 0 And s_val_new_3 <>'10' And s_val_new_1 IS NOT NULL Then 'Se '||GetParametro(240,'Tipo linea contatto')||' non è '||GetValueFromCode (240, '10')||', il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_1_1 - Errore: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_2_4_1_1;
--
-- ------------------------------------------------------------------------------------------------
--   Procedure SET_1_1_1_2_4_1_2_A (67)  - length+AP+CORR  benchè numerico libero - prima parte A
-- 1.1.1.2.4.1.2 - EOS_InfoPhase - Informazioni sulla separazione di fase (A: Lunghezza separazione fase [NNN])
-- Stringa di caratteri predefinita: lunghezza [NNN] + interruttore per lo spegnimento[S/N] + pantografo più basso [S/N]
-- Il parametro è applicabile se il parametro 1.1.1.2.4.1.1 è valorizzato con [S].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_1_2_A (n_controllo       In  Number,
                                 id_sol            In  Varchar2,
                                 id_sol_track      In  Varchar2,
                                 id_dtp            In  Varchar2,
                                 n_controllo_padre In  Number,
                                 p_error_split     Out Number  )     Is
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_new_3                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;
      n_errore                   Number;
      d_definizione              Varchar2 (1000);
      s_stringa_dominio          Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                        Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3             Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI            EMPCUR;            -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.1.2.A');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_4_1_2_A', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    AP unica
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_AP', id_sol_track);   
--    1.1.1.2.4.1.1 - separazione di fase
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_1', id_sol_track);           
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 Then
                If (Nvl(s_val_new_2, 0) = 'Y' And s_val_new_1 <= 999) Or
                   (Nvl(s_val_new_2, 0) = 'N' And s_val_new_1 Is Null) Or
                       (s_val_new_2 Is Null And s_val_new_1 Is Null) Then                 --se non AP 411, va bene che questo sia non AP
                     n_errore := 1;
                Else n_errore := 0;
                End If; 
           Else n_errore:=0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 Is Null Then 'Se '||GetParametro(65,'Separazione di Fase')||' non è applicabile, il parametro non deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' Then 'Se '||GetParametro(65,'Separazione di Fase')||' è '||GetValueFromCode (65, 'N')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_1 > 999 Then 'Il campo Lunghezza deve essere composto da tre cifre'
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(65,'Separazione di Fase')||' è '||GetValueFromCode (65, 'Y')||', il parametro deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre 
                     GetMessFallitoPadreSingolo(65),--------------------------------------------------------------->''Separazione Fase''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_1_2_A - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_1_2_A;
--
-- ------------------------------------------------------------------------------------------------
--   Procedure SET_1_1_1_2_4_1_2_B (66)  - DOMINIO+AP  +CORR - seconda parte B
-- 1.1.1.2.4.1.2 - EOS_InfoPhase - Informazioni sulla separazione di fase (B: Disattivazione freno [S/N])
-- Stringa di caratteri predefinita: lunghezza [NNN] + interruttore per lo spegnimento[S/N] + pantografo più basso [S/N]
-- Il parametro è applicabile se il parametro 1.1.1.2.4.1.1 è valorizzato con [S].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_1_2_B (n_controllo       In  Number,
                                 id_sol            In  Varchar2,
                                 id_sol_track      In  Varchar2,
                                 id_dtp            In  Varchar2,
                                 n_controllo_padre In  Number,
                                 p_error_split     Out Number  )     Is
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_new_3                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;
      n_errore                   Number;
      d_definizione              Varchar2 (1000);
      s_stringa_dominio          Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                        Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3             Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.1.2.B');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_B', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    AP unica
      s_val_new_AP:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_AP', id_sol_track);   
--    1.1.1.2.4.1.1 - separazione di fase
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_4_1_1', id_sol_track);           
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
       If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP  Then
                n_ok_dominio := 1;
           Else
                n_ok_dominio := 0;
           End If; 

           If n_ok_AP = 1 Then
                If (Nvl(s_val_new_2, 0) = 'Y' And s_val_new_1 = 'Y') Or         -- 1.1.1.2.4.1.1 = [S] --> 1.1.1.2.4.1.2.B = [S]
                   (Nvl(s_val_new_2, 0) = 'N' And s_val_new_1 Is Null) Or       -- 1.1.1.2.4.1.1 = [N] -->[]
                   (s_val_new_2 Is Null And s_val_new_1 Is Null) Then           -- se non AP 1.1.1.2.4.1.1, va bene che questo sia non AP
                     n_errore := 1;
                Else  
				     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

          SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' Then 'Se '||GetParametro(65, 'Separazione di Fase')||' è '||GetValueFromCode (65, 'N')||', il parametro non deve essere valorizzato'
                          When n_ok_dominio = 0 Then 'Il campo Interruttore Spegnimento ammette solamente ' || GetCorrectRangeStringPURA (n_parametro)
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(65, 'Separazione di Fase')||' è '||GetValueFromCode (65, 'Y')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Y')
                          When n_errore = 0 And s_val_new_2 Is Null Then 'Se '||GetParametro(65, 'Separazione di Fase')||' non è applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                     Else 0
                     End,
                     14,                            -- fallito padre 
                     GetMessFallitoPadreSingolo(65),--------------------------------------------------------------->''Separazione Fase''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_1_2_B - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_1_2_B;
