-- ------------------------------------------------------------------------------------------------
--   Procedure SET_1_1_1_2_4_1_2_C (68)  - DOMINIO + AP + CORR - terza parte C
-- 1.1.1.2.4.1.2 - EOS_InfoPhase - Informazioni sulla separazione di fase (C: Abbassamento archetti)
-- Stringa di caratteri predefinita: lunghezza [NNN] + interruttore per lo spegnimento[S/N] + pantografo più basso [S/N]
-- Il parametro è applicabile se il parametro 1.1.1.2.4.1.1 è valorizzato con [S].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_1_2_C (n_controllo       In  Number,
                                 id_sol            In  Varchar2,
                                 id_sol_track      In  Varchar2,
                                 id_dtp            In  Varchar2,
                                 n_controllo_padre In  Number,
                                 p_error_split     Out Number  )     Is
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_new_3                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;
      n_errore                   Number;
      d_definizione              Varchar2 (1000);
      s_stringa_dominio          Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                        Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3             Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.1.2.C');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_C', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    AP unica
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_AP', id_sol_track);   
--    1.1.1.2.4.1.1 - separazione di fase
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_1', id_sol_track);           
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
           Else
                n_ok_dominio := 0;
           End If; 

           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (Nvl(s_val_new_2, 0) = 'Y' And s_val_new_1 = 'N') Or             -- 1.1.1.2.4.1.1 = [S] --> 1.1.1.2.4.1.2.C = [N]
                        (Nvl(s_val_new_2, 0) = 'N' And s_val_new_1 Is Null) Or           -- 1.1.1.2.4.1.1 = [N] -->[]
                         (s_val_new_2 Is Null And  s_val_new_1 Is Null)   Then           -- se non AP 1.1.1.2.4.1.1, va bene che questo sia non AP
                          n_errore := 1;
                     Else  
					      n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 

           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' Then 'Se '||GetParametro(65, 'Separazione di Fase')||' è '||GetValueFromCode (65, 'N')||', il parametro non deve essere valorizzato'
                          When n_ok_dominio = 0 Then 'Il campo Pantografo Basso ammette solamente ' || GetCorrectRangeStringPURA (n_parametro)
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(65, 'Separazione di Fase')||' è '||GetValueFromCode (65, 'Y')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'N')
                          When n_errore = 0 And s_val_new_2 Is Null Then 'Se '||GetParametro(65,'Separazione di Fase')||' non è applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre 
                     GetMessFallitoPadreSingolo(65),--------------------------------------------------------------->''Separazione Fase''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_1_2_C - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_1_2_C;
--
-- ------------------------------------------------------------------------------------------------
-- 1.1.1.2.4.1.2 TOTALE Lunghezza separazione FASE+Disatt freno+Abbass.archetti AP+CORRELAZIONE - concatenato
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_1_2_TOTALE (n_controllo       In  Number,
                                      id_sol            In  Varchar2,
                                      id_sol_track      In  Varchar2,
                                      id_dtp            In  Varchar2,
                                      n_controllo_padre In  Number,
                                      p_error_split     Out Number  )     Is
      n_parametro                     Number;
      s_val_new_1                     Varchar2 (1000);
      s_val_new_2                     Varchar2 (1000);
      s_val_new_3                     Varchar2 (1000);
      s_val_new_4                     Varchar2 (1000);
      s_val_old_ok_1                  Varchar2 (1000);
      s_val_new_AP                    Varchar2 (1000);
      n_ok_AP                         Number;            -- variabile appoggio applicabilità 0/1
      n_ok_dominio                    Number;            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1            Number;
      n_errore                        Number;
      d_definizione                   Varchar2 (1000);
      s_stringa_dominio               Varchar2 (1000);   -- stringa concatenata del dominio
      NYA                             Number;            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2                  Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3                  Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro (come riferimento uso A)
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.1.2.A');          
----  recupero valori A new e old ok
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_A', id_sol_track, s_val_new_1, s_val_old_ok_1); 
--    recupero valori B new e old ok
      Select new.SOL_TRACK_1_1_1_2_4_1_2_B new_val,                                             
             old.SOL_TRACK_1_1_1_2_4_1_2_B old_val   
	    Into s_val_new_2, s_val_old_ok_2
        From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
             Rinf_Controllati_Evo.BINARI_CORSA_SOL old
       Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
	     And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track ;
--    recupero valori C new e old ok
      Select new.SOL_TRACK_1_1_1_2_4_1_2_C new_val,                                             
             old.SOL_TRACK_1_1_1_2_4_1_2_C old_val   
		Into s_val_new_3, s_val_old_ok_3
        From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
             Rinf_Controllati_Evo.BINARI_CORSA_SOL old
       Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
	     And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track ;
--    come riferimento uso A: se NYA A, allora do per scontato se lo siano anche B e C
      NYA := GetNYA (n_parametro);         
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_1_2_AP', id_sol_track);
--    1.1.1.2.4.1.1 - separazione di fase
      s_val_new_4 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_4_1_1', id_sol_track);           
--    come riferimento uso A: se NYA A, allora do per scontato se lo siano anche B e C
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);         
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 Then
                If (Nvl (s_val_new_4, 0) = 'Y' And s_val_new_1 <= 999 And Nvl(s_val_new_2, 0) = 'Y' And Nvl(s_val_new_3, 0) = 'N') Or  --CORRETTA
                   (Nvl (s_val_new_4, 0) = 'N' And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null) Or
                   (s_val_new_4 Is Null And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null)  Then
                     n_errore := 1;
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_4, 0) = 'Y' Then 'Se '||GetParametro(65,'Separazione di Fase')||' è '||GetValueFromCode (65, 'Y')||' il parametro deve essere nella forma [NNN]+[S]+[N]'
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_4, 0) = 'N' Then 'Se '||GetParametro(65,'Separazione di Fase')||' è '||GetValueFromCode (65, 'N')||' il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_4 Is Not Null And (s_val_new_1 is  null Or s_val_new_2 is  null Or s_val_new_3 Is Null) Then 'Lunghezza Separazione Fase/ Apertura Interruttore/ Abbassamento Pantografo mancante'
                          When n_errore = 0 And s_val_new_4 Is Null Then 'Se '||GetParametro(65,'Separazione di Fase')||' non è applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     Case
                         When n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then Null           --se AP è giusta ed è NO, allora non scrive nulla
                         Else s_val_new_1||'+'||s_val_new_2||'+'||s_val_new_3
                     End,
                     Case
                         When n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then Null           --se AP è giusta ed è NO, allora non scrive nulla
                         Else s_val_old_ok_1||'+'||s_val_old_ok_2||'+'||s_val_old_ok_3
                     End,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     18,   --14,                            -- fallito padre (composito)
                     GetMessFallitoPadreSingolo(65),--------------------------------------------------------------->''Separazione Fase''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_1_2_TOTALE - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_1_2_TOTALE;
--
-- ------------------------------------------------------------------------------------------------
--               Procedure SET_1_1_1_2_4_2_1 - AP+DOMINIO+CORRELAZIONE (69)
-- 1.1.1.2.4.2.1 - EOS_System - Separazione di sistema - Indicazione dell’esistenza di separazione di sistema
-- Il parametro è applicabile se il parametro 1.1.1.2.2.1.1 è valorizzato [Linea di contatto aerea (OCL)].
-- Qualora applicabile, sono ammessi soltanto valori [S] o [N] previsti dal formato del parametro
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_2_4_2_1(n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_new_5            Varchar2 (1000);
      s_val_new_6            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
dbms_output.put_line (' n_controllo_old_ok_1: '||n_controllo_old_ok_1);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
dbms_output.put_line ('d_definizione: '||d_definizione);
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.2.1');
dbms_output.put_line ('n_parametro: '||n_parametro);
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
dbms_output.put_line ('il parametro può essere NYA: '||NYA);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_1_AP', id_sol_track);
dbms_output.put_line ('Applicabilità (s_val_new_AP): '||s_val_new_AP);	  
--    1.1.1.2.2.1.2
     s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
dbms_output.put_line ('s_val_new_2: '||s_val_new_2);
--    1.1.1.2.2.1.1
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);
dbms_output.put_line ('s_val_new_3: '||s_val_new_3);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
dbms_output.put_line ('Il valore è coerente con l''applicabilità - n_ok_AP :'||n_ok_AP );
--
      If n_controllo_padre = 0 Then
dbms_output.put_line ('n_controllo_padre = 0');

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ok_AP --> n_ok_dominio: '||n_ok_dominio);	
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then   
		        n_ok_dominio := 1;
dbms_output.put_line ('n_ok_AP = 1 e s_val_new_AP = v_ko_AP --> n_ok_dominio = 1');
           Else
		        n_ok_dominio := 0;
           End If; 
dbms_output.put_line ('n_ok_dominio (end if): '||n_ok_dominio);	
--
           If n_ok_AP = 1 Then
dbms_output.put_line ('n_ok_AP = 1 ');	
                If n_ok_dominio = 1 Then
dbms_output.put_line ('n_ok_AP = 1 e n_ok_dominio = 1');
                     If ( s_val_new_3 = '10' And s_val_new_1 Is Not Null ) Or   -- 1.1.1.2.2.1.1=['10': Linea di contatto aerea (OCL)]
					    ( s_val_new_3 = '40' And s_val_new_1 Is Null )    Or
                        (s_val_new_3 Is Null And s_val_new_1 Is Null) Then          
                        n_errore := 1;
                     Else
                        n_errore := 0;
                     End If; 
                 Else
                     n_errore := 0;
                 End If; 
           Else
                 n_errore := 0;
           End If; 
dbms_output.put_line ('n_errore: '||n_errore);
--
          SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240,'Tipo linea contatto')||' è '|| GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'     --è una specifica della successiva per il caso non elettrificato
                          When n_errore = 0 And s_val_new_3 <> '10' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240,'Tipo linea contatto')||' non è '|| GetValueFromCode (240, '10')||',  il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When  NYA=1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),--------------------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_2_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_2_1;
--
-- ------------------------------------------------------------------------------------------------
-- Procedure SET_1_1_1_2_4_2_2_A (72) - A: Lunghezza separazione fase: length+AP+CORR (benchè numerico libero) - prima parte A
-- 1.1.1.2.4.2.2 - EOS_InfoSystem - Informazioni sulla separazione di sistema
-- Stringa di caratteri predefinita: lunghezza [NNN] + interruttore per lo spegnimento [S/N] + pantografo più basso [S/N] + stringa di caratteri
-- Il parametro è applicabile se il parametro 1.1.1.2.4.2.1 è valorizzato con [S].
-- Qualora applicabile, il parametro assume il formato [NNN] + [S] + [S]. È accettato il formato
-- [NNN] + [S] + [S] + [S], che permetta la compatibilità con il formato definito dalla precedente Decisione 880/2014.
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_2_2_A (n_controllo   In     Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.2.2.A');

      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_2_A', id_sol_track, s_val_new_1, s_val_old_ok_1);

      NYA := GetNYA (n_parametro);
--    AP unica
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_2_AP', id_sol_track);   
--    1.1.1.2.2.4.2.1 - separazione di sistema (69)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_1', id_sol_track);           
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 Then
                If (Nvl(s_val_new_2, '0') = 'Y' And s_val_new_1 <= 999) Or
                   (Nvl(s_val_new_2, '0') = 'N' And s_val_new_1 Is Null) Or
                   (s_val_new_2 Is Null And s_val_new_1 Is Null) Then           -- se non AP 1.1.1.2.2.4.2.1, va bene che questo sia non AP
                     n_errore := 1;
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' Then 'Se '||GetParametro(69, 'Separazione di sistema')||' è '||GetValueFromCode (69, 'N')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_1 > 999 Then 'Il campo Lunghezza deve essere composto da tre cifre'
                          When n_ok_AP = 1 And n_errore = 0 And Nvl (s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(69, 'Separazione di sistema')||' è '||GetValueFromCode (69, 'Y')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 Is Null Then 'Se '||GetParametro(69, 'Separazione di sistema')||' non è applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When  NYA=1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(69),--------------------------------------------------------------->''Separazione Sistema''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_2_2_A - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_2_2_A;
--
-- ------------------------------------------------------------------------------------------------
-- Procedure SET_1_1_1_2_4_2_2_B (71) - B: Disattivazione freni: DOMINIO + AP + CORR - seconda parte B
-- 1.1.1.2.4.2.2 - EOS_InfoSystem - Informazioni sulla separazione di sistema
-- Stringa di caratteri predefinita: lunghezza [NNN] + interruttore per lo spegnimento [S/N] + pantografo più basso [S/N] + stringa di caratteri
-- Il parametro è applicabile se il parametro 1.1.1.2.4.2.1 è valorizzato con [S].
-- Qualora applicabile, il parametro assume il formato [NNN] + [S] + [S]. È accettato il formato
-- [NNN] + [S] + [S] + [S], che permetta la compatibilità con il formato definito dalla precedente Decisione 880/2014.
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_2_2_B (n_controllo   In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.2.2.B');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_4_2_2_B', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_2_AP', id_sol_track);   
--    1.1.1.2.2.4.2.1 - separazione di sistema (69)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_1', id_sol_track); 

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (Nvl(s_val_new_2, '0') = 'Y' And s_val_new_1 = 'Y') Or
                        (Nvl(s_val_new_2, '0') = 'N' And s_val_new_1 Is Null) Or
                        (s_val_new_2 Is Null And s_val_new_1 Is Null)  Then              --se non AP 421, va bene che questo sia non AP
                          n_errore := 1;
                     Else n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then 'Il campo Apertura interruttore ammette solamente ' || GetCorrectRangeStringPURA (n_parametro)
                          When n_errore = 0 And s_val_new_2 Is Null Then 'Se '||GetParametro(69,'Separazione di sistema')||' non è applicabile, il parametro non deve essere valorizzato'
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' Then 'Se '||GetParametro(69, 'Separazione di sistema')||' è '||GetValueFromCode (69, 'N')||', il parametro non deve essere valorizzato'
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_2, 0) = 'Y' Then 'Se '||GetParametro(69, 'Separazione di sistema')||' è '||GetValueFromCode (69, 'Y')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Y')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(69),--------------------------------------------------------------->''Separazione Sistema''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_2_2_B - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_2_2_B;
