      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
dbms_output.put_line (' n_controllo_old_ok_1: '||n_controllo_old_ok_1);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);    
dbms_output.put_line ('d_definizione: '||d_definizione);	  
--    come riferimento uso la parte A del parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.2.2.A');   
dbms_output.put_line ('n_parametro: '||n_parametro);	  
 --   recupero valori A new e old ok
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_2_A', id_sol_track, s_val_new_1, s_val_old_ok_1);
dbms_output.put_line ('valore attuale e precedente - s_val_new_1: '||s_val_new_1||' - s_val_old_ok_1: '||s_val_old_ok_1);
--    recupero valori B new e old ok
      Select new.SOL_TRACK_1_1_1_2_4_2_2_B new_val,                                             
             old.SOL_TRACK_1_1_1_2_4_2_2_B old_val   
	    INTO s_val_new_2, s_val_old_ok_2
        From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
             Rinf_Controllati_Evo.BINARI_CORSA_SOL old
       Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
	     And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
dbms_output.put_line ('valore attuale e precedente - s_val_new_2: '||s_val_new_2||' - s_val_old_ok_2: '||s_val_old_ok_2);
--
--    recupero valori C new e old ok
      Select new.SOL_TRACK_1_1_1_2_4_2_2_C new_val,                                             
             old.SOL_TRACK_1_1_1_2_4_2_2_C      old_val   
	    Into s_val_new_3, s_val_old_ok_3
       From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
             Rinf_Controllati_Evo.BINARI_CORSA_SOL old
       Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
	     And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track;
dbms_output.put_line ('valore attuale e precedente - s_val_new_3: '||s_val_new_3||' - s_val_old_ok_3: '||s_val_old_ok_3);
--     
--    recupero valori D new e old ok - Non più necessaria col Reg.777/2019
      SELECT new.SOL_TRACK_1_1_1_2_4_2_2_D new_val,                                             
             old.SOL_TRACK_1_1_1_2_4_2_2_D old_val   
	    Into s_val_new_4, s_val_old_ok_4
       From Rinf_Lavorazione_Evo.BINARI_CORSA_SOL new,
             Rinf_Controllati_Evo.BINARI_CORSA_SOL old
       Where new.SOL_TRACK_1_1_1_0_0_1 = old.SOL_TRACK_1_1_1_0_0_1 (+) 
	     And new.SOL_TRACK_1_1_1_0_0_1 = id_sol_track;

dbms_output.put_line ('valore attuale e precedente - s_val_new_4: '||s_val_new_4||' - s_val_old_ok_4: '||s_val_old_ok_4);
--    come riferimento uso A: se NYA A, allora do per scontato se lo siano anche B e C e D
      NYA:= GetNYA (n_parametro);         
dbms_output.put_line ('il parametro può essere NYA: '||NYA);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_2_AP', id_sol_track);
dbms_output.put_line ('Applicabilità (s_val_new_AP): '||s_val_new_AP);
--
--    1.1.1.2.4.2.1 - separazione di sistema
      s_val_new_5 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_2_1', id_sol_track);        
dbms_output.put_line ('1.1.1.2.4.2.1 - separazione di sistema (s_val_new_5): '||s_val_new_5);
--	  
--    come riferimento uso A: se NYA A, allora do per scontato se lo siano anche B e C e D
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);         
dbms_output.put_line ('Il valore è coerente con l''applicabilità - n_ok_AP :'||n_ok_AP );
--
      If n_controllo_padre = 0 Then
dbms_output.put_line ('n_controllo_padre = 0');  
           If n_ok_AP = 1 Then
--                If (Nvl(s_val_new_5, 0) = 'Y' And s_val_new_1 <= 999 And Nvl(s_val_new_2, 0) = 'Y' And Nvl(s_val_new_3, 0) = 'Y' And Nvl(s_val_new_4, 0) = 'Y') Or
--                   (Nvl(s_val_new_5, 0) = 'N' And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null And s_val_new_4 Is Null ) Or
--                   (s_val_new_5 Is Null And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null And s_val_new_4 Is Null) Then
                If (Nvl(s_val_new_5, '0') = 'Y' And s_val_new_1 <= 999 And Nvl(s_val_new_2, 0) = 'Y' And Nvl(s_val_new_3, 0) = 'Y') Or
                   (Nvl(s_val_new_5, '0') = 'N' And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null ) Or
                   (s_val_new_5 Is Null And s_val_new_1 Is Null And s_val_new_2 Is Null And s_val_new_3 Is Null ) Then
                     n_errore := 1;
                Else n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
dbms_output.put_line ('n_errore: '||n_errore);	

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
--                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_5, 0) = 'Y' Then 'Se '||GetParametro(69,'Separazione di sistema')||' è '||GetValueFromCode (69, 'Y')||', il parametro deve essere nella forma [NNN]+[S]+[S]+[S]'
                          When n_ok_AP = 1 And n_errore = 0 And Nvl(s_val_new_5, 0) = 'Y' Then 'Se '||GetParametro(69,'Separazione di sistema')||' è '||GetValueFromCode (69, 'Y')||', il parametro deve essere nella forma [NNN]+[S]+[S]'
                          When n_ok_AP = 1 And n_errore = 0 And NVL (s_val_new_5, 0) ='N' Then 'Se '||GetParametro(69,'Separazione di sistema')||' è '||GetValueFromCode (69, 'N')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_5 Is Not Null And (s_val_new_1 Is Null Or s_val_new_2 Is Null Or s_val_new_3 Is Null) Then 'Lunghezza Separazione Sistema/ Apertura Interruttore/ Abbassamento Pantografo mancante'
--                          When n_errore = 0 And s_val_new_5 is not null And (s_val_new_1 is  null OR s_val_new_2 is  null OR s_val_new_3 is  null OR s_val_new_4 is  null) Then 'Lunghezza Separazione Sistema/ Apertura Interruttore/ Abbassamento Pantografo/ Cambio Alimentazione mancante'
                          When n_errore = 0 And s_val_new_5 Is Null Then 'Se '||GetParametro(69, 'Separazione di sistema')||' non è applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     Case
                          When n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then Null           --se AP è giusta ed è NO, allora non scrive nulla
                          When n_ok_AP = 1 And s_val_new_4 Is Not Null And s_val_old_ok_4 Is Not Null Then s_val_new_1||'+'||s_val_new_2||'+'||s_val_new_3||'+'||s_val_new_4
                          Else s_val_new_1||'+'||s_val_new_2||'+'||s_val_new_3
                     End,
                     Case
                          When n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then Null           --se AP è giusta ed è NO, allora non scrive nulla
                          When n_ok_AP = 1 And s_val_new_4 Is Not Null And s_val_old_ok_4 Is Not Null Then s_val_old_ok_1||'+'||s_val_old_ok_2||'+'||s_val_old_ok_3||'+'||s_val_old_ok_4
                          Else s_val_old_ok_1||'+'||s_val_old_ok_2||'+'||s_val_old_ok_3
                     End,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     18,   --14,                            -- fallito padre (composito)
                     GetMessFallitoPadreSingolo(69),--------------------------------------------------------------->' ''Separazione Sistema''
                     Case
                          When n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then null           --se AP è giusta ed è NO, allora non scrive nulla
                          When n_ok_AP = 1 And s_val_new_4 Is Not Null And s_val_old_ok_4 Is Not Null Then s_val_new_1||'+'||s_val_new_2||'+'||s_val_new_3||'+'||s_val_new_4 
                          Else  s_val_new_1||'+'||s_val_new_2||'+'||s_val_new_3
                      End,
                      Case
                         When n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then null           --se AP è giusta ed è NO, allora non scrive nulla
                         When n_ok_AP = 1 And s_val_new_4 Is Not Null And s_val_old_ok_4 Is Not Null Then s_val_new_1||'+'||s_val_new_2||'+'||s_val_new_3||'+'||s_val_new_4
                         Else  s_val_old_ok_1||'+'||s_val_old_ok_2||'+'||s_val_old_ok_3
                      End,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_2_2_TOTALE - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_2_2_TOTALE;
--
-- ------------------------------------------------------------------------------------------------
-- 1.1.1.2.4.3 - EOS_DistSignToPhaseEnd - Distanza tra il pannello e la fine della separazione di fase - NA Intera rete
-- Distanza tra il pannello che autorizza l'agente di condotta ad «alzare il pantografo» o «chiudere l'interruttore di protezione del circuito 
--   di alimentazione» dopo aver superato la separazione di fase e la fine della sezione a separazione di fase.
-- Il parametro è applicabile solo per la rete francese. Questo parametro deve essere sempre valorizzato = [non applicabile].

--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_2_4_3 (292) - NA Intera Rete
-- 1.1.1.2.4.3 - EOS_DistSignToPhaseEnd - Distanza tra il pannello e la fine della separazione di fase
-- Nuovo parametro - Reg.777/2019 solo per la rete francese - AP=N - [N]
-- Questo parametro deve essere sempre valorizzato [non applicabile]. Cotrollo: Campo obbligatoriamente nullo (10)
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_4_3    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.4.3');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      s_val_new_AP := Nvl(GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_4_3_AP', id_sol_track), 'N'); 
--
      NYA := GetNYA(n_parametro);
--
--           If n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                 n_errore := 1;
--	       Else  
--		        n_errore := 0;
--           End If; 
--
           If n_controllo_padre = 0 Then
--
--              verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
--                n_errore := GetCorrectValue(n_parametro, s_val_new_1);

                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          10,
                          Case
                               When n_errore = 0 And s_val_new_1 Is Not Null Then s_commento_AP_ko
--                               When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End);
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_4_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_4_3;


--                            1.1.1.2.5 Requisiti per il materiale rotabile
-- ------------------------------------------------------------------------------------------------
--           Procedure SET_1_1_1_2_5_1 - NCT - (74)  - AP+DOMINIO+CORRELAZIONE
--  1.1.1.2.5.1 - ERS_PowerLimitOnBoard - Limitazione di corrente o di potenza a bordo richiesta
-- Indicazione se sia necessaria una funzione per la limitazione di corrente o di potenza a bordo sui veicoli
-- Il parametro non è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato [non elettrificato].
-- Nel caso in cui il parametro 1.1.1.2.2.1.1 – Tipo di sistema di linea di contatto sia stato valorizzato <> [non elettrificato], 
-- questo parametro deve essere = [S].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_5_1 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.5.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_5_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_5_1_AP', id_sol_track);
--    1.1.1.2.2.1.2 (55)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1 (240)
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
 /*
                    If    (s_val_new_3 = '40' And s_val_new_1 Is Not Null)
                       OR (s_val_new_3 = '30' And s_val_new_1 <> 'Y')
                       OR (s_val_new_3 = '20' And s_val_new_1 <> 'Y')
                       OR (s_val_new_3 = '10' And s_val_new_1 <> 'Y')
                    Then
                       n_errore := 0;
                    Else
                       n_errore := 1;
                    End If; 
*/
                      If ((s_val_new_3 = '40' And s_val_new_1 Is Null) Or
                         (s_val_new_3 <> '40' And s_val_new_1 = 'Y'))  Then
                          n_errore := 1;
                     ElsIf (s_val_new_3 <> '40' And (s_val_new_2 ='20' Or s_val_new_2 ='40') And s_val_new_1 Is Not Null) Then
                          n_errore := 1;
                     Else
                          n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then   s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_ok_dominio = 0 And s_val_new_2 = '30' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Y')
--                          When n_ok_dominio = 0 And s_val_new_2 = '20' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Y')
                          When n_ok_dominio = 0 And s_val_new_2 = '10' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Y')
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, s_val_new_3 )|| ', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_3 <>'40' And s_val_new_1 <> 'Y' Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, s_val_new_3 )||', il parametro deve essere '||GetValueFromCode (n_parametro, 'Y')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_5_1 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_5_1;
--
-- ------------------------------------------------------------------------------------------------
--                    Procedure SET_1_1_1_2_5_2 (75) - NCT
-- 1.1.1.2.5.2 - Forza di contatto autorizzata - Indicazione della forza di contatto autorizzata espressa in newton 
-- Il parametro non è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato [non elettrificato] - AP+DOMINIO+CORRELAZIONE
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1.2 – Sistema di alimentazione elettrica
--  (voltaggio e frequenza) è valorizzato con [CC 3 kV]=30, questo parametro deve essere [Fm = 0,00097*v2+110].
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1 – Sistema di alimentazione elettrica
--  (voltaggio e frequenza) è valorizzato con [CA 25 kV-50 Hz]=10, questo parametro deve essere [Fm = 0,00097*v2+70].
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1 – Sistema di alimentazione elettrica
--  (voltaggio e frequenza) è valorizzato con [CA 15kV-16.7Hz]=20, questo parametro deve essere [da definire].
-- Se nella stessa sezione di linea il parametro 1.1.1.2.2.1 – Sistema di alimentazione elettrica
--   (voltaggio e frequenza) è valorizzato con [CC 1.5 kV]=40, questo parametro deve essere [da definire].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_5_2 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.5.2');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_5_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_5_2_AP', id_sol_track);
--    1.1.1.2.2.1.2 - Sistema di alimentazione elettrica (voltaggio e frequenza) - (55)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
--    1.1.1.2.2.1.1 - Tipo di sistema di linea di contatto - (240)
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If  ( (s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> 'Fm=0,00097*v^2+70')       --25kV
                        Or (s_val_new_2 = '20' And s_val_new_1 Is Null)                              --15 kV in sospeso Svizzera, per ora metto solo che se ho 15KV deve essere valorizzato
                        Or (s_val_new_2 = '30' And NVL (s_val_new_1, 0) <> 'Fm=0,00097*v^2+110')     --3 kV
 --                       Or (s_val_new_2 = '40' And s_val_new_1 Is Null)                              --15 kV in sospeso Svizzera, per ora metto solo che se ho 15KV deve essere valorizzato
                        Or (s_val_new_3 = '40' And s_val_new_1 Is Not Null)  )                                     --not elect
                      Then n_errore := 0;
                      Else n_errore := 1;
                      End If; 
                Else
                      n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                          When n_ok_dominio = 0 And s_val_new_2 = '10' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Fm=0,00097*v^2+70')
                          --When n_ok_dominio = 0 And s_val_new_2 = '20' Then 'Il campo deve essere valorizzato '--||GetValueFromCode (n_parametro, 'èè')
                          When n_ok_dominio = 0 And s_val_new_2 = '30' Then 'Il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'Fm=0,00097*v^2+110')
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_3 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = '10' And Nvl(s_val_new_1, 0) <> 'Fm=0,00097*v^2+70'  Then  'Se '||GetParametro(55, 'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '10')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'Fm=0,00097*v^2+70')
                          --When n_errore = 0 And s_val_new_2 = '20' And s_val_new_1 IS NULL Then 'Il campo deve essere valorizzato '--||GetValueFromCode (n_parametro, 'èè')
                          When n_errore = 0 And s_val_new_2 = '30' And Nvl(s_val_new_1, 0) <> 'Fm=0,00097*v^2+110' Then  'Se '||GetParametro(55, 'Sistema alim.elettr.')||' è '||GetValueFromCode (55, '30')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'Fm=0,00097*v^2+110')
                          Else  Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (55), ---------------------------------------->''Sistema alimentazione elettrica''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(55),--------------------------------------------------------------->''Sistema alimentazione elettrica''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_5_2 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_2_5_2;
--
-- ------------------------------------------------------------------------------------------------
--          Procedure SET_1_1_1_2_5_3 (76) - MODIFICATO
-- 1.1.1.2.5.3  - Dispositivo di distacco automatico richiesto - Indicazione di quando sia richiesto sul veicolo 
-- un dispositivo di distacco automatico (ADD – Automatic Dropping Device) AP+DOMINIO+CORRELAZIONE
-- Il parametro è applicabile quando il parametro 1.1.1.2.2.1.1 è valorizzato [Linea di contatto aerea (OCL)]
-- Questo parametro non è applicabile quando il parametro 1.1.1.2.2.1.1 “Tipo di sistema di linea dicontatto” è [non elettrificato].
-- Il valore del parametro, se applicabile, può essere solo [S] o [N].
-- Il valore di questo parametro dovrà essere = [N] se il valore del parametro 1.1.1.1.2.5 “Velocità massima consentita” è = [160].
-- Se il valore del parametro 1.1.1.1.2.5 “Velocità massima consentita” è > [160], il valore di questo parametro deve essere [S].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_2_5_3 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.2.5.3');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_2_5_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_5_3_AP', id_sol_track);
--    1.1.1.2.2.1.1 - Tipo di sistema di linea di contatto - (240)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_1', id_sol_track);
--    1.1.1.1.2.5 Velocità massima consentita >160
--        s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_2_2_1_2', id_sol_track);
      s_val_new_3 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
       If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
/* 
 If     (s_val_new_2 = '10' --And s_val_new_3 = '10' 
                                And s_val_new_1 <> 'Y')
                               --OR (s_val_new_2 = '10' 
							   And s_val_new_1 <> 'Y')
                               OR (s_val_new_2 = '20' And s_val_new_1 IS NOT NULL)
                               OR (s_val_new_2 = '30' And s_val_new_1 IS NOT NULL)
                               OR (s_val_new_2 = '40' And s_val_new_1 IS NOT NULL)
                            Then n_errore := 0;
                            Else  n_errore := 1;
                            End If; 
*/
                     If s_val_new_2 = '40' Then                                         -- [non elettrificato]
					      If s_val_new_1 Is Not Null Then
					           n_errore := 0;
						  ElsIf s_val_new_1 Is Null Then
					           n_errore := 1;
						  End If;
				     ElsIf s_val_new_2 = '10' Then                                         -- Linea di contatto aerea (OCL)
					      If (s_val_new_3  > 160 And s_val_new_1 = 'Y' Or 
						      s_val_new_3 <= 160 And s_val_new_1 = 'N' ) Then
					           n_errore := 1;
						  Else 
					           n_errore := 0;
						  End If;
                     Else
          	              n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2 = '40' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '40')||', il parametro deve essere nullo (deve essere valorizzato solo se '||GetValueFromCode (240, '10')||')'
                          When n_errore = 0 And s_val_new_2 = '10' And s_val_new_3  > 160 And s_val_new_1 <> 'Y' Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '10')||' e la '||GetParametro(17,'Velocità')||' > 160 il parametro deve essere '||GetValueFromCode (n_parametro, 'Y')
                          When n_errore = 0 And s_val_new_2 = '10' And s_val_new_3 <= 160 And s_val_new_1 <> 'N' Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '10')||' e la '||GetParametro(17,'Velocità')||' <= 160 il parametro deve essere '||GetValueFromCode (n_parametro, 'N')
                          When n_errore = 0 And s_val_new_2 = '20' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '20')||', il parametro deve essere nullo (deve essere valorizzato solo se '||GetValueFromCode (240, '10')||')'
                          When n_errore = 0 And s_val_new_2 = '30' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(240, 'Tipo linea contatto')||' è '||GetValueFromCode (240, '30')||', il parametro deve essere nullo (deve essere valorizzato solo se '||GetValueFromCode (240, '10')||')'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split:= Mod(n_errore +1, 2);                               
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre -splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo (240), ---------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo (17), ---------------------------------------->''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(240),----------------------------------------------------->''Tipo Linea Contatto''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(17),--------------------------------------------------------------->''Velocità massima consentita''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_2_5_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_2_5_3;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_1_1_3_1_1 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3           Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;       --CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;       --serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO

       BEGIN
       --1.1.1.3.1.1  Dichiarazione CCS EC FORMATO E APP                             parametro con tabella multipla a parte

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.1.1');

      NYA:= GetNYA (n_parametro);

      GetOldNewValueMultiploDICH('DICHIARAZIONI_BINARIO_SOL_CCS', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_1_1','SOL_TRACK_1_1_1_3_1_1_AP',id_sol_track,'EC', valori_multipli) ;           --multiplo

      n_errore:=1;              --inizializzo l'errore per poterlo puoi valorizzare nel loop

      FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;

          If n_controllo_padre = 0 Then

                  If VALORI_MULTIPLI%FOUND Then
                      LOOP

                            n_ok_AP := GetCorrectAPDICH (s_val_new_AP, s_val_new_1);

                            If n_ok_AP = 1
                            Then
                                        If (s_val_new_1 = ' ')
                                        OR (s_val_new_1 <> ' ' And GetCorrectDECLFormat(s_val_new_1) = 1)
                                        Then n_errore:=GREATEST(n_errore,1);                           --se mi fallisce un parametro multiplo, fallisce il controllo
                                        Else n_errore:=LEAST(n_errore, 0);
                                        End If; 
                              Else n_errore := 0;
                            End If; 

                      SetControlDetails(
                                n_controllo,
                                id_sol,
                                id_sol_track,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                7,
                                Case
                                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                       When n_errore = 0 And s_val_new_1 <> ' ' Then s_commento_DICH_FORM_KO
                                       Else
                                          NULL
                                    End,
                                    s_val_new_1,
                                    s_val_old_ok_1,
                                    n_controllo_old_ok_1,
                                      Case
                                            When n_errore = 0 And NYA=0 Then 0
                                            When n_errore = 0 And NYA=1 Then 1
                                            When n_errore = 1  Then 0
                                       End);

                        FETCH VALORI_MULTIPLI INTO s_val_new_1, s_val_old_ok_1,s_val_new_AP;
                        EXIT When VALORI_MULTIPLI%NOTFOUND;

                       End LOOP;

                   Else
                   n_errore:=0;                 --se non ci sono Dich, non ci sarà neanche l'AP perchè è nella stessa tabella

                    SetControlDetails(
                            n_controllo,
                            id_sol,
                            id_sol_track,
                            n_parametro,
                            d_definizione,
                            Case When  NYA=1 Then 1
                            Else n_errore
                            End,
                            4,
                            Case When n_errore = 0 Then s_commento_DICH_CE||'binario sottosistema CCS'
                               Else NULL
                            End,
                            s_val_new_1,
                            s_val_old_ok_1,
                            n_controllo_old_ok_1,
                                  Case
                                    When n_errore = 0 And NYA=0 Then 0
                                    When n_errore = 0 And NYA=1 Then 1
                                    When n_errore = 1  Then 0
                               End);
                   End If; 


           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
           End If; 

       CLOSE VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_1_1: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_1_1;
--
-- ------------------------------------------------------------------------------------------------
--                     Procedure SET_1_1_1_3_2_1 
-- 1.1.1.3.2.1 Livello ETCS DOMINIO+CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_2_1  (n_controllo         In Number,
                             id_sol              In Varchar2,
                             id_sol_track        In Varchar2,
                             id_dtp              In Varchar2,
                             n_controllo_padre   In Number,
                             p_error_split      Out Number)      Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_dominio           Number;            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);   -- stringa concatenata del dominio
      NYA                    Number;            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_4         Varchar2 (1000);   -- serve per recuperare i valori D dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
      p_error_split := 0;         -- l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.1');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track, s_val_new_1, s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_2', id_sol_track);

      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_3', id_sol_track);

      s_val_new_4 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_4', id_sol_track);

      If n_controllo_padre = 0 Then

          n_ok_dominio := GetCorrectValue(n_parametro, s_val_new_1);

--          If n_ok_dominio = 1                                                                                      --sulle LG viene scritto che questo parametro 1.1.1.3.2.1 dipende dai successivi 1.1.1.3.2.2/3/4 e poi questi
--          Then                                                                                                             --a loro volta dal 1.1.1.3.2.1; non mi sembra corretto quindi ho messo 1.1.1.3.2.1 padre che non dipende dai figli
--             If    (s_val_new_2 is not null And s_val_new_1 = 'N')                                    --e solo i figli che dipEndono dal padre
--                OR (NVL (s_val_new_3, 0) = 'Y' And nvl(s_val_new_1,0) <> '1')
--                OR (NVL(s_val_new_4,0) <>'none' And NVL(s_val_new_1,0) <> '1')
--             Then n_errore := 0;
--             Else  n_errore := 1;
--             End If; 
--          Else
--             n_errore := 0;
--          End If; 

          n_errore := n_ok_dominio;

          SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    7,
                    Case
                       When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       --When     n_errore = 0 And  (s_val_new_2 is not null And s_val_new_1 = 'N') Then  'Deve essere diverso da '||GetValueFromCode (n_parametro, 'N')||' perchè versione base ETCS è applicabile'
                       --When     n_errore = 0  And (NVL (s_val_new_3, 0) = 'Y' And nvl(s_val_new_1,0) <> '1') Then 'Deve essere '|| GetValueFromCode (n_parametro, '1')||' perchè Funzione infill di linea è '|| GetValueFromCode (85, 'Y')
                       --When     n_errore = 0  And (NVL(s_val_new_4,0) <>'none' And nvl(s_val_new_1,0) <> '1') Then 'Deve essere '|| GetValueFromCode (n_parametro, '1')|| ' perchè Funzione infill di terra è diversa da '||GetValueFromCode (86, 'none')
                       Else
                          NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
--           p_error_split := 1;              --ERRORE!           
           p_error_split := Mod(n_errore +1, 2);     

       Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                         When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                         --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_1: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_1;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_2_2 - (84) Parametro modificato
-- 1.1.1.3.2.2 - CPE_Baseline - Baseline dell'ETCS - Versione base ETCS AP+DOMINIO+CORRELAZIONE
-- Il parametro non è applicabile quando il parametro 1.1.1.3.2.1 sia valorizzato con [N]
-- Non deve essere ammesso un valore diverso da [prebaseline 2], [baseline 2], [baseline 3 Maintenance release 1] o [baseline 3 release 2].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_2_2 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.2');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_2_AP', id_sol_track);
--    1.1.1.3.2.1
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
       If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If s_val_new_2 = 'N' And s_val_new_1 Is Not Null Then 
                          n_errore := 0;
                     Else 
   					      n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2 = 'N' And s_val_new_1 Is Not Null Then  'Se '||GetParametro(83, 'Livello ETCS')||' è '|| GetValueFromCode (83, 'N')||', il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split:= Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_2_2 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_2;
--
-- ------------------------------------------------------------------------------------------------
--             Procedure SET_1_1_1_3_2_3 (85) [S/N]
-- 1.1.1.3.2.3 - CPE_Infill - Funzione infill dell'ETCS necessaria per accedere alla linea - AP+DOMINIO+CORRELAZIONE
-- Il parametro è applicabile quando il parametro 1.1.1.3.2.1 sia valorizzato con [1]
-- Non deve essere ammesso un valore diverso da [S] o [N] 
-- Se il parametro 1.1.1.3.2.1 “Livello ETCS” è valorizzato ? [1], questo parametro 1.1.1.3.2.3
--   “Funzione Infill dell’ETCS necessaria per accedere alla linea” non deve essere valorizzato (non applicabile)
-- Se il parametro 1.1.1.3.2.4 “Funzione Infill dell’ETCS installata a terra” è valorizzato [nessuno],
-- questo parametro 1.1.1.3.2.3 “Funzione Infill dell’ETCS necessaria per accedere alla linea” deve assumere valore [N].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_2_3 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.3');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_3_AP', id_sol_track);
--    1.1.1.3.2.1 - Livello ETCS
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);
--    1.1.1.3.2.4 - Funzione Infill dell’ETCS installata a terra
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_4', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then  
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then  
                n_ok_dominio := 1;
           Else 
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If    ( (Nvl(s_val_new_2, 0)  = '1' And s_val_new_1 Is Null)
                         Or  (Nvl(s_val_new_2, 0) <> '1' And s_val_new_1 Is Not Null)
                         Or  (s_val_new_3 = 'none' And Nvl(s_val_new_1, 0) <> 'N') ) Then
                          n_errore := 0;
                     Else
                          n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
              n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And (Nvl(s_val_new_2, 0)  = '1' And s_val_new_1 Is Null) Then  'Se '||GetParametro(83, 'Livello ETCS')||' è '|| GetValueFromCode (83, '1')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And (Nvl(s_val_new_2, 0) <> '1' And s_val_new_1 Is Not Null) Then  'Se '||GetParametro(83, 'Livello ETCS')||' non è '|| GetValueFromCode (83, '1')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And (s_val_new_3 = 'none' And Nvl(s_val_new_1, 0) <> 'N') Then  'Se '||GetParametro(86, 'Funzione infill ETCS di terra')||' è '||GetValueFromCode (86, 'none')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'N')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                   End);
--
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then  
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                               -- fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                              -- fallito padre
                     GetMessFallitoPadreSingolo(86),--------------------------------------------------------------->''Funzione infill ETCS a terra''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
-- 
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then            
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then  

           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                            -- fallito padre
                GetMessFallitoPadreSingolo(86),--------------------------------------------------------------->''Funzione infill ETCS a terra''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_2_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_3;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
  PROCEDURE SET_1_1_1_3_2_4 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
        --1.1.1.3.2.4 Infill ETCS terra AP+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

       n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.4');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_4',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

     s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_4_AP',id_sol_track);

     s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_1',id_sol_track);

     s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_3',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

     If n_controllo_padre = 0 Then

        If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
      Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
      Then n_ok_dominio := 1;
      End If; 

      If n_ok_AP = 1
      Then
         If n_ok_dominio = 1
         Then
            If   (s_val_new_2 = '1' And s_val_new_1 is not null)
            OR (s_val_new_2 <> '1' And s_val_new_1 is null)
            OR (s_val_new_3 <> '1' And nvl(s_val_new_1,0) = 'none')
            Then
               n_errore := 1;
            Else
               n_errore := 0;
            End If; 
         Else
            n_errore := 0;
         End If; 
      Else
         n_errore := 0;
      End If; 

      SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                Else n_errore
                End,
                6,
                Case
                   When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                   When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                   When n_errore = 0 And (s_val_new_2 = '1' And s_val_new_1 is null) Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '1')||', il parametro deve essere valorizzato'
                   When n_errore = 0 And (s_val_new_2 <> '1' And s_val_new_1 is not null) Then  'Se '||GetParametro(83,'Livello ETCS')||' è diverso da '||GetValueFromCode (83, '1')||', il parametro non deve essere valorizzato'
                  When n_errore = 0 And  (s_val_new_3 <> '1' And nvl(s_val_new_1,0) <> 'none') Then  'Se '||GetParametro(85,'Funzione infill ETCS di linea')||' è diversa da '|| GetValueFromCode (85, '1')||', il parametro deve essere' ||GetValueFromCode (n_parametro, 'none')
                   Else
                      NULL
                End,
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_errore = 0 And NYA=0 Then 0
                        When n_errore = 0 And NYA=1 Then 1
                        When n_errore = 1  Then 0
                   End);

       p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

        Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                        When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_4: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_4;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_2_5 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.2.5 Applic. naz.ETCS AP+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.5');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_5',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

     s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_5_AP',id_sol_track);

     s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

     If n_controllo_padre = 0 Then

      If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
      Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
      Then n_ok_dominio := 1;
      End If; 

      If n_ok_AP = 1
      Then
         If n_ok_dominio = 1
         Then
            If    (s_val_new_2 = 'N' And s_val_new_1 IS NOT NULL)
                OR (s_val_new_2 <> 'N' And s_val_new_1 IS NULL)
            Then n_errore := 0;
            Else n_errore := 1;
            End If; 
         Else
            n_errore := 0;
         End If; 
      Else
         n_errore := 0;
      End If; 

      SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                Else n_errore
                End,
                6,
                Case
                   When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                   When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                   When n_errore = 0 And s_val_new_2 = 'N' And s_val_new_1 IS NOT NULL Then  'Se '||GetParametro(83,'Livello ETCS')||' è ' || GetValueFromCode (83, 'N')|| ', il parametro non deve essere valorizzato'
                   When n_errore = 0 And s_val_new_2 <> 'N' And s_val_new_1 IS NULL Then  'Se '||GetParametro(83,'Livello ETCS')||' è diverso da ' || GetValueFromCode (83, 'N')|| ', il parametro deve essere valorizzato'
                   Else
                      NULL
                End,
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_errore = 0 And NYA=0 Then 0
                        When n_errore = 0 And NYA=1 Then 1
                        When n_errore = 1  Then 0
                   End);

       p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

        Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                        When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_5: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_5;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_1_1_3_2_6 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
       --1.1.1.3.2.6 Cond oper ETCS AP+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

     n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.6');

     GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_6',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

     NYA:= GetNYA (n_parametro);

     s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_6_AP',id_sol_track);

     s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

      If n_controllo_padre = 0 Then

              If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
              Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
              Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
              Then n_ok_dominio := 1;
              End If; 

              If n_ok_AP = 1
              Then
                 If n_ok_dominio = 1
                 Then
                    If    (s_val_new_2 = 'N' And s_val_new_1 IS NOT NULL)
                        OR (s_val_new_2 <> 'N' And s_val_new_1 IS NULL)
                    Then
                       n_errore := 0;
                    Else
                       n_errore := 1;
                    End If; 
                 Else
                    n_errore := 0;
                 End If; 
              Else
                 n_errore := 0;
              End If; 

              SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                         Case When  NYA=1 Then 1
                        Else n_errore
                        End,
                        6,
                        Case
                           When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                           When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                           When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                           When n_errore = 0 And s_val_new_2 = 'N' And s_val_new_1 IS NOT NULL Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, 'N')||', il parametro non deve essere valorizzato'
                           When n_errore = 0 And s_val_new_2 <> 'N' And s_val_new_1 IS NULL Then  'Se '||GetParametro(83,'Livello ETCS')||' è diverso da ' || GetValueFromCode (83, 'N')|| ', il parametro deve essere valorizzato'
                           Else
                              NULL
                        End,
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_errore = 0 And NYA=0 Then 0
                                When n_errore = 0 And NYA=1 Then 1
                                When n_errore = 1  Then 0
                           End);

                    p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

        Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                        When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_6: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_6;
