--                                1.1.1.3.3 Radio (GSM-R) conforme alla STI
-- ------------------------------------------------------------------------------------------------
--                     Procedure SET_1_1_1_3_3_1 (90) - AP=Y
-- 1.1.1.3.3.1	- CRG_Version - Versione GSM-R  - DOMINIO (--+CORRELAZIONE)
-- Numero della versione del GSM-R FRS e SRS installata a terra
-- Per questo parametro è ammesso solo il valore [Baseline 1]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_3_1 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           --  ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato	  
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.1');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      --s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_6_1',id_sol_track);
--
      NYA := GetNYA (n_parametro);

      If n_controllo_padre = 0 Then

           n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
/*
           If n_ok_dominio = 1  Then
              If  (Nvl(s_val_new_1, '0') = 'none' Or Nvl(s_val_new_1, '0') = 'Baseline 0 r3' ) Then 
			       n_errore := 0;
              Else  
			       n_errore := 1;
              End If; 
           Else
              n_errore := 0;
           End If; 
*/           
		   n_errore := n_ok_dominio;

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     4,
                     Case When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                        --When n_errore = 0 And s_val_new_2='Y' And nvl(s_val_new_1,0) <> 'none'  Then  'Se Altri sistemi radio installati è '|| GetValueFromCode (96, 'Y')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'none')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );

--           If (Nvl(s_val_new_1, '0') = 'none' Or Nvl(s_val_new_1, '0') = 'Baseline 0 r3') Then       -- Gestione del transitorio per mantenere corretti i "figli" diversamente da NYA
           If Nvl(s_val_new_1, '0') = 'Baseline 0 r3' Then       -- Gestione del transitorio per mantenere corretti i "figli" diversamente da NYA
                p_error_split := 0;
           Else   
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
           End If;   

--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_3_3_1;
--
-- ------------------------------------------------------------------------------------------------
--                                      Procedure SET_1_1_1_3_3_2 (91)
-- 1.1.1.3.3.2 - CRG_NumActiveMob - Numero consigliato di dispositivi mobili GSM-R (EDOR) attivi a bordo per ETCS Livello 2
-- Il parametro è applicabile solo quando il parametro 1.1.1.3.2.1 sia valorizzato con [2] o con [3].
-- Controllo:  AP+DOMINIO+CORRELAZIONE - Elenco valori: [1] - [2] - Non deve essere ammesso un valore diverso da [2].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_3_2 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number   )       Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                               
      n_errore               Number;                               
      d_definizione          Varchar2 (1000);                      
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.2');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_2_AP', id_sol_track);
--    Estrazione valore parametro 1.1.1.3.2.1 - Livello ETCS per il controllo di congruità per l'Applicabilità
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
                Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                Then n_ok_dominio := 1;
		   Else                        -- n_ok_AP = 0 (aggiunto)
		        n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If    (Nvl(s_val_new_2, 0) = 'N' And s_val_new_1 Is Not Null)
                        Or (Nvl(s_val_new_2, 0) = '1' And s_val_new_1 Is Not Null)
                        Or (Nvl(s_val_new_2, 0) = '2' And Nvl(s_val_new_1, 0) <> '2' )
                        Or (Nvl(s_val_new_2, 0) = '3' And Nvl(s_val_new_1, 0) <> '2' )
                     Then
                        n_errore := 0;
                     Else
                        n_errore := 1;
                     End If; 
                Else                    -- n_ok_dominio = 0
                   n_errore := 0;
                End If; 
           Else                         -- n_ok_AP = 0
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then 'Il campo ammette solamente '||GetCorrectRangeStringPURA (n_parametro)||' se '||GetParametro(83, 'Livello ETCS')||' è '|| GetValueFromCode (83, '2')||' o '|| GetValueFromCode (83, '3')
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = 'N' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(83, 'Livello ETCS')||' è diverso da '|| GetValueFromCode (83, '2')||' o '|| GetValueFromCode (83, '3')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = '1' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(83, 'Livello ETCS')||' è diverso da '|| GetValueFromCode (83, '2')||' o '|| GetValueFromCode (83, '3')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = '2' And Nvl(s_val_new_1, 0) <> '2' Then 'Se '||GetParametro(83, 'Livello ETCS')||' è '|| GetValueFromCode (83, '2')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, '2')
                          When n_errore = 0 And Nvl(s_val_new_2, 0) = '3' And Nvl(s_val_new_1, 0) <> '2' Then 'Se '||GetParametro(83, 'Livello ETCS')||' è '|| GetValueFromCode (83, '3')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, '2')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 = errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_2 - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_2;
--
-- ------------------------------------------------------------------------------------------------
--                        Procedure SET_1_1_1_3_3_3_MULT (92) 
-- 1.1.1.3.3.3 - CRG_OptionalFunctions - Funzioni GSM-R facoltative  - Parametro MULTIVALORE tabella: PAR_1_1_1_3_3_3_GSM_R_FAC
-- parametro MODIFICATO con il Reg.777/2019 (aggiunti valori in elenco LookUpValues) 
-- Il parametro non è applicabile quando il parametro 1.1.1.3.3.1 – “Versione GSM-R” è valorizzato [nessuna]. (90)
-- Controlli: AP+DOMINIO+CORRELAZIONE(6) - parametro con tabella multipla a parte - PAR_1_1_1_3_3_3_GSM_R_FAC
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_3_MULT (n_controllo       In Number,
                                 id_sol            In Varchar2,
                                 id_sol_track      In Varchar2,
                                 id_dtp            In Varchar2,
                                 n_controllo_padre In Number,
                                 p_error_split    Out Number   )    Is
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                        -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                        -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;                           
      n_errore                   Number;                           
      d_definizione              Varchar2 (1000);                  
      s_stringa_dominio          Varchar2 (1000);               -- stringa concatenata del dominio
      NYA                        Number;                        -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);               -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                                   -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.3');
--
      GetOldNewValueMultiplo ('PAR_1_1_1_3_3_3_GSM_R_FAC', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3', id_sol_track, valori_multipli);           -- multiplo
--    1.1.1.3.3.1 - Versione GSM-R
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_AP', id_sol_track);
--
      Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then
--
           If VALORI_MULTIPLI%Found Then 
             Loop
--> loop        Se esistono valori si esegue il controllo sul dominio e sull'applicabilità
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
                If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                                      --> AP=Y e s_val_new_1 in not null
                     n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                                   --> AP=N e s_val_new_1 in null
                     n_ok_dominio := 1;
				Else n_ok_dominio := 0;
                End If; 
--	            verifica di correlazione con altro parametro 1.1.1.3.3.1			
                If n_ok_AP = 1 Then
                     If n_ok_dominio = 1 Then
                          If  (s_val_new_2  = 'none' And s_val_new_1 Is Null)
                           Or (s_val_new_2 <> 'none' And s_val_new_1 Is Not Null)  Then
                               n_errore := 1;
                          Else
                               n_errore := 0;
                          End If; 
                     Else
                          n_errore := 0;
                     End If; 
                Else
                    n_errore := 0;
                End If; 
--
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                               When n_ok_AP = 1 And n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                               When n_errore = 0 And s_val_new_2 = 'none' And s_val_new_1 IS Not Null Then  'Se '||GetParametro(90, 'Versione GSM-R')||' è '||GetValueFromCode (90, 'none')||', il parametro non deve essere valorizzato'
                               When n_errore = 0 And s_val_new_2 <> 'none' And s_val_new_1 Is Null Then  'Se '||GetParametro(90, 'Versione GSM-R')||' è diverso da '||GetValueFromCode (90, 'none')||', il parametro deve essere valorizzato'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );

                 Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
                   Exit When valori_multipli%NOTFOUND;
--> end loop
             End Loop;
--
--         Se non esistono valori
           Else 
                If VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'N' Then                    -- Se è non applicabile va tutto bene
                      n_errore := 1;
                      n_ok_AP := 1;
                      n_ok_dominio :=1;
                Elsif VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'Y' Then                 -- Se è applicabile va tutto male
                      n_errore := 0;
                      n_ok_AP := 0;
                      n_ok_dominio :=0;
                End If; 

                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );

           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(90),--------------------------------------------------------------->''Versione GSM-R''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_3_MULT - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_3_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_3_1 (300) 
--                     1.1.1.3.3.3.1 - Informazioni supplementari sulle caratteristiche di rete
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--     Non Applicabile se 1.1.1.3.3.1 - Versione GSM-R = [nessuna] 
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_3_1   (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.3.1');
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_1_AP', id_sol_track);
--    legge il valore del parametro "padre" 1.1.1.3.3.1 - Versione GSM-R (90)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);    
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_3_3_1 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                     If ( (lower(s_val_new_2) <> 'none' And s_val_new_1 Is Not Null) Or
					       (lower(s_val_new_2) = 'none' And s_val_new_1 Is Null) ) Then
					      n_errore := 1;
				     Else
					      n_errore := 0;
                     End If;
                Else n_errore := 0;                                                          --valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                               --valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And lower(s_val_new_2) <> 'none' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(90),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_3_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_3_1;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_3_2 (302) 
--  1.1.1.3.3.3.2 - CRG_GPRSForETCS - GPRS per ETCS (S/N)  --> Se applicabile, ammette solo [N]
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--  Il parametro non è applicabile quando il parametro 1.1.1.3.3.1 – “Versione GSM-R” è valorizzato [nessuna] o quando il
--  parametro 1.1.1.3.2.1 “Livello ETCS” è valorizzato [N], [NTC], [0] o [1].
--  Non deve essere ammesso un valore diverso da [2].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_3_3_2  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.3.2');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_2_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.2.1 - Livello ETCS  (83)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);    
--    legge il valore del parametro "padre" 1.1.1.3.3.1 - Versione GSM-R  (90)
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--		   
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                          -- Correlazione AP-Valore=ok e AP=Y
                  n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);      -- Controlla se il valore è compreso nell'elenco "LookUp Value" - N.B. AMMETTE SOLO [N]
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                       -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else
				n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1   Then                                                   -- se l'applicabilità è coerente con il valore
                If n_ok_dominio = 1 Then                                           -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
                     If (((s_val_new_3 = 'none') Or                                              -- 1.1.1.3.3.1 - Versione GSM-R (campo CODIFICA_VALORE)
						 (s_val_new_2 = '1' Or s_val_new_2 = 'N') ) And s_val_new_1 Is Null)     -- 1.1.1.3.2.1 - Livello ETCS
                          Then n_errore := 1;
                     Elsif ((s_val_new_3 = 'none' Or (s_val_new_2 = '1' Or s_val_new_2 = 'N')) And s_val_new_1 Is Not Null)
                          Then n_errore := 0;
						  Else n_errore := 1;
 	                 End If; 
                 Else n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else   n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And n_ok_dominio = 0  Then GetCorrectRangeString(n_parametro)
                          When (n_errore = 0 And s_val_new_3 = 'none' And s_val_new_1 Is Not Null) Then 'Il parametro non è applicabile quando '||GetParametro(90, 'Versione GSM-R')|| ' è uguale a '||GetValueFromCode (90, '10')
                          When (n_errore = 0 And s_val_new_2 = '1' Or s_val_new_2 = 'N' And s_val_new_1 Is Not Null) Then  'Il parametro non è applicabile quando '||GetParametro(83, 'Livello ETCS')|| ' è diverso da '||GetValueFromCode (83, '2')||' e '||GetValueFromCode (83, '3')
                          When (n_errore = 0 And s_val_new_3 <> 'none' And s_val_new_1 Is Null) Then 'Valore mancante'
                          When (n_errore = 0 And (s_val_new_2 = '2' Or s_val_new_2 = '3') And s_val_new_1 Is Null) Then  'Se '||GetParametro(83, 'Livello ETCS')|| ' è ' ||GetValueFromCode (83, '2')|| ', o '||GetValueFromCode (83, '3')|| ' il parametro deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--                
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
-->
--    se falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then 
--
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                21,                             -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(83),--------------------------------------------------------->''Livello ETCS''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				 When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                15,                            -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(90),-------------------------------------------------------->''Versione GSM-R''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il primo padre,
      Elsif n_controllo_padre = 2 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				     When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             -- falliti padri
                GetMessFallitoPadreSingolo(83),--------------------------------------------------------->''Livello ETCS''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                     When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il secondo padre, ossia Velocità
      Elsif n_controllo_padre = 3 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				    When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                14,                            -- falliti padri
                GetMessFallitoPadreSingolo(90),-------------------------------------------------------->''Versione GSM-R''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                    End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_3_3_2: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_3_2;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_3_3 (304) 
--           1.1.1.3.3.3.3 - CRG_GPRSAreaOfImpl - Zona di implementazione del GPRS
-- Indicazione della zona in cui il GPRS può essere utilizzato per l'ETCS 
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
-- Il parametro non è applicabile quando il parametro 1.1.1.3.3.1 – “Versione GSM-R” è valorizzato [nessuna] o quando il
-- parametro 1.1.1.3.2.1 “Livello ETCS” è valorizzato [N], [NTC], [0] o [1] o quando il parametro 1.1.1.3.3.3.2 “GPRS per ETCS” è valorizzato [N].
-- Questo parametro deve essere valorizzato solo se il parametro 1.1.1.3.3.3.2 – “GPRS per ETCS” è valorizzato [S]. Nel caso
-- di RFI il parametro suddetto è sempre valorizzato [N], pertanto tale parametro è sempre non applicabile.
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_3_3   (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.3.3');
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--    legge se il dato è applicabile o meno
--      s_val_new_AP:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_3_AP', id_sol_track);
--    legge il valore del parametro "padre" 1.1.1.3.3.3.2 - GPRS per ETCS
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_3_2', id_sol_track);    
--    Se la procedura "padre" SET_1_1_1_3_3_3_2 è terminata correttamente
      If n_controllo_padre = 0 Then

          If (s_val_new_2 = 'N' Or s_val_new_2 Is Null ) And s_val_new_1 Is Null Then
			    n_errore := 1;
		   Else
			    n_errore := 0;
           End If;
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And s_val_new_2  = 'N' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And s_val_new_2 <> 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(302),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_3_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_3_3;

--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_4 (306) - NCT 
--     1.1.1.3.3.4 - Utilizzo del gruppo 555 (S/N) --> Se applicabile, ammette solo [N]
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--     Non Applicabile se 1.1.1.3.3.1 - Versione GSM-R = [nessuna] 
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_4     (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.4');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_4_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.3.1 - Versione GSM-R (90)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_3_3_1 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (lower(s_val_new_2) <> 'none' And s_val_new_1 Is Not Null) Or
					     (lower(s_val_new_2) = 'none' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                          --valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                               --valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And lower(s_val_new_2) <> 'none' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := MOD(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          GetMessFallitoPadreSingolo(90),--------------------------------------------->Controllo padre fallito 
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_4 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_4;


--
-- ------------------------------------------------------------------------------------------------
--                         Procedure SET_1_1_1_3_3_5_MULT 
-- 1.1.1.3.3.5  - Reti GSM-R coperte da accordo di roaming (308) - NCT 
-- Nuovo parametro Reg.777/2019 (elenco valori)
-- Il parametro non è applicabile quando il parametro 1.1.1.3.3.1 – “Versione GSM-R” è valorizzato [nessuna]. (90)
-- Controlli: AP+DOMINIO+CORRELAZIONE(6) - parametro con tabella multipla a parte - PAR_1_1_1_3_3_5_RETI_GSM_R
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_5_MULT (n_controllo       In Number,
                                 id_sol            In Varchar2,
                                 id_sol_track      In Varchar2,
                                 id_dtp            In Varchar2,
                                 n_controllo_padre In Number,
                                 p_error_split    Out Number   )    Is
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                        -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                        -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;                           
      n_errore                   Number;                           
      d_definizione              Varchar2 (1000);                  
      s_stringa_dominio          Varchar2 (1000);               -- stringa concatenata del dominio
      NYA                        Number;                        -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);               -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI            EMPCUR;                        -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.5');
--
      GetOldNewValueMultiplo ('PAR_1_1_1_3_3_5_RETI_GSM_R', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_5', id_sol_track, valori_multipli);           -- multiplo
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_5_AP', id_sol_track);
--
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);
--
      Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then
--
           If VALORI_MULTIPLI%Found Then 
             Loop
--> loop        Se esistono valori si esegue il controllo sul dominio e sull'applicabilità
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
                If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                                           --> AP=Y e s_val_new_1 in not null
                   Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP                                        --> AP=N e s_val_new_1 in null
                   Then  n_ok_dominio := 1;
				Else n_ok_dominio := 0;
                End If; 
--	            verifica di correlazione con altro parametro 1.1.1.3.3.1			
                If n_ok_AP = 1 Then
                     If n_ok_dominio = 1 Then
                          If  (s_val_new_2  = 'none' And s_val_new_1 Is Not Null)
                           Or (s_val_new_2 <> 'none' And s_val_new_1 Is Null)
                          Then
                             n_errore := 0;
                          Else
                             n_errore := 1;
                          End If; 
                     Else
                          n_errore := 0;
                     End If; 
                Else
                    n_errore := 0;
                End If; 
--
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_errore = 0 And s_val_new_2 = 'none' And s_val_new_1 IS Not Null Then  'Se '||GetParametro(90,'Versione GSM-R')||' è '||GetValueFromCode (90, 'none')||', il parametro non deve essere valorizzato'
                               When n_errore = 0 And s_val_new_2 <> 'none' And s_val_new_1 Is Null Then  'Se '||GetParametro(90,'Versione GSM-R')||' è diverso da '||GetValueFromCode (90, 'none')||', il parametro deve essere valorizzato'
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                               When n_ok_AP = 1 And n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
--			    
                 Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
                   Exit When valori_multipli%NOTFOUND;
--> end loop
             End Loop;
--
--         Se non esistono valori
           Else 
                If VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'N' Then                    -- Se è non applicabile va tutto bene
                      n_errore := 1;
                      n_ok_AP := 1;
                      n_ok_dominio :=1;
                Elsif VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'Y' Then                 -- Se è applicabile va tutto male
                      n_errore := 0;
                      n_ok_AP := 0;
                      n_ok_dominio :=0;
                End If; 
--
                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(90),--------------------------------------------------------------->''Versione GSM-R''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_5_MULT - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_5_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_6 (310) - 
--     1.1.1.3.3.6_Presenza di roaming su reti pubbliche - Se applicabile, ammette solo [S]
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--     Non Applicabile se 1.1.1.3.3.1 - Versione GSM-R = [nessuna] 
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_6     (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.6');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_6', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_6_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.3.1 - Versione GSM-R (90)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_3_3_1 è terminata correttamente
      If n_controllo_padre = 0 Then
--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (lower(s_val_new_2) <> 'none' And s_val_new_1 Is Not Null) Or
					     (lower(s_val_new_2) = 'none' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                          --valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                               --valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And lower(s_val_new_2) <> 'none' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          GetMessFallitoPadreSingolo(90),--------------------------------------------->Controllo padre fallito 
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_6 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_6;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_7 (312) 
--  1.1.1.3.3.7 - Dettagli relativi al roaming su reti pubbliche  --> Se applicabile, ammette solo [TIM: (I), (A); VODAFONE: (I)]
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--  Il parametro non è applicabile quando il parametro 1.1.1.3.3.1 – “Versione GSM-R” è valorizzato [nessuna] 
-- Il parametro è applicabile quando il parametro 1.1.1.3.3.6 - Presenza di roaming su reti pubbliche = [S]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_3_7    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.7');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_7', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_7_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.3.1 - Versione GSM-R  (90)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);    
--    legge il valore del parametro "padre" 1.1.1.3.3.6 - Presenza dio roaming su reti pubbliche  (310)
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_6', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--		   
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                          -- Correlazione AP-Valore=ok e AP=Y
                  n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);      -- Controlla se il valore è compreso nell'elenco "LookUp Value" - N.B. AMMETTE SOLO [...]
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                       -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else
				n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1   Then                                                   -- se l'applicabilità è coerente con il valore
                If n_ok_dominio = 1 Then                                           -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
                     If ((s_val_new_2 = 'none') Or                                -- 1.1.1.3.3.1 - Versione GSM-R (campo CODIFICA_VALORE)
						 (s_val_new_3 <> 'Y' ) And s_val_new_1 Is Null)            -- 1.1.1.3.3.6 - Presenza di roaming su reti pubbliche
                          Then n_errore := 1;
                     Elsif (s_val_new_2 <> 'none' And (s_val_new_3 = 'Y' ) And s_val_new_1 Is Not Null)
                          Then n_errore := 1;
						  Else n_errore := 0;
 	                 End If; 
                 Else n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else   n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And s_val_new_2 = 'none' And s_val_new_1 Is Not Null) Then 'Il parametro non è applicabile quando '||GetParametro(90, 'Versione GSM-R')|| ' è uguale a '||GetValueFromCode (90, '10')
                          When (n_errore = 0 And s_val_new_3 <> 'Y' And s_val_new_1 Is Not Null) Then  'Il parametro non è applicabile quando '||GetParametro(310, 'Presenza Roaming')|| ' è diverso da '||GetValueFromCode (310, 'Y')
                          When (n_errore = 0 And s_val_new_2 <> 'none' And s_val_new_1 Is Null) Then 'Valore mancante'
                          When (n_errore = 0 And (s_val_new_3 = 'Y') And s_val_new_1 Is Null) Then  'Se '||GetParametro(310, 'Presenza Roaming')|| ' è ' ||GetValueFromCode (310, 'Y')|| ' il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_errore = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_errore = 0 And n_ok_dominio = 0  Then GetCorrectRangeString(n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--                
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
-->
--    se falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then 
--
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                21,                             -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(90),-------------------------------------------------------->''Versione GSM-R''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				 When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                15,                            -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(310),-------------------------------------------------------->''Presenza di roaming''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il primo padre,
      Elsif n_controllo_padre = 2 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				     When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             -- falliti padri
                GetMessFallitoPadreSingolo(90),-------------------------------------------------------->''Versione GSM-R''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                     When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				    When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                14,                            -- falliti padri
                GetMessFallitoPadreSingolo(310),-------------------------------------------------------->''Presenza di roaming''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                    End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_3_7: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_7;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_3_8 (314) - 
--     1.1.1.3.3.8 - Assenza di copertura GSMR (S/N)
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--     Non Applicabile se 1.1.1.3.3.1 - Versione GSM-R = [nessuna] 
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_8     (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.8');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_8', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_8_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.3.1 - Versione GSM-R (90)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_3_3_1 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (lower(s_val_new_2) <> 'none' And s_val_new_1 Is Not Null) Or
					     (lower(s_val_new_2) = 'none' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                          --valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                               --valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And lower(s_val_new_2) <> 'none' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And lower(s_val_new_2)  = 'none') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          GetMessFallitoPadreSingolo(90),--------------------------------------------->Controllo padre fallito 
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_8 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_8;
