--                         Procedure SET_1_1_1_3_3_9_MULT 
-- 1.1.1.3.3.9 - Compatibilità del sistema radio-voce (316) - NCT 
-- Nuovo parametro Reg.777/2019 (elenco valori ancora da pubblicare)
-- Il parametro non è applicabile quando il parametro 1.1.1.3.3.1 – “Versione GSM-R” è valorizzato [nessuna]. (90)
-- Controlli: AP+DOMINIO+CORRELAZIONE(6) - parametro con tabella multipla a parte - PAR_1_1_1_3_3_3_9_RADIO_VOCE
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_3_9_MULT (n_controllo       In Number,
                                 id_sol            In Varchar2,
                                 id_sol_track      In Varchar2,
                                 id_dtp            In Varchar2,
                                 n_controllo_padre In Number,
                                 p_error_split    Out Number   )    Is
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                        -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                        -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;                           
      n_errore                   Number;                           
      d_definizione              Varchar2 (1000);                  
      s_stringa_dominio          Varchar2 (1000);               -- stringa concatenata del dominio
      NYA                        Number;                        -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);               -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                                   -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.3.9');
--
      GetOldNewValueMultiplo ('PAR_1_1_1_3_3_9_RADIO_VOCE', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_9', id_sol_track, valori_multipli);           -- multiplo
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_9_AP', id_sol_track);
--
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_1', id_sol_track);
--
      Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then
--
           If VALORI_MULTIPLI%Found Then 
             Loop
--> loop        Se esistono valori si esegue il controllo sul dominio e sull'applicabilità
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
                If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                                           --> AP=Y e s_val_new_1 in not null
                   Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP                                        --> AP=N e s_val_new_1 in null
                   Then  n_ok_dominio := 1;
				Else n_ok_dominio := 0;
                End If; 
--	            verifica di correlazione con altro parametro 1.1.1.3.3.1			
                If n_ok_AP = 1 Then
                     If n_ok_dominio = 1 Then
                          If  (s_val_new_2  = 'none' And s_val_new_1 Is Not Null)
                           Or (s_val_new_2 <> 'none' And s_val_new_1 Is Null)
                          Then
                             n_errore := 0;
                          Else
                             n_errore := 1;
                          End If; 
                     Else
                          n_errore := 0;
                     End If; 
                Else
                    n_errore := 0;
                End If; 
--
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_errore = 0 And s_val_new_2 = 'none' And s_val_new_1 IS Not Null Then  'Se '||GetParametro(90, 'Versione GSM-R')||' è '||GetValueFromCode (90, 'none')||', il parametro non deve essere valorizzato'
                               When n_errore = 0 And s_val_new_2 <> 'none' And s_val_new_1 Is Null Then  'Se '||GetParametro(90, 'Versione GSM-R')||' è diverso da '||GetValueFromCode (90, 'none')||', il parametro deve essere valorizzato'
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                               When n_ok_AP = 1 And n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
--			    
                 Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
                   Exit When valori_multipli%NOTFOUND;
--> end loop
             End Loop;
--
--         Se non esistono valori
           Else 
                If VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'N' Then                    -- Se è non applicabile va tutto bene
                      n_errore := 1;
                      n_ok_AP := 1;
                      n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NOTFOUND And s_val_new_AP = 'Y' Then                 -- Se è applicabile va tutto male
                      n_errore := 0;
                      n_ok_AP := 0;
                      n_ok_dominio := 0;
                End If; 
--
                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(90),--------------------------------------------------------------->''Versione GSM-R''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_3_9_MULT - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_3_9_MULT;
