--
-- ------------------------------------------------------------------------------------------------
--                              Procedure SET_1_1_1_3_4_1 
-- 1.1.1.3.4.1 - Esistenza di un sistema di rilevamento del treno pienamente conforme alla STI (93)
-- Controlli: 7) DOMINIO + CORRELAZIONE  - AP=Y
-- Nel caso in cui sulla SdL interessata il parametro 1.1.1.3.1.1 “Dichiarazioni di verifica CE del binario (CCS)” 
-- non è valorizzato, questo parametro 1.1.1.3.4.1 deve essere valorizzato [N].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_4_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )       Is                    
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;                               
      n_errore               Number;                               
      d_definizione          Varchar2 (1000);                      
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      CONTA_MULTIPLO         Number;                            -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.4.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_4_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--    il nome conta_mulitplo non è corretto (non ho parametri multipli qui); ci ricicliamo questa variabile solo per appoggio
      Select Count(*) Into CONTA_MULTIPLO                  
      From Rinf_Lavorazione_Evo.DICHIARAZIONI_BINARIO_SOL_CCS
      Where SOL_TRACK_1_1_1_0_0_1 = id_sol_track
      And SOL_TRACK_1_1_1_3_1_1 <> ' ';                     -- aggiunta questa where così non mi conta le diciarazioni inserite vuote, ossia con lo spazio
--
      If n_controllo_padre = 0 Then
           If (CONTA_MULTIPLO = 0 And Nvl(s_val_new_1, 0) <> 'N') Or (CONTA_MULTIPLO <> 0 And s_val_new_1 Is Null)
                Then  n_errore := 0;
                Else  n_errore := GetCorrectValue (n_parametro, s_val_new_1);
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When  NYA=1 Then 1
                     Else n_errore
                     End,
                     7,
                     Case
                          When n_errore = 0 And CONTA_MULTIPLO = 0 And Nvl(s_val_new_1, 0) <> 'N' Then 'Se '||GetParametro(79, 'Dichiarazioni CCS EC')||' non è valorizzato, il parametro deve essere '||GetValueFromCode (n_parametro, 'N')
                          When n_errore = 0 And CONTA_MULTIPLO <> 0 And s_val_new_1 Is Null Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And CONTA_MULTIPLO <> 0 Then 'Il campo ammette solamente '||GetCorrectRangeStringPURA (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else  SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End );
--          in p_error 1 è errato (al contrario di n_errore)
            p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_4_1 - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_4_1;
--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_3_5_1
-- PARAMETRO CANCELLATO
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_5_1 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
      --1.1.1.3.5.1 Sistemi cl.B  DOMINIO+CORRELAZIONE           --eliminata per aggiornamento ERA (mail Schillaci 19/05/2016 e risposta ERA tramite mail Autiero 19/05/2016)

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.5.1');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_5_1',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      --s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_5_1_AP',id_sol_track); --eliminata per aggiornamento ERA (mail Schillaci 19/05/2016 e risposta ERA tramite mail Autiero 19/05/2016)

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_1',id_sol_track);

      --n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1); --eliminata AP per aggiornamento ERA (mail Schillaci 19/05/2016 e risposta ERA tramite mail Autiero 19/05/2016)

             If n_controllo_padre = 0 Then

--                         If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                        --eliminata per aggiornamento ERA (mail Schillaci 19/05/2016 e risposta ERA tramite mail Autiero 19/05/2016)
--                              Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--                              Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
--                              Then n_ok_dominio := 1;
--                              End If; 
                 n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);


                             -- If n_ok_AP = 1
                             -- Then
                                 If n_ok_dominio = 1
                                 Then
--                                    If       (s_val_new_2='N' And nvl(s_val_new_1,0) <>'Y')
--                                        OR (s_val_new_2='1' And s_val_new_1 is not null)
--                                        OR (s_val_new_2='2' And s_val_new_1 is not null)
--                                        OR (s_val_new_2='3' And s_val_new_1 is not null)
                                    If       s_val_new_2='N' And nvl(s_val_new_1,0) <>'Y'
                                    Then
                                       n_errore := 0;
                                    Else
                                       n_errore := 1;
                                    End If; 
                                 Else
                                    n_errore := 0;
                                 End If; 
                              --Else
                              --n_errore := 0;
                              --End If; 

                              SetControlDetails (
                                        n_controllo,
                                        id_sol,
                                        id_sol_track,
                                        n_parametro,
                                        d_definizione,
                                        Case When  NYA=1 Then 1
                                        Else n_errore
                                        End,
                                        6,
                                        Case
                                           When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                                           When n_errore = 0 And s_val_new_2='N' And nvl(s_val_new_1,0) <>'Y' Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, 'N')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'Y')
                                           --aggiornamento ERA (mail Schillaci 19/05/2016 e risposta ERA tramite mail Autiero 19/05/2016)
                                           --When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                                           --When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                                           --When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                                           --When n_errore = 0 And s_val_new_2='N' And nvl(s_val_new_1,0) <>'Y' Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, 'N')||' il parametro deve essere '||GetValueFromCode (n_parametro, 'Y') --ridondante
                                           --When n_errore = 0 And s_val_new_2='1' And s_val_new_1 is not null Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '1') ||' il parametro deve essere non applicabile'
                                           --When n_errore = 0 And s_val_new_2='2' And s_val_new_1 is not null Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '2') ||' il parametro deve essere non applicabile'
                                           --When n_errore = 0 And s_val_new_2='3' And s_val_new_1 is not null Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '3') ||' il parametro deve essere non applicabile'
                                           Else NULL
                                        End,
                                        s_val_new_1,
                                        s_val_old_ok_1,
                                        n_controllo_old_ok_1,
                                         Case
                                                When n_errore = 0 And NYA=0 Then 0
                                                When n_errore = 0 And NYA=1 Then 1
                                                When n_errore = 1  Then 0
                                           End);

                        p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

                Else  SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When  NYA=1 Then 1
                                When n_controllo_padre = 1 Then 1
                        Else 0
                        End,
                        14,                 --fallito padre
                        GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_controllo_padre = 1 Then 1
                                When NYA=0 Then 0
                                When NYA=1 Then 1
                           End);

                           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
               End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_5_1: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_5_1;
--
-- ------------------------------------------------------------------------------------------------
--                 Procedure SET_1_1_1_3_5_2
-- PARAMETRO CANCELLATO
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_5_2 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.5.2 Più sistemi cl. B  APPLICABILITA'+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.5.2');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_5_2',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_5_2_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_2_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

     If n_controllo_padre = 0 Then

                 If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
                      Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                      Then n_ok_dominio := 1;
                      End If; 

                      If n_ok_AP = 1
                      Then
                         If n_ok_dominio = 1
                         Then
                            If       s_val_new_2='N' And s_val_new_1 = 'N'
                                OR s_val_new_2<>'N' And s_val_new_1 is null
                            Then
                               n_errore := 1;
                            Else
                               n_errore := 0;
                            End If; 
                         Else
                            n_errore := 0;
                         End If; 
                      Else
                         n_errore := 0;
                      End If; 

                      SetControlDetails (
                                n_controllo,
                                id_sol,
                                id_sol_track,
                                n_parametro,
                                d_definizione,
                                Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                6,
                               Case
                                When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                                   When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                                   When n_errore = 0 And s_val_new_2='N' And s_val_new_1 <>'N' Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, 'N') ||', il parametro deve essere '||GetValueFromCode (n_parametro, 'N')
                                   When n_errore = 0 And s_val_new_2='1' And s_val_new_1 is not null Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '1') ||', il parametro non deve essere valorizzato'
                                   When n_errore = 0 And s_val_new_2='2' And s_val_new_1 is not null Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '2') ||', il parametro non deve essere valorizzato'
                                   When n_errore = 0 And s_val_new_2='3' And s_val_new_1 is not null Then  'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, '3') ||', il parametro non deve essere valorizzato'
                                   Else NULL
                                End,
                                s_val_new_1,
                                s_val_old_ok_1,
                                n_controllo_old_ok_1,
                                 Case
                                        When n_errore = 0 And NYA=0 Then 0
                                        When n_errore = 0 And NYA=1 Then 1
                                        When n_errore = 1  Then 0
                                   End);

                p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

        Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                        When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->' ''Livello ETCS''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_5_2: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_5_2;

-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_5_3_MULT (320) - 
-- 1.1.1.3.5.3 - Sistema preesistente di protezione del treno - Nuovo parametro - Reg.777/2019 - Sempre Applicabile
-- Tipo Controllo: 4-DOMINIO (elenco) - Multipla PAR_1_1_1_3_5_3_SIST_PRE_PROT
/*************************************************************************/
--> N.B.verificare se scrivere una nuova funzione GetCorrectValue per gestire due valori del dominio[BACC]+[RSDD/SCMT] 
-- oppre sostituire a 12-[BACC] [BACC]+[RSDD/SCMT] nel dominio
/*************************************************************************/
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_5_3_MULT    (n_controllo       In     Number,
                                     id_sol            In     Varchar2,
                                     id_sol_track      In     Varchar2,
                                     id_dtp            In     Varchar2,
                                     n_controllo_padre In     Number,
                                     p_error_split    Out     Number  )    Is
      n_parametro                    Number;
      s_val_new_1                    Varchar2 (1000);
      s_val_new_2                    Varchar2 (1000);
      s_val_new_3                    Varchar2 (1000);
      s_val_old_ok_1                 Varchar2 (1000);
      s_val_new_AP                   Varchar2 (1000);
      n_ok_AP                        Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio                   Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1           Number;
      n_errore                       Number;
      d_definizione                  Varchar2 (1000);
      s_stringa_dominio              Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                            Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2                 Varchar2 (1000); 
      VALORI_MULTIPLI                EMPCUR;                            -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);    
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.5.3');
--
      GetOldNewValueMultiplo ('PAR_1_1_1_3_5_3_SIST_PRE_PROT', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_5_3', id_sol_track, valori_multipli);           -- multiplo
--
      NYA := GetNYA (n_parametro);
--
      Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then
--
           If VALORI_MULTIPLI%Found Then 
             Loop
--> loop       
--              verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
                n_errore := GetCorrectValue(n_parametro, s_val_new_1);
--
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          4,
                          Case
                               When n_errore = 0 And s_val_new_1 Is Null Then 'Valore mancante'
                               When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End);
--
                 Fetch valori_multipli Into s_val_new_1, s_val_old_ok_1;
                   Exit When valori_multipli%NOTFOUND;
--> end loop
             End Loop;
--
--         Se non esistono valori
           Else 
                n_errore := 0;
--
                SetControlDetails(
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          4,
                          Case
                               When s_val_new_1 Is Null Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_5_3_MULT - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_5_3_MULT;

--
-- ------------------------------------------------------------------------------------------------
--                        PROCEDURE SET_1_1_1_3_6_1 - Modificata con il Reg.777/2019 (96)
-- 1.1.1.3.6.1 Altri sistemi radio installati (sistemi radio preesistenti) - NCT - AP=Y
-- In tutte le sezioni di linea a questo parametro deve essere attribuito il valore costante [GSM-P].
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_6_1 (n_controllo       In   Number,
                            id_sol            In   Varchar2,
                            id_sol_track      In   Varchar2,
                            id_dtp            In   Varchar2,
                            n_controllo_padre In   Number,
                            p_error_split    Out   Number  )  Is
      n_parametro           Number;
      s_val_new_1           Varchar2 (1000);
      s_val_new_2           Varchar2 (1000);
      s_val_new_appo        Varchar2 (1000);
      s_val_old_ok_1        Varchar2 (1000);
      s_val_new_AP          Varchar2 (1000);
      n_ok_AP               Number;               -- variabile appoggio applicabilità 0/1
      n_ok_dominio          Number;               -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1  Number;
      n_errore              Number;
      d_definizione         Varchar2 (1000);
      s_stringa_dominio     Varchar2 (1000);      -- stringa concatenata del dominio
      NYA                   Number;               -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2        Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);  
--    Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.6.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_6_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      If n_controllo_padre = 0 Then
           n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--
		   If n_ok_dominio = 1 Then
		        If (s_val_new_1 = 'Y' or s_val_new_1 = 'N' ) Then 
				   s_val_new_appo := s_val_new_1;
				   s_val_new_1 := GetCodeFromValue (n_parametro, 'GSM-P');
		           n_errore := 1;
		        Else 
		           n_errore := 1;
                End If;
		   Else 
   		        s_val_new_appo := s_val_new_1;
                s_val_new_1 := GetCodeFromValue (n_parametro, 'GSM-P');
		        n_errore := 1;
           End If;
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case
 --                       When n_errore = 0 Then 'Il Presente parametro deve assumere solamente il valore [GSM-P]'
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When s_val_new_appo  <> GetCodeFromValue (n_parametro, 'GSM-P') Then 'Il parametro ammette solamente il valore '||GetCodeFromValue (n_parametro, 'GSM-P')
                          Else NULL
                     End,
--                     s_val_new_1,
                     s_val_new_appo,                                -- serve per scrivere il valore non corretto
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--				 
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------------------------->
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_6_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_6_1;
--
-- ------------------------------------------------------------------------------------------------
--       PROCEDURE SET_1_1_1_3_7_1 sostituito da SET_1_1_1_3_7_1_1 dal Reg.777/2019 (97)
--                            1.1.1.3.7.1 Sistemi loc. treni DOMINIO
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number) Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0

  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.1');
--
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
--
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     4,
                     Case When n_errore = 0 Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0  Then 0
                          When n_errore = 0 And NYA = 1  Then 1
                          When n_errore = 1              Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio					 
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                         
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_1 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_1;
--
-- ------------------------------------------------------------------------------------------------
--       PROCEDURE SET_1_1_1_3_7_1_1 sostituisce la SET_1_1_1_3_7_1_1 dal Reg.777/2019 (322)
--          1.1.1.3.7.1.1 Tipo di sistema di rilevamento del treno - AP+DOMINIO - NCT
-- [circuito di binario] - track Circuito - in presenza di circuiti di binario
-- [rilevatore di ruota] - wheel detector - in presenza di pedali
-- [non applicabile]  - in presenza di blocco telefonico o blocco elettrico manuale
-- loop - non ammesso per RFI
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_7_1_1 (n_controllo       In Number,
                              id_sol            In Varchar2,
                              id_sol_track      In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number)   Is                        
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_new_3             Varchar2 (1000);
      s_val_new_4             Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      n_ok_AP                 Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio            Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;
      n_errore                Number;
      d_definizione           Varchar2 (1000);
      s_stringa_dominio       Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                     Number;                            -- ritorna se è NYA = 1 o 0
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.1.1');
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--    acquisisce il valore dell'Applicabilità associata al parametro
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1_AP', id_sol_track);
--    Verifica che l'applicabilità e il valore siano coerenti (AP=Y e valore not null o AP=N e valore null)--> n_ok_AP=1 altrimenti =0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then
				n_errore := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then 
                n_errore := 1;
           Else 	                   
			    n_errore := 0;     
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     12,
                     Case 
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
					      When n_errore = 0 Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0  Then 0
                          When n_errore = 0 And NYA = 1  Then 1
                          When n_errore = 1              Then 0
                     End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio					 
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else  SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1               Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End  );
--        in p_error 1 è errato (al contrario di n_errore)
          p_error_split := 1;                         
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_1_1 - Errore: ' ||Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_1_1;
--
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_7_1_2 (324) 
--  1.1.1.3.7.1.2 - Tipo di circuiti di binario o contatori assi per i quali sono richieste verifiche specifiche
--         Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE - NCT
-- Il parametro è applicabile e deve essere valorizzato solo se il parametro 1.1.1.3.7.1.1 - "Tipo di sistema di Rilevamento del treno"
-- assume i valori: [circuito binario] o [rilevatore di ruota]
-- Questo parametro deve essere valorizzato quando il valore del parametro 1.1.1.3.4.1 
-- “Esistenza di un sistema di rilevamento del treno pienamente conforme alla STI” è [N]. --Eliminato il controllo con la Mail di Schillaci del 23/03/2021 
-- Modifica del 02/04/2021:
/*
Il parametro deve essere valorizzato se siamo in presenza di circuiti di binario o rilevatori di ruota che richiedono verifiche
specifiche in ambito di compatibilità treno-tratta.
Nel caso di circuiti di binario il parametro può assumere i valori:
   VALORE                          valore_XML    CODIFICA_VALORE
- cdb 50Hz                          10            - track circuit 50Hz
- cdb 50Hz + 178Hz                  20            - track circuit 50Hz + 178Hz
- cdb 83.3Hz                        30            - track circuit 83.3Hz
- cdb 83.3Hz + 178Hz                40            - track circuit 83.3Hz + 178Hz
- cdb Audiofrequenza                50            - track circuit Audiofrequency
Nel caso di rilevatore di ruota il parametro può assumere i valori:                       
- pedale Siemens                    60            - wheel detector Siemens
- pedale ITT/A                      70            - wheel detector ITT/A
- pedale Alstom (ex-Siliani)        80            - wheel detector Alstom(ex-Sil)
- pedale Alstom (BCA2)              90            - wheel detector Alstom (BCA2)
- pedale Ducati                    100            - wheel detector Ducati
- pedale Thales                    110            - wheel detector Thales
- pedale ECM                       120            - wheel detector ECM
- pedale Bombardier                130            - wheel detector Bombardier
*/                                                                                       
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_1_2  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
-- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.1.2');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_2', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--
--    acquisisce il valore del parametro 1.1.1.3.7.1.1 - Tipo di localizzazione dei treni dalla tabella BINARI_CORSA_SOL
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.3.4.1 - Esistenza di un Sistema di rilevamento del treno pienamente conforme alla STI dalla tabella BINARI_CORSA_SOL
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_4_1', id_sol_track);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_2_AP', id_sol_track); 
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Controllo padre: dipende dal parametrio 1.1.1.3.7.1.1 
--
      If n_controllo_padre = 0 Then
--		   
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                          -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                       -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else
				n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1   Then                                                   -- se l'applicabilità è coerente con il valore
                If n_ok_dominio = 1 Then                                           -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
--	
/*********** eliminato il controllo con il parametro 1.1.1.3.4.1	     
                     If s_val_new_3 = 'Y' Then                                     -- [Esistenza di un sistema di rilevamento del treno pienamente conforme alla STI]
					      If s_val_new_1 Is Null Then 
                               n_errore := 1;                        
						  Else
                               n_errore := 0;                                      -- errore
						  End if;
                     Elsif s_val_new_3 = 'N' Then
						  If (((s_val_new_2 = 'Track circuit' Or s_val_new_2 = 'Wheel detector') and s_val_new_1 Is Not Null) Or    --[circuito di binario] o [rilevatore di ruota]
                              ((s_val_new_2 <> 'Track circuit' And s_val_new_2 <> 'Wheel detector') And s_val_new_1 Is Null))  Then   
   						         n_errore := 1;
						  Else 
                                 n_errore := 0;
                          End If; 
                     Else
                                 n_errore := 0;
	                 End If; 
***********/
---> aggiunto in sostituzione del precedente controllo
--				     If (((s_val_new_2 = 'Track circuit' Or s_val_new_2 = 'Wheel detector') and s_val_new_1 Is Not Null) Or    --[circuito di binario] o [rilevatore di ruota]
 				     If (((Lower(s_val_new_2) = 'track circuit'  And Substr(Lower(s_val_new_1), 1, 5) = 'track')  Or
					      (Lower(s_val_new_2) = 'wheel detector' And Substr(Lower(s_val_new_1), 1, 5) = 'wheel')) Or    --[circuito di binario] o [rilevatore di ruota]
--                         ((Lower(s_val_new_2) <> 'track circuit'  And Lower(s_val_new_2) <> 'wheel detector') And s_val_new_1 Is Null) Or
						 (s_val_new_2 Is Null And s_val_new_1 Is Null ) ) Then   -- AGGIUNTO IL 22/10/2021   
   				            n_errore := 1;
				     Else 
                            n_errore := 0;
                     End If; 
--->
                 Else  
				      n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                End If; 
           Else  
		        n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
--                          When (n_errore = 0 And s_val_new_3 = 'Y' And s_val_new_1 Is Not Null) Then 'Il parametro non è applicabile quando esiste un sistema di rilevamento del treno pienamente conforme alla STI'
--                          When (n_errore = 0 And s_val_new_3 = 'N' And s_val_new_1 Is Null) Then 'Valore mancante'
                          When (n_errore = 0 And Lower(s_val_new_2) = 'track circuit' And Substr(Lower(s_val_new_1), 1, 5) <> 'track')  Then  'Se '||GetParametro(322, 'Tipo Rilevamento')|| ' è ' ||GetCodValueFromXML (322, '10')|| ', il parametro deve essere valorizzato con i valori ammessi'
                          When (n_errore = 0 And Lower(s_val_new_2) = 'wheel detector' And Substr(Lower(s_val_new_1), 1, 5) <> 'wheel') Then  'Se '||GetParametro(322, 'Tipo Rilevamento')|| ' è ' ||GetCodValueFromXML (322, '20')|| ', il parametro deve essere valorizzato con i valori ammessi'
 --                         When (n_errore = 0 And Lower(s_val_new_2) = 'track circuit' And Lower(s_val_new_2) = 'wheel detector' And s_val_new_1 Is Not Null) Then  'Il parametro non è applicabile quando '||GetParametro(322, 'Tipo Rilevamento')|| ' è diverso da '||GetCodValueFromXML (322, '10')||' e '||GetCodValueFromXML (322, '20')
                          When (n_errore = 0 And Lower(s_val_new_2) <> 'track circuit' And Lower(s_val_new_2) <> 'wheel detector' And s_val_new_1 Is Not Null) Then  'Il parametro non è applicabile quando '||GetParametro(322, 'Tipo Rilevamento')|| ' è diverso da '||GetCodValueFromXML (322, '10')||' e '||GetCodValueFromXML (322, '20')
                          When (n_errore = 0 And Lower(s_val_new_2) = 'track circuit' Or Lower(s_val_new_2) = 'wheel detector' And s_val_new_1 Is Null) Then  'Il parametro deve essere valorizzato quando '||GetParametro(322, 'Tipo Rilevamento')|| ' è ['||GetCodValueFromXML (322, '10')||'] o ['||GetCodValueFromXML (322, '20')||']'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--                
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
-->
--    se fallisce il padre
      Else
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				     When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             -- fallito padre
                GetMessFallitoPadreSingolo(322),--------------------------------------------------------->''Tipo di Sistema di rilevamento del treno''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                     When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
-- 
     End if;
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_1_2: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_1_2;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_7_1_3_MULT(326)  - Multivalore: PAR_1_1_1_3_7_1_3_SIS_RIL_DOC
--  1.1.1.3.7.1.3 - CTD_TCCheckDocRef - Documento riportante la/le procedura/e relativa/e ai tipi di sistema di rilevamento del treno di cui al punto 1.1.1.3.7.1.2
--         Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE - NCT
-- Il parametro è applicabile quando il parametro 1.1.1.3.7.1.2 è valorizzato
-- Questo parametro deve essere valorizzato quando il valore del parametro 1.1.1.3.4.1 
-- “Esistenza di un sistema di rilevamento del treno pienamente conforme alla STI” è [N].   --Eliminato il controllo con la Mail di Schillaci del 07/04/2021 
-- Il parametro, quando applicabile, assume il valore [ERA/TD/2011-01/XA ver. 1.2] e [documenti emanati dal gestore infrastruttura - ANSF]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_1_3_MULT  (n_controllo       In     Number,
                                     id_sol            In     Varchar2,
                                     id_sol_track      In     Varchar2,
                                     id_dtp            In     Varchar2,
                                     n_controllo_padre In     Number,
                                     p_error_split    Out     Number)     Is
      n_parametro                    Number;
      s_val_new_1                    Varchar2 (1000);
      s_val_new_2                    Varchar2 (1000);
      s_val_new_3                    Varchar2 (1000);
      s_val_old_ok_1                 Varchar2 (1000);
      s_val_new_AP                   Varchar2 (1000);
      n_ok_AP                        Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio                   Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1           Number;
      n_errore                       Number;
      d_definizione                  Varchar2 (1000);
      s_stringa_dominio              Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                            Number;                            -- ritorna se è NYA = 1 o 0
      VALORI_MULTIPLI                EMPCUR;                            -- Cursore Per I Valori NEW e OLD Dei Parametri In Tabella Multipli A Parte
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.1.3');
--
--    legge il valore attuale e precedente dalla tabella PAR_1_1_1_3_7_1_3_SISTRILTRAIN degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValueMultiplo('PAR_1_1_1_3_7_1_3_SISTRILTRAIN', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_3', id_sol_track, valori_multipli); -- multiplo
--
--    acquisisce il valore del parametro 1.1.1.3.7.1.2 - Tipo di localizzazione dei treni dalla tabella BINARI_CORSA_SOL
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_2', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.3.4.1 - Esistenza di un Sistema di rilevamento del treno pienamente conforme alla STI dalla tabella BINARI_CORSA_SOL
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_4_1', id_sol_track);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_2_AP', id_sol_track); 
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
--
--    Controllo padre: dipende dai parametri 1.1.1.3.7.1.1 [e 1.1.1.3.4.1]
      If n_controllo_padre = 0 Then
--
--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
--> loop
		     Loop
--              verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);               
--
                     If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                          -- Correlazione AP-Valore=ok e AP=Y
--                        n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);       -- Controlla se il valore è compreso nell'elenco "LookUp Value"
                          n_ok_dominio := 1;
                     Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                       -- Correlazione AP-Valore=ok (=Null) e AP=N
                          n_ok_dominio := 1;
		             Else
			          	  n_ok_dominio := 0;
                     End If; 
--                   
                     If n_ok_AP = 1   Then                                                   -- se l'applicabilità è coerente con il valore
                          If n_ok_dominio = 1 Then                                           -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
/*		          
                               If s_val_new_3 = 'Y' Then                                     -- [Esistenza di un sistema di rilevamento del treno pienamente conforme alla STI]
			      		           If s_val_new_1 Is Null Then 
                                         n_errore := 1;                        
			      		     	    Else
                                         n_errore := 0;                                      -- errore
			      		     	    End if;
                               Elsif s_val_new_3 = 'N' Then
-- VERIFICARE I VALORI  
*/     
			      		     	    If ((s_val_new_2 Is Not Null And s_val_new_1 Is Not Null)    
                                     Or (s_val_new_2 Is Null And s_val_new_1 Is Null))  
						     	    Then   
   			      		     	         n_errore := 1;
			      		     	    Else 
                                          n_errore := 0;
                                    End If; 
/*
                               Else
                                    n_errore := 0;
	                           End If; 
*/
                          Else  
		           	           n_errore := 0;  -- il valore non è compreso nell'elenco dei valori ammessi
                          End If; 
                     Else  
		                  n_errore := 0; -- il valore del parametro non è coerente con l'applicabilità 
                     End If; 
--
                     SetControlDetails (
                               n_controllo,
                               id_sol,
                               id_sol_track,
                               n_parametro,
                               d_definizione,
                               Case When NYA = 1 Then 1
                                    Else n_errore
                               End,
                               6,
                               Case
                                    When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                                    When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
--                                    When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                                    When (n_errore = 0 And s_val_new_2 Is Not Null And s_val_new_1 Is Null) Then  'Se '||GetParametro(324, 'Tipo di circuiti')|| ' è valorizzato il presente parametro deve essere applicabile'
                                    When (n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null) Then  'Il parametro non è applicabile quando '||GetParametro(324, 'Tipo di circuiti')|| ' non è valorizzato'
--                                    When (n_errore = 0 And s_val_new_3 = 'Y' And s_val_new_1 Is Not Null) Then 'Il parametro non deve essere valorizzato quando esiste un sistema di rilevamento del treno pienamente conforme alla STI'
--                                    When (n_errore = 0 And s_val_new_3 = 'N' And s_val_new_1 Is Null) Then 'Il parametro deve essere valorizzato quando non è presente un sistema di rilevamento del treno pienamente conforme alla STI'
                                    Else Null
                               End,
                               s_val_new_1,
                               s_val_old_ok_1,
                               n_controllo_old_ok_1,
                               Case
                                    When n_errore = 0 And NYA = 0 Then 0
                                    When n_errore = 0 And NYA = 1 Then 1
                                    When n_errore = 1             Then 0
                               End);
--                          
--                   siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                     p_error_split := Mod(n_errore +1, 2);                               
-->             

                     Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                      Exit When VALORI_MULTIPLI%NotFound;
--> end loop 		 
             End Loop;
--			  
--         Se NO DATA FOUND
           Else 
                If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then          -- Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then      -- Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If; 
                     SetControlDetails
					  (   n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          12,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP 
						       Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1  Then 0
                          End	  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
--    
      Elsif n_controllo_padre = 1 Then 
--
/*
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                21,                             -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(324),--------------------------------------------------------->''Tipo di Circuito di binario o contatori assi''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				 When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                15,                            -- falliti padri - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                GetMessFallitoPadreSingolo(93),-------------------------------------------------------->''Esistenza Sistema di Rilevamento Treno''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    se fallisce il primo padre,
      Elsif n_controllo_padre = 2 Then 
*/
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				     When NYA = 1 Then 1
                     When n_controllo_padre = 1 Then 1
                     Else 0
                End,
                14,                             -- falliti padri
                GetMessFallitoPadreSingolo(324),--------------------------------------------------------->''Tipo di Circuito di binario o contatori assi''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                     When n_controllo_padre = 1 Then 1
                     When NYA = 0 Then 0
                     When NYA = 1 Then 1
                End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
/*
--    se fallisce il secondo padre, ossia "Esistenza Sistema di Rilevamento Treno"
      Elsif n_controllo_padre = 3 Then 
           SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case 
				    When NYA = 1 Then 1
                    When n_controllo_padre = 1 Then 1
                    Else 0
                End,
                14,                            -- falliti padri
                GetMessFallitoPadreSingolo(93),-------------------------------------------------------->''Esistenza Sistema di Rilevamento Treno''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                    When n_controllo_padre = 1 Then 1
                    When NYA = 0 Then 0
                    When NYA = 1 Then 1
                    End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
*/  
  End If; 
--
      Close VALORI_MULTIPLI;

  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_1_3_MULT - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_1_3_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_7_1_4 (328) - NA Intera Rete
-- 1.1.1.3.7.1.4 - CTD_TCLimitation - Sezione con limitazione di rilevamento del treno
-- Nuovo parametro - Reg.777/2019 solo per la rete francese - AP=N - [N]
-- Questo parametro deve essere sempre valorizzato = [non applicabile]. Cotrollo: Campo obbligatoriamente nullo (10)
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_1_4  (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number)    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
 --   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.1.4');
--
--    legge il valore attuale e precedente dalle tabelle BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_4', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      s_val_new_AP := Nvl(GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_4_AP', id_sol_track), 'N'); 
--
      NYA := GetNYA(n_parametro);
--
--           If n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                 n_errore := 1;
--	       Else  
--		        n_errore := 0;
--           End If; 
--
           If n_controllo_padre = 0 Then
--
--              verifica se il valore è contenuto nell'elenco dei valori ammessi (Dominio)
--                n_errore := GetCorrectValue(n_parametro, s_val_new_1);

                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          10,
                          Case
                               When n_errore = 0 And s_val_new_1 Is Not Null Then s_commento_AP_ko
--                               When n_errore = 0 Then GetCorrectRangeString(n_parametro)
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End);
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
--
           Else SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               When n_controllo_padre = 1 Then 1
                               Else 0
                          End,
                          14,                            -- fallito padre
                          MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_controllo_padre = 1 Then 1
                               When NYA = 0 Then 0
                               When NYA = 1 Then 1
                          End);
--
--              in p_error 1 è errato (al contrario di n_errore)
                p_error_split := 1;
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_1_4 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_1_4;

--
-- ------------------------------------------------------------------------------------------------
--                           PROCEDURE SET_1_1_1_3_7_2_1 NCT (110)
-- 1.1.1.3.7.2.1 - CTD_TSIMaxDistConsecutiveAxles - Conformità alla STI della distanza massima autorizzata tra due assi consecutivi; 
-- Tipo Controllo: Ap+DOMINIO+correlazione - Il parametro deve essere valorizzato quando il parametro 1.1.1.3.7.1.1 è applicabile
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_2_1 (n_controllo       In Number,
                               id_sol            In Varchar2,
                               id_sol_track      In Varchar2,
                               id_dtp            In Varchar2,
                               n_controllo_padre In Number,
                               p_error_split    Out Number  )   Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                      Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2           Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se è corretto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol); 
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.2.1');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_2_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    acquisisce il valore del parametro 1.1.1.3.7.1.1 - Tipo di sistema di rilevamento del treno dalla tabella BINARI_CORSA_SOL
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_2_1_AP', id_sol_track); 

      NYA:= GetNYA (n_parametro);
--
      If n_controllo_padre = 0 Then
--
--         verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
           n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);               
--         
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then                          -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then                       -- Correlazione AP-Valore=ok (=Null) e AP=N
                n_ok_dominio := 1;
		   Else
				  n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1   Then                                                   -- se l'applicabilità è coerente con il valore
                If n_ok_dominio = 1 Then                                           -- se anche il valore è compreso nell'elenco dei valori ammessi (Dominio)
--		   
 			       	 If ((s_val_new_2 Is Not Null And s_val_new_1 Is Not Null)    
                     Or (s_val_new_2 Is Null And s_val_new_1 Is Null))  Then   
   			      	      n_errore := 1;
			         Else 
                          n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;                  -- il valore non è compreso nell'elenco dei valori ammessi
	            End If; 
           Else  
		        n_errore := 0;                        -- il valore del parametro non è coerente con l'applicabilità 
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When (n_errore = 0 And s_val_new_2 Is Not Null And s_val_new_1 Is Null) Then  'Se '||GetParametro(322, 'Sistemi di rilevamento')|| ' è valorizzato il presente parametro deve essere applicabile'
                          When (n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null) Then  'Il parametro non è applicabile quando '||GetParametro(322, 'Sistemi di rilevamento')|| ' non è valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre (97 --> 322)
                     GetMessFallitoPadreSingolo(322),--------------------------------------------------------------->' ''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_2_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
 End SET_1_1_1_3_7_2_1;
--
-- ------------------------------------------------------------------------------------------------
--                                  PROCEDURE SET_1_1_1_3_7_2_2 - (112)
-- 1.1.1.3.7.2.2 Distanza massima consentita tra due assi consecutivi in caso di non conformità alla STI - (5)AP+CORRELAZIONE
-- dipende da due padri: 1.1.1.3.7.1.1 e 1.1.1.3.7.2.1 - conformità alla STI della distanza massima autorizzata tra due assi consecutivi
-- Il Parametro deve essere valorizzato quando il valore del parametro: 1.1.1.3.7.2.1 è [Non conforme alla STI] 
-- In RFI il parametro: 1.1.1.3.7.2.1 è sempre [Conforme alla STI] --> sempre Non Applicabile - NA
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_7_2_2 (n_controllo       In Number,
                              id_sol            In Varchar2,
                              id_sol_track      In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number  )   Is
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_new_3             Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      n_ok_AP                 Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio            Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;
      n_errore                Number;
      d_definizione           Varchar2 (1000);
      s_stringa_dominio       Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                     Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2          Varchar2 (1000); 
  BEGIN
--    l'errore nelle procedure vale 0 se il risultato è giusto, 1 se è errato : E' Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.2.2');
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL e RINF_CONTROLLATI_EVO.BINARI_CORSA_SOL
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_2_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--    acquisisce il valore dell'Applicabilità associata al parametro
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_2_2_AP', id_sol_track);
--    acquisisce il valore del parametro 1.1.1.3.7.2.1
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_2_1', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.3.7.1.1 - (é inutile in quanto il presente parametro è sempre NA) 
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 Then
                If (s_val_new_2 = 'TSI compliant'     And s_val_new_1 Is Null) Or
                   (s_val_new_2 = 'TSI not compliant' And s_val_new_1 Is Not Null ) Or 
				   (s_val_new_3 Is Null  And s_val_new_1 Is Null)
                Then
                     n_errore := 1;
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP    Then s_commento_AP_ko
                          When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP    Then s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2  = 'TSI compliant' And s_val_new_1 Is Not Null Then 'Poiche '||GetParametro(110, 'Conformità alla STI della distanza massima')||' deve essere sempre '||GetValueFromCode (110, 'TSI compliant')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2  = 'TSI not compliant' And s_val_new_1 Is Null Then 'Se '||GetParametro(110, 'Conformità alla STI della distanza massima')||' è '||GetValueFromCode (110, 'TSI not compliant')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_1 Is Not Null Then 'Poiche '||GetParametro(110, 'Conformità alla STI della distanza massima')||' deve essere sempre '||GetValueFromCode (110, 'TSI compliant')||', il parametro non deve essere valorizzato' --ridondante
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

 --   se falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then       
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                             -- fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(322),---------------------------------------->''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,       -- fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(110),---------------------------------------->''Distanza massima assi''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
      Elsif n_controllo_padre = 2 Then        -- fallisce il primo padre

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(322),--------------------------------------------------------------->'''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then       
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(110),--------------------------------------------------------------->' ''Distanza massima assi''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_2_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_2_2;
--
-- ------------------------------------------------------------------------------------------------
--                       Procedure SET_1_1_1_3_7_3
--  1.1.1.3.7.3 Distanza minima consentita tra due assi consecutivi [NNNN] in mm - Controlli: AP+CORRELAZIONE
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” 
-- è [rilevatore di ruota]. Il valore di questo parametro, quando applicabile, deve essere [700] o [900].
-- Il valore di questo parametro dovrà essere = [700], se il valore del parametro 1.1.1.1.2.5 “Velocità massima consentita” è = [100].
-- Se il valore del parametro 1.1.1.1.2.5 “Velocità massima consentita” è > [100], il valore di questo parametro deve essere [900].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_3 (n_controllo       In  Number,
                             id_sol            In  Varchar2,
                             id_sol_track      In  Varchar2,
                             id_dtp            In  Varchar2,
                             n_controllo_padre In  Number,
                             p_error_split     Out Number  )       Is
     n_parametro             Number;
     s_val_new_1             Varchar2 (1000);
     s_val_new_2             Varchar2 (1000);
     s_val_new_3             Varchar2 (1000);
     s_val_old_ok_1          Varchar2 (1000);
     s_val_new_AP            Varchar2 (1000);
     n_ok_AP                 Number;                            -- variabile appoggio applicabilità 0/1
     n_ok_dominio            Number;                            -- variabile appoggio esistenza valore in dominio 0/1
     n_controllo_old_ok_1    Number;
     n_errore                Number;
     d_definizione           Varchar2 (1000);
     s_stringa_dominio       Varchar2 (1000);                   -- stringa concatenata del dominio
     NYA                     Number;                            --  ritorna se è NYA = 1 o 0
     s_val_old_ok_2          Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.3');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_3_AP', id_sol_track);
--    Acquisisce il parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” 
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--    Acquisisce il valore del paramtero 1.1.1.1.2.5 “Velocità massima consentita”
      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 Then
                If  (s_val_new_2 = 'Wheel detector' And s_val_new_1 Is Null)
                Or  (Nvl(s_val_new_2, 0) <> 'Wheel detector' And s_val_new_1 Is Not Null )
                Or  (s_val_new_2 = 'Wheel detector' And Nvl(s_val_new_3, 0)<= 100 And Nvl(s_val_new_1, 0) <> 700)
                Or  (s_val_new_2 = 'Wheel detector' And Nvl(s_val_new_3, 0) > 100 And Nvl(s_val_new_1, 0) <> 900)
                Then
                   n_errore := 0;
                Else
                   n_errore := 1;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     5,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 = 'Wheel detector' And s_val_new_1 Is Null Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And (Nvl(s_val_new_2, 0) <> 'Wheel detector' And s_val_new_1 Is Not Null ) Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And (s_val_new_2 = 'Wheel detector' And Nvl(s_val_new_3, 0) <= 100 And nvl(s_val_new_1,0) <> 700) Then 'Se '||GetParametro(17, 'Velocità')||' è minore o uguale a 100 km/h e '||GetParametro(17, 'Velocità')||' è ' ||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere 700'
                          When n_errore = 0 And (s_val_new_2 = 'Wheel detector' And Nvl(s_val_new_3, 0)  > 100 And nvl(s_val_new_1,0) <> 900)  Then 'Se '||GetParametro(17, 'Velocità')||' è maggiore di 100 km/h e '||GetParametro(17, 'Velocità')||' è ' ||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere 900'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
---        siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--    falliscono entrambi i padri
      Elsif n_controllo_padre = 1 Then        
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                            -- fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(17),----------------------------------------->''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA= 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                            -- fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(322),----------------------------------------->'''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il primo padre
      Elsif n_controllo_padre = 2 Then        
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(17),---------------------------------------------------------------> ''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
--
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then        
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(322),--------------------------------------------------------------->''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_3;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_7_4 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.7.4 Dist.min.assi estr AP+CORRELAZIONE (dominio tirato fuori)

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.4');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_4', id_sol_track, s_val_new_1, s_val_old_ok_1);

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_4_AP', id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

              If n_controllo_padre = 0 Then

                  If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                 -- (13/06/2016 dominio tirato fuori)
                  Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                  Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                  Then n_ok_dominio := 1;
                  End If; 

                      If n_ok_AP = 1
                         Then
                              If n_ok_dominio = 1
                                Then
                                    If    (s_val_new_2 = 'Track circuit' And s_val_new_1 IS NULL)
                                    OR (nvl(s_val_new_2,0) <> 'Track circuit' And  s_val_new_1 IS NOT NULL)
                                    --OR  (s_val_new_2 = 'Track circuit' And nvl(s_val_new_1,0) <> 3000)
                                    Then n_errore := 0;
                                    Else n_errore := 1;
                                    End If; 
                                Else n_errore := 0;
                              End If; 
                          Else n_errore := 0;
                      End If; 

             SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                         Case When  NYA=1 Then 1
                        Else n_errore
                        End,
                        6,--5
                        Case
                           When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then  s_commento_AP_ko
                           When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then  s_commento_AP_ok
                           When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                           When n_errore = 0 And  (s_val_new_2 = 'Track circuit' And s_val_new_1 IS NULL) Then  'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere valorizzato'
                           When n_errore = 0 And (nvl(s_val_new_2,0) <> 'Track circuit' And  s_val_new_1 IS NOT NULL) Then  'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Track circuit')||', il parametro non deve essere valorizzato'
                           --When n_errore = 0 And  (s_val_new_2 = 'Track circuit' And nvl(s_val_new_1,0) <> 3000) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere 3000'
                           Else
                              NULL
                        End,
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_errore = 0 And NYA=0 Then 0
                                When n_errore = 0 And NYA=1 Then 1
                                When n_errore = 1  Then 0
                           End);

               p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

                Else  SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When  NYA=1 Then 1
                                When n_controllo_padre = 1 Then 1
                        Else 0
                        End,
                        14,                 --fallito padre
                        GetMessFallitoPadreSingolo(322),--------------------------------------------------------------->''Sistema Localizzazione Treni''
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_controllo_padre = 1 Then 1
                                When NYA=0 Then 0
                                When NYA=1 Then 1
                           End);

                           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
               End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_4: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_4;
--
-- ------------------------------------------------------------------------------------------------
--                      PROCEDURE SET_1_1_1_3_7_5       - Modificato Reg.777/95
-- 1.1.1.3.7.5 (117) - AP+DOMINIO+CORRELAZIONE(6) - Distanza massima tra la fine del treno e il primo asse 
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” 
-- è [rilevatore di ruota] o [circuito di binario].
-- Quando applicabile il parametro x deve essere  [4500]<= x <= [5000].
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_5 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
--    servono per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      CONTA_MULTIPLO         Number;       
      CONTA_MULTIPLO_2       Number;       
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);
--
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.5');
--
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL e RINF_CONTROLLATI_EVO.BINARI_CORSA_SOL
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_5', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--
--    acquisisce il valore dell'Applicabilità associata al parametro
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_5_AP', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.3.7.1.1 - Tipo di sistema di rilevamento del treno
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
--    verifica la coerenza della coppia di dati AP/valore parametro e NAP/nullo: 1:ok - 0:KO
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
--         Controllo dominio e AP
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP  Then                         
                n_ok_dominio := GetCorrectRange (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
	       Else
		        n_ok_dominio := 0;
           End If; 
--	       Controllo Congruità con il parametro 1.1.1.3.7.1.1	   
	       If n_ok_AP = 1  And n_ok_dominio = 1 Then

                If (((s_val_new_2 = 'Wheel detector') Or (s_val_new_2 = 'Track circuit')) And s_val_new_1 Is Not Null) Or
				    (s_val_new_2 Is Null And s_val_new_1 Is Null) Then
                     n_errore := 1;
                Else
                     n_errore := 0;
                End If; 
           Else
               n_errore := 0;
           End If; 
--
--         scrittura nella tabella RINF_LAVORAZIONE_EVO.DETTAGLIO_CONTROLLATI
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetMessFuoriRange(117) 
                          When n_errore = 0 And ((s_val_new_2 = 'Wheel detector') Or (s_val_new_2 = 'Track circuit')) And s_val_new_1 Is Null Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è [Rilevatore di ruota] o [circuito di binario]'||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 is Null And s_val_new_1 Is Not Null Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' Non è Applicabile, anche questo parametro deve essere Non Applicabile'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else  SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''    
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_5 - Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_5;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_7_6 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.7.6 Largh. min.corona AP+CORRELAZIONE (dominio tirato fuori)

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

       n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.6');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_6',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_6_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      --s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_7',id_sol_track);          --eliminato perchè inutile

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

         If n_controllo_padre = 0 Then

                  If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                 -- (13/06/2016 dominio tirato fuori)
                  Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                  Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                  Then n_ok_dominio := 1;
                  End If; 

             If n_ok_AP = 1
                Then
                      If n_ok_dominio = 1
                            Then
                                 If   s_val_new_2 = 'Wheel detector' And s_val_new_1 is null
                                 OR (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null )
                                 --OR (s_val_new_2 = 'Wheel detector' And /*nvl(s_val_new_3,0)>= 330 And*/ nvl(s_val_new_1,0) <> 133)
                                 Then n_errore := 0;
                                 Else n_errore := 1;
                                 End If; 
                            Else n_errore := 0;
                      End If; 
                 Else n_errore := 0;
             End If; 

         SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    6,--5
                    Case
                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                       When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                       When n_errore = 0 And  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null ) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                       --When n_errore = 0 And  (s_val_new_2 = 'Wheel detector' And/* nvl(s_val_new_3,0)>= 330 And*/ nvl(s_val_new_1,0) <> 133) Then 'Il parametro deve essere 133'
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_6: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_6;
--
-- ------------------------------------------------------------------------------------------------
--           PROCEDURE SET_1_1_1_3_7_7 - Modificato dal Reg.777/2019
--         1.1.1.3.7.7 Diametro minimo consentito della ruota in mm - 6) AP+CORRELAZIONE+DOMINIO
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” 
-- è [rilevatore di ruota]. I valori ammessi dipendo dal parametro 1.1.1.1.2.5 - velocità massima consentita
-- Il valore di questo parametro, quando applicabile, deve essere [350] o [470]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_7 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                    Number;                           -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
  BEGIN
--   l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' Il Contrario Di Quello Che Succede Nei Controlli con N_ERRORE
      p_error_split := 0;         
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.7');
--
--    acquisisce il valore attuale e il precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e  RINF_CONTROLLATI_EVO
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_7', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--
--    acquisisce il valore dell'Applicabilità associata al parametro
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_7_AP', id_sol_track);
--
--    acquisisce il valore del parametro 1.1.1.3.7.1.1 - Tipo di sistema di rilevamento del treno
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--	  dbms_output.put_line ('s_val_new_2 :'||s_val_new_2);
--
--    acquisisce il valore del parametro 1.1.1.1.2.5 - Velocità massima consentita
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
--	  dbms_output.put_line ('s_val_new_3 :'||s_val_new_3);
--
--    APPLICABILITà: verifica la coerenza della coppia di dati AP/valore parametro e NAP/nullo: 1:ok - 0:KO
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--	  dbms_output.put_line ('n_ok_AP :'||n_ok_AP);
--
--    se il codice di ritorno delle procedure SET_1_1_1_1_2_5 = 0  e SET_1_1_1_3_7_1_1 = 0
      If n_controllo_padre = 0 Then
--    Controllo applicabilità e dominio 
            If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then       
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
            Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                n_ok_dominio := 1;
  		    Else
  		        n_ok_dominio := 0;
            End If; 
--	        dbms_output.put_line ('n_ok_dominio :'||n_ok_dominio);
--          se il valore è coerente con l'applicabilità
                If n_ok_AP = 1  Then
                     If n_ok_dominio = 1  Then
                          If ((s_val_new_2 = GetCodValueFromXML(322, '20') And s_val_new_1 Is Null ) Or    -- 'Wheel detector' - rilevatore di ruota
                             (Nvl(s_val_new_2, '0') <> GetCodValueFromXML(322, '20') And s_val_new_1 Is Not Null ) Or
                             (s_val_new_2 = GetCodValueFromXML(322, '20') And Nvl(s_val_new_3, '0') <= 100 And Nvl(s_val_new_1, 0) <> GetValueFromCode(119, 350)) Or
                             (s_val_new_2 = GetCodValueFromXML(322, '20') And Nvl(s_val_new_3, '0')  > 100 And Nvl(s_val_new_1, 0) <> GetValueFromCode(119, 470)))
                                  Then n_errore := 0;
                                  Else n_errore := 1;
                          End If; 
                     Else n_errore := 0;
                     End If; 
                Else n_errore := 0;
                End If; 
--
--	       dbms_output.put_line ('n_errore :'||n_errore);
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
				          Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_errore = 0 And s_val_new_2 = GetCodValueFromXML(322, '20') And s_val_new_1 Is Null Then 'Se ' ||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è '||GetCodValueFromXML(322, '20')|| ', il parametro deve essere valorizzato'
                          When n_errore = 0 And (Nvl(s_val_new_2, 0) <> GetCodValueFromXML(322, '20') And s_val_new_1 Is Not Null ) Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' non è '||GetCodValueFromXML(322, '20')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And (s_val_new_2 = GetCodValueFromXML(322, '20') And Nvl(s_val_new_3, 0) <= 100 And Nvl(s_val_new_1, 0) <> 350) Then 'Se '||GetParametro(17, 'Velocità')||' è minore o uguale a 100 km/h e '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è '||GetCodValueFromXML(322, '20')||', il parametro deve essere 350'
                          When n_errore = 0 And (s_val_new_2 = GetCodValueFromXML(322, '20') And Nvl(s_val_new_3, 0) >  100 And Nvl(s_val_new_1, 0) <> 470) Then 'Se '||GetParametro(17, 'Velocità')||' è maggiore di 100 km/h e '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è '||GetCodValueFromXML(322, '20')||', il parametro deve essere 470'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Elsif n_controllo_padre = 1 Then        --falliscono entrambi i padri
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,        --fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(17), ----------------------------------------------->''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--					 
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,     --fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(322), ----------------------------------------------->''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)				    
           p_error_split := 1;                        
--
      Elsif n_controllo_padre = 2 Then        --fallisce il primo padre
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(17),---------------------------------------------------------------> ''Velocità massima consentita''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
--
      Elsif n_controllo_padre = 3 Then        --fallisce il primo padre
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When  NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                    End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_7 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_7;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_7_8 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.7.8 Spessore min.bordino AP+CORRELAZIONE (dominio tirato fuori)

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.8');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_8',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_8_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

         If n_controllo_padre = 0 Then

                  If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                 -- (13/06/2016 dominio tirato fuori)
                  Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                  Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                  Then n_ok_dominio := 1;
                  End If; 

              If n_ok_AP = 1
                Then
                    If n_ok_dominio = 1
                       Then
                             If        (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null )
                             OR  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null )
                             --OR (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 22)
                             Then n_errore := 0;
                             Else n_errore := 1;
                             End If; 
                       Else n_errore := 0;
                    End If; 
                 Else n_errore := 0;
              End If; 

         SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    6,--5
                    Case
                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                       When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       When n_errore = 0 And s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                       When n_errore = 0 And  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null ) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                       --When n_errore = 0 And  (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 22) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere 22'
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_8: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_8;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_7_9 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.7.9 Altezza min.bordino AP+CORRELAZIONE (dominio tirato fuori)

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.9');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_9',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      s_val_new_1 := replace(s_val_new_1,',','.');              --13/06/2016 aggiunta questa conversione in quanto, nel caso di parametri numerici CON VIRGOLA, il DB non riconosce la virgola ma il punto

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_9_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

         If n_controllo_padre = 0 Then

                  If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                 -- (13/06/2016 dominio tirato fuori)
                  Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                  Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                  Then n_ok_dominio := 1;
                  End If; 

              If n_ok_AP = 1
                Then
                    If n_ok_dominio = 1
                       Then
                             If        (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null )
                             OR  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null )
                             --OR (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 27.5)
                             Then n_errore := 0;
                             Else n_errore := 1;
                             End If; 
                      Else n_errore := 0;
                    End If; 
                  Else n_errore := 0;
              End If; 

         SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    6,--5
                    Case
                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                       When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                       When n_errore = 0 And  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null ) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                       --When n_errore = 0 And  (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 27.5) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere 27.5'
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_9: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_9;
--
-- ------------------------------------------------------------------------------------------------
--              Procedure SET_1_1_1_3_7_10  (98)
-- 1.1.1.3.7.10 Altezza massima consentita del bordino AP+CORRELAZIONE (dominio tirato fuori) - [NN.N]
-- AP: Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” è [rilevatore di ruota].
-- Il valore di questo parametro, quando applicabile, deve essere [36.0].
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_7_10 (n_controllo       In Number,
                               id_sol            In Varchar2,
                               id_sol_track      In Varchar2,
                               id_dtp            In Varchar2,
                               n_controllo_padre In Number,
                               p_error_split    Out Number  )    Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                     -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                     -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);            -- stringa concatenata del dominio
      NYA                      Number;                     -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000);            -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.10');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_10', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_10_AP', id_sol_track);
--
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP   Then            -- (13/06/2016 dominio tirato fuori)
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP  Then
                n_ok_dominio := 1;
		   Else
                n_ok_dominio := 0;	   
           End If; 

           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If  (s_val_new_2 = 'Wheel detector' And s_val_new_1 Is Null )
                      Or (nvl(s_val_new_2, 0) <> 'Wheel detector' And s_val_new_1 Is Not Null )
                             --OR (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 36)
                     Then n_errore := 0;
                     Else n_errore := 1;
                     End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,--5
                     Case
                        When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                        When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                        When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                        When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 Is Null Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                        When n_errore = 0 And  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 Is Not Null ) Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
--                      When n_errore = 0 And (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 36) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere 36'
                        Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_10 - Errore: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_10;
--
-- ------------------------------------------------------------------------------------------------
--                     Procedure SET_1_1_1_3_7_11 (CANCELLATO)
-- 1.1.1.3.7.11 Carico min. asse AP+CORRELAZIONE (dominio tirato fuori)
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_7_11 (n_controllo       In Number,
                               id_sol            In Varchar2,
                               id_sol_track      In Varchar2,
                               id_dtp            In Varchar2,
                               n_controllo_padre In Number,
                               p_error_split    Out Number  )     Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                       -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                       -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);              -- stringa concatenata del dominio
      NYA                      Number;                       -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000);              -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.11');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_11',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_11_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

         If n_controllo_padre = 0 Then

                  If n_ok_AP = 1 And s_val_new_AP = v_ok_AP                 -- (13/06/2016 dominio tirato fuori)
                  Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                  Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                  Then n_ok_dominio := 1;
                  End If; 

             If n_ok_AP = 1
              Then
                   If n_ok_dominio = 1
                       Then
                             If        (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null )
                             Or        (s_val_new_2 = 'Track circuit' And s_val_new_1 is null)
                             --or   (     s_val_new_2 = 'Wheel detector' And  nvl(s_val_new_1,0) <> 5.0)
                             --or  (       s_val_new_2 = 'Track circuit' And  nvl(s_val_new_1,0) <> 5.0)
 							 Or         (s_val_new_2 Is Null And s_val_new_1 Is Not Null)

                             Then n_errore := 0;
                             Else n_errore := 1;
                             End If; 
                   Else n_errore := 0;
                   End If; 
              Else n_errore := 0;
              End If; 

        SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    6,--5
                    Case
                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                       When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                       When n_errore = 0 And  s_val_new_2 = 'Track circuit' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere valorizzato'
                       --When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And  nvl(s_val_new_1,0) <> 5 Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere 5'
                       --When n_errore = 0 And  s_val_new_2 = 'Track circuit' And  nvl(s_val_new_1,0) <> 5 Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere 5'
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_11: ' || Substr (Sqlerrm, 1, 250));
    End SET_1_1_1_3_7_11;

-- ------------------------------------------------------------------------------------------------
--                              Procedure SET_1_1_1_3_7_11_1_MULT
--    1.1.1.3.7.11.1 Carico minimo consentito per asse per categoria di veicoli NUOVO PARAMETRO(330)
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” è 
-- [rilevatore di ruota] o [circuito di binario]. Nel caso in cui il parametro 1.1.1.3.7.1.1 sia “circuito di binario” o “rilevatore di ruota”, 
-- il valore di questo parametro è: "[5.0] per veicoli con più di 4 assi e freni a ceppi";
--    Controllo: AP+DOMINIO+CORRELAZIONE - parametro con tabella multipla a parte PAR_1_1_1_3_7_11_1_CARMIN_ASSE 
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_11_1_MULT (n_controllo       In     Number,
                                     id_sol            In     Varchar2,
                                     id_sol_track      In     Varchar2,
                                     id_dtp            In     Varchar2,
                                     n_controllo_padre In     Number,
                                     p_error_split     Out    Number   )   Is
      n_parametro                    Number;
      s_val_new_1                    Varchar2 (1000);
      s_val_new_2                    Varchar2 (1000);
      s_val_old_ok_1                 Varchar2 (1000);
      s_val_new_AP                   Varchar2 (1000);
      n_ok_AP                        Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio                   Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1           Number;
      n_errore                       Number;
      d_definizione                  Varchar2 (1000);
      s_stringa_dominio              Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                            Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2                 Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI                EMPCUR;                            -- Cursore Per I Valori NEW e OLD Dei Parametri In Tabella Multipli A Parte
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.11.1');
--    verifica che il parametro possa assumere il valore NYA o meno
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_1_1_3_7_11_1_CARMIN_ASSE', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_11_1', id_sol_track, valori_multipli) ;  -- multiplo
--    
--      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_4_3_AP', id_sol_track); -- (errore)
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_11_1_AP', id_sol_track);
--	  
--    acquisisce il valore del parametro "padre" 1.1.1.3.7.1.1
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then

--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
			  Loop
--> loop
--                Test AP e Correlazione
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);               

                If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                     n_ok_dominio := GetCorrectValue(n_parametro, s_val_new_1);         -- verifica che il valore sia tra quelli ammessi
                Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                     n_ok_dominio := 1;
		        Else 
				     n_ok_dominio := 0;
                End If; 
--              
                If n_ok_AP = 1 Then
--                   Se il valore è nella LookUp value oppure è Null
                     If n_ok_dominio = 1 Then
--                        Controllo l'applicabilità con il parametro "padre" 1.1.1.1.7.1.1 
                          If ((s_val_new_2 = 'Wheel detector') Or (s_val_new_2 = 'Track circuit')) And s_val_new_1 Is Null Then 
                               n_errore := 0;
                          Elsif ((s_val_new_2 <> 'Wheel detector') And (s_val_new_2 <> 'Track circuit') And s_val_new_1 Is Not Null) Then 
                               n_errore := 0;
                          Else n_errore := 1;
                          End If; 
                     Else n_errore := 0;                                                      -- valore non coerente con AP
                     End If; 

                Else n_errore := 0;                                                      -- valore non coerente con AP
                End If; 
--
                SetControlDetails
                    (     n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 Then 1
                               Else n_errore
                          End,
                          6,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                               When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                               When n_errore = 0 And ((s_val_new_2 = 'Wheel detector') Or (s_val_new_2 = 'Track circuit')) And s_val_new_1 Is Null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', o '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                               When n_errore = 0 And (s_val_new_2 <> 'Wheel detector') And (s_val_new_2 <> 'Track circuit') And s_val_new_1 is not null  Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è diverso da '||GetValueFromCode (322, 'Track circuit')||', e '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
--> VERIFICARE IL VALORE [5.0]
--                               When n_errore = 0 And ((s_val_new_2 = 'Wheel detector') Or (s_val_new_2 = 'Track circuit')) And Nvl(s_val_new_1, 0) <> '5.0' Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', o '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, '5.0')
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1              Then 0
                          End  );
--		 
                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                 Exit When VALORI_MULTIPLI%NotFound;
--> end loop 		 
              End Loop;
--         Se NO DATA FOUND
           Else 
               If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then          -- Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then      -- Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If; 
                    SetControlDetails
					  ( n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When NYA = 1 
						     Then 1
                             Else n_errore
                        End,
                        12,
                        Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP 
						     Then s_commento_AP_ok
                             Else Null
                        End,
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                        Case When n_errore = 0 And NYA = 0 Then 0
                             When n_errore = 0 And NYA = 1 Then 1
                             When n_errore = 1  Then 0
                        End
					  );

          End If; 
--        siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
          p_error_split := Mod(n_errore +1, 2);                               

     Else  SetControlDetails 
                  (  n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     'Valori errati',--s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End	    );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_11_1_MULT - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_11_1_MULT;


--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_7_12 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.7.12 Conformità STI  spazio privo metallo ruote DOMINIO +AP+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.12');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_12',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_12_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

         If n_controllo_padre = 0 Then

              If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
              Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
              Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
              Then n_ok_dominio := 1;
              End If; 

              If n_ok_AP = 1
              Then
                     If n_ok_dominio = 1
                     Then
                            If        (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null )
                                or  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null )
                                or (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 'TSI compliant')
                            Then
                               n_errore := 0;
                            Else
                               n_errore := 1;
                            End If; 
                     Else
                        n_errore := 0;
                     End If; 
              Else
                 n_errore := 0;
              End If; 

        SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                    Else n_errore
                    End,
                    6,
                    Case
                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                       --When n_errore = 0 Then GetCorrectRangeString (n_parametro)
                       When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                       When n_errore = 0 And  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null ) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                       When n_errore = 0 And  (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0) <> 'TSI compliant') Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'TSI compliant')
                       Else NULL
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_errore = 0 And NYA=0 Then 0
                            When n_errore = 0 And NYA=1 Then 1
                            When n_errore = 1  Then 0
                       End);

           p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_12: ' || Substr (Sqlerrm, 1, 250));
    End SET_1_1_1_3_7_12;
--
-- ------------------------------------------------------------------------------------------------
--  1.1.1.3.7.13 - CTD_TSIMetalConstruction - Conformità alla STI delle norme sulla costruzione metallica del veicolo  (101)
--  Il parametro è applicabile solo quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistemi di localizzazione dei treni” sia [loop].
--  Poiché, alla data di redazione delle presenti Linee Guida, per le sezioni di linea della rete gestita da RFI, non è ammesso il
--  valore [loop], ne consegue che questo parametro è sempre non applicabile.
--  1.1.1.3.7.13 Norme massa veic. AP+DOMINIO+CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_7_13   (n_controllo       In Number,
                                 id_sol            In Varchar2,
                                 id_sol_track      In Varchar2,
                                 id_dtp            In Varchar2,
                                 n_controllo_padre In Number,
                                 p_error_split    Out Number)        Is
--
      n_parametro                Number;
      s_val_new_1                Varchar2 (1000);
      s_val_new_2                Varchar2 (1000);
      s_val_old_ok_1             Varchar2 (1000);
      s_val_new_AP               Varchar2 (1000);
      n_ok_AP                    Number;                               -- variabile appoggio applicabilità 0/1
      n_ok_dominio               Number;                               -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1       Number;
      n_errore                   Number;
      d_definizione              Varchar2 (1000);
      s_stringa_dominio          Varchar2 (1000);                      -- stringa concatenata del dominio
      NYA                        Number;                               -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2             Varchar2 (1000);                      -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1:= GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto	  
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.13');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_13', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_13_AP', id_sol_track);
--
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--        
      If n_controllo_padre = 0 Then
--
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then   
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
                n_ok_dominio := 1;
		   Else 
		        n_ok_dominio := 0;
           End If; 
--         
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If  s_val_new_1 Is Not Null Then
                         n_errore := 0;
                     Else
                         n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
              n_errore := 0;
           End If; 
--
            SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 
					     Then 1
                         Else n_errore
                    End,
                    6,
                    Case
                       When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                       When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                       When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                       When n_errore = 0 And s_val_new_1 Is Not Null Then 'Il parametro non deve essere valorizzato (è valorizzato solo in caso di presenza di Loop)'
                       Else Null
                    End,
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case
                       When n_errore = 0 And NYA = 0 Then 0
                       When n_errore = 0 And NYA = 1 Then 1
                       When n_errore = 1 Then 0
                    End);
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore+1, 2);                               

      Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When NYA = 1 Then 1
                         When n_controllo_padre = 1 Then 1
                         Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                    Case When n_controllo_padre = 1 Then 1
                         When NYA = 0 Then 0
                         When NYA = 1 Then 1
                    End);
--        in p_error 1 è errato (al contrario di n_errore) 
          p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_13: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_13;
--
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
   PROCEDURE SET_1_1_1_3_7_14 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.7.14 Ferromagnetiche AP+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

     n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.14');

     GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_14',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

     NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_14_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

     If n_controllo_padre = 0 Then

       If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
      Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
      Then n_ok_dominio := 1;
      End If; 

      If n_ok_AP = 1
      Then
        If n_ok_dominio = 1
         Then
                If     (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null)
                        or  (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null )
                        or (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0)<>'TSI not compliant' )
                Then
                    n_errore := 0;
                Else
                    n_errore := 1;
                End If; 
        Else
            n_errore := 0;
        End If; 
            Else
         n_errore := 0;
      End If; 

     SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                 Case When  NYA=1 Then 1
                Else n_errore
                End,
                6,
                Case
                   When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                   When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                   When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                   When n_errore = 0 And (nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null ) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                   When n_errore = 0 And s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0)<>'TSI not compliant' Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'TSI not compliant')
                   Else NULL
                End,
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_errore = 0 And NYA=0 Then 0
                        When n_errore = 0 And NYA=1 Then 1
                        When n_errore = 1  Then 0
                   End);

       p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

        Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                        When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_14: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_14;
