      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_15_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

             If n_controllo_padre = 0 Then

                      If n_ok_AP = 1
                      Then
                             If        (s_val_new_2 = 'TSI not compliant' And s_val_new_1 is null )
                                    or (s_val_new_2 is null And s_val_new_1 is not null)
                                    or (s_val_new_2 = 'TSI compliant' And s_val_new_1 is not null)
                             Then
                               n_errore := 0;
                             Else
                               n_errore := 1;
                             End If; 
