                        n_controllo_old_ok_1,
                         Case
                                When n_controllo_padre = 1 Then 1
                                When NYA=0 Then 0
                                When NYA=1 Then 1
                           End);

                           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)

               Elsif n_controllo_padre = 3 Then            --fallisce il secondo padre

                SetControlDetails (
