                           End);

                SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When  NYA=1 Then 1
                                When n_controllo_padre = 1 Then 1
                        Else 0
                        End,
                        15,                 --fallito padre                   --splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                        GetMessFallitoPadreSingolo(107),---------------------------------------------------------------->''Necessità disattivazione dispositivo sabbiatura''
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_controllo_padre = 1 Then 1
                                When NYA=0 Then 0
                                When NYA=1 Then 1
                           End);

                           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)

              Elsif n_controllo_padre = 2 Then       --fallisce il primo padre

                SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When  NYA=1 Then 1
                                When n_controllo_padre = 1 Then 1
                        Else 0
                        End,
                        14,                 --fallito padre
                        GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_controllo_padre = 1 Then 1
                                When NYA=0 Then 0
                                When NYA=1 Then 1
                           End);

                           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)

             Elsif n_controllo_padre = 3 Then       --fallisce il secondo padre

                SetControlDetails (
                        n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When  NYA=1 Then 1
                                When n_controllo_padre = 1 Then 1
                        Else 0
                        End,
                        14,                 --fallito padre
                        GetMessFallitoPadreSingolo(107),---------------------------------------------------------------> ''Necessitè disattivazione dispositivo sabbiatura''
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                         Case
                                When n_controllo_padre = 1 Then 1
                                When NYA=0 Then 0
                                When NYA=1 Then 1
                           End);

                           p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
               End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_7_16: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_16;
--
-- ------------------------------------------------------------------------------------------------
--                            Procedure SET_1_1_1_3_7_17 - Quantità massima di sabbia
--               1.1.1.3.7.17 (106)  AP+CORRELAZIONE con altro parametro
-- Parametro Modificato con il Reg.777/2019
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” è 
-- [circuito di binario].
-- Quando il parametro 1.1.1.1.2.5 – Velocità massima della linea è = 140 il valore di questo parametro
-- deve essere [Conforme alla STI quando la velocità è minore di 140 km/h];
-- Quando il parametro 1.1.1.1.2.5 – Velocità massima della linea è = 140 il valore di questo parametro
-- deve essere [Conforme alla STI quando la velocità è minore di 140 km/h];
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_7_17 (n_controllo       In     Number,
                             id_sol            In     Varchar2,
                             id_sol_track      In     Varchar2,
                             id_dtp            In     Varchar2,
                             n_controllo_padre In     Number,
                             p_error_split     Out    Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);    -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_Errore
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
	  n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);  
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.17');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_17', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--
      NYA:= GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_17_AP', id_sol_track);
--
--    parametro 1.1.1.3.7.1.1 - Tipo di Sistema di rilevamento del treno
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
--    parametro 1.1.1.1.2.5 - Velocità massima della linea
      s_val_new_3 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_1_2_5', id_sol_track);
--
      n_ok_AP := GetCorrectAP(s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
		        n_ok_dominio := 1;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
/*
                     If (Nvl(s_val_new_2, 0) = 'Track circuit' And s_val_new_1 Is Null )
                         or (s_val_new_2 Is Null And s_val_new_1 Is Not Null )
                         or (Nvl(s_val_new_2, 0) <> 'Track circuit' And s_val_new_1 Is Not Null )    --18/05/2016. aggiunto per irrobustire codice
                     Then n_errore := 0;
                     Else n_errore := GetCorrectValue (n_parametro, s_val_new_1);
                     End If; 
*/
                     If ((s_val_new_2 = GetCodValueFromXML(322, '10') And s_val_new_3 <= 140 And s_val_new_1 = '10') Or 
                         (s_val_new_2 = GetCodValueFromXML(322, '10') And s_val_new_3 > 140 And s_val_new_1 = '30') Or 
						 (s_val_new_2 <> GetCodValueFromXML(322, '10') And s_val_new_1 Is Null ) Or
						 (s_val_new_2 Is Null And s_val_new_1 Is Null ) ) Then   -- AGGIUNTO IL 22/10/2021
                          n_errore := 1;
                     Else n_errore := 0;
                     End If; 
                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_errore = 0 And nvl(s_val_new_2, 0) = 'Track circuit' And s_val_new_1 Is Null Then 'Se '||GetParametro(322, 'Rilevamento Treno')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null Then 'Se '||GetParametro(322, 'Rilevamento Treno')||' è non applicabile, il parametro non deve essere valorizzato'
                          When n_errore = 0 And nvl(s_val_new_2, 0) <> 'Track circuit' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(322, 'Rilevamento Treno')||' è  diverso da'||GetValueFromCode (322, 'Track circuit')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_3 <= 140 and s_val_new_1 <> 10 Then 'Quando il parametro '||GetParametro(17, 'vel. max linea')||'  è <= 140 il valore di questo parametro deve essere ['||GetValueFromCode (106, '10')||']'
                          When n_errore = 0 And s_val_new_3 > 140 and s_val_new_1 <> 30 Then 'Quando il parametro '||GetParametro(17, 'vel. max linea')||' è > 140 il valore di questo parametro deve essere ['||GetValueFromCode (106, '30')||']'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And  NYA = 0 Then 0
                          When n_errore = 0 And  NYA = 1 Then 1
                          When n_errore = 1              Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore+1, 2);      
--
      Elsif n_controllo_padre = 1 Then        --falliscono entrambi i padri

           SetControlDetails  (
				     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     21,                 --fallito padre - splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(322),------------------------------------------------------------------->''Tipo di sistema di rilevamento del Treno''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
           SetControlDetails 
				  (  n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     15,                 --fallito padre                   --splittato messaggio come da richesta Schillaci 18/05/2016 (due distinte righe di errore)
                     GetMessFallitoPadreSingolo(17),------------------------------------------------------------------->''Velocità Massima consentita sulla linea''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
-- fallisce il primo padre
      Elsif n_controllo_padre = 2 Then                      

           SetControlDetails 
			(        n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Tipo di sistema di rilevamento del Treno''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                
--    fallisce il secondo padre
      Elsif n_controllo_padre = 3 Then            
--
           SetControlDetails 
			    (    n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(17),---------------------------------------------------------------> ''Velocità Massima consentita sulla linea''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
	       p_error_split := 1;  
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_17 - Errore: ' || Substr(Sqlerrm, 1, 250));
 End SET_1_1_1_3_7_17;
--
-- ------------------------------------------------------------------------------------------------
--                                 Procedure SET_1_1_1_3_7_18
--  1.1.1.3.7.18 Necessità di disattivazione del dispositivo di sabbiatura ad opera del macchinista
-- Controlli:  AP+DOMINIO+CORRELAZIONE
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” 
-- è [circuito di binario]. Questo parametro, se applicabile, deve essere valorizzato [S].
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_7_18 (n_controllo       In Number,
                               id_sol            In Varchar2,
                               id_sol_track      In Varchar2,
                               id_dtp            In Varchar2,
                               n_controllo_padre In Number,
                               p_error_split    Out Number  )     Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                      Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.18');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_18', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_18_AP', id_sol_track);
--
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                n_ok_dominio := 1;
           Else  
			    n_ok_dominio := 0;
           End If; 

           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If ( s_val_new_2 = 'Track circuit' And s_val_new_1 Is Null ) 
                       Or (Nvl(s_val_new_2, 0) <> 'Track circuit' And s_val_new_1 Is Not Null )
                       Or (s_val_new_2 = 'Track circuit' And nvl(s_val_new_1, 0) <> 'Y' )
                     Then
                       n_errore := 0;
                     Else
                       n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And  s_val_new_2 = 'Track circuit' And s_val_new_1 Is Null Then 'Se '||GetParametro(322, 'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And (Nvl(s_val_new_2, 0) <> 'Track circuit' And s_val_new_1 Is Not Null ) Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Track circuit')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 = 'Track circuit' And Nvl(s_val_new_1, 0)<> 'Y' Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere valorizzata '||GetValueFromCode (n_parametro, 'Y')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1              Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split :=1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_18 - Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_3_7_18;
--
-- ------------------------------------------------------------------------------------------------
--                                 Procedure SET_1_1_1_3_7_19  (108)
-- 1.1.1.3.7.19 Conformità alla STI delle Norme sulle caratteristiche della sabbia AP+DOMINIO+CORRELAZIONE
-- Il parametro è applicabile quando il valore del parametro 1.1.1.3.7.1.1 “Tipo di sistema di localizzazione dei treni” 
-- è [circuito di binario]. Questo parametro, se applicabile, deve essere valorizzato [Conforme alla STI]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_7_19 (n_controllo       In Number,
                              id_sol            In Varchar2,
                              id_sol_track      In Varchar2,
                              id_dtp            In Varchar2,
                              n_controllo_padre In Number,
                              p_error_split    Out Number)      Is
      n_parametro             Number;
      s_val_new_1             Varchar2 (1000);
      s_val_new_2             Varchar2 (1000);
      s_val_old_ok_1          Varchar2 (1000);
      s_val_new_AP            Varchar2 (1000);
      n_ok_AP                 Number;                      -- variabile appoggio applicabilità 0/1
      n_ok_dominio            Number;                      -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1    Number;
      n_errore                Number;
      d_definizione           Varchar2 (1000);
      s_stringa_dominio       Varchar2 (1000);             -- stringa concatenata del dominio
      NYA                     Number;                      -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2          Varchar2 (1000);  -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.7.19');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_19', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_19_AP', id_sol_track);
--
      s_val_new_2:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_7_1_1', id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
