           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_7_19 - Errore: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_7_19;
