-- ------------------------------------------------------------------------------------------------
--                  Procedure SET_1_1_1_3_8_2 (123)
-- 1.1.1.3.8.2 Esistenza di commutazione tra sistemi radio diversi - Modificato dal Reg.2019/777
-- Il parametro è applicabile quando nella sezione di linea sono presenti almeno due sistemi radio diversi e la commutazione da
-- un sistema all’altro viene effettuata in movimento, determinando un’inaccessibilità temporanea al servizio di comunicazione.
-- Controllo:  AP+DOMINIO - Questo parametro deve essere sempre valorizzato a [N], ad eccezione dei seguenti casi:
-- Sezione di Linea “TARVISIO BOSCOVERDE” - “CONFINE DI STATO” - TR0501 (TR0501-BC-BC01 e TR0501-BC-BC02)
-- Sezione di linea priva di segnale GSM-R (1.1.1.3.3.8 = [Sì]) che si dirama da una linea con segnale GSM-R (1.1.1.3.3.8 = [No]).
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_8_2 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.8.2');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_8_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_8', id_sol_track);
--      s_val_new_3:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_3_8', id_sol_track_diramata);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_8_2_AP', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then 
			    n_ok_dominio := 1; 
		   Else 
		        n_ok_dominio := 0;
           End If; 
--
/****  modifica del 19/07/2021 a seguito delle osservazione contenute nella mail di Piantedosi del 09/07/2021
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If (s_val_new_1 Is Null Or s_val_new_1 = 'N') Then 
					      n_errore := 1;
                     Elsif (s_val_new_1 = 'Y' And id_sol = 'TR0501')
--					    Or (s_val_new_2 = 'Y' And s_val_new_1 = 'N' ) -- AGGIUNGERE il controllo sulla diramata  s_val_new_3 = 'N'
						 Then   
						  n_errore := 1;
                     Else 
						  n_errore := 0;
                     End If; 

                Else n_errore := 0;
                End If; 
           Else n_errore := 0;
           End If; 
***/
           n_errore := n_ok_dominio;

--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     12,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
--                          When n_errore = 0 And ((id_sol = 'TR0501') /*Or (s_val_new_2 = 'Y' And s_val_new_1 = 'N' )*/) Then 'Il parametro deve essere valorizzato con [S]'
--                          When n_errore = 0 And  s_val_new_1 = 'Y'  Then 'Il parametro deve essere valorizzato con [N]'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                              -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
--                    GetMessFallitoPadreSingolo(314),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_8_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_8_2;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
 PROCEDURE SET_1_1_1_3_9_1 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
    --1.1.1.3.9.1 Norme campi mag. AP+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

       n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.9.1');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_9_1',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_9_1_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

          If n_controllo_padre = 0 Then

                       If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
                      Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                      Then n_ok_dominio := 1;
                      End If; 

                      If n_ok_AP = 1
                      Then
                            If n_ok_dominio = 1
                             Then
                                    If         (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null )
                                            or (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0)<>'TSI compliant' )
                                            or (s_val_new_2 = 'Track circuit' And s_val_new_1 is not null )
                                           --or (s_val_new_2 = 'Track circuit' And s_val_new_1 is null )
                                            --or (s_val_new_2 = 'Track circuit' And nvl(s_val_new_1,0)<>'TSI compliant' )
                                    Then
                                        n_errore := 0;
                                    Else
                                        n_errore := 1;
                                    End If; 
                            Else
                                n_errore := 0;
                            End If; 
                         Else
                         n_errore := 0;
                      End If; 

                      SetControlDetails (
                                n_controllo,
                                id_sol,
                                id_sol_track,
                                n_parametro,
                                d_definizione,
                                 Case When  NYA=1 Then 1
                                Else n_errore
                                End,
                                6,
                                Case
                                   When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                                   When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                                   When n_errore = 0 And  s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                                   When n_errore = 0 And s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0)<>'TSI not compliant' Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato '||GetValueFromCode (n_parametro, 'TSI compliant')
                                   When n_errore = 0 And s_val_new_2 = 'Track circuit' And s_val_new_1 is not null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                                   --When n_errore = 0 And  s_val_new_2 = 'Track circuit' And s_val_new_1 is null Then 'Se presente '||GetValueFromCode (322, 'Track circuit')||', la voce deve essere valorizzata'
                                   --When n_errore = 0 And s_val_new_2 = 'Track circuit' And nvl(s_val_new_1,0)<>'TSI not compliant' Then 'Se presente '||GetValueFromCode (322, 'Track circuit')||', la voce deve essere valorizzata '||GetValueFromCode (n_parametro, 'TSI compliant')
                                   Else NULL
                                End,
                                s_val_new_1,
                                s_val_old_ok_1,
                                n_controllo_old_ok_1,
                                Case
                                        When n_errore = 0 And NYA=0 Then 0
                                        When n_errore = 0 And NYA=1 Then 1
                                        When n_errore = 1  Then 0
                                   End);

                        p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

            Else  SetControlDetails (
                    n_controllo,
                    id_sol,
                    id_sol_track,
                    n_parametro,
                    d_definizione,
                    Case When  NYA=1 Then 1
                            When n_controllo_padre = 1 Then 1
                    Else 0
                    End,
                    14,                 --fallito padre
                    GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                    s_val_new_1,
                    s_val_old_ok_1,
                    n_controllo_old_ok_1,
                     Case
                            When n_controllo_padre = 1 Then 1
                            When NYA=0 Then 0
                            When NYA=1 Then 1
                       End);

                       p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
           End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_9_1: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_9_1;
--
-- ------------------------------------------------------------------------------------------------
--
-- ------------------------------------------------------------------------------------------------
--
PROCEDURE SET_1_1_1_3_9_2 (n_controllo    IN     Number,
                                 id_sol         IN     Varchar2,
                                 id_sol_track   IN     Varchar2,
                                 id_dtp         IN     Varchar2,
                                 n_controllo_padre IN Number,
                                 p_error_split          OUT Number)
       IS
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            --variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                           --variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio Varchar2 (1000);                      --stringa concatenata del dominio
      NYA Number;                       --ritorna se è NYA = 1 o 0
      s_val_old_ok_2            Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri

       BEGIN
     --1.1.1.3.9.2 Limiti armoniche AP+DOMINIO+CORRELAZIONE

      p_error_split :=0;         --l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      n_controllo_old_ok_1:=GetCorrectControlId(id_sol);    --Recupero il codice del controllo del dato pubblicato
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     --Recupero la definizione dell'oggetto

       n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.9.2');

      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_9_2',id_sol_track, s_val_new_1,s_val_old_ok_1) ;

      NYA:= GetNYA (n_parametro);

      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_9_2_AP',id_sol_track);

      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_7_1_1',id_sol_track);

      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

      If n_controllo_padre = 0 Then

      If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
      Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
      Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
      Then n_ok_dominio := 1;
      End If; 

      If n_ok_AP = 1
      Then
         If n_ok_dominio = 1
            Then
             If          (s_val_new_2 = 'Track circuit' And s_val_new_1 is null )
                      or (s_val_new_2 = 'Wheel detector' And s_val_new_1 is null )
                      or (nvl(s_val_new_2,0) <> 'Track circuit' And nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null)
                      or (s_val_new_2 = 'Track circuit' And nvl(s_val_new_1,0)<>'TSI compliant' /*And nvl(s_val_new_1,0)<>'none' */)
                      or (s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0)<>'TSI compliant' /*And nvl(s_val_new_1,0)<>'none' */)
             Then  n_errore := 0;
             Else   n_errore := 1;
             End If; 
          Else
             n_errore := 0;
          End If; 
            Else
         n_errore := 0;
      End If; 

      SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                 Case When  NYA=1 Then 1
                Else n_errore
                End,
                6,
                Case
                   When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                   When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                   When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                   When n_errore = 0 And s_val_new_2 = 'Track circuit' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere valorizzato'
                   When n_errore = 0 And s_val_new_2 = 'Wheel detector' And s_val_new_1 is null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere valorizzato'
                   When n_errore = 0 And nvl(s_val_new_2,0) <> 'Track circuit' And nvl(s_val_new_2,0) <> 'Wheel detector' And s_val_new_1 is not null Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' non è '||GetValueFromCode (322, 'Track circuit')||' o '||GetValueFromCode (322, 'Wheel detector')||', il parametro non deve essere valorizzato'
                   When n_errore = 0 And s_val_new_2 = 'Track circuit' And nvl(s_val_new_1,0)<>'TSI compliant' /*And nvl(s_val_new_1,0)<>'none' */Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Track circuit')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'TSI compliant')--||' o Nessuno'--||GetValueFromCode (n_parametro, 'none')
                   When n_errore = 0 And s_val_new_2 = 'Wheel detector' And nvl(s_val_new_1,0)<>'TSI compliant' /*And nvl(s_val_new_1,0)<>'none' */Then 'Se '||GetParametro(322,'Tipo di sistema di rilevamento dei treni')||' è '||GetValueFromCode (322, 'Wheel detector')||', il parametro deve essere '||GetValueFromCode (n_parametro, 'TSI compliant')--||' o Nessuno'--||GetValueFromCode (n_parametro, 'none')
                   Else NULL
                End,
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                Case
                        When n_errore = 0 And NYA=0 Then 0
                        When n_errore = 0 And NYA=1 Then 1
                        When n_errore = 1  Then 0
                   End);

                    p_error_split:=MOD(n_errore+1, 2);                               --siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio

        Else  SetControlDetails (
                n_controllo,
                id_sol,
                id_sol_track,
                n_parametro,
                d_definizione,
                Case When  NYA=1 Then 1
                        When n_controllo_padre = 1 Then 1
                Else 0
                End,
                14,                 --fallito padre
                GetMessFallitoPadreSingolo(322),---------------------------------------------------------------> ''Sistema Localizzazione Treni''
                s_val_new_1,
                s_val_old_ok_1,
                n_controllo_old_ok_1,
                 Case
                        When n_controllo_padre = 1 Then 1
                        When NYA=0 Then 0
                        When NYA=1 Then 1
                   End);

                   p_error_split :=1;                        --in p_error 1 è errato (al contrario di n_errore)
       End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_9_2: ' || Substr (Sqlerrm, 1, 250));
   End SET_1_1_1_3_9_2;
--
-- ------------------------------------------------------------------------------------------------
--                     Procedure SET_1_1_1_3_10_1  (77)
-- 1.1.1.3.10.1 Livello ETCS per situazioni degradate - Controlli: AP+DOMINIO+CORRELAZIONE
-- Il parametro non è applicabile quando il parametro 1.1.1.3.2.1 sia valorizzato con [N].
-- Non deve essere ammesso un valore diverso da [nessuno], [0], [1], [2], [3] o [NTC].
-- Il livello ETCS in condizioni degradate di cui al presente campo 1.1.1.3.10.1 deve essere inferiore
-- al livello ETCS di cui al campo 1.1.1.3.2.1.
-- ------------------------------------------------------------------------------------------------
--
   Procedure SET_1_1_1_3_10_1 (n_controllo       In Number,
                               id_sol            In Varchar2,
                               id_sol_track      In Varchar2,
                               id_dtp            In Varchar2,
                               n_controllo_padre In Number,
                               p_error_split    Out Number  )      Is
      n_parametro              Number;
      s_val_new_1              Varchar2 (1000);
      s_val_new_2              Varchar2 (1000);
      s_val_old_ok_1           Varchar2 (1000);
      s_val_new_AP             Varchar2 (1000);
      n_ok_AP                  Number;                           -- variabile appoggio applicabilità 0/1
      n_ok_dominio             Number;                           -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1     Number;
      n_errore                 Number;
      d_definizione            Varchar2 (1000);
      s_stringa_dominio        Varchar2 (1000);                  -- stringa concatenata del dominio
      NYA                      Number;                           -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2           Varchar2 (1000); --serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.10.1');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_10_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA := GetNYA (n_parametro);
--
      s_val_new_AP:= GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_10_1_AP', id_sol_track);
--
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP
                Then n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP
                Then n_ok_dominio := 1;
           End If; 
--
           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If   (s_val_new_2 = 'N' And s_val_new_1 Is Not Null )
                      Or  (s_val_new_2 = '1' And s_val_new_1 = '1')
                      Or  (s_val_new_2 = '1' And s_val_new_1 = '2')
                      Or  (s_val_new_2 = '1' And s_val_new_1 = '3')
                      Or  (s_val_new_2 = '2' And s_val_new_1 = '2')
                      Or  (s_val_new_2 = '2' And s_val_new_1 = '3')
                      Or  (s_val_new_2 = '3' And s_val_new_1 = '3')
                          Then  n_errore := 0;
                          Else  n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And  s_val_new_2 = 'N' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(83,'Livello ETCS')||' è '||GetValueFromCode (83, 'N')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And (s_val_new_2 = '1' And s_val_new_1 = '1' ) Then GetParametro(n_parametro, 'Livello ETCS degradato')||' deve essere inferiore a '||GetParametro(83,'Livello ETCS')
                          When n_errore = 0 And (s_val_new_2 = '1' And s_val_new_1 = '2' ) Then GetParametro(n_parametro, 'Livello ETCS degradato')||' deve essere inferiore a '||GetParametro(83,'Livello ETCS')
                          When n_errore = 0 And (s_val_new_2 = '1' And s_val_new_1 = '3' ) Then GetParametro(n_parametro, 'Livello ETCS degradato')||' deve essere inferiore a '||GetParametro(83,'Livello ETCS')
                          When n_errore = 0 And (s_val_new_2 = '2' And s_val_new_1 = '2' ) Then GetParametro(n_parametro, 'Livello ETCS degradato')||' deve essere inferiore a '||GetParametro(83,'Livello ETCS')
                          When n_errore = 0 And (s_val_new_2 = '2' And s_val_new_1 = '3' ) Then GetParametro(n_parametro, 'Livello ETCS degradato')||' deve essere inferiore a '||GetParametro(83,'Livello ETCS')
                          When n_errore = 0 And (s_val_new_2 = '3' And s_val_new_1 = '3' ) Then GetParametro(n_parametro, 'Livello ETCS degradato')||' deve essere inferiore a '||GetParametro(83,'Livello ETCS')
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case 
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(83),---------------------------------------------------------------> ''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_10_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_10_1;
--
-- ------------------------------------------------------------------------------------------------
--              Procedure SET_1_1_1_3_10_2 (78) - Parametro MODIFICATO
-- 1.1.1.3.10.2 - CLD_OtherProtectControlWarn - Altri sistemi di protezione, controllo e allerta in caso di situazioni degradate
-- Il parametro è applicabile quando il parametro 1.1.1.3.10.1 sia valorizzato con [nessuno].
-- Non deve essere ammesso un valore diverso da [Nessuno] e [RSDD/SCMT] (prima era S/N)
-- 1.1.1.3.10.2 Altri sistemi degr. - Controlli:  AP+DOMINIO+CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_10_2 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )    Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN

--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato: è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);    
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.10.2');
--
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_3_10_2', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_10_2_AP', id_sol_track);
--
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_10_1', id_sol_track);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then
           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                n_ok_dominio := 1;
		   Else 
                n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1  Then
                If n_ok_dominio = 1 Then
                     If  (s_val_new_2 = 'none' And s_val_new_1 Is Null )
                      Or (Nvl(s_val_new_2, 0) <> 'none' And s_val_new_1 Is Not Null )
                      Or (s_val_new_2 Is Null And s_val_new_1 Is Not Null)
                          Then  n_errore := 0;
                          Else  n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2 = 'none' And s_val_new_1 Is Null Then 'Se '||GetParametro(77, 'Livello ETCS degradato')||' è '||GetValueFromCode (77, 'none')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2, 0) <> 'none' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(77, 'Livello ETCS degradato')||' è diverso da '||GetValueFromCode (77, 'none')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null Then 'Se '||GetParametro(77, 'Livello ETCS degradato')||' è non applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               

      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(77),--------------------------------------------------------------->''Livello ETCS degradato''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_10_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_3_10_2;
--
-- ------------------------------------------------------------------------------------------------
--          PROCEDURE SET_1_1_1_3_11_1  (80) Modificata dal Reg.777/2019 - sempre applicabile - NCT
-- 1.1.1.3.11.1 Distanza Massima di frenatura richiesta in m (DOMINIO + CORRELAZIONE) [NNNNN]
-- Il parametro può assumere i soli valori: [800], [1000], [1200], [2700], [4050], [5400], [12000]
-- Se il parametro 1.1.1.3.2.1 Livello ETCS assume il valore “2” il parametro deve essere valorizzato con [12000]
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_11_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )  Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                     -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                     -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);            -- stringa concatenata del dominio
      NYA                    Number;                     -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);            -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato 
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.11.1');
--    acquisisce il valore attuale e il precedente dalla tabella Rinf_Lavorazione_Evo.BINARI_CORSA_SOL
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_11_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--    acquisisce il valore del parametro 1.1.1.3.2.1 - Livello ETCS
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);
--
      If n_controllo_padre = 0 Then
--         verifica che il valore appartenga al dominio dei valori ammessi (aggiunto i valori nella tabella DOMINIO_PARAMETRO)
           n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
--			
		   If n_ok_dominio = 1 Then
                If Nvl(s_val_new_2, '0') <> '2' And s_val_new_1 Is Not Null Then
				     n_errore := 1;
				ElsIf Nvl(s_val_new_2, '0') = '2' And Nvl(s_val_new_1, 0) = 12000 Then
				     n_errore := 1;
				Else 
				     n_errore := 0;
				End if;
		   Else 
			    n_errore := 0;
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     7,
                     Case
                         When n_ok_dominio = 0 Then GetCorrectRangeString(n_parametro)
                         When n_errore = 0 And Nvl(s_val_new_2, '0') = '2' And s_val_new_1 <> 12000 Then 'Se '||GetParametro(83, 'Livello ETCS')||' è '||GetValueFromCode (83, '2')||', il parametro deve essere sempre valorizzato con 12000 m'
                         Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                         When n_errore = 0 And NYA = 0 Then 0
                         When n_errore = 0 And NYA = 1 Then 1
                         When n_errore = 1             Then 0
                     End  );
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore  +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_11_1 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_11_1;
--
-- ------------------------------------------------------------------------------------------------
--          PROCEDURE SET_1_1_1_3_11_2  Modificata dal Reg.777/2019 - sempre applicabile - NCT (332)
-- 1.1.1.3.11.2 - CBP_AddInfoAvailable - Disponibilità di informazioni supplementari da parte del GI  
-- Per questo parametro è ammesso soltanto il valore [S] AP=Y Valore=[S] - Controlli: (DOMINIO + CORRELAZIONE) - sempre applicabile
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_11_2 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                     -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                     -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);            -- stringa concatenata del dominio
      NYA                    Number;                     -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);            -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato 
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.11.2');
--    acquisisce il valore attuale e il precedente dalla tabella RINF_LAVORAZIONE_EVO.BINARI_CORSA_SOL
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_11_2', id_sol_track, s_val_new_1, s_val_old_ok_1) ;
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
      If n_controllo_padre = 0 Then
--         verifica che il valore appartenga al dominio dei valori ammessi (aggiunto i valori nella tabella DOMINIO_PARAMETRO)
           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
	                      Then 1
                          Else n_errore
                     End,
                     4,
                     Case
                          When n_errore  = 0 Then GetCorrectRangeString(n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     MessControlloSuSeStessoFallito,--------------------------------------------->Controllo su se stesso fallito
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_11_2 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_11_2;

--
-- ------------------------------------------------------------------------------------------------
--                        PROCEDURE SET_1_1_1_3_11_3 - Nuovo Parametro Reg.777/2019 (334)
-- 1.1.1.3.11.3_Documenti sulle prestazioni di frenata messi a disposizione dal GI  - NCT
-- In tutte le sezioni di linea a questo parametro deve essere attribuito il valore costante = [PGOS-IF]
-- Il parametro è applicabile quando il parametro 1.1.1.3.11.2 è valorizzato con [S]. Nel caso di RFI il parametro 1.1.1.3.11.2 è
-- sempre valorizzato con [S], pertanto il parametro è sempre applicabile.
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_11_3(n_controllo       In   Number,
                            id_sol            In   Varchar2,
                            id_sol_track      In   Varchar2,
                            id_dtp            In   Varchar2,
                            n_controllo_padre In   Number,
                            p_error_split    Out   Number  )  Is
      n_parametro           Number;
      s_val_new_1           Varchar2 (1000);
      s_val_new_2           Varchar2 (1000);
      s_val_new_appo        Varchar2 (1000);
      s_val_old_ok_1        Varchar2 (1000);
      s_val_new_AP          Varchar2 (1000);
      n_ok_AP               Number;               -- variabile appoggio applicabilità 0/1
      n_ok_dominio          Number;               -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1  Number;
      n_errore              Number;
      d_definizione         Varchar2 (1000);
      s_stringa_dominio     Varchar2 (1000);      -- stringa concatenata del dominio
      NYA                   Number;               -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2        Varchar2 (1000); 
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.11.3');
--
      GetOldNewValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_11_3', id_sol_track, s_val_new_1, s_val_old_ok_1);
dbms_output.put_line ('s_val_new_1 :'||s_val_new_1);
dbms_output.put_line ('s_val_old_ok_1 :'||s_val_old_ok_1);

--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
dbms_output.put_line ('NYA  :'||NYA );
--    acquisisce il valore del parametro 1.1.1.3.11.2 - Disponibilità di informazioni supplementari da parte del GI (S/N)
      s_val_new_2 := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_11_2', id_sol_track);
dbms_output.put_line ('s_val_new_2 :'||s_val_new_2);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_11_3_AP', id_sol_track);
dbms_output.put_line ('s_val_new_AP :'||s_val_new_AP);
--
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
dbms_output.put_line ('n_ok_AP :'||n_ok_AP);
--
      If n_controllo_padre = 0 Then
           If s_val_new_1 Is Null Then 
 		        s_val_new_appo := s_val_new_1;
		        s_val_new_1 := GetCodeFromValue (n_parametro, 'PGOS - IF');
				n_ok_dominio := 0;
dbms_output.put_line ('s_val_new_1 Is Null - n_ok_dominio = 0');
		   Else 
                If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                     n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
dbms_output.put_line ('n_ok_dominio - if - v_ok_AP:'||n_ok_dominio);
                Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                     n_ok_dominio := 1;
dbms_output.put_line ('n_ok_dominio - if - v_ko_AP:'||n_ok_dominio);
		        Else                                                                  -- (n_ok_ap = 0)
				     s_val_new_appo := s_val_new_1;
				     s_val_new_1 := GetCodeFromValue (n_parametro, 'PGOS - IF');
                     n_ok_dominio := 0;
dbms_output.put_line ('s_val_new_1 Is Not Null - n_ok_dominio = 0: '||s_val_new_appo );

                End If; 
		   End If;
dbms_output.put_line ('n_ok_dominio - end if:'||n_ok_dominio);
--
           If n_ok_dominio = 1 Then
                If  s_val_new_2 = 'Y' Then 
				     n_errore := 1;
                Else 
					 n_errore := 0;
                End If; 
           Else
                     n_errore := 1;
           End If; 
dbms_output.put_line ('n_errore:'||n_errore);
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2 = 'Y' And s_val_new_1 Is Null Then 'Se '||GetParametro(332, 'Informazioni Supplementari')||' è '||GetValueFromCode (322, 'Y')||', il parametro deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2, 'N') = 'N' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(332, 'Informazioni Supplementari')||' è diverso da '||GetValueFromCode (322, 'Y')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null Then 'Se '||GetParametro(332, 'Informazioni Supplementari')||' è non applicabile, il parametro non deve essere valorizzato'
                          Else Null
                     End,
                     Case When n_ok_dominio = 0 
					      Then s_val_new_appo
                          Else s_val_new_1
                     End,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--				 
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(332),--------------------------------------------------------------->''Disponibilità informazioni supplementari da parte del GI''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_11_3 - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_11_3;
--
-- ------------------------------------------------------------------------------------------------
--       Procedure SET_1_1_1_3_12_1  (PARAMETRO CANCELLATO)
--  1.1.1.3.12.1 Assetto variabile AP+DOMINIO+CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_3_12_1 (n_controllo       In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )     Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
   BEGIN

--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' IL CONTRARIO DI QUELLO CHE SUCCEDE NEI CONTROLLI IN N_ERRORE
      p_error_split := 0;         
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);  
--    Recupero la definizione dell'oggetto
      d_definizione:=GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1','SOL_TRACK_1_1_1_0_0_1_D',id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.12.1');
-- 
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_12_1', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
      NYA:= GetNYA (n_parametro);
--	 
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_12_1_AP', id_sol_track);
--	 
      s_val_new_2:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);
--	 
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
      If n_controllo_padre = 0 Then

           If n_ok_AP = 1 And s_val_new_AP = v_ok_AP Then 
                 n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                 n_ok_dominio := 1;
           Else 
                 n_ok_dominio := 0;
           End If; 

           If n_ok_AP = 1 Then
                If n_ok_dominio = 1 Then
                     If ((s_val_new_2 = 'N' And s_val_new_1 Is Not Null) Or (Nvl(s_val_new_2, 0) <> 'N' And s_val_new_1 Is Null)) Then 
                          n_errore := 0;
                     Else   
					      n_errore := 1;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
           Else
                n_errore := 0;
           End If; 

           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 
					      Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then  s_commento_AP_ko
                          When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then  s_commento_AP_ok
                          When n_ok_dominio = 0 Then GetCorrectRangeString (n_parametro)
                          When n_errore = 0 And s_val_new_2 = 'N' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(83,'Livello ETCS ')||' è '||GetValueFromCode (83, 'N')||', il parametro non deve essere valorizzato'
                          When n_errore = 0 And Nvl(s_val_new_2,0) <> 'N' And s_val_new_1 Is Null Then 'Se '||GetParametro(83,'Livello ETCS ')||' è diverso da '||GetValueFromCode (83, 'N')||', il parametro deve essere valorizzato'
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End  );
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------------------------->''Livello ETCS''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_3_12_1 Errore: ' || Substr(Sqlerrm, 1, 250));
   End SET_1_1_1_3_12_1;
