                 n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
           Elsif n_ok_AP = 1 And s_val_new_AP = v_ko_AP Then
                 n_ok_dominio := 1;
           Else 
                 n_ok_dominio := 0;
           End If; 

--         verifica che il valore appartenga al dominio dei valori ammessi (aggiunto i valori nella tabella DOMINIO_PARAMETRO)
--           n_errore := GetCorrectValue (n_parametro, s_val_new_1);
           n_errore := n_ok_dominio;
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
