--
-- ------------------------------------------------------------------------------------------------
--                  Procedure SET_1_1_1_4_2_MULT (338) - PAR_1_1_1_4_2_NORME_DOC
-- 1.1.1.4.2 - Documenti relativi a norme e restrizioni di natura strettamente locale messi a disposizione del GI
-- Il parametro è applicabile quando il valore del parametro 1.1.1.4.1“Esistenza di norme e restrizioni di natura strettamente
-- locale” è [S]. - Controlli: AP+DOMINIO+CORRELAZIONE
-- ------------------------------------------------------------------------------------------------
--
 Procedure SET_1_1_1_4_2_MULT(n_controllo      In Number,
                             id_sol            In Varchar2,
                             id_sol_track      In Varchar2,
                             id_dtp            In Varchar2,
                             n_controllo_padre In Number,
                             p_error_split    Out Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                     -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                     -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);            -- stringa concatenata del dominio
      NYA                    Number;                     -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);            -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI        EMPCUR;                     -- Cursore Per I Valori NEW e OLD Dei Parametri In Tabella Multipli A Parte
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0;
--    Recupero il codice del controllo del dato pubblicato 
      n_controllo_old_ok_1 := GetCorrectControlId (id_sol);  
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--    lettura codice_parametro
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.4.2');
--    legge il valore attuale e precedente dalla tabella PAR_1_1_1_4_2_NORME_DOC degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValueMultiplo('PAR_1_1_1_4_2_NORME_DOC', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_4_2', id_sol_track, valori_multipli); -- multiplo
--
--    verifica che il parametro accetti valori NYA
      NYA := GetNYA (n_parametro);
--    estrae il valore del parametro: 1.1.1.4.1_Esistenza di norme e restrizioni di natura strettamente locale (S/N)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_4_1', id_sol_track);
--
      s_val_new_AP := GetParameterValue ('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_4_2_AP', id_sol_track);
--
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;

      If n_controllo_padre = 0 Then
--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
--> loop
		     Loop
--              verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
                n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);               

                If ((n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Or (n_ok_AP = 1 And s_val_new_AP = v_ko_AP)) Then
                     n_ok_dominio := 1;
		        Else 
                     n_ok_dominio := 0;
                End If; 
--              
                If n_ok_AP = 1  Then
                     If n_ok_dominio = 1 Then
                          If  (s_val_new_2 = 'Y' And s_val_new_1 Is Null ) Or (Nvl(s_val_new_2, 'N') <> 'Y' And s_val_new_1 Is Not Null )
                               Or (s_val_new_2 Is Null And s_val_new_1 Is Not Null) Then
                               n_errore := 0;
                          Else n_errore := 1;
                          End If; 
                     Else
                          n_errore := 0;
                     End If; 
                Else
                     n_errore := 0;
                End If; 
--
                SetControlDetails (
                          n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
	                           Then 1
                               Else n_errore
                          End,
                          4,
                          Case
                               When n_ok_AP = 0 And s_val_new_AP = v_ko_AP  Then s_commento_AP_ko
                               When n_ok_AP = 0 And s_val_new_AP = v_ok_AP  Then s_commento_AP_ok
                               When n_errore = 0 And s_val_new_2 = 'Y' And s_val_new_1 Is Null Then 'Se '||GetParametro(336, 'norme e restrizioni')||' è '||GetValueFromCode (336, 'Y')||', il parametro deve essere valorizzato'
                               When n_errore = 0 And Nvl(s_val_new_2, 'N') <> 'Y' And s_val_new_1 Is Not Null Then 'Se '||GetParametro(336, 'norme e restrizioni')||' è diverso da '||GetValueFromCode (336, 'Y')||', il parametro non deve essere valorizzato'
                               When n_errore = 0 And s_val_new_2 Is Null And s_val_new_1 Is Not Null Then 'Se '||GetParametro(336, 'norme e restrizioni')||' è non applicabile, il parametro non deve essere valorizzato'
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case
                               When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1             Then 0
                          End  );
--              siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
                p_error_split := Mod(n_errore +1, 2);                               
-->             
                Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                Exit When VALORI_MULTIPLI%NotFound;
--> end loop 		 
             End Loop;
--			  
--         Se NO DATA FOUND
           Else 
                If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then          -- Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then      -- Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If; 
                     SetControlDetails
					  (   n_controllo,
                          id_sol,
                          id_sol_track,
                          n_parametro,
                          d_definizione,
                          Case When NYA = 1 
						       Then 1
                               Else n_errore
                          End,
                          12,
                          Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP 
						       Then s_commento_AP_ok
                               Else Null
                          End,
                          s_val_new_1,
                          s_val_old_ok_1,
                          n_controllo_old_ok_1,
                          Case When n_errore = 0 And NYA = 0 Then 0
                               When n_errore = 0 And NYA = 1 Then 1
                               When n_errore = 1  Then 0
                          End	  );
           End If; 
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                            -- fallito padre
                     GetMessFallitoPadreSingolo(336),--------------------------------------------------------------->''Esistenza di Norme e Restrizioni''
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End  );
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                        
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('SET_1_1_1_4_2_MULT - Errore: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_4_2_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                           PROCEDURE SetControlSOLTrackINF 
--                   procedura per il controllo dei parametri INF di SOL TRACK 
-- ------------------------------------------------------------------------------------------------
--
 Procedure SetControlSOLTrackINF (n_controllo    In     Number,    
                                  id_sol         In     Varchar2,
                                  id_sol_track   In     Varchar2,
                                  id_dtp         In     Varchar2,
                                  p_error       Out     Number )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_new_5            Varchar2 (1000);
      s_val_new_6            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;          -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;          -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      l_lungh                Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
--    stringa concatenata del dominio
      s_stringa_dominio      Varchar2 (1000);   
--    minimo del gradiente	  
      min_gradiente          Number;                              
--    ritorna se è NYA = 1 o 0
      NYA                    Number;                               
--    CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      VALORI_MULTIPLI        EMPCUR;       
--    serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      CONTA_MULTIPLO         Number;       
      CONTA_MULTIPLO_2       Number;
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2         Varchar2 (1000); 
--    serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000); 
--    serve per recuperare i valori D dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_4         Varchar2 (1000); 
--    usato per il gradiente per evitare di far scrivere tante righe di errore delle livellette
      n_errore_totale        Number;          
--    serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)
      p_error_split          Number;          
      p_error_1_1_1_1_2_1    Number;       
--      p_error_1_1_1_1_2_5    Number;       --variabile trasversale tra più classi di controlli, quindi definita a cappello del package
      p_error_1_1_1_1_4_1    Number;
--
--    variabile di appoggio per valutare più padri contemporaneamente
      p_error_1_1_1_1_2_4_MULT_I Number;
      p_error_UNION              Number;                     
      p_error_1_1_1_1_3_1        Number;
      p_error_1_1_1_1_3_2        Number;
      p_error_1_1_1_1_3_3        Number;
      p_error_1_1_1_1_3_4_MULT_I Number;
      p_error_1_1_1_1_3_5_MULT_I Number;
      p_error_1_1_1_1_7_2        Number;
      p_error_1_1_1_1_7_4        Number;
      p_error_1_1_1_1_7_5        Number;
-- ---------------------------------------
   BEGIN
      p_error := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
-- 1.1.1.0.0.1 ID binario SOL                       - OBBLIGATORIO
-- 1.1.1.0.0.2  Normale direzione di marcia DOMINIO - OBBLIGATORIO spostato nella procedura SetControlSOLTrackObl dei controlli comuni a Regular Sol e Link
--
-- ------------------------------------------------
--           Controllo Parametri INFRASTRUTTURA 
-- -------------------------------------------------
--
-- 1.1.1.1.2.5 V max DOMINIO IN RANGE
-- Il Controllo Sulla Velocita' È Messo Come Primo Perche Padre Di Altri Parametri Precedenti A Lui
      SET_1_1_1_1_2_5 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);         
	  p_error_1_1_1_1_2_5 := p_error_split;
--
-- 1.1.1.1.4.1 Scartamento nominale = 1435 mm DOMINIO                   
-- Il Controllo Sullo Scartamento È Messo Come Secondo Perche Padre Di Altri Parametri Precedenti A Lui
       SET_1_1_1_1_4_1 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);        
	   p_error_1_1_1_1_4_1 := p_error_split;
--
-- 1.1.1.1.1.1  Dichiarazione INF EC FORMATO E APP - parametro con tabella multipla a parte
     SET_1_1_1_1_1_1 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_4_1, p_error_split);
--
-- 1.1.1.1.1.2  Dichiarazione INF EI FORMATO E APP - parametro con tabella multipla a parte
     SET_1_1_1_1_1_2 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
-- 1.1.1.1.2.1  TEN class binari DOMINIO - parametro con tabella multipla a parte
     SET_1_1_1_1_2_1 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
	 p_error_1_1_1_1_2_1 := p_error_split;
--
-- 1.1.1.1.2.1.2 -  IPP_TENGISID - Identità del sistema informativo geografico (GIS ID) TEN  -  Nuovo parametro - Reg.777/2019 
--     SET_1_1_1_1_2_1_2 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_2_1, p_error_split);                   ----> disattivato fino a quando non verranno forniti i dati da PIC

--
-- 1.1.1.1.2.2  Categoria Linea DOMINIO + APPLICABILITA' - parametro con tabella multipla a parte
     SET_1_1_1_1_2_2 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);                     
	 p_error_1_1_1_1_2_2 := p_error_split;
--
-- 1.1.1.1.2.3 Corridoio merci APPLICABILITA'
     SET_1_1_1_1_2_3 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
-- 1.1.1.1.2.4 Capacità carico ----------> parte prima:DOMINIO  + CORRELAZIONE - parametro con tabella multipla a parte

/****          Modificato il 19/07/2021 a seguito della segnalazione con mail del 09/07/2021 di Piantedosi
-- dipende da due padri, quindi faccio la sintesi tra i due errori dei padri (se almeno uno è 1, il controllo sul figlio deve fallire)
-- modificato via tel da Schillaci 29/10/2015 p_error_UNION := GREATEST (p_error_1_1_1_1_2_2, p_error_1_1_1_1_2_5);  
     If    p_error_1_1_1_1_2_2 = 0 And p_error_1_1_1_1_2_5 = 0 Then p_error_UNION := 0;  -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
     Elsif p_error_1_1_1_1_2_2 = 1 And p_error_1_1_1_1_2_5 = 1 Then p_error_UNION := 1;  -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
     Elsif p_error_1_1_1_1_2_2 = 1 And p_error_1_1_1_1_2_5 = 0 Then p_error_UNION := 2;  -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
     Elsif p_error_1_1_1_1_2_2 = 0 And p_error_1_1_1_1_2_5 = 1 Then p_error_UNION := 3;  -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
     End If; 
***/
--
--     SET_1_1_1_1_2_4_MULT (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);           
     SET_1_1_1_1_2_4_MULT (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_2_2, p_error_split);           
--   p_error_1_1_1_1_2_4_MULT_I := p_error_split;
--
--   1.1.1.1.2.4 Capacità carico ------------> parte seconda: CORRELAZIONE - parametro con tabella multipla a parte
--   SET_1_1_1_1_2_4_MULT_II (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
    --1.1.1.1.2.4_1 
     SET_1_1_1_1_2_4_1 (n_controllo,  id_sol, id_sol_track,   id_dtp, 0, p_error_split);
--
    --1.1.1.1.2.4_2 
     SET_1_1_1_1_2_4_2 (n_controllo,  id_sol, id_sol_track,   id_dtp, p_error_1_1_1_1_2_5, p_error_split);
--
    --1.1.1.1.2.4_3
    SET_1_1_1_1_2_4_3_MULT  (n_controllo,  id_sol, id_sol_track,   id_dtp, 0, p_error_split);

    --1.1.1.1.2.4_4 Documento riportante la/le procedure per le verifiche di compatibilità statica e dinamica della tratta
     SET_1_1_1_1_2_4_4 (n_controllo,  id_sol, id_sol_track,   id_dtp, 0, p_error_split);

--   il controllo sulla velocita' 1.1.1.1.2.5 è messo come primo perche padre di altri parametri precedenti a lui

--   1.1.1.1.2.6 Campo temperatura DOMINIO
     SET_1_1_1_1_2_6 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.1.2.7 Altezza Max LUNGHEZZA max 4 digit
     SET_1_1_1_1_2_7 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.1.2.8 Cond climatiche estreme DOMINIO
     SET_1_1_1_1_2_8 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.3.1 Scart interoperabile DOMINIO + CORRELAZIONE
     SET_1_1_1_1_3_1 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);         
	 p_error_1_1_1_1_3_1 := p_error_split;
--
--    1.1.1.1.3.2 Sagome multi DOMINIO + CORRELAZIONE + APPLICABILITA'
     SET_1_1_1_1_3_2 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_3_1, p_error_split);         
	 p_error_1_1_1_1_3_2 := p_error_split;
--
--    1.1.1.1.3.3 Sagome naz DOMINIO + CORRELAZIONE + APPLICABILITA'
     SET_1_1_1_1_3_3 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_3_2, p_error_split);
	 p_error_1_1_1_1_3_3 := p_error_split;

--    1.1.1.1.3.1_1 Sagoma - DOMINIO + APPLICABILITA'
     SET_1_1_1_1_3_1_1 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.1.3.1_2  - NA
     SET_1_1_1_1_3_1_2 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.1.3.1_3 - NA'
     SET_1_1_1_1_3_1_3 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.3.4  Profilo casse mobili ----------> AP + DOMINIO + CORRELAZIONE - parametro con tabella multipla a parte
 --    SET_1_1_1_1_3_4_MULT (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_2_1, p_error_split);
     SET_1_1_1_1_3_4_MULT (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.3.5  Profilo semi rimorchi ----------> AP + DOMINIO + CORRELAZIONE - parametro con tabella multipla a parte
--     SET_1_1_1_1_3_5_MULT (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_2_1, p_error_split);
     SET_1_1_1_1_3_5_MULT (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.3.6 Gradiente - DOMINIO IN RANGE - parametro con tabella multipla a parte
     SET_1_1_1_1_3_6 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.3.7 Raggio minimo curvatura orizzontale >150m
     SET_1_1_1_1_3_7 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   N.B. IL CONTROLLO SULLO SCARTAMENTO 1.1.1.1.4.1 Scartamento nominale è MESSO COME PRIMO PERCHE PADRE DI ALTRI PARAMETRI PRECEDENTI A LUI
--
--   1.1.1.1.4.2 Insufficienza  sopraelevazione DOMINIO
     SET_1_1_1_1_4_2 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.4.3 Inclinazione rotaia  = 1:20  DOMINIO
     SET_1_1_1_1_4_3 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.4.4  Esistenza ballast DOMINIO+CORRELAZIONE+APPLICABILITA'
     SET_1_1_1_1_4_4 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_2_5, p_error_split);
--
--   1.1.1.1.5.1 Armam conforme STI  DOMINIO (solo Y)
     SET_1_1_1_1_5_1 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.5.2 Diametro minino ruote DOMINIO (unico valore unico ammissibile 330)
     SET_1_1_1_1_5_2 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.6.1 Decelerazione massima treno AP+CORRELAZIONE
     SET_1_1_1_1_6_1 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_4_1, p_error_split);
--
--   1.1.1.1.6.2 Freni correnti parassite DOMINIO (valore unico ammissibile not allowed)
     SET_1_1_1_1_6_2 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.6.3 Freni magnetici DOMINIO (valore unico ammissibile not allowed)
     SET_1_1_1_1_6_3 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.6.4  - NA 
     SET_1_1_1_1_6_4 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.6.5 - NA 
     SET_1_1_1_1_6_5 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.7.1 Lubrificazione flangia DOMINIO (deve contenere solo N)
     SET_1_1_1_1_7_1 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--   1.1.1.1.7.2 PL DOMINIO
     SET_1_1_1_1_7_2 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);         
	 p_error_1_1_1_1_7_2 := p_error_split;
--
--   1.1.1.1.7.3 Accelerazione PL AP+DOMINIO 0.0
     SET_1_1_1_1_7_3 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_2, p_error_split);
--
--   1.1.1.1.7.4_Esistenza di un sistema di rilevamento di anomalo riscaldamento boccole (RTB) a terra
     SET_1_1_1_1_7_4 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);         
	 p_error_1_1_1_1_7_4 := p_error_split;
--
--   1.1.1.1.7.5_Sistema di RTB a terra conforme a STI
     SET_1_1_1_1_7_5 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_4, p_error_split);         
	 p_error_1_1_1_1_7_5 := p_error_split;
--
--   1.1.1.1.7.6_Individuazione di sistema RTB a terra conforme a STI
     SET_1_1_1_1_7_6 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_5, p_error_split);         
--
--   1.1.1.1.7.7_ Generazione di un sistema RTB a terra
--     SET_1_1_1_1_7_7 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_4, p_error_split);         
     SET_1_1_1_1_7_7 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_5, p_error_split);         -- correzione del 19/07/2021 a seguito della segnalazione nella mail di Piantedosi
--
--   1.1.1.1.7.8_Localizzazione ferroviaria di un sistema RTB a terra
     SET_1_1_1_1_7_8_MULT (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_5, p_error_split);         
--
--   1.1.1.1.7.9_Direzione della misurazione di sistema RTB a terra [N/O/B]
     SET_1_1_1_1_7_9 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_1_7_5, p_error_split);         
--
--   1.1.1.1.7.10_Richieste luci rosse fisse [S/N]
     SET_1_1_1_1_7_10 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);         
--
--   1.1.1.1.7.11_Appartenente a una tratta meno rumorosa  [S/N]
     SET_1_1_1_1_7_11 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);         


  EXCEPTION
      When OTHERS  Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line  ('Errore - SetControlSOLTrackINF: '||Substr(Sqlerrm, 1, 250));
   End SetControlSOLTrackINF;
--
-- ------------------------------------------------------------------------------------------------
--            PROCEDURE SetControlSOLTrackENE
-- procedura per il controllo dei parametri ENE di SOL TRACK
-- ------------------------------------------------------------------------------------------------
--
 PROCEDURE SetControlSOLTrackENE (n_controllo    In  Number,   
                                  id_sol         In  Varchar2,
                                  id_sol_track   In  Varchar2,
                                  id_dtp         In  Varchar2,
                                  p_error       Out  Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_new_5            Varchar2 (1000);
      s_val_new_6            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      l_lungh                Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      s_stringa_dominio Varchar2 (1000);                       -- stringa concatenata del dominio
      min_gradiente Number;                                    -- minimo del gradiente
      NYA Number;                                              -- ritorna se è NYA = 1 o 0
      VALORI_MULTIPLI EMPCUR;                                  -- CURSORE PER I VALORI NEW E OLD DEI PARAMETRI IN TABELLA MULTIPLI A PARTE
      CONTA_MULTIPLO Number;                                   -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      CONTA_MULTIPLO_2 Number;
      s_val_old_ok_2            Varchar2 (1000); -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3            Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_4            Varchar2 (1000);   -- serve per recuperare i valori D dei concatenati e farli scrivere come stringa unica con gli altri
      n_errore_totale Number;               -- usato per il gradiente per evitare di far scrivere tante righe di errore delle livellette
      p_error_split Number;                 -- serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)
      p_error_1_1_1_2_2_1_1 Number;
      p_error_1_1_1_2_2_1_2 Number;
      p_error_1_1_1_2_4_1_1 Number;
      p_error_1_1_1_2_4_2_1 Number;
      p_error_UNION Number;
   BEGIN
      p_error := 0;
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
----  Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
--    ------------------------------------------------
--    ---------------------SSE----------------------
--    ------------------------------------------------
--    1.1.1.2.1.1  Dichiarazione ENE EC - FORMATO E APP - parametro con tabella multipla a parte
      SET_1_1_1_2_1_1 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.2.1.2  Dichiarazione ENE EI - FORMATO E APP - parametro con tabella multipla a parte
      SET_1_1_1_2_1_2 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.2.2.1.1 Tipo sistema linea contatto - DOMINIO   --NUOVO 082       LookUp Value
      SET_1_1_1_2_2_1_1 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);     
	  p_error_1_1_1_2_2_1_1 := p_error_split;
--
--    1.1.1.2.2.1.2 Sistema alimentazione elettrica - AP+DOMINIO+CORRELAZIONE     LookUp Value
      SET_1_1_1_2_2_1_2 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_2_1_1, p_error_split);      
	  p_error_1_1_1_2_2_1_2 := p_error_split;
--
      If    p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_2_1_2 = 0 Then p_error_UNION := 0;      -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_2_1_2 = 1 Then p_error_UNION := 1;      -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_2_1_2 = 0 Then p_error_UNION := 2;      -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_2_1_2 = 1 Then p_error_UNION := 3;      -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 

--    1.1.1.2.2.1.2.1 - Conformità alle STI del sistema di alimentazione elettrica (tensione nominale e frequenza)
      SET_1_1_1_2_2_1_2_1 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);  
--
--    1.1.1.2.2.1.3 - Umax2 - NA Intera Rete RFI 
      SET_1_1_1_2_2_1_3 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);      

--    1.1.1.2.2.2  Corrente max treno - AP+CORRELAZIONE
--      SET_1_1_1_2_2_2 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_2_1_1, p_error_split);
      SET_1_1_1_2_2_2 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.2.3  Corrente max pantografo - AP+CORRELAZIONE
--    modificato da Schillaci via tel 29/01/2015 p_error_UNION:=GREATEST (p_error_1_1_1_2_2_1_1,p_error_1_1_1_2_2_1_2);   -- dipende da due padri, quindi faccio la sintesi tra i due errori dei padri (se almeno uno è 1, il controllo sul figlio deve fallire)
      SET_1_1_1_2_2_3 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.2.4  Frenatura a recup. AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_2_4 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.2.5 Altezza max LCD AP+CORRELAZIONE
      SET_1_1_1_2_2_5 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.2.6 Altezza min LCD AP+CORRELAZIONE
      SET_1_1_1_2_2_6 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.1  sist alim elettr AP+DOMINIO+CORRELAZIONE
--      SET_1_1_1_2_3_1 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_2_1_1, p_error_split);
      SET_1_1_1_2_3_1 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.2  archetti accettati AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_3_2 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.3.A req.n.patografi  DOMINIO +AP         prima parte A
      SET_1_1_1_2_3_3_A (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.3.B DistMin.pantografi DOMINIO +AP                   seconda parte B
      SET_1_1_1_2_3_3_B (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.3.C Vel.riferimento DOMINIO +AP         terza parte C
      SET_1_1_1_2_3_3_C (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.3 TOTALE req.n.patografi+dist+velocità AP+CORRELAZIONE                            concatenato
      SET_1_1_1_2_3_3_TOTALE (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.3.4  archetti accettati AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_3_4 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.4.1.1 separazione fase AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_4_1_1 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);   
	  p_error_1_1_1_2_4_1_1 := p_error_split;
--
--    1.1.1.2.4.1.2.A Lunghezza separazione fase  length+AP+CORR  benchè numerico libero        prima parte A
--    eliminato da Schillaci via tel 29/10/2015 p_error_UNION:=GREATEST (p_error_1_1_1_2_2_1_1,p_error_1_1_1_2_4_1_1);   -- dipende da due padri, quindi faccio la sintesi tra i due errori dei padri (se almeno uno è 1, il controllo sul figlio deve fallire)
      If    p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_4_1_1 = 0 Then p_error_UNION := 0;       -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_4_1_1 = 1 Then p_error_UNION := 1;       -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_4_1_1 = 0 Then p_error_UNION := 2;       -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_4_1_1 = 1 Then p_error_UNION := 3;       -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 
--
      SET_1_1_1_2_4_1_2_A (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.4.1.2.B Disattivazione freno DOMINIO+AP  +CORR                   seconda parte B
      SET_1_1_1_2_4_1_2_B (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.4.1.2.C Pantografo basso DOMINIO+AP  +CORR        terza parte C
      SET_1_1_1_2_4_1_2_C (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.4.1.2 TOTALE Lunghezza separazione FASE+Disatt freno+Abbass.archetti AP+CORRELAZIONE       concatenato
      SET_1_1_1_2_4_1_2_TOTALE (n_controllo, id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.4.2.1 Separaz. sistema AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_4_2_1 (n_controllo,  id_sol, id_sol_track,   id_dtp, p_error_1_1_1_2_2_1_1, p_error_split);    
	  p_error_1_1_1_2_4_2_1 := p_error_split;
--
--    modificato da Schillaci via tel 29/10/2015  p_error_UNION:=GREATEST (p_error_1_1_1_2_2_1_1,p_error_1_1_1_2_4_2_1);    --  dipende da due padri, quindi faccio la sintesi tra i due errori dei padri (se almeno uno è 1, il controllo sul figlio deve fallire)
      If    p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_4_2_1 = 0 Then p_error_UNION := 0;     -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_4_2_1 = 1 Then p_error_UNION := 1;     -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_4_2_1 = 0 Then p_error_UNION := 2;     -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_4_2_1 = 1 Then p_error_UNION := 3;     -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 
--    Non è necessario perchè se fallisce 1.1.1.2.2.1.1 --> fallisce 1.1.1.2.4.2.1 e, quindi, 1.1.1.2.4.2.2. A,B,C,D e TOTALE
--    1.1.1.2.4.2.2.A Lunghezza separazione sist  length+AP +CORR  benchè numerico libero        prima parte A
--      SET_1_1_1_2_4_2_2_A (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
      SET_1_1_1_2_4_2_2_A (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_4_2_1, p_error_split);
--
--    1.1.1.2.4.2.2.B Disattivazione freno DOMINIO  +AP +CORR                  seconda parte B
--      SET_1_1_1_2_4_2_2_B (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
      SET_1_1_1_2_4_2_2_B (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_4_2_1, p_error_split);
--
--    1.1.1.2.4.2.2.C Pantografo basso DOMINIO  +AP +CORR        terza parte C
--      SET_1_1_1_2_4_2_2_C (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
      SET_1_1_1_2_4_2_2_C (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_4_2_1, p_error_split);
--
--    1.1.1.2.4.2.2.D Cambiamento alimentazione DOMINIO  +AP  +CORR       quarta parte D
--      SET_1_1_1_2_4_2_2_D (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
      SET_1_1_1_2_4_2_2_D (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_4_2_1, p_error_split);
--
--    1.1.1.2.4.2.2 TOTALE Lunghezza SEPARAZIONE SISTEMA+Disatt freno+Abbass.archetti+Cambiamento alimenatzione AP+CORRELAZIONE       concatenato
--      SET_1_1_1_2_4_2_2_TOTALE (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
      SET_1_1_1_2_4_2_2_TOTALE (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_2_4_2_1, p_error_split);
--
--    1.1.1.2.4.3 - NA - Intera Rete RFI
      SET_1_1_1_2_4_3 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--      
      If    p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_2_1_2 = 0 Then p_error_UNION := 0;      -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_2_1_2 = 1 Then p_error_UNION := 1;      -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_2_2_1_2 = 0 Then p_error_UNION := 2;      -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_2_2_1_2 = 1 Then p_error_UNION := 3;      -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 
--    1.1.1.2.5.1 Limitaz.cor.bordo AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_5_1 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.2.5.2 Fmc autorizzata AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_5_2 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
      If    p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_1_2_5 = 0 Then p_error_UNION := 0;      -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_1_2_5 = 1 Then p_error_UNION := 1;      -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_2_2_1_1 = 1 And p_error_1_1_1_1_2_5 = 0 Then p_error_UNION := 2;      -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_2_2_1_1 = 0 And p_error_1_1_1_1_2_5 = 1 Then p_error_UNION := 3;      -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 
--    1.1.1.2.5.3 DDA richiesto AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_2_5_3 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line ('Errore - SetControlSOLTrackENE: '||Substr(Sqlerrm, 1, 250));
   End SetControlSOLTrackENE;
--
-- ------------------------------------------------------------------------------------------------
--                                Procedure SetControlSOLTrackCCS
--                      procedura per il controllo dei parametri CCS di SOL TRACK
-- ------------------------------------------------------------------------------------------------
--
 Procedure SetControlSOLTrackCCS (n_controllo    In     Number,    
                                  id_sol         In     Varchar2,
                                  id_sol_track   In     Varchar2,
                                  id_dtp         In     Varchar2,
                                  p_error        Out    Number  )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_new_3            Varchar2 (1000);
      s_val_new_4            Varchar2 (1000);
      s_val_new_5            Varchar2 (1000);
      s_val_new_6            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      l_lungh                Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      m_min                  Number;
      m_max                  Number;
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      min_gradiente          Number;                            -- minimo del gradiente
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      VALORI_MULTIPLI        EMPCUR;                            -- Cursore Per I Valori New E Old Dei Parametri In Tabella Multipli A Parte
      CONTA_MULTIPLO         Number;                            -- serve per contare se è presente un valore di un parametro in un dominio PER I PARAMETRI A VALORE MULTIPLO
      CONTA_MULTIPLO_2       Number;
      s_val_old_ok_2         Varchar2 (1000);   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_3         Varchar2 (1000);   -- serve per recuperare i valori C dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_4         Varchar2 (1000);   -- serve per recuperare i valori D dei concatenati e farli scrivere come stringa unica con gli altri
      n_errore_totale        Number;            -- usato per il gradiente per evitare di far scrivere tante righe di errore delle livellette
      p_error_split          Number;            -- serve questa variabile di appoggio perchè se uso p_error nelle procedure splittate, mi rimane in memoria e me lo stampa come messaggio di errore di fine procedura (cioè mi mette 1 anche la rpocedura va bene e, quindi, dovrebbe essere 0)
      p_error_1_1_1_3_2_1    Number;
      p_error_1_1_1_3_2_3    Number;
      p_error_1_1_1_3_2_4    Number;
      p_error_1_1_1_3_3_1    Number;
      p_error_1_1_1_3_3_3_2  Number;
      p_error_1_1_1_3_3_6    Number;
      p_error_1_1_1_3_5_1    Number;
      p_error_UNION          Number;                            -- variabile di appoggio per valutare più padri contemporaneamente
      p_error_1_1_1_3_7_1    Number;
      p_error_1_1_1_3_7_1_1  Number;
      p_error_1_1_1_3_7_1_3  Number;
      p_error_1_1_1_3_7_1_2  Number;
      p_error_1_1_1_3_7_2_1  Number;
      p_error_1_1_1_3_10_1   Number;
      p_error_1_1_1_3_7_15_1 Number;
      p_error_1_1_1_3_7_16   Number;
      p_error_1_1_1_3_7_18   Number;
	  p_error_1_1_1_3_11_2   Number;
      n_abilitazione         Number;
--
   BEGIN
      p_error := 0;
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);    
-- -----------------------------------------------------
--  ----------------   CCS   --------------------------
-- -----------------------------------------------------
--    1.1.1.3.1.1  Dichiarazione CCS EC FORMATO E APP  (parametro con tabella multipla a parte)
      SET_1_1_1_3_1_1 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.3.2.1 Livello ETCS DOMINIO+CORRELAZIONE
      SET_1_1_1_3_2_1 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);     
      p_error_1_1_1_3_2_1 := p_error_split;
--
--    1.1.1.3.2.2 Versione base ETCS AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_2_2 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
--
--    1.1.1.3.2.3 Infill ETCS linea AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_2_3 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
      p_error_1_1_1_3_2_3 := p_error_split;
--
      If    p_error_1_1_1_3_2_1 = 0 And p_error_1_1_1_3_2_3 = 0 Then p_error_UNION := 0;      -- dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_3_2_1 = 1 And p_error_1_1_1_3_2_3 = 1 Then p_error_UNION := 1;      -- se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_3_2_1 = 1 And p_error_1_1_1_3_2_3 = 0 Then p_error_UNION := 2;      -- se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_3_2_1 = 0 And p_error_1_1_1_3_2_3 = 1 Then p_error_UNION := 3;      -- se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 
--
--    1.1.1.3.2.4 Infill ETCS terra AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_2_4 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
      p_error_1_1_1_3_2_4 := p_error_split;
--
--    1.1.1.3.2.5 Applic. naz.ETCS AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_2_5 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
--
--    1.1.1.3.2.6 Cond oper ETCS AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_2_6 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
--
--    1.1.1.3.2.7 Funz. facol.ETCS AP+CORRELAZIONE
