      If    p_error_1_1_1_3_7_1_1 = 0 And p_error_1_1_1_1_2_5 = 0 Then p_error_UNION := 0;         --dipende da due padri: se entrambi giusti, 0 così entra nel ciclo regolare del controllo
      Elsif p_error_1_1_1_3_7_1_1 = 1 And p_error_1_1_1_1_2_5 = 1 Then p_error_UNION := 1;         --se entrambi errati, 1 così entra nel ciclo di messaggio errore per emtrambi
      Elsif p_error_1_1_1_3_7_1_1 = 1 And p_error_1_1_1_1_2_5 = 0 Then p_error_UNION := 2;         --se errato il primo, 2 così entra nel ciclo di messaggio errore per il primo
      Elsif p_error_1_1_1_3_7_1_1 = 0 And p_error_1_1_1_1_2_5 = 1 Then p_error_UNION := 3;         --se errato il primo, 3 così entra nel ciclo di messaggio errore per il secondo
      End If; 
--
      SET_1_1_1_3_7_17 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_UNION, p_error_split);
--
--    1.1.1.3.7.18 Disat.sabbiatura AP+DOMINIO+CORRELAZIONE      N.B.  !!spostato prima del 16 perchè dal 18 dipende il 16
--    
--    1.1.1.3.7.19 Norme car. sabbia AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_7_19 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--    
--    1.1.1.3.7.20 Lubrific.flangia AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_7_20 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--    
--    1.1.1.3.7.21 Blocchi freno AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_7_21 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--    
--    1.1.1.3.7.22 Assistenza shunt AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_7_22 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--    
--    1.1.1.3.7.23 Norme imp.manovra AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_7_23 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--
--    1.1.1.3.8.1 Commutaz. sistemi AP+DOMINIO+CORRELAZIONE
--      SET_1_1_1_3_8_1 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
      SET_1_1_1_3_8_1 (n_controllo, id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.3.8.2 Commutaz.radio AP+DOMINIO
      SET_1_1_1_3_8_2 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
--
--    1.1.1.3.9.1 Norme campi mag. AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_9_1 (n_controllo, id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--
--    1.1.1.3.9.2 Limiti armoniche AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_9_2 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_7_1_1, p_error_split);
--
--    1.1.1.3.10.1 Liv.ETCS degr. AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_10_1 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);       
      p_error_1_1_1_3_10_1 := p_error_split;
--
--    1.1.1.3.10.2 Altri sistemi degr. AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_10_2 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_10_1, p_error_split);
--
--    1.1.1.3.11.1 Max dist. frenata DOMINIO RANGE + CORRELAZIONE
      SET_1_1_1_3_11_1 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
--
--    1.1.1.3.11.2 Disponibilità di informazioni supplementari da parte del GI - AP=Y Value=[S] - Intera Rete RFI
      SET_1_1_1_3_11_2 (n_controllo,  id_sol, id_sol_track, id_dtp, 0, p_error_split);
      p_error_1_1_1_3_11_2 := p_error_split;
--
--    1.1.1.3.11.3 Documenti sulle prestazioni di frenata messi a disposizione dal GI - AP=Y Value=[PGOS-IF] - Intera Rete RFI
      SET_1_1_1_3_11_3 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_11_2, p_error_split);
--
--    1.1.1.3.12.1 Assetto variabile AP+DOMINIO+CORRELAZIONE
      SET_1_1_1_3_12_1 (n_controllo,  id_sol, id_sol_track, id_dtp, p_error_1_1_1_3_2_1, p_error_split);
--
   EXCEPTION
      When OTHERS Then
         p_error := SQLCODE;
         Dbms_Output.Put_Line('SetControlSOLTrackCCS - Errore: '||Substr(Sqlerrm, 1, 250));
   End SetControlSOLTrackCCS;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_2_8 (294) 
--        1.1.1.3.2.8 - Conferma dell’integrità del treno a bordo necessaria per accedere alla linea (S/N)
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--       Applicabile solo se 1.1.1.3.2.1 Livello ETCS = [3] Altrimenti: NA  - NCT 
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_2_8    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.8');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_8', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_8_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.2.1 - Livello ETCS  (83)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_3_2_1 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (s_val_new_2 = '3' And s_val_new_1 Is Not Null) Or        -- Controllo con il parametro "padre" 1.1.1.3.2.1
					     (s_val_new_2 <> '3' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                      -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And s_val_new_2 <> '3' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And s_val_new_2 = '3' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And s_val_new_2 = '3') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_8: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_8;
--
-- ------------------------------------------------------------------------------------------------
--                           Procedure SET_1_1_1_3_2_9_MULT 
--            1.1.1.3.2.9_Compatibilità con il sistema ETCS  (296)
-- Questo parametro NON è applicabile quando il parametro 1.1.1.3.2.1 = [N]
-- Controllo:  AP - Dominio - Correlazione con altro parametro (6) - parametro con tabella multipla a parte PAR_1_1_1_1_7_8_LOCA_SIST_RTB - NCT 
-- il parametro, se applicabile, deve essere inserito nel formato [±NNNN.NNN]
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_2_9_MULT (n_controllo      In     Number,
                                 id_sol            In     Varchar2,
                                 id_sol_track      In     Varchar2,
                                 id_dtp            In     Varchar2,
                                 n_controllo_padre In     Number,
                                 p_error_split     Out    Number   )   Is
      n_parametro            Number;
      s_val_new_1            Varchar2 (1000);
      s_val_new_2            Varchar2 (1000);
      s_val_old_ok_1         Varchar2 (1000);
      s_val_new_AP           Varchar2 (1000);
      n_ok_AP                Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio           Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1   Number;
      n_errore               Number;
      d_definizione          Varchar2 (1000);
      s_stringa_dominio      Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                    Number;                            -- ritorna se è NYA = 1 o 0
      s_val_old_ok_2         Varchar2 (1000);                   -- serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      VALORI_MULTIPLI EMPCUR;                                   -- Cursore Per I Valori NEW e OLD Dei Parametri In Tabella Multipli A Parte
  BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : E' il contrario di quello che succede nei controlli con N_ERRORE
      p_error_split := 0; 
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--    Recupero la definizione dell'oggetto
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.9');
--
      NYA:= GetNYA (n_parametro);
--
      GetOldNewValueMultiplo('PAR_1_1_1_3_2_9_COMP_ETCS', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_9', id_sol_track, valori_multipli) ;  -- multiplo
--
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_9_AP', id_sol_track);

--    legge il valore del parametro "padre" 1.1.1.3.2.1 - Livello ETCS (83)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);    
---
      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
--
      If n_controllo_padre = 0 Then
--         Il controllo di correlazione va eseguito solo se esistono valori
           If VALORI_MULTIPLI%Found Then 
			    Loop
                     n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);

--                   Test AP e Correlazione
                     If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                          n_ok_dominio := 1;              --getCorrectValue
--                        n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);
                     Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                          n_ok_dominio := 1;
		             Else n_ok_dominio := 0;
                     End If; 
--                   
                     If n_ok_AP = 1 Then
--                        Se il valore è nella LookUp value
                          If n_ok_dominio = 1 Then
                                If (s_val_new_2 <> 'N' And s_val_new_1 Is Not Null) or        -- Controllo con il parametro "padre" 1.1.1.3.2.1 
			          		     (s_val_new_2 = 'N' And s_val_new_1 Is Null) Then
			          		      n_errore := 1;
			          	      Else
			          		      n_errore := 0;
                                End If;
                          Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                          End If; 
                     Else n_errore := 0;                                                      -- valore non coerente con AP
                     End If; 
---
                     SetControlDetails
                        (     n_controllo,
                              id_sol,
                              id_sol_track,
                              n_parametro,
                              d_definizione,
                              Case When NYA = 1 Then 1
                                   Else n_errore
                              End,
                              6,
                              Case 
                                   When (n_errore = 0 And s_val_new_2  = 'N' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                                   When (n_errore = 0 And s_val_new_2 <> 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
 							       When n_ok_AP  = 0 And s_val_new_AP = v_ko_AP Then s_commento_AP_ko
                                   When n_ok_AP  = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                                   Else Null
                              End,
                              s_val_new_1,
                              s_val_old_ok_1,
                              n_controllo_old_ok_1,
                              Case When n_errore = 0 And NYA = 0 Then 0
                                   When n_errore = 0 And NYA = 1 Then 1
                                   When n_errore = 1 Then 0
                              End  );
--		 
                      Fetch VALORI_MULTIPLI Into s_val_new_1, s_val_old_ok_1;
                      Exit When VALORI_MULTIPLI%NotFound;
--	 
                  End Loop;
--         Se NO DATA FOUND
           Else 
               If VALORI_MULTIPLI%NotFound And s_val_new_AP = 'N' Then --Se è non applicabile va tutto bene
                     n_errore := 1;
                     n_ok_AP  := 1;
                     n_ok_dominio := 1;
                Elsif VALORI_MULTIPLI%NotFound And s_val_new_AP = 'Y' Then --Se è applicabile va tutto male
                     n_errore := 0;
                     n_ok_AP  := 0;
                     n_ok_dominio := 0;
                End If; 
                    SetControlDetails
					  ( n_controllo,
                        id_sol,
                        id_sol_track,
                        n_parametro,
                        d_definizione,
                        Case When NYA = 1 
						     Then 1
                             Else n_errore
                        End,
                        5,
                        Case When n_ok_AP = 0 And s_val_new_AP = v_ok_AP Then s_commento_AP_ok
                             Else Null
                        End,
                        s_val_new_1,
                        s_val_old_ok_1,
                        n_controllo_old_ok_1,
                        Case When n_errore = 0 And NYA = 0 Then 0
                             When n_errore = 0 And NYA = 1 Then 1
                             When n_errore = 1             Then 0
                        End );
          End If; 
--        siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
          p_error_split := Mod(n_errore +1, 2);                               
--
     Else  SetControlDetails 
                  (  n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------->Controllo padre fallito 
                     'Valori errati',     --s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End	    );
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;                       
      End If; 
--
      Close VALORI_MULTIPLI;
--
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_9_MULT: ' || Substr (Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_9_MULT;
--
-- ------------------------------------------------------------------------------------------------
--                       PROCEDURE SET_1_1_1_3_2_10 (298) 
--        1.1.1.3.2.10 - ETCS M_version  - Numerico
--  Nuovo parametro - Reg.777/2019 - Tipo Controllo: 6-AP+DOMINIO+CORRELAZIONE CON ALTRO PARAMETRO 
--       Applicabile solo se 1.1.1.3.2.1 Livello ETCS <> [N] Altrimenti: NA 
-- ------------------------------------------------------------------------------------------------
--
  Procedure SET_1_1_1_3_2_10    (n_controllo       In     Number,
                                id_sol            In     Varchar2,
                                id_sol_track      In     Varchar2,
                                id_dtp            In     Varchar2,
                                n_controllo_padre In     Number,
                                p_error_split    Out     Number   )    Is
      n_parametro               Number;
      s_val_new_1               Varchar2 (1000);
      s_val_new_2               Varchar2 (1000);
      s_val_new_3               Varchar2 (1000);
      s_val_old_ok_1            Varchar2 (1000);
      s_val_new_AP              Varchar2 (1000);
      n_ok_AP                   Number;                            -- variabile appoggio applicabilità 0/1
      n_ok_dominio              Number;                            -- variabile appoggio esistenza valore in dominio 0/1
      n_controllo_old_ok_1      Number;
      n_errore                  Number;
      d_definizione             Varchar2 (1000);
      s_stringa_dominio         Varchar2 (1000);                   -- stringa concatenata del dominio
      NYA                       Number;                            -- ritorna se è NYA = 1 o 0
--    serve per recuperare i valori B dei concatenati e farli scrivere come stringa unica con gli altri
      s_val_old_ok_2            Varchar2 (1000); 
--
   BEGIN
--    l'errore nelle procedure vale 0 se è giusto, 1 se è errato : è Il Contrario Di Quello Che Succede Nei Controlli Con N_ERRORE
      p_error_split := 0;        
--
--    Recupero il codice del controllo del dato pubblicato
      n_controllo_old_ok_1 := GetCorrectControlId(id_sol);    
--
--    Recupero la definizione del parametro
      d_definizione := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_0_0_1_D', id_sol_track);     
--
      n_parametro := pkg_rinf_interfaccia.GetParameterID ('1.1.1.3.2.10');
--
--    legge il valore attuale e precedente dalla tabella BINARI_CORSA_SOL degli schemi RINF_LAVORAZIONE_EVO e RINF_CONTROLLATI_EVO rispettivamente
      GetOldNewValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_10', id_sol_track, s_val_new_1, s_val_old_ok_1);
--
--    aggiunta istruzione per gestire la conversione da numerico decimale a character
      s_val_new_1 := to_char( replace (s_val_new_1, ',', '.'));
      s_val_old_ok_1 := to_char( replace (s_val_old_ok_1, ',', '.'));
--
--    verifica se può assumere valori NYA
      NYA := GetNYA(n_parametro);
--
--    legge se il dato è applicabile o meno
      s_val_new_AP:= GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_10_AP', id_sol_track);
--
--    legge il valore del parametro "padre" 1.1.1.3.2.1 - Livello ETCS  (83)
      s_val_new_2 := GetParameterValue('BINARI_CORSA_SOL', 'SOL_TRACK_1_1_1_0_0_1', 'SOL_TRACK_1_1_1_3_2_1', id_sol_track);    
--
--    verifica se la correlazione Valore=Not Null - AP=Y o AP=N - Valore=Null è corretta (=1) altrimenti=0
      n_ok_AP := GetCorrectAP (s_val_new_AP, s_val_new_1);
--
--    Se la procedura "padre" SET_1_1_1_3_2_1 è terminata correttamente
      If n_controllo_padre = 0 Then

--         Test AP e Correlazione
           If (n_ok_AP = 1 And s_val_new_AP = v_ok_AP) Then                        -- Correlazione AP-Valore=ok e AP=Y
                n_ok_dominio := GetCorrectValue (n_parametro, s_val_new_1);        -- Controlla se il valore è compreso nell'elenco "LookUp Value"
           Elsif (n_ok_AP = 1 And s_val_new_AP = v_ko_AP) Then                     -- Correlazione AP-Valore=ok e AP=N
                n_ok_dominio := 1;
		   Else n_ok_dominio := 0;
           End If; 
--
           If n_ok_AP = 1 Then
--              Se il valore è nella LookUp value
                If n_ok_dominio = 1 Then
                      If (Nvl(s_val_new_2, 'S') <> 'N' And s_val_new_1 Is Not Null) Or        -- Controllo con il parametro "padre" 1.1.1.3.2.1
					     (Nvl(s_val_new_2, 'S')  = 'N' And s_val_new_1 Is Null) Then
					      n_errore := 1;
				      Else
					      n_errore := 0;
                      End If;
                Else n_errore := 0;                                                 -- valore non incluso nella LookUp value
                End If; 
           Else n_errore := 0;                                                      -- valore non coerente con AP
           End If; 
--
           SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          Else n_errore
                     End,
                     6,
                     Case
                          When (n_errore = 0 And s_val_new_2 = 'N' And s_val_new_1 Is Not Null) Then s_commento_AP_ko
                          When (n_errore = 0 And s_val_new_2 <> 'N' And s_val_new_1 Is Null) Then s_commento_AP_ok
                          When (n_errore = 0 And s_val_new_2 <> 'N') Then GetCorrectRangeString (n_parametro)
                          Else Null
                     End,
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_errore = 0 And NYA = 0 Then 0
                          When n_errore = 0 And NYA = 1 Then 1
                          When n_errore = 1             Then 0
                     End);
--
--         siccome p_error è giusto se 0 e 1 se sbagliato e n_errore è il contrario, usiamo questo artificio
           p_error_split := Mod(n_errore +1, 2);                               
--
      Else SetControlDetails (
                     n_controllo,
                     id_sol,
                     id_sol_track,
                     n_parametro,
                     d_definizione,
                     Case When NYA = 1 Then 1
                          When n_controllo_padre = 1 Then 1
                          Else 0
                     End,
                     14,                             -- fallito padre
                     GetMessFallitoPadreSingolo(83),--------------------------------------------->Controllo padre fallito 
                     s_val_new_1,
                     s_val_old_ok_1,
                     n_controllo_old_ok_1,
                     Case
                          When n_controllo_padre = 1 Then 1
                          When NYA = 0 Then 0
                          When NYA = 1 Then 1
                     End);
--
--         in p_error 1 è errato (al contrario di n_errore)
           p_error_split := 1;
      End If; 
  EXCEPTION
      When OTHERS Then
         p_error_split := 1; 
         Dbms_Output.Put_Line ('Errore - SET_1_1_1_3_2_10: ' || Substr(Sqlerrm, 1, 250));
  End SET_1_1_1_3_2_10;

End PKG_RINF_CONTROLLO_PAR_V082;
/